pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly worthless.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead); // tiny unusable gap: heavy penalty
        } else if dead < 20.0 {
            score += 15.0 * (20.0 - dead) / 10.0; // likely dead space
        }
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item is large relative to mean residual or many bins exist).
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let pressure = open_bins_count as f64;
        let tight = (bin_residual as f64 - item_size as f64).max(0.0);
        score += 30.0; // base cost of opening a bin
        score -= pressure * 0.5; // slight relief of open-bin pressure
        // If the next item could combine with the leftover, opening is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // If this item leaves a big usable gap, opening a fresh bin is bad.
        score += (item_size as f64 / 10.0) * 2.0;
        let _ = tight;
    }

    // Mild open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.15;

    // Prefer bins with residual close to the item (tight packing).
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += slack * 0.3;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 5.0; // leftover too small for next item: dead space
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item (1..100 range, but typical min item known via
    // lookahead) are pure waste. Penalize them quadratically.
    let min_future = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual < min_future {
        score += 8.0 * (min_future - post_residual) as f64;
    } else {
        // Reward leaving a gap that exactly fits the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Reward tight fits (small relative post residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio;

    // Penalize creating tiny unusable slivers (0 < post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // placement is very efficient; makes new bins attractive for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - fit_ratio));

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: empty bin should only win when the current bin would
    // leave a bad dead-space gap or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        if post_residual < min_future && post_residual > 0 {
            // Opening fresh is fine for near-full placement in a new bin.
            score -= 4.0;
        } else {
            // Prefer reusing an existing bin when fit is decent.
            score += 14.0 * (1.0 - fit_ratio);
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (more full).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - match_quality / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize bins that leave post_residual too small for the next item (dead space).
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin opening when decent fits exist, unless residual is very tight overall.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        if tightness < 0.25 {
            score -= 5.0; // open a new bin when open bins are mostly full
        } else {
            score += 20.0; // discourage wasting a fresh bin
        }
    }

    // Late-stream bias: consolidate more aggressively as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins where the next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact 2-step match is gold: subtract heavily.
            let slack2 = (post_residual - next_item_size) as f64;
            score -= 60.0 + 40.0 * (1.0 - slack2 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted chain potential.
            score += 0.35 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 5.0;
    }

    // Tightness reward relative to mean residual: filling an unusually full bin is good.
    let tightness = (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.25 * tightness;

    // Penalize creating very small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default is neutral (score == capacity residual scale);
    // make it slightly unattractive unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0;
        // During late stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If next item is large and this new bin would fit it perfectly, encourage opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Mild penalty for hoarding many open bins when a tight fit exists elsewhere.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post residual is small relative to capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize leaving dead space that no future item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits in the post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect pairing: item + next item exactly fill this bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins -> this placement is low-stakes; slight penalty for waste.
    if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state coupling: when mean residual is low, conserve bin space more aggressively.
    let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += pressure * (post_residual as f64) * 0.3;

    // Time horizon: early in stream, be more willing to open bins (penalize cramming);
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 3.0;

    // New-bin candidate handling: empty bin is a fallback.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when current bins are fragmented
        // (high mean residual spread) or item is large and nothing fits well.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 - 0.4 * (open_bins_count as f64) + fragmentation * 0.1;
        // If this is the only fitting option, opening a new bin is natural.
        if fitting_bins_count <= 1 {
            score += 10.0;
        }
        // Late stream: discourage new bins.
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: penalize leftover space, with non-linear scaling
    let mut score = x * (1.0 + 0.8 * x * (1.0 - x));

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - x;
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 6.0 * progress_coupling * tightness * tightness;

    // Reward near-perfect fits more aggressively as stream advances
    score -= 4.0 * (1.0 - x * x) * progress;

    // Penalize bins that are much worse than the mean residual (non-linear divergence)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 3.0 + 5.0 * progress_coupling;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill = nxt / pr.max(1.0);
            score -= 5.0 * fill * fill * (0.5 + 0.5 * progress);
        } else {
            score += 2.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for many open bins (encourage consolidation early)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are dead weight; penalize them quadratically.
    if post_residual > 0 && post_residual < item_size {
        let dead = (item_size - post_residual) as f64;
        score += dead * dead * 0.5;
    }
    // Gaps below the absolute minimum item size are pure loss.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 25.0;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score += pressure * 2.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item would leave this bin's residual unusable anyway, mild reward.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: baseline attractiveness so we only open a new bin
    // when existing bins have poor fits. Scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 25.0 * progress + mean_residual * 0.15;
        // If this bin is the last chance, opening new is worse.
        if fitting_bins_count == 1 {
            score += 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no future item (1..100)
    // can fill is worse than space that some class can still fill.
    let pr = post_residual;
    let usable = if pr == 0 {
        1.0
    } else if pr >= 50 {
        0.9
    } else if pr >= 34 {
        0.6
    } else if pr >= 26 {
        0.45
    } else if pr >= 20 {
        0.35
    } else if pr >= 10 {
        0.25
    } else {
        0.05
    };
    score -= usable * 60.0;

    // Modulo-10 harmonic bonus: residuals that are multiples of 10 are
    // classic "friendly" sizes for future items.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Penalty for tiny unusable slivers (dead space)
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 120.0;
        } else if gap < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item would NOT fit here, slightly penalize (chain break)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are very full
    // or the item simply does not leave a good residual anywhere.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 15.0 {
            score -= 25.0;
        } else {
            score += 30.0 + pressure * 2.0;
        }
        // Late in the stream, avoid spawning bins with small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 30 && progress > 0.5 {
            score += 20.0;
        }
    }

    // Prefer tighter bins overall: closeness of fit
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Mild preference to keep mean residual balanced
    if (bin_residual as f64 - mean_residual).abs() < 10.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // This open bin is the only existing bin that can take the item
    // (the residual < capacity check excludes the brand-new-bin candidate).
    let last_chance = fitting_bins_count == 1 && bin_residual < bin_capacity;

    // Harmonic stacking class: does the lookahead item also fit here after placement?
    let stackable = next_item_size > 0 && post_residual >= next_item_size;

    let mut score;

    if stackable {
        // Tier 1: both current and next item fit in this bin.
        // Dominant tier: stacking two items into one bin beats splitting them
        // across bins whenever it is feasible (concentrates free space).
        score = post - 1000.0;
        // Perfect pairwise fill: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // Tier 2: next item cannot follow into this bin.
        // Base: best-fit on post residual. The uniform +nxt shift raises the
        // whole tier above any stacking bin (incl. a fresh bin where the next
        // item would fit), without distorting ranking inside the tier.
        score = post + nxt;
        // Harmonic class tiebreak: round residual classes (multiples of 10)
        // are marginally more reusable by future items.
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 0.75;
        }
    }

    // Last-chance reward: strongly prefer consuming the final fitting open bin
    // over fragmenting capacity into a new bin (unless tier-1 stacking overrides).
    if last_chance {
        score -= 40.0;
    }

    // Negligible consolidation tiebreak: mildly favor bins tighter than the mean.
    score += (mean_residual - bin_residual as f64) * 1e-4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 900.0;
        } else {
            score -= 200.0 / (gap as f64 + 1.0);
        }
    }

    // Penalize small unusable dead space (waste) when next item can't use it
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let tightness = post_residual as f64 / next_item_size as f64;
        score += 60.0 * (1.0 - tightness);
    }

    // Reward bins tighter than mean residual (good fits)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // New bin candidate: only prefer when current bin would leave big waste
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bin mildly, unless it enables a good 2-step chain
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 250.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Slight penalty for very fragmented open-bin pools
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: item + next item fill bin exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward near-perfect matches (post_residual can hold next item with little waste).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use, scaled by how small the gap is.
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 2.0 * gap;
    }

    // Penalize leaving small unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer tight fits relative to current residual.
    score += 0.3 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    // Relative to mean residual: bins with residual near mean are neutral; large-residual bins
    // should absorb items to consolidate small bins.
    score -= 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: make it attractive only when few bins fit the item
    // or the residual is large and the item is big (poor fit elsewhere).
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 20.0;
        } else {
            // Discourage opening new bins when existing bins fit fine.
            score += 40.0 + 0.5 * item_size as f64;
        }
    }

    // Late in the stream, be more conservative: favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward good fits relative to bin space (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 25.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> prefer compacting into existing ones.
    score += open_bins_count as f64 * 1.5;
    // But penalize bins that are already tight relative to the mean residual
    // (prefer filling bins that are already low when many bins are open).
    if (bin_residual as f64) < mean_residual && post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item almost fits (small miss), slight penalty for stranding space.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this call's post_residual is large relative to item) or bins are scarce.
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin has full capacity; make it moderately attractive
        // so it beats bins with terrible fits, but loses to decent fits.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
        // Many open bins: discourage opening yet another unless necessary.
        score += open_bins_count as f64 * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are worthless.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }
    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward residuals that can still hold future items, scaled by lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual >= next_item_size * 2 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the known next item.
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: neutral baseline, only attractive when fits are bad.
    if bin_residual == bin_capacity {
        score = 25.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 1 {
            score += 50.0; // never open new bin when a last-chance fit exists
        }
        if post_residual == 0 {
            score += 100.0;
        }
    }

    // Slight preference for tighter existing fits.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    score += open_bins_count as f64 * 0.6;

    // If next item fits exactly into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 3.0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't host the next item: mild penalty scaled by gap.
        score += ((next_item_size - post_residual) as f64).min(20.0) * 0.4;
    }

    // Mean-residual coupling: if this bin is far below average residual
    // (already dense), slightly favor it.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; high enough that good fits win,
        // low enough to beat bins leaving tiny dead space.
        score = bin_capacity as f64 * 0.85 + open_bins_count as f64 * 0.2;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
        if post_residual == 0 {
            score -= 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 45.0; // worst dead space
    } else if pr > 10 && pr <= 20 {
        score += 18.0;
    } else if pr > 20 && pr <= 35 {
        score += 6.0;
    } else if pr == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Integer-division class: residual mod 10 (harmonic granularity of item sizes)
    let residue_class = pr % 10;
    if pr > 0 && residue_class != 0 {
        score += residue_class as f64 * 0.8;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 22.0; // chain placement possible
            // extra reward if next item exactly fills the leftover
            if next_item_size == pr {
                score -= 18.0;
            }
        } else {
            // next item won't fit here: penalize more if leftover is small
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when current bin fits poorly,
        // but discourage when a good existing fit exists.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * progress;
        if fitting_bins_count <= 1 && item_size < bin_capacity {
            score -= 20.0; // poor alternatives: new bin acceptable
        }
        // A fresh bin keeps max flexibility for the lookahead item
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Prefer tighter bins among fitting ones (relative to mean residual)
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Slight preference for bins that will end more full
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (<10, minimum item size) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
