    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bins pressure: discourage spreading across many bins; keep consolidation.
    score += open_bins_count as f64 * 2.0;

    // Slightly favor bins tighter than the mean residual (better fits).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress.
        score = bin_capacity as f64 + 80.0 + (step_index as f64 / total_items.max(1) as f64) * 50.0;
        // If this is a last-chance situation, opening a new bin is acceptable.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // If lookahead item is large, a fresh bin can host it after this one.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost unusable
    // (min item size ~1..100, but gaps < 20 rarely get filled later).
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 12.0; // heavy penalty for tiny gaps
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    }

    // Reward tight fits relative to bin residual (waste ratio).
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 25.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage creating more
    // dead space spread across bins; favor consolidating into existing space.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: if average residual is already small, opening
    // a new bin is costly, so penalize the new-bin candidate implicitly via
    // its large post_residual; additionally reward filling bins when mean
    // residual is low.
    if mean_residual < 25.0 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item could use the post_residual, reward leaving
    // exactly that much space; otherwise penalize leaving space that matches
    // nothing.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, prefer closing bins out (fill existing ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class of post_residual modulo capacity fractions:
    // classify dead space into usable bands (>= next item, >= 50, >= 25, tiny).
    let pr = post_residual;
    let class: f64 = if next_item_size > 0 && pr >= next_item_size {
        0.0 // residual can host the lookahead item: very usable
    } else if pr >= 50 {
        1.0
    } else if pr >= 25 {
        2.0
    } else if pr == 0 {
        0.0
    } else {
        3.0 // tiny dead space
    };
    score += class * 30.0;

    // Reward residual that is an exact multiple of common small sizes
    // (harmonic divisibility: 10/20/25/50 leave reusable chunks).
    if pr > 0 && (pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0) {
        score -= 12.0;
    }

    // Penalize post_residual in awkward zone (1..10): unusable dust.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if pr > 0 && pr < 10 {
            score += 60.0; // but not if it creates dust
        }
    }

    // New-bin candidate: default moderately high score; open a new bin only
    // when all existing placements would waste a lot (score above threshold).
    if bin_residual == bin_capacity {
        score = 100.0 + mean_residual * 0.3 - (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // pairing large items into fresh bins helps
        }
    }

    // Late in the stream, tighten bins harder (less room to amortize waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / cap);

    // Slight preference for fuller bins relative to mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large ones.
    let usable = post_residual >= next_item_size && next_item_size > 0;
    if next_item_size > 0 && !usable {
        // Gap too small for the next item: heavy penalty scaled by gap smallness.
        let gap_ratio = post_residual as f64 / next_item_size as f64;
        score += (1.0 - gap_ratio).max(0.0) * 40.0 + 10.0;
    }

    // Reward very tight fits (low waste) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmentation;
    // with few open bins, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (1.0 + progress) * 2.0;

    // New-bin candidate: baseline attractiveness so a new bin is chosen only
    // when all open bins look bad (their dead-space penalties push below this).
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
