    }
    // new-bin candidate: penalize mildly unless residuals are tight
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (mean_residual / cap).powi(2);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quarters of capacity.
    let quarter = (bin_capacity / 4) as f64;
    let cls = (post_residual as f64 / quarter).floor().min(3.0);

    // Reward near-perfect fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 25.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 10.0;
    }

    // Penalize residuals in the "unusable" band: too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * (next_item_size as f64);
    } else if next_item_size > post_residual {
        score += 3.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many fitting bins means we should reuse one).
    if bin_residual == bin_capacity {
        let crowd = fitting_bins_count as f64;
        // Base penalty so new bins are opened only when reuse is bad.
        score += 30.0 + crowd * 6.0;
        // But if this bin would be very full with the item (large item),
        // a fresh bin is fine — reduce penalty.
        let fill = item_size as f64 / cap;
        if fill > 0.6 {
            score -= 20.0 * (fill - 0.6) / 0.4;
        }
        // Late in the stream, prefer closing out bins tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (balance spreading).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Harmonic class adjustment: odd classes (small leftovers) slightly favored.
    if cls as u32 % 2 == 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual gaps below the minimum item size (1..10)
    // are unusable "waste" — penalize them heavily, but an exact fit (0) is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Tight fit reward: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last chance: this is the only bin that fits — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 10.0; // would create dead space after next item
    }

    // Open-bin pressure: prefer spreading load into existing bins when many are open,
    // making the fresh-bin candidate less attractive unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: bins far below mean residual have more room — mildly favor them.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Late-stream consolidation: near the end, close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, penalized mildly so it's
    // chosen only when open bins are truly bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = bin_capacity as f64 * 0.6 + item_size as f64;
        // Prefer opening a new bin when nothing else fits well.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        return score;
    }

    // Reward tight fits: small post_residual is good.
    score = post_residual as f64;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a perfect pairing — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item fits too: mild reward proportional to how snugly.
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next <= 10 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item will NOT fit in the leftover: leftover likely dead space,
            // unless it's small enough to be negligible.
            if post_residual < 10 {
                score -= 5.0; // dead space is tiny anyway
            } else {
                score += (next_item_size - post_residual) as f64 * 0.35;
            }
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Compare against mean residual: bins tighter than average are precious;
    // waste them only on good fits. Bins looser than average should absorb
    // items preferentially to consolidate space.
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual).min(30.0) * 0.4;
    } else {
        score += (mean_residual - post_residual as f64).min(30.0) * 0.25;
    }

    // Penalize leaving large awkward residuals (dead space) that few items can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // small leftovers are fine (near-full bins)
    } else if post_residual >= 10 && post_residual < 25 {
        // awkward middle zone where only small items fit
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let last_chance = fitting_bins_count <= 1 && !is_new_bin;

    // Tight fits are excellent: strongly reward small post-residuals non-linearly.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= (15 - post_residual) as f64 * 1.5;
    }

    // Penalize dead space that is too small for typical future items
    // (unusable slivers), scaled by how much of the stream remains.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (1.5 + progress);
    }

    // Lookahead coupling: if the next item fits the post-residual well,
    // reward this placement; if it leaves a gap that blocks the next item,
    // penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            if slack <= 10.0 {
                score -= 12.0; // perfect chained fit
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += (nxt - post_residual as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if last_chance {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is costly; only attractive
    // when item is large relative to capacity or many bins are open with
    // low mean residual (fragmented state) and stream is early.
    if is_new_bin {
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let penalty = 30.0
            + 20.0 * (1.0 - item_frac)
            + 5.0 * pressure
            - 10.0 * progress;
        // If existing bins are highly fragmented, opening fresh is less bad.
        let relief = if fragmentation > 40.0 { 12.0 } else { 0.0 };
        score += penalty - relief;
    } else {
        // Mild bonus for filling bins that are already well used.
        let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 6.0 * used_frac;
    }

    // Prefer bins whose residual is close to the item (minimize leftover),
    // using mean residual as a global anchor.
    let residual_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += residual_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post-residual, with non-linear tightening as stream progresses.
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Polynomial coupling: penalize mid-range dead space quadratically, normalized by capacity.
    let norm_post = pr / cap;
    score += 30.0 * norm_post * (1.0 - norm_post) * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly later in the stream (cubic in progress).
    score -= 12.0 * (1.0 - norm_post).powi(3) * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Penalize leaving residual that the next item cannot use.
        score += 6.0 * (next_item_size as f64 / cap) * (0.5 + 0.5 * progress);
    }

    // Deviation from mean residual: prefer bins whose post-residual stays near the mean,
    // keeping residual diversity (helps future items find fits).
    score += 4.0 * ((pr - mean_residual) / cap).abs();

    // Mild penalty when many bins are open, encouraging consolidation.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // New-bin candidate: neutral-ish base so it's chosen only when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + 25.0 * progress - 10.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 decile classes.
    let class = post_residual / 10;
    // Dead-space penalty: classes 1..3 (residual 10..39) are hard to reuse for
    // typical item sizes -> heavily penalize leaving them behind.
    if class >= 1 && class <= 3 {
        score += (4 - class) as f64 * 18.0;
    }
    // Classes 4..6 (40..69) are moderately reusable; small penalty.
    if class >= 4 && class <= 6 {
        score += 4.0;
    }
    // Classes 7..9 (70..99): roomy residuals, mildly reward.
    if class >= 7 && class < 10 {
        score -= 6.0;
    }
    // Exact fill or near-zero residual is perfect.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 9 {
        score -= 15.0;
    }

    // Modulo coupling: reward when post_residual is a multiple of 10 or 25
    // (harmonic packing targets), since future items often align to these.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits the post residual exactly or nearly,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 20.0;
            } else if gap <= 15 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this residual: penalize small leftovers more.
            if post_residual < next_item_size && post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Default: discourage opening a new bin when any open bin fits decently.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 45.0 + 5.0 * pressure + mean_residual * 0.3;
        // But if this is the last item, a new bin is irrelevant; neutralize a bit.
        if next_item_size == 0 {
            score -= 25.0;
        }
        // If item is huge (> 60) and mean residual is small, new bin is fine.
        if item_size > 60 && mean_residual < 25.0 {
            score -= 35.0;
        }
    }

    // Slight stream-progress tilt: late in the stream, prefer closing bins
    // tightly (small post_residual) since fewer future items remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.25;

    // Penalize bins whose residual deviates far from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) < 10.0;
        if dead {
            score += 60.0; // gap too small for any item (min size 1..100 unknown, but tiny gaps are waste)
        }
        // Non-linear penalty: quadratic growth of "unusability" as gap shrinks below typical small item sizes.
        let r = post_residual as f64;
        score += 900.0 / (r + 5.0);
    } else {
        // Perfect fit: strongly reward.
        score -= 120.0;
    }

    // Reward residual that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 {
        score += 15.0; // blocks the next item: penalize
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing ones (this is an existing bin),
    // and make the new-bin candidate (residual == capacity) less attractive when few bins are open.
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost of opening a new bin.
        score = bin_capacity as f64 - 10.0 + (open_bins_count as f64) * 3.0;
        // If the new bin would be a perfect fit for the item, make it more attractive.
        if bin_capacity == item_size {
            score -= 100.0;
        }
        // If no existing bin fits well (this call happens alongside fitting bins), keep default.
    } else {
        // Existing bin: reward choosing it, scaled by open bin pressure.
        score -= (open_bins_count as f64) * 2.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing) mildly.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Late in the stream, be more conservative: avoid opening bins (penalize new-bin candidate more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item still fits snugly after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / 50.0).max(0.0);
    } else if next_item_size > 0 {
        // Next item would NOT fit here after placement: penalize dead space.
        score += 15.0;
    }

    // Compare post_residual against mean residual: tight residual vs. average is good.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage unless current placement leaves terrible waste.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = 30.0 + waste * 0.3 + poor_fit * 10.0
            - (fitting_bins_count as f64) * 2.0
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic penalty on residual waste.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Small dead space is nearly perfect: proportionally strong reward.
        score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly; reward it heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild bonus scaled by how well it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / bin_capacity as f64);
        }
    }

    // Global state: penalize creating many small residuals when open bins
    // already have low mean residual (fragmentation risk).
    let frag_pressure = (mean_residual / bin_capacity as f64).min(1.0);
    score += 10.0 * frag_pressure * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer consolidating into existing bins rather than
    // leaving many partially-filled bins around.
    if open_bins_count > 3 {
        score -= 4.0 * ((open_bins_count as f64).ln());
    }

    // New-bin candidate logic: an empty bin should only win when the fit in
    // existing bins would be poor. Penalize the empty bin by default, but
    // relax the penalty when it is the only option or the stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 30.0;
        // Early in the stream, opening bins is cheap and useful for the future.
        new_bin_penalty *= 1.0 - 0.5 * (1.0 - progress);
        // If the item fits nowhere else, opening a bin is fine.
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        // If the next item is large and this fresh bin would hold both well,
        // soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty *= 0.4;
        }
        score += new_bin_penalty;
    }

    // Time-horizon modulation: late in the stream, waste matters more since
    // there are fewer future items to fill gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight tie-breaker toward bins with less residual overall (denser bins).
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: residual fraction and its square/cube terms
    let rf = pr / cap;
    score += 12.0 * rf * rf - 8.0 * rf * rf * rf;

    // Tight fits are rewarded quadratically, more so late in the stream
    let tightness = 1.0 - rf;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Interaction of post-residual with mean residual: prefer bins that
    // end below the mean (consolidating space)
    score += 0.15 * (pr as f64 - mean_residual).abs() * (1.0 - tightness);

    // Lookahead: reward if next item fits the post-residual, penalize waste
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 10.0 * (1.0 - ((pr - n) / cap));
        } else {
            score += 5.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.6 + 0.4 * progress);
    }

    // New empty bin candidate: penalize unless existing bins are bad fits
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 18.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // opening a new bin is attractive when the item is large
        score -= 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual is "wasted" in small
    // chunks (residual mod 10) are less valuable than clean multiples of 10.
    let rmod = post_residual % 10;
    score += rmod as f64 * 0.6;

    // Integer-division thresholds: classify post_residual into harmonic bands.
    let band = post_residual / 10; // 0..10
    match band {
        0 => score -= 12.0, // near-perfect fit, highly desirable
        1 => score -= 6.0,
        2 => score -= 2.5,
        3 => score -= 0.5,
        7 => score += 1.5,  // mid-large residuals less attractive
        8 => score += 2.5,
        9 => score += 4.0,
        _ => {}
    }

    // Reward tight fits relative to capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 15.0;

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        score -= 10.0;
        if chain % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Residual after placement cannot host the next item: penalize dead space
        // proportional to how close-but-unusable it is.
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it mildly attractive only when open bins are
    // fragmented; otherwise discourage wasting bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 55.0 + 25.0 * (1.0 - fragmentation) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        }
    }

    // Small global pressure: fewer open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Residuals in [10, 25) are risky: only tiny items can use them.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // consolidating into existing bins; few open bins -> new bins are cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when the item is large and would
    // leave a big unusable gap everywhere, or when the lookahead item is
    // large and current residuals are small.
    if bin_residual == bin_capacity {
        let gap_risk = if post_residual > 0 && post_residual < 25 { 1.0 } else { 0.0 };
        let lookahead_need = if next_item_size > 0 && next_item_size as f64 > mean_residual { 1.0 } else { 0.0 };
        // Base handicap so new bins are chosen only when justified.
        score += 55.0;
        score -= 30.0 * gap_risk;
        score -= 20.0 * lookahead_need;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead synergy: if the next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 18.0;
    }
    // Penalize placements that strand space the lookahead item needed.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Mild preference for bins below mean residual (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0); // perfect chain match gets full -40
        } else {
            // next item won't fit here: penalize wasted residual
            score += (post_residual as f64) * 0.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate baseline: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85 + (item_size as f64) * 0.2;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pairing potential in a fresh bin
            score -= 20.0;
        }
        if fitting_bins_count > 0 {
            score += 40.0; // discourage opening when alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling: post_residual penalized more heavily as stream progresses.
    let poly = base * (1.0 + 1.5 * progress * base + 0.75 * progress * progress * base * base);

    // Reward tight fits (small post_residual) with a squared bonus.
    let mut score = poly - 2.0 * (1.0 - base) * (1.0 - base);

    // Lookahead: if next item can fit into the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.2 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Penalize creating dead space below typical item range relative to mean residual.
    if pr < item_size as f64 && pr > 0.0 {
        score += 0.8 * (1.0 - pr / cap);
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = if open_bins_count > 0 { (mean_residual / cap).abs() } else { 0.0 };
        score += 2.5 + 2.0 * (1.0 - frag);
        // If item fits poorly nowhere else, new bin becomes acceptable via fitting_bins_count signal.
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic class logic: classify dead space by modulo classes of capacity.
    // Residuals in classes {0,1,2,...} mod 10 are "small dead zones" that rarely
    // fit future items (items >= 1 but typically chunky). Penalize mid-range
    // residuals that are too small for likely items but waste capacity.
    let dead_class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + dead_class as f64; // unusable sliver, worse the larger relative to nothing gained
    } else if post_residual >= 10 && post_residual < 20 {
        // borderline zone: could fit small items; mild penalty scaled by class
        score += 8.0 + (dead_class as f64) * 0.5;
    }

    // Lookahead coupling: if next item fits into post_residual, this is great —
    // reward chaining. If next item does NOT fit, we stranded capacity.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly; stronger reward the tighter the chain
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - chain_slack.min(20.0);
        } else {
            // next item won't fit here; penalize proportionally to wasted look
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fit_ratio > 0.7 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the current fit is very poor
    // (large post_residual that strands capacity). Otherwise penalize new bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales with how many bins already open
        score += 45.0 + open_bins_count as f64 * 2.0;
        // But if the item is large relative to capacity and would leave a bad
        // fit elsewhere, opening fresh is fine — reduce penalty for large items.
        if item_size >= 70 {
            score -= 20.0;
        }
        // Early in stream, new bins are cheap-ish; late in stream prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Contextual penalty: if this bin's residual is far from the mean residual,
    // placing here may unbalance the pool; mild regularization.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer bins that are already partially filled (reduce bin count pressure):
    // small bonus for using an open bin vs implicit new bin handled above.
    if bin_residual < bin_capacity && post_residual >= 0 {
        score -= 3.0;
    }

    // Integer-division threshold on post_residual quarters: quarter buckets.
    let quarter = post_residual / 25;
    score += match quarter {
        0 => -12.0, // post_residual < 25: dense packing zone
        1 => 0.0,   // 25..49: neutral
        2 => 4.0,   // 50..74: half-empty bin after placement, meh
        _ => 10.0,  // nearly untouched bin used for a small item
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: raw post residual (tighter fit -> lower score).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are unusable "dead" space. Penalize small non-zero gaps super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    } else if post_residual > 10 && post_residual <= 20 {
        // Moderately risky gap: only usable by small future items.
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect chain -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            // Next item leaves dead space here -> mild penalty.
            score += 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Next item cannot use this gap at all -> dead space confirmed.
            score += 12.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 15.0; // still fine: kills the bin cleanly
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage new bin only when open bins are mostly empty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score: base at capacity, adjusted by pressure.
        let mut nb = bin_capacity as f64;
        // Many open bins with low mean residual -> reuse instead of opening.
        if mean_residual < item_size as f64 && open_bins_count > 0 {
            nb += 25.0;
        }
        // Early stream with few bins: opening is cheap.
        nb -= 10.0 * (1.0 - progress);
        // If no other bin fits, new bin is the fallback: make it attractive.
        if fitting_bins_count == 0 {
            nb -= 100.0;
        }
        score = nb;
    } else {
        // Fitting an open bin: slight penalty for hoarding many open bins'
        // slack when this placement wastes a lot.
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
        // Prefer bins below mean residual (tighter than average).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect match, strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (chain packing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits perfectly after this placement (2-item exact fill)
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
        score -= 500.0;
    }
    // Next item fits but leaves awkward gap: penalize small gaps that waste space
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 10 {
            score += 50.0; // tiny dead space after two placements
        } else {
            score -= 30.0; // next item still fits reasonably
        }
    }
    // Next item does NOT fit in remaining space: penalize creating a bin
    // that can't take the following item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0;
    }

    // Penalize large post_residual relative to mean residual (wasteful placement)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New empty bin candidate: penalize unless no good fit exists
    if bin_residual == bin_capacity {
        score += 200.0;
        // But if next item is huge and mean residual is small, opening a new bin
        // may be wise: soften penalty
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 150.0;
        }
    }

    // Late in stream: prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer filling bins tightly (low post residual).
    let mut score = pr;

    // Smooth non-linear reward for tight fit: quadratic coupling of post residual with item size.
    score -= 60.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space that is too small to be useful later: smooth trough around small residuals.
    let dead = (norm_pr - 0.15).abs();
    score += 25.0 * (-dead * dead / 0.02).exp();

    // Stream progress coupling: later in stream, favor tighter packing more aggressively.
    score -= 40.0 * progress * norm_item * (1.0 - norm_pr);

    // Lookahead: reward if next item fits in post residual (smooth interaction).
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        let fits = (gap / 0.1).tanh();
        score -= 30.0 * (0.5 + 0.5 * fits) * norm_next * norm_pr;
    } else {
        // Last item: strongly prefer minimizing residual.
        score += 20.0 * norm_pr * norm_pr;
    }

    // Last chance bin: this is the only fitting bin; strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier worth filling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless open bins are poor fits.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 35.0 + 8.0 * crowding;
        // Allow new bin late in stream if it would give a very clean residual for next item.
        if next_item_size > 0 && (cap - norm_next * cap) >= item_size as f64 {
            score -= 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Small classes are good (tight fit).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual
    let quarter = bin_capacity / 4;      // 25
    let eighth  = bin_capacity / 8;      // 12
    let half    = bin_capacity / 2;      // 50

    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < eighth {
        score -= 25.0; // near-perfect: tiny dead space
    } else if post_residual <= quarter {
        score -= 10.0; // good class
    } else if post_residual <= half {
        score += 8.0;  // mediocre class
    } else {
        score += 20.0; // large dead space class
    }

    // Modulo arithmetic: residual divisible by common item sizes is reusable
    for m in [10u32, 20, 25, 50] {
        if post_residual >= m && post_residual % m == 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fits
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 12.0 * (1.0 - fit_ratio);
        } else {
            // next item won't fit here: penalize leaving big unusable residue
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bins are poor
    if bin_residual == bin_capacity {
        // fresh bin: neutral base, but discount when stream is early or
        // open bins are already crowded with large residuals
        score = 55.0 + 0.1 * (post_residual as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 30.0 && open_bins_count > 0 {
            score -= 10.0; // open bins nearly full -> new bin reasonable
        }
        if progress < 0.3 {
            score += 5.0; // early stream: prefer consolidating into open bins
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the only fitting bin
        }
    }

    // Mild preference to fill fuller bins when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any realistic item are dead space.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64;
    }

    // Reward very tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a good pairing with next item.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < dead_threshold {
            score -= 45.0; // perfect two-item plan
        } else {
            score += 25.0 + open_bins_count as f64 * 0.5; // discourage wasteful new bins
        }
    } else {
        // Open-bin pressure: mild penalty as bin count grows to encourage consolidation.
        score += open_bins_count as f64 * 0.3;

        // Lookahead synergy: favor bins whose leftover accommodates the next item snugly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next < dead_threshold {
                score -= 20.0;
            }
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // leftover blocks the known next item
        }
    }

    // Prefer filling bins with larger residual when mean residual is high (fragmentation risk).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten up: penalize any leftover more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 25.0 - leftover_after_next as f64 * 0.5;
    }
    // Next item does NOT fit here: penalize proportionally to how close we were
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Penalize creating tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Reward tight fits (small post_residual)
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins are full-ish or few options
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if next_item_size > 0 && post_residual == next_item_size { 1.0 } else { 0.0 };
        score = 45.0 + open_bins_count as f64 * 2.0 - progress * 10.0 - pressure * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: later on, prefer tighter packing (dead space is costlier).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base tightness reward: exact fits are ideal.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item is small and post_residual is small, dead space is less of an issue.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 0.05 * post_residual as f64 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize creating tiny unusable residuals (< 10 can never fit any item).
    if post_residual < 10 {
        score += 5.0 * (1.0 + progress);
    }

    // Global state coupling: if many bins are open with large mean residual, discourage opening new bins.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 + 10.0 * (1.0 - pressure) + 3.0 * open_bins_count as f64 * (0.3 + progress);
        // But if no fitting bins exist at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Reward using bins whose residual deviates below mean (consolidating space).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
        }
    }

    // Late-stream tightness amplification.
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: post residual, with a non-linear (quadratic/cubic) penalty for
    // small-but-not-tiny residuals (dead space), softened by stream progress.
    let mut score = post;
    score += 40.0 * norm_post * (1.0 - norm_post) * (0.5 + 0.5 * progress);
    score += 25.0 * norm_post * norm_post * (1.0 - norm_post);

    // Smooth coupling with mean residual: prefer bins whose post residual
    // stays near the mean (keeps residual distribution usable).
    let mean_coupling = (post - mean_residual) / cap;
    score += 15.0 * mean_coupling * mean_coupling;

    // Last-chance bonus: smooth reward when few fitting bins remain.
    if fitting_bins_count <= 1 {
        score -= 20.0;
    } else {
        score -= 18.0 / (fitting_bins_count as f64);
    }

    // Lookahead: reward if next item fits well into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - ((post - nxt) / cap).abs();
            score -= 12.0 * fit_quality;
        } else {
            score += 8.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // New-bin candidate: smooth penalty scaled by how many bins are open
    // and how much of the stream has passed (avoid needless bin sprawl).
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Mild progress-driven tightening: later in stream, waste matters more.
    score *= 1.0 + 0.3 * progress * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "nice" divisors of capacity (25, 50, 20, 10...) are reusable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit is always great
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -9.0
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        // awkward residual: penalize small dead space that nothing can use
        if pr < 10 { 15.0 } else { 0.0 }
    };
    score -= harmonic_bonus;

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // next item seals this bin perfectly
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by dead space
            score += 4.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score += 10.0; // but not if it creates unusable dust
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when the item is huge relative to
        // remaining capacity or all open bins are badly fragmented.
        let tightness = item_size as f64 / cap;
        let fragmentation = if mean_residual > 0.0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            0.0
        };
        let pressure = (open_bins_count as f64).ln_1p();
        // Default: discourage new bins mildly; reward when item is large and open bins are full-ish
        score += 25.0
            - 20.0 * tightness
            + 15.0 * fragmentation * (1.0 - tightness)
            - 2.0 * pressure;
        // Huge item (>= 60% of capacity) with fragmented bins: new bin is attractive
        if tightness >= 0.6 && fragmentation < 0.4 {
            score -= 15.0;
        }
        // Never open a new bin when a perfect or near-perfect fit exists elsewhere
        if fitting_bins_count > 0 && item_size % 25 == 0 {
            score += 10.0;
        }
    }

    // Late-stream tightening: waste matters more as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // Prefer filling fuller bins when many bins are open (bin consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / cap);
    score -= 3.0 * fill_ratio * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, ~12) is nearly unusable.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 * (12.0 - post_residual as f64) / 12.0;
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            // post residual cannot serve next item: penalize proportionally to waste
            if post_residual < next_item_size && post_residual > 0 {
                score += 0.3 * (post_residual as f64);
            }
        } else {
            // next item fits; penalize leftover after that hypothetical placement
            let left2 = post_residual - next_item_size;
            if left2 < 12 {
                score += 0.5 * (12.0 - left2 as f64);
            } else {
                score -= 5.0;
            }
        }
    }

    // Last chance: strongly prefer using the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default is mildly unattractive; only attractive when
    // current bin would leave a small dead gap and open bins are numerous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 8.0 + 0.1 * open_bins_count as f64;
        // If placing here creates unusable gap, new bin becomes relatively better.
        if post_residual > 0 && post_residual < 12 {
            nb -= 20.0;
        }
        // Early stream: be generous with opening bins.
        nb -= 6.0 * (1.0 - progress);
        score += nb;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins tighter than average (filling nearly-full bins first).
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match of post_residual with next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is a perfect two-item fill.
        if diff < 0.5 {
            score -= 40.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            // Next item fits: reward proportional to tightness of the pair.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot fit in the leftover: penalize dead space creation.
            score += 8.0 + 0.15 * (post_residual as f64);
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far above mean are "loose";
    // prefer filling tight bins unless the lookahead fits.
    let rel = post_residual as f64 - mean_residual;
    score += 0.05 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // (avoid opening a new bin), unless post_residual would be tiny dead space.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
        if post_residual < 10 && post_residual > 0 {
            score += 6.0; // but avoid stranding a sliver
        }
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., this call is the fresh bin with full residual).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slight penalty so we only open when open bins are bad.
        score += 10.0;
        // If lookahead is large, a fresh bin gives room for the pair.
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 5.0;
        }
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Prefer denser packing when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly
    // or well; penalize if post_residual is awkward relative to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0; // perfect chaining
        } else if post_residual > next_item_size {
            score -= 3.0 * (1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64));
        } else {
            // next item cannot fit here; slight penalty proportional to leftover
            score += 2.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Global state coupling: when mean residual is high, prefer filling bins
    // with large residuals (reduce fragmentation); when low, prefer tight fits.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Time horizon: early in the stream, be more conservative (favor new bins
    // for poor fits); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: score slightly above its raw post_residual unless
        // the fit in open bins would be terrible.
        score += 5.0 * (1.0 - progress);
        if item_size > 0 && (bin_capacity as f64 - item_size as f64) < 0.15 * bin_capacity as f64 {
            // item almost fills a fresh bin anyway; new bin is fine
            score -= 6.0;
        }
    } else if progress > 0.7 {
        score -= 4.0 * progress;
    }

    // Mild penalty for accumulating too many open bins when fit is loose.
    if open_bins_count > 4 && post_residual as f64 > 0.5 * bin_capacity as f64 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = post;

    // Smooth polynomial waste penalty: dead space squared, normalized.
    let waste_frac = post / cap;
    score += 6.0 * waste_frac * waste_frac * cap * 0.1;

    // Tightness reward: smooth coupling of fill ratio with stream progress.
    let fill = item / res.max(1.0);
    let tight = (1.0 - (1.0 - fill).powi(2)) * (1.0 + 1.5 * progress);
    score -= 8.0 * tight;

    // Last-chance bin bonus: smooth, stronger late in the stream.
    if fitting_bins_count == 1 {
        score -= 10.0 + 12.0 * progress;
    }

    // Lookahead coupling: reward leaving a residual that still fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            let slack = (post - nx) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - 0.5 * progress);
        } else {
            // Penalize blocking the next item, smoothly.
            score += 3.0 * ((nx - post) / cap).min(1.0);
        }
    }

    // New-bin candidate: must lose to any reasonable existing fit,
    // unless the item is huge relative to the mean residual (poor fit everywhere).
    let is_new_bin = (bin_residual as u64) == (bin_capacity as u64);
    if is_new_bin {
        let desperation = ((item - mean_residual) / cap).clamp(0.0, 1.0);
        score += 15.0 + 20.0 * (1.0 - desperation) + 5.0 * progress;
    } else {
        // Mild crowding preference: reuse existing bins, more so as stream progresses.
        score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- New-bin candidate: penalize opening a new bin unless nothing fits well ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: strong preference for using an existing bin.
        score += 60.0 + 0.5 * open_bins_count as f64;
        // If this is the ONLY fitting option (or fits nowhere else), opening is fine.
        if fitting_bins_count <= 1 {
            score -= 120.0;
        }
        // Late in the stream, avoid new bins even more (fewer chances to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // Big items: a fresh bin is natural.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // --- Harmonic class of post_residual: dead-space classification ---
    // Classes via integer division thresholds on post_residual.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual fraction

    // Perfect/near-perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Dead-space zone: residual too small for typical future items (1..=100 unknown dist,
    // but small residuals below ~15 are hard to fill) -> penalize.
    if post_residual > 10 && post_residual < 20 {
        score += 15.0;
    }

    // Harmonic class via modulo: residuals that are "round" fractions of capacity
    // (25, 33, 50, 66, 75) are reusable by harmonic-sized items -> reward.
    let harmonic_targets: [u32; 6] = [10, 20, 25, 30, 50, 75];
    for &t in harmonic_targets.iter() {
        if post_residual >= t && post_residual <= t + 3 {
            score -= 12.0;
        }
    }

    // Modulo-10 structure: residual divisible by 10 is more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack.min(30) as f64) * 0.3;
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting open bin, favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Tightness ratio: prefer bins where item fills a large share of residual.
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill;
    }

    // Prefer packing into bins below the mean residual (consolidate emptier bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference to spread across fewer bins late in stream.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (>= 1..=20) can use it well.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0; // small gap => large penalty
    }

    // Reward very tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect fill of residual: item exactly matches bin residual.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Last chance bonus: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fills the bin completely after placement.
        if post_residual - next_item_size == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next known item: dead space risk.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bins pressure: discourage spreading across many bins when pressure is high,
    // encourage using existing bins; when few bins open, new bins are cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (0.5 + progress);
    score += bin_pressure * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean in a "fillable" way:
    // bins with residual much larger than mean are good targets to consolidate.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.1;
    } else {
        score += (-dev) * 0.05;
    }

    // New-bin candidate control: an empty bin has huge residual; make it attractive
    // only when the item is large or no good existing fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Large items justify opening a new bin more readily.
        score -= (item_size as f64 / 100.0) * 20.0;
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 8.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        score += progress * 20.0;
    }

    // Mild penalty for leaving exactly mid-sized awkward gaps (25..=40) that
    // only mid-size items can fill: keep them but slightly discourage.
    if (25..=40).contains(&post_residual) {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: leave exactly enough room for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying smoothly with distance.
        score -= 60.0 * (1.0 - diff / 100.0).powi(3);
        // Extra bonus for the exact chain-fill (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that neither the next item nor a small item could use.
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / 100.0);
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward bins whose residual is already below the mean (tight bins get emptied first).
    score -= 15.0 * ((mean_residual - post_residual as f64) / bin_capacity as f64).max(-1.0).min(1.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Late in the stream, tighten packing further (less tolerance for slack).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New empty bin: only attractive when current bin would leave unusable waste.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize post_residual nonlinearly (dead space grows quadratically in cost).
    let pr = post_residual as f64;
    score += 0.012 * pr * pr / bin_capacity as f64;

    // Strong bonus for exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 7.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // reward; if post-residual is smaller than next item but nonzero, it's
    // likely dead space unless small enough to be acceptable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 6.0 * (1.0 - pr / bin_capacity as f64);
        } else if pr > 0 && pr < nxt {
            // residual too small for next item: dead space penalty scaled by gap
            score += 0.35 * (nxt - pr);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * (1.0 - pr / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have low mean residual (all quite full) or fit is very poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 25.0;
        // Cheaper to open a new bin early in the stream (more future items to pack)
        score -= 15.0 * (1.0 - progress);
        // If mean residual of open bins is small, new bin is relatively fine.
        score -= 0.08 * mean_residual;
        // If many bins are open with slack, discourage one more.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // If the item is large relative to capacity, a fresh bin gives a clean fit.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins that are already heavily loaded,
    // consolidated via bin_residual relative to capacity.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio;

    // Late in the stream, tighten up: avoid leaving mid-size holes that nothing can use.
    if progress > 0.7 {
        score += 0.02 * pr;
    }

    // Small tie-breaker: prefer bins with lower residual overall.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post_norm = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear emphasis
    let mut score = post + 40.0 * post_norm * post_norm;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; later, dead space becomes costly.
    let coupling = post_norm * (1.0 - post_norm) * (progress - 0.5);
    score += 120.0 * coupling * coupling * (progress - 0.5).signum();

    // Penalize bins whose residual drifts far below the mean residual
    // (fragmented bins), weighted by how much of the stream remains.
    let drift = mean_residual - post;
    if drift > 0.0 {
        score += 0.35 * drift * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly reward it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else {
        // Mild reward for having alternatives (keeps flexibility)
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: residual == capacity. Penalize unless no open bin fits
    // or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let load_factor = open_bins_count as f64 / (1.0 + progress * 10.0);
        score += 30.0 * scarcity + 5.0 * load_factor - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 and modulo 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Dead-space penalty: residuals that no typical item (>=1) can use well.
    // Small but nonzero residues are "almost full" bins -> good, reward them.
    if post_residual > 0 && post_residual <= 5 {
        score -= 12.0; // near-perfect fill
    }
    // Harmonic penalty: residuals in awkward classes (1..9 mod 10 that can't
    // host items of size 10 multiples) get penalized proportionally.
    if r10 != 0 && post_residual > 5 {
        score += (10 - r10) as f64 * 0.8;
    }
    // Quarter-capacity harmonic classes: post_residual near multiples of 25
    // are future-friendly (items often cluster around quarter capacities).
    let q = (post_residual as i32 - 25 * (post_residual as i32 / 25)).abs();
    score += q as f64 * 0.35;

    // Lookahead coupling: if the next item fits the post residual exactly or
    // harmonically, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let diff = post_residual - next_item_size;
            if diff % 10 == 0 {
                score -= 14.0; // harmonic continuation
            } else {
                score -= 6.0;
            }
        } else {
            // next item cannot follow here; penalize slightly more if this bin
            // would otherwise be a "greedy trap"
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fits are poor (high post residual spread).
    if bin_residual == bin_capacity {
        // Base preference for fresh bins when many open bins are fragmented.
        score = bin_capacity as f64 * 0.5 + mean_residual * 0.3;
        if post_residual <= 10 && fitting_bins_count >= 1 {
            score += 40.0; // discourage fresh bin when a tight fit exists
        }
        if open_bins_count == 0 {
            score -= 100.0; // must use a new bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild fragmentation penalty relative to mean residual: bins far below
    // the mean residual are already fragmented; using them for big items is bad.
    if (item_size as f64) > mean_residual {
        score += 50.0;
    }

    // Progress-aware tightness bonus: early on, keep bins balanced; later,
    // prefer tightest fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small to be
    // useful for typical future items are heavily penalized.
    let dead_threshold = 10.0f64; // smallest useful residual
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else {
        // Mildly reward small-but-usable residuals to prefer tight fits.
        score -= 2.0 * (1.0 - (post_residual as f64) / 100.0);
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0;
        } else if slack <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual can't hold the next item: mild penalty scaled by gap.
        score += 0.1 * (next_item_size - post_residual) as f64;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 20.0);
    score += 0.05 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate: an empty bin has residual == capacity. It should only
    // win when no open bin offers a decent fit. Penalize it so tight existing
    // fits beat opening a new bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if nothing fits except this candidate (fitting_bins_count == 1
        // refers only to open bins), the last-chance bonus above keeps open
        // bins preferred; relax the penalty slightly when bins are crowded.
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the new residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits too: mild reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * fill;
        } else {
            // Next item cannot fit here: penalize leaving a gap smaller than next item.
            let gap = post_residual as f64;
            if gap > 0.0 && (next_item_size as f64 - gap) <= 10.0 {
                score += 50.0; // near-miss dead space is costly
            }
        }
    }

    // Relative to mean residual: bins with more room than average are safer targets.
    score -= 2.0 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current bins are tight or item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (mean_residual < item_size as f64) as i32;
        let big_item = (item_size > 60) as i32;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score = 150.0 - 100.0 * (tight as f64) - 50.0 * (big_item as f64)
                - 30.0 * progress + 20.0 * pressure;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 60.0; // pair both items in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual), with non-linear sharpening.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Lookahead (k=2): reward bins whose post_residual can host the next item,
    // penalize post_residuals that are awkward dead space (too small for typical items).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 12.0; // chain placement possible
        } else {
            // Dead space: waste grows when post_residual is far below the next item.
            let dead = (nxt - post_residual as f64) / bin_capacity as f64;
            score += 25.0 * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is penalized unless the item
    // is large enough that existing bins would waste a lot, or the stream is early
    // and future flexibility is valuable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are cheap early (future flexibility), expensive late.
        let time_bonus = 25.0 * (1.0 - progress);
        // Penalize new bins when many alternatives already fit.
        let alt_penalty = 10.0 * (fitting_bins_count as f64);
        // Reward new bin for large items (poor fits elsewhere are costly).
        let large_item_reward = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += alt_penalty - time_bonus - large_item_reward;
        // Extra penalty if a fresh bin leaves large residual that likely becomes dead space.
        if post_residual < 20 {
            score -= 15.0; // near-perfect fit in a new bin is actually great
        }
    }

    // Global state coupling: if mean residual across open bins is high, we can afford
    // looser fits; if low, be greedy about tightness.
    let mr = mean_residual / bin_capacity as f64;
    score += 8.0 * (0.5 - mr) * fit_ratio * 10.0;

    // Slight preference to fill bins with higher residual when many bins are open
    // (consolidation pressure reduces bin sprawl).
    score -= 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // normalized post residual in [0,1)

    // Base: penalize wasted space quadratically (small residuals are dead space)
    let mut score = norm_pr * norm_pr * 100.0;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fills (low post residual); later, allow looser fits
    let tight_bias = (1.0 - progress) * (1.0 - progress);
    score += tight_bias * norm_pr * 60.0;

    // Interaction: post residual vs mean residual — prefer bins below mean residual
    // (filling the emptiest-ish bins first keeps larger residuals available)
    let mr_norm = mean_residual / cap;
    let coupling = (norm_pr - mr_norm) * (norm_pr - mr_norm);
    score += coupling * 40.0;

    // Smooth cubic interaction of progress with post residual:
    // late in stream, residual matters more (consolidate)
    score += progress * progress * progress * norm_pr * 80.0;

    // Lookahead: reward bins whose post residual can host the next item (smooth bump)
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_margin = (pr - next_item_size as f64) / cap;
        score -= (1.0 - fit_margin * fit_margin) * 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate: make it moderately attractive only when it enables a
    // perfect-ish future pairing; otherwise open bins should win.
    if bin_residual == bin_capacity {
        // smooth sigmoid-like gate on progress: new bins more acceptable late
        let gate = 1.0 / (1.0 + (-6.0 * (progress - 0.5)).exp());
        score = 45.0 + 30.0 * gate + item_size as f64 * 0.2;
        if next_item_size > 0 {
            // prefer new bin if item + next item pair well in a fresh bin
            let pair = (item_size + next_item_size) as f64;
            if pair <= cap {
                score -= (1.0 - (pair / cap)) * 30.0;
            } else {
                score += (pair - cap) * 0.5;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post-residual falls into
    // "small residue" classes are nearly wasted; penalize dead space nonlinearly.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Integer-division thresholds on post_residual (harmonic buckets of size 10)
    let post_class = post_residual / 10; // 0..10
    // Residues in classes 1..4 (11..49) are the least reusable for typical items.
    if post_class >= 1 && post_class <= 4 {
        score += 12.0 * post_f / cap_f;
    } else if post_class == 0 {
        // Perfect/near-perfect fill: strongly reward
        score -= 25.0;
    } else {
        // Large residues (50..100) remain highly reusable: mild reward
        score -= 4.0 * post_f / cap_f;
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward a residue class that exactly hosts the next item (tight chaining)
        if post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
        score -= 6.0 * (next_item_size as f64) / cap_f;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residue: penalize proportionally to dead space
        score += 5.0 * post_f / cap_f;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (large post_residual in a bad class).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it wins only when
    // existing bins have awful fits; slightly penalize when many bins are open
    // and mean residual is large (we should consolidate instead).
    if bin_residual == bin_capacity {
        score = cap_f - (item_size as f64);
        score += 8.0 * (mean_residual / cap_f).min(1.0);
        // Late in the stream, opening new bins is cheap to do early, costly late
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild consolidation pressure: prefer bins below mean residual (tighter bins)
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item are pure waste. Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Gaps below the lookahead item's needs are semi-dead if next item can't use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0 + 0.25 * post_residual as f64;
    }
    // Reward bins whose leftover exactly accommodates the next item (chained fit).
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; few open bins -> new empty bin is cheap.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate handling: empty bin starts at residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad existing fits are.
        score += 30.0;
        // If current bin would leave a large dead gap, opening fresh is better.
        let dead_gap = post_residual as f64;
        if dead_gap > 0.0 && dead_gap < 30.0 {
            score -= 22.0;
        }
        // Early in stream, opening bins is cheaper (room to consolidate later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If the mean residual across open bins is large, existing bins are
        // fragmented; a fresh bin can absorb future items cleanly.
        if mean_residual > 40.0 {
            score -= 8.0;
        }
    } else {
        // Existing bin: small bonus for keeping fragmentation low relative to mean.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * diff;
        // Strong reward for exact 2-step match.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // Dead space: next item cannot fit here; penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 0.1 * post_residual as f64;
    }

    // Tight fit reward relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with residual below mean (more filled bins first).
    score += 0.25 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: penalize unless current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 22.0; // opening a new bin may be better than creating dead space
        }
        if item_size >= 60 {
            score -= 10.0; // large items fit best in fresh bins
        }
    }

    // Early in stream: slightly discourage bin proliferation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tightness * tightness;

    // Penalize waste relative to the current item size: leaving gaps the
    // next item could use is bad only if the gap is awkwardly sized.
    let gap = post_residual as f64;
    let next_fits_gap = (next_item_size as f64) <= gap && next_item_size > 0;
    if next_item_size > 0 {
        if next_fits_gap {
            // Reward bins whose leftover exactly anticipates the next item.
            let slack = gap - next_item_size as f64;
            score -= 12.0 / (1.0 + slack);
        } else {
            // Gap too small for the next item: penalize proportionally to
            // how close it *almost* fits (dead-space risk).
            let miss = gap - next_item_size as f64;
            if miss < 10.0 {
                score += 8.0 * (1.0 - miss / 10.0);
            }
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item is large relative to capacity or fits are scarce.
    if bin_residual == bin_capacity {
        let load_ratio = (item_size as f64) / (bin_capacity as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening a new bin mildly; the base post_residual (=capacity
        // - item) already makes big items cheaper here.
        score -= 6.0 * load_ratio + 10.0 * scarcity - 5.0 * late;
    } else {
        // Encourage filling existing bins when many are open (bin-count pressure).
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score -= 2.0 * pressure * (1.0 - tightness);
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins),
    // leaving larger residuals spread across fewer bins.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Mild time-horizon modulation: early on, keep options open (avoid
    // extremely tight fits that strand space); late, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0 * tightness - progress * 4.0 * tightness;

    // Small deterministic tie-breaker favoring lower post residual exactly.
    score += 0.01 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    let dead = (post - mean_residual) / cap;
    score += 12.0 * dead * dead.abs();

    // Lookahead: reward leaving space for next item, penalize waste
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post as f64 >= nxt {
            score -= 15.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + progress);
    }

    // Mild penalty for proliferation of open bins
    score += open_bins_count as f64 * 0.15;

    // New-bin candidate: keep neutral-ish baseline, discourage early opening
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item (1..100 range, but typical min item known via
    // lookahead) are pure waste. Penalize them quadratically.
    let min_future = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual < min_future {
        score += 8.0 * (min_future - post_residual) as f64;
    } else {
        // Reward leaving a gap that exactly fits the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Reward tight fits (small relative post residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio;

    // Penalize creating tiny unusable slivers (0 < post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // placement is very efficient; makes new bins attractive for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - fit_ratio));

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: empty bin should only win when the current bin would
    // leave a bad dead-space gap or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        if post_residual < min_future && post_residual > 0 {
            // Opening fresh is fine for near-full placement in a new bin.
            score -= 4.0;
        } else {
            // Prefer reusing an existing bin when fit is decent.
            score += 14.0 * (1.0 - fit_ratio);
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (more full).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Default: make new bin slightly worse than a decent fit (post_residual < ~25 is decent).
        let mut new_bin_score = bin_capacity as f64 - 15.0;
        // If no open bin can fit the item, new bin is the only option -> strong preference.
        if fitting_bins_count == 0 {
            new_bin_score = -1000.0;
        } else {
            // If this bin is the last fitting bin and the fit would leave large dead space,
            // opening a fresh bin may be better.
            if fitting_bins_count == 1 && post_residual > 30 {
                new_bin_score -= 10.0;
            }
            // Late in the stream, avoid proliferating bins.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            if progress > 0.7 {
                new_bin_score += 25.0 * progress;
            }
            // Many open bins with slack: prefer reusing.
            if mean_residual > 40.0 && open_bins_count > 3 {
                new_bin_score += 15.0;
            }
        }
        return new_bin_score;
    }

    // --- Aggressive 2-step lookahead matching for open bins ---
    // Perfect fit: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Near-exact fit reward (small dead space is exponentially penalized otherwise).
        let dead = post_residual as f64;
        score += 0.02 * dead * dead;

        // Lookahead: does the next item fit exactly into the post-residual?
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0; // perfect chaining of two items
            } else if next_item_size < post_residual {
                // Next item fits, reward proportional to how tight the chained fit is.
                let chain_slack = (post_residual - next_item_size) as f64;
                score -= 100.0 - 0.5 * chain_slack;
            } else {
                // Next item cannot use the residual: residual is likely dead space,
                // penalize more if the gap is small-but-unusable.
                let gap = (next_item_size - post_residual) as f64;
                score += 0.3 * gap.min(30.0);
            }
        }

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }

        // Reward filling bins that are below-average residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }

        // Reward larger item placement into tighter bins (best-fit flavor).
        score -= 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins whose post_residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny slivers are nearly useless; slightly discourage? keep small
        score += 0.0;
    }
    if post_residual >= 10 {
        // post_residual >= 10 is reusable; reward proportionally to reusability
        score -= (post_residual as f64).ln() * 4.0;
    } else {
        // dead space below min item size: penalize
        score += 20.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // with multiple options, prefer filling bins that are already quite full
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
        // next item won't fit here; mildly penalize leaving awkward residuals
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 10.0 {
            score += 8.0; // near-miss residual is wasted
        }
    }

    // Global state: when many bins are open, consolidate rather than spread.
    let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.15 * congestion;

    // Mean-residual coupling: placing into a bin below mean residual tightens the spread.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream, allow spreading (favor new bins slightly);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_score = 55.0;
        // attractive late in stream? no: late => consolidate, so raise cost
        new_bin_score += 30.0 * progress;
        // attractive when many bins open with large mean residual (fragmentation) — actually then reuse is better, so raise cost
        new_bin_score += 0.2 * open_bins_count as f64;
        // if item is large and current open bins would be badly fragmented, opening may win
        let would_waste = bin_capacity.saturating_sub(item_size) as f64;
        new_bin_score -= 0.3 * would_waste;
        // if next item is large, a fresh bin gives flexibility
        if next_item_size >= 50 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: quadratic penalty on leftover space (dead space hurts super-linearly)
    let mut score = post_norm * post_norm * 100.0 + post_norm * 10.0;

    // Reward tight fits: subtract proportional to fill fraction, non-linearly
    let fill = 1.0 - post_norm;
    score -= fill * fill * 40.0;

    // Smooth stream-progress coupling: early on, prefer keeping residual flexible;
    // later, prefer aggressive tight packing.
    let flex_bonus = post_norm * (1.0 - progress) * 25.0;
    score += flex_bonus;
    score -= fill * progress * 15.0;

    // Lookahead coupling: reward residual that can still host the next item,
    // penalize residual that nearly-but-not-quite fits it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post as u32 >= next_item_size {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            let gap = (nxt - post) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // Many open bins with high mean residual: encourage consolidation
    let pressure = (open_bins_count as f64).ln1p() * (mean_residual / cap);
    score += pressure * 3.0;

    // New-bin candidate: penalize opening a bin unless the item is large
    // (smoothly) or no other bin fits well.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln1p();
        score += 30.0 + openness * 5.0 - fit_ratio * fit_ratio * 60.0 * (1.0 - progress * 0.5);
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality.
    // Residuals that are small multiples of common item sizes are reusable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, best outcome
    } else if pr <= 10 {
        30.0 // nearly useless sliver
    } else if pr % 10 == 0 {
        -25.0 // clean decade residual, highly reusable
    } else if pr % 5 == 0 {
        -12.0
    } else if pr >= 20 && pr <= 45 {
        -8.0 // usable mid-range residual
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainability reward, stronger for tighter chains
            let chain_tightness = next_item_size as f64 / pr as f64;
            score -= 15.0 + 20.0 * chain_tightness;
        } else {
            // post_residual cannot host next item -> dead space penalty scaled
            let waste = (pr - (next_item_size % (pr.max(1)))) as f64;
            score += 5.0 + 0.15 * waste;
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere (large post_residual penalty elsewhere)
    // or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of a fresh bin
        score += 45.0 - 20.0 * progress;
        if open_bins_count < 3 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
        // if next item is big, a fresh bin is valuable
        if next_item_size >= 70 {
            score -= 10.0;
        }
    } else {
        // penalize fragmenting bins that still have lots of space when many
        // bins are open (spread usage instead)
        if (bin_residual as f64) > mean_residual + 25.0 && open_bins_count > 4 {
            score += 8.0;
        }
    }

    // Integer-division threshold coupling on item class vs residual class
    let item_class = item_size / 20; // 0..4
    let resid_class = pr / 20;
    if item_class == resid_class && pr > 0 {
        score -= 6.0; // same magnitude class tends to chain well
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (1..100 stream) are nearly unusable -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < dead_threshold {
            score += 25.0; // would create fresh dead space for the next item
        }
    }

    // Fit tightness: reward filling a large fraction of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Prefer reusing an existing bin that is a "last chance" fit.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        // Opening a bin is acceptable when current bins fit poorly (low fill ratio signal).
        if fill_ratio <= 0.0 {
            // empty-bin call: fill_ratio is 0 by construction; neutralize slight bias
            score -= 10.0;
        }
        // Penalize opening new bins when mean residual across open bins is large.
        score += 0.6 * mean_residual;
        // Early in the stream, opening bins is cheaper; later, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    } else {
        // Reusing bins: reward being the only fitting bin (avoid opening a new bin).
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward bins whose post_residual is exactly 0
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size exactly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 900.0;
    }
    // Reward post_residual close to next_item_size (chained fit)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 400.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    }
    // Penalize post_residual just below next_item_size (near-miss dead space)
    else if next_item_size > 0 && post_residual > 0 {
        let miss = next_item_size as f64 - post_residual as f64;
        if miss > 0.0 && miss <= 10.0 {
            score += 250.0 * (1.0 - miss / 10.0);
        }
    }

    // Penalize small unusable residuals (< smallest plausible item) more than large ones
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Relative-to-mean coupling: prefer bins with residual above the mean (absorb into emptier bins),
    // penalize dipping far below mean residual creating outliers
    let mean_ref = if mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    let rel = post_residual as f64 - mean_ref;
    if rel > 0.0 {
        score -= 60.0 * (rel / bin_capacity as f64);
    } else {
        score += 60.0 * (-rel / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 350.0;
    }
    // When many bins fit, prefer the tightest fit naturally via post_residual, but add
    // mild penalty scaled by fitting count to break ties toward emptier bins
    else if fitting_bins_count > 1 {
        score += 15.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity && item_size <= bin_capacity {
        // Base new-bin score: slightly above a perfect fit but below mediocre fits
        score = bin_capacity as f64 * 0.35 + post_residual as f64;
        // Lookahead: if next item is large relative to current, opening fresh bin is safer
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 120.0;
        }
        // If many fitting bins exist, discourage opening a new bin
        if fitting_bins_count > 2 {
            score += 300.0;
        }
        // Late in stream, prefer consolidating into existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 200.0 * progress;
    }

    // Mild late-stream consolidation pressure
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: post residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item nests
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; mild penalty scaled by wasted potential
            score += 5.0;
        }
    } else {
        // Last item: prefer any bin that fits, strongly avoid opening a new bin.
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter ones (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 30.0;
        // Penalize more when many bins are open (fragmentation).
        score += 3.0 * (open_bins_count as f64).sqrt();
        // Early in stream: opening bins is fine; late: discourage strongly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        // If current item is large, new bin is more acceptable.
        score -= 0.15 * item_size as f64;
        // If mean residual of open bins is low (bins nearly full), new bin reasonable.
        score -= 0.2 * mean_residual;
        // If next item is large and won't fit anywhere anyway, new bin ok.
        if next_item_size > bin_residual.min(50) {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer filling bins whose residual deviates
    // from the mean in a way that reduces variance (consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer bins with smaller residual overall (fill fuller bins first),
    // modulated by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.1 * bin_residual as f64 * (0.5 + 0.5 * progress);

    // Small tie-breaker noise-free deterministic nudge toward earlier bins.
    score += 0.001 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nxt = next_item_size as f64;

    // Base: prefer filling bins tightly (small post_residual).
    let mut score = pr;

    // Non-linear coupling: tight fits (small pr) are rewarded super-linearly,
    // scaled by stream progress so late in the stream we squeeze even harder.
    let tightness = (1.0 - pr / cap).clamp(0.0, 1.0);
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Dead-space penalty: if the leftover space is too small for the lookahead
    // item, that residual is likely wasted. Penalize smoothly.
    if nxt > 0.0 && pr > 0.0 && pr < nxt {
        let waste = (nxt - pr) / cap;
        score += 30.0 * waste * waste * (1.0 - progress);
    }

    // Reward exact/near-exact fits (post_residual near zero) strongly.
    let exactness = (1.0 - pr / cap).clamp(0.0, 1.0);
    score -= 8.0 * exactness.powi(8);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (new-bin candidate would score ~ cap - item).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight penalty when this bin is far below the mean residual (very empty
    // open bin) unless it's the new-bin candidate itself.
    if bin_residual != bin_capacity {
        let dev = (mean_residual - pr) / cap;
        score += 5.0 * dev.max(0.0);
    } else {
        // New-bin candidate: neutral baseline with mild progress-dependent
        // reluctance so we only open new bins when fits are genuinely poor.
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class of post_residual modulo capacity fractions:
    // classify dead space into usable bands (>= next item, >= 50, >= 25, tiny).
    let pr = post_residual;
    let class: f64 = if next_item_size > 0 && pr >= next_item_size {
        0.0 // residual can host the lookahead item: very usable
    } else if pr >= 50 {
        1.0
    } else if pr >= 25 {
        2.0
    } else if pr == 0 {
        0.0
    } else {
        3.0 // tiny dead space
    };
    score += class * 30.0;

    // Reward residual that is an exact multiple of common small sizes
    // (harmonic divisibility: 10/20/25/50 leave reusable chunks).
    if pr > 0 && (pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0) {
        score -= 12.0;
    }

    // Penalize post_residual in awkward zone (1..10): unusable dust.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if pr > 0 && pr < 10 {
            score += 60.0; // but not if it creates dust
        }
    }

    // New-bin candidate: default moderately high score; open a new bin only
    // when all existing placements would waste a lot (score above threshold).
    if bin_residual == bin_capacity {
        score = 100.0 + mean_residual * 0.3 - (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // pairing large items into fresh bins helps
        }
    }

    // Late in the stream, tighten bins harder (less room to amortize waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / cap);

    // Slight preference for fuller bins relative to mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item can use
    // (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Gaps that are "almost full" are excellent: reward tight packing.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Penalize gaps in the awkward mid-range (11..=30) where few items fit,
    // scaled by how much slack the bin already had.
    if post_residual >= 10 && post_residual <= 30 {
        score += 6.0 - (post_residual as f64 - 10.0) * 0.15;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins below mean residual (they are the "worst" bins; fill them first),
    // keeping high-residual bins flexible for future items.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin is attractive only if no open bin
    // fits well, or the item is huge (little flexibility remains anyway).
    if bin_residual == bin_capacity {
        let huge_item = item_size > bin_capacity / 2;
        let poor_alternatives = fitting_bins_count == 0;
        if huge_item || poor_alternatives {
            score -= 12.0;
        } else {
            // Keep existing bins attractive vs. a fresh bin.
            score += 15.0;
        }
        // Lookahead: if next item is large, a fresh empty bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Placing into an open bin is worse if the next item could have used
        // this bin's post_residual better.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
        // Reward when post_residual can still fit the lookahead item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Late in the stream: prioritize closing bins out (minimize leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Reward dense packing: bigger items relative to capacity get a discount.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Lookahead coupling: penalize residuals the next item cannot use (dead space),
    // reward residuals that remain exploitable by the next item.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate penalty: opening a fresh bin is only worthwhile when all
    // existing placements would leave very poor fits. Slightly relax late in stream.
    if bin_residual == bin_capacity {
        score += 25.0 + item_size as f64 * 0.4 - progress * 10.0;
    }

    // Mild tie-break toward bins with residual below the mean (consolidating waste).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with a smooth non-linear (quadratic-ish) shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, compactness matters more
    score += 12.0 * progress * (pr / cap) * (pr / cap) * cap * 0.1;

    // Dead-space penalty: residuals too small for the smallest plausible item
    let dead = (cap * 0.2 - pr).max(0.0);
    score += dead * dead / (cap * 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 5.0 * (ni - pr) / cap;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packing)
    score += 0.3 * (mean_residual - bin_residual as f64).abs().sqrt();

    // New-bin candidate: penalize opening a new bin, more so early/mid stream,
    // unless the item is large relative to capacity
    if bin_residual == bin_capacity {
        score = cap as f64 * (1.2 + 0.8 * progress) - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo small integers
    // capture "useful" leftover sizes that pair well with common item sizes.
    let pr = post_residual;
    let r4 = (pr % 4) as f64;
    let r5 = (pr % 5) as f64;
    let r10 = (pr % 10) as f64;

    // Reward residuals whose harmonic classes align with typical item granularity.
    score -= 2.5 * (1.0 - r4 / 4.0);
    score -= 1.5 * (1.0 - r5 / 5.0);
    score -= 1.0 * (1.0 - r10 / 10.0);

    // Integer-division thresholds: small post residuals are dead space unless near zero.
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr < 10 {
        score += 8.0; // unusable sliver below minimum item size
    } else if pr <= 20 {
        score -= 6.0; // still useful for small items
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (next_item_size as f64) * 0.15; // chain placement enabled
            // harmonic bonus when next item exactly matches a class multiple
            if pr % next_item_size.max(1) == 0 && pr > 0 {
                score -= 4.0;
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or mean residual is too small relative to the item.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + step_index as f64);
        let pressure = (item_size as f64) - mean_residual;
        let mut newbin = 40.0; // baseline penalty: prefer reusing open bins
        newbin -= pressure.max(0.0) * 1.2;  // item doesn't fit typical residuals
        newbin -= congestion * 3.0;          // many bins per item seen => wasteful
        newbin -= (mean_residual / bin_capacity as f64) * 10.0; // low mean residual helps new bin
        score = newbin;
    }

    // Slight progression tilt: later in the stream, tighten packing more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.3;

    // Penalize bins far from mean residual (fragmentation of the fleet).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: heavily reward closing a bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead space: gaps too small for the minimum item size (1..10) are wasted.
    // Penalize unusable gaps strongly; small-but-usable gaps get graded pressure.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 25.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    // (penalize the new-bin candidate and discourage spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: baseline cost plus pressure from open bins and progress.
        score += 30.0 + open_bins_count as f64 * 4.0 + progress * 20.0;
        // But if the item is huge relative to typical residual, new bin may be reasonable.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    } else {
        // Existing bin: mild reward when many bins are open (consolidation).
        score -= open_bins_count.min(20) as f64 * 0.8;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to how well it uses the gap.
        score -= (next_item_size as f64 / post_residual as f64) * 10.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use the tiny gap we would create: extra dead-space penalty.
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Post-residual close to next_item_size: reward tight lookahead fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in leftover: penalize proportionally to waste.
        let gap = (next_item_size - post_residual) as f64;
        score += 40.0 * (gap / bin_capacity as f64);
    }

    // Reward small post-residual (tight packing) with a non-linear squash.
    let pr = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * pr * pr;

    // Compare against mean residual: bins already tighter than average get preference.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // unless the item is large and residuals are mostly too small.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        let scarcity = if open_bins_count > 0 { (fitting_bins_count as f64) / (open_bins_count as f64) } else { 1.0 };
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - avg_fit);
        let bonus = 120.0 * scarcity + 100.0 * pressure;
        score += 150.0 - bonus;
        // Empty-bin post-residual comparison with lookahead: opening is OK if next item fits well.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // Slight late-stream conservatism: prefer tightening existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
