pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * fit_norm * fit_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, penalize residual more aggressively
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * late * (pr / cap) * (pr / cap);

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins with residual much larger than mean (fragmentation signal)
    score += 0.05 * (pr - mean_residual).abs();

    // Lookahead: bonus if next item fits into post_residual (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for very many open bins (encourage consolidation)
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: keep it slightly unattractive unless current fit is bad
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * late * (1.0 - fit_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "compatible class" with the next item are rewarded.
    let post = post_residual;
    let next = next_item_size;

    if next > 0 && next <= post {
        // Next item fits exactly or nearly: strong reward scaled by tightness.
        let slack = (post - next) as f64;
        score -= 60.0 * (1.0 - slack / cap);
        if post == next {
            score -= 40.0; // perfect closure
        }
    } else if next > 0 {
        // Next item cannot use this bin's leftover; penalize dead space.
        score += 12.0;
    }

    // Integer-division thresholds on post_residual: classify leftover into
    // harmonic buckets of capacity/8.
    let bucket = post / 13; // 100/8 ~ 12.5
    score += match bucket {
        0 => -15.0,          // near-perfect fill
        1 => -8.0,
        2 => 0.0,
        3 => 5.0,
        4 => 9.0,
        5 => 12.0,
        6 => 14.0,
        _ => 16.0,           // large leftover, wasteful
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when the
    // current item is large relative to the mean residual landscape.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let pressure = mean_residual / cap;
        // Open new bin when item is big and existing residuals are small.
        score = 30.0 - 25.0 * item_frac + 20.0 * pressure;
        if next > 0 && (next as f64 / cap) > 0.7 {
            score -= 10.0; // big next item benefits from a fresh bin
        }
    }

    // Mild stream-progress coupling: later in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Perfect fit is extremely rewarded.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward leaving a gap that the lookahead item can still use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: mild penalty proportional to waste.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidation;
    // when few are open, opening a new bin is less costly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0 * (1.0 - progress * 0.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize slightly, but relax penalty under
        // low pressure or when this bin is the only fitting option elsewhere.
        score += 12.0 + pressure - (fitting_bins_count as f64) * 2.0;
        // Strongly discourage new bin if a near-perfect fit exists elsewhere
        // (approximated by low mean residual spread).
        if mean_residual < item_size as f64 * 0.6 {
            score += 20.0;
        }
    } else {
        // Existing bin: bonus when it is the last chance to fit.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Slight preference for bins below mean residual (balancing).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but avoid leaving
    // dead space that nothing useful can fill.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when next_item_size fits exactly
    // into the post_residual; penalize when next item can't use it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Next item fits: reward proximity to a perfect chain fit.
            let gap = pr - nxt;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            // Exact chain match is golden.
            if gap == 0.0 {
                score -= 40.0;
            }
        } else {
            // Dead space for the next item: penalize proportionally to
            // how unusable the leftover is.
            let dead = pr / nxt;
            score += 25.0 * dead;
        }
    }

    // Compare against mean residual: placing into a bin with residual far
    // from the mean can either consolidate or fragment; mildly prefer
    // bins below mean residual (tighter bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // item is large relative to capacity or no good chain fit exists.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; make it slightly unattractive early,
        // more acceptable late in the stream.
        score += 30.0 - 20.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity as f64 - item_size as f64) {
            // Fresh bin gives a clean full-capacity residual for the next item.
            score -= 10.0;
        }
    }

    // Slight preference for filling bins with larger residual when many
    // bins are open (consolidation pressure).
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Tiny tie-break toward exact fits.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic penalty on leftover space.
    score += 0.012 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the resulting residual,
    // reward strongly; if next item barely misses, penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            score -= 6.0 + 0.05 * nx;
            // Chain bonus: residual after hypothetically placing next item.
            let chain_left = pr - nx;
            score -= 4.0 * (1.0 - chain_left / bin_capacity as f64);
        } else if nx <= pr + 15 {
            score += 3.0;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many options, mild preference for fuller bins.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a bin is expensive unless the item
    // is large or no good fit exists. Base new-bin penalty.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 * (bin_capacity as f64 - mean_residual).max(0.0) / bin_capacity as f64;
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins more when many bins are open and time pressure is low.
        let new_bin_penalty = 20.0 + 8.0 * pressure + 10.0 * (1.0 - fill_ratio) - 6.0 * time_frac;
        score += new_bin_penalty;
        // Large items waste less in a fresh bin.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Global state: prefer using bins whose residual is far from the mean
    // (rebalance toward consolidating space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins that are already mostly full.
    let used_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * used_ratio;

    // Mild noise-free exploration term from stream position.
    let t = step_index as f64;
    score += 0.3 * (0.01 * t).sin() * (1.0 - used_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - (bin_residual as f64 / cap);

    // Base: prefer small post-residual, with a quadratic tightening
    let mut score = pr * (1.0 + 0.9 * fill * fill);

    // Smooth progress coupling: later in stream, penalize waste more strongly (super-linear)
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += prog_term * pr * 0.8;

    // Cubic dead-space penalty for tiny residuals (unusable slivers)
    let sliver = if pr <= 10.0 { (10.0 - pr).powi(3) / 100.0 } else { 0.0 };
    score += sliver;

    // Lookahead: reward if next item fits into post-residual (chained packing)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (1.0 - n / cap) * (1.0 + progress);
        } else {
            // next item won't fit here; penalize large leftover waste mildly
            score += 0.3 * pr * (n / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * (1.0 - pr / cap);
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins) when waste matters
    let mr = mean_residual;
    score += 0.25 * (pr - mr) * (0.5 + prog_term);

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: keep it neutral-to-slightly-high so it wins only when
    // open bins would leave large unusable residuals
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 0.4 * pr * (1.0 - prog_term)
            + if next_item_size > 0 && (next_item_size as f64) > cap * 0.5 { -8.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: prefer residuals in
    // "useful" classes for future items (items 1..=100, unknown distribution).
    let pr = post_residual as i64;

    // Dead-space penalty: very small residuals are nearly unusable.
    if pr > 0 && pr < 10 {
        score += 40.0;
    } else if pr == 0 {
        // Perfect fit: reward strongly.
        score -= 25.0;
    }

    // Modulo / harmonic class logic on post_residual (capacity = 100).
    // Residuals that are multiples of common size classes (10, 20, 25, 50)
    // are more likely to be filled exactly by future items.
    let harmonic_bonus = if pr > 0 {
        if pr % 10 == 0 { 12.0 }
        else if pr % 25 == 0 { 10.0 }
        else if pr % 5 == 0 { 6.0 }
        else { 0.0 }
    } else { 0.0 };
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if pr == ni {
            score -= 20.0;
        } else if pr > ni && pr - ni < 10 {
            // Next item fits but leaves near-dead space.
            score += 8.0;
        } else if pr >= ni {
            score -= 4.0;
        }
        // Harmonic match: next item size shares a divisor class with residual.
        if ni > 0 && pr % ni.max(1) == 0 && pr > 0 {
            score -= 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, penalize opening
    // a new bin by making this bin more attractive.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should
    // only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // If few bins fit the item, opening fresh space is more acceptable.
        if fitting_bins_count == 0 {
            score -= 70.0;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 30.0;
    } else {
        // Favor bins whose residual is close to the item (tight fits).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
        // Slight preference for bins below mean residual (consolidating space).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild penalty per open bin: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (1..=10) are pure waste; penalize heavily, worst near the middle.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    } else {
        // Small gaps that only fit tiny items are risky dead space.
        let gap = post_residual as f64;
        if gap < 20.0 {
            score += (20.0 - gap) * 1.5;
        }
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0; // gap remains usable for the next item
        } else if post_residual > 0 {
            score += 25.0; // gap cannot hold next item: dead space risk
        }
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // last-chance bin: strongly prefer using it
    }
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: prefer bins with residual below the mean
    // (concentrate waste in few bins).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // early in the stream with heavy load.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual < 10 && post_residual > 0;
        if bad_fit || (fitting_bins_count <= 1 && open_bins_count > 0) {
            score -= 45.0; // opening a new bin beats creating dead space
        } else {
            score += 35.0 + progress * 20.0; // prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // ideal: bin closes completely after next item
        } else if post_residual >= next_item_size {
            // Next item fits; reward tightness of the leftover after both items.
            let two_step_left = post_residual - next_item_size;
            score -= 25.0 * (1.0 - two_step_left as f64 / bin_capacity as f64);
            // Extra reward when residual is too small for typical items (effectively closed).
            if two_step_left < 10 {
                score -= 15.0;
            }
        } else {
            // Dead space: next item cannot use the leftover residual.
            score += 20.0 + 0.5 * post_residual as f64;
        }
    } else {
        // Last item: only tightness matters.
        score -= 10.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize bins far from the mean residual (prefer balanced / tight bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // More competing bins -> slightly higher penalty for waste (be picky).
    score += 0.05 * fitting_bins_count as f64 * (post_residual as f64 - mean_residual).max(0.0);

    // Brand-new empty bin candidate: discourage unless it's genuinely attractive.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
        // Allow new bin late in stream if lookahead suggests big future item.
        if next_item_size > item_size && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Early stream: slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is good, but a dead zone
    // that can't fit typical small items (<=10) is worthless.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * fit_quality * fit_quality * item_size as f64;

    // Penalize post-residuals that are small but unusable relative to
    // the next item's lookahead requirement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            // This bin remains usable for the lookahead item: reward.
            score -= 1.5 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space: can never fit the next item; penalize strongly.
            score += 3.0 * (1.0 - post_residual as f64 / nx);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 3.0 * (1.0 - t);
    }

    // Scarcity pressure: when few bins fit the item, favor using one.
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 2.0 * scarcity;
    }

    // Global state coupling: if mean residual is high (bins are loose),
    // prefer consolidating into existing bins; if low, new bins are cheap.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.35 * mean_gap;

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin decays over the stream (late items
        // justify new bins more readily since stream end is near).
        let horizon = 1.0 - t;
        score += 6.0 + 8.0 * horizon;
        // If no open bin fits at all (fitting_bins_count counts only this
        // empty candidate), opening is necessary: reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Opening a bin is attractive when the current item is large and
        // would leave an awkward residual in any partially-filled bin.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 5.0 * large_item * large_item;
        // If the next item is also large, a fresh bin pairs them well.
        if next_item_size >= 50 {
            score -= 2.0;
        }
    } else {
        // Mild preference for filling fuller bins first (best-fit flavor
        // with occupancy weighting).
        let occupancy = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 1.2 * occupancy;
    }

    // Late-stream urgency: near the end, waste less; squeeze existing bins.
    score -= 2.0 * t * fit_quality;

    // Small stabilizing coupling between open bins and mean residual:
    // many open bins with high mean residual => fragmentation, prefer
    // placements that reduce fragmentation (low post_residual).
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;          // normalized post residual
    let fit = item_size as f64 / cap;             // normalized item size

    // Smooth non-linear coupling: penalize large residuals more as stream progresses
    let progress_weight = progress * progress;
    score += 40.0 * progress_weight * pr * pr;

    // Reward tight fits (low post residual) with a smooth cubic reward
    score -= 30.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - pr) * fit;

    // Interaction between post residual and mean residual: prefer bins close to mean packing
    let mean_pr = mean_residual / cap;
    let coupling = (pr - mean_pr) * (pr - mean_pr);
    score += 12.0 * coupling * (1.0 - progress);

    // Lookahead: if next item fits in post residual, reward; smooth quadratic bonus
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 25.0 * gap * gap * (1.0 - pr);
        } else {
            score += 18.0 * (-gap) * (-gap);
        }
    }

    // Last-chance bonus: smooth exponential-like reward via polynomial approximation
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Penalize opening new bins when many bins are open and residual is large
    let open_factor = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        score += 20.0 * open_factor * (1.0 - progress * 0.5) + 10.0 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 1..100 -> residual classes mod 10
    let res_class = post_residual % 10;
    // Dead-space penalty: residuals in awkward classes (1..9 small remainders) are wasteful
    if post_residual > 0 && res_class != 0 {
        let awkward = match res_class {
            1..=3 => 3.0,
            4..=6 => 2.0,
            _ => 1.0,
        };
        // Smaller post_residual with awkward class is worse relative to its size
        score += awkward * (10.0 / (post_residual as f64 + 5.0)) * 4.0;
    }
    // Perfect fill is heavily rewarded
    if post_residual == 0 {
        score -= 40.0;
    }

    // Integer-division threshold: how many size-10 chunks fit in the remainder
    let chunks = post_residual / 10;
    if chunks == 0 && post_residual > 0 {
        score += 6.0; // remainder < 10, nearly dead space unless future tiny items
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how well the next item would fill the remainder
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fill;
            // Harmonic pair: post_residual % 10 == next_item_size % 10 suggests future compatibility
            if post_residual > 0 && next_item_size % 10 == post_residual % 10 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use the remainder: penalize proportionally to leftover waste
            score += 4.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline so it's only chosen when
    // all open bins score badly (high residual waste)
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins already open / early stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 20.0 + 10.0 * (1.0 - progress);
        // If no bin currently fits, new bin is necessary anyway
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Mean residual high -> open bins are fragmented, new bin fine
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Slight preference to fill bins with larger residual first (waste reduction)
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual nonlinearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Strict dead-space avoidance: mid-range unusable gaps are penalized.
    // A residual gap that no typical item can use (1..10) is wasted space.
    if post_residual >= 1 && post_residual < 10 {
        score += 20.0; // created a tiny dead gap -> bad
    }
    // Large leftover is also bad unless it can fit the lookahead item.
    if post_residual > 40 {
        score += 5.0;
        if (next_item_size as f64) <= post_residual as f64 && next_item_size > 0 {
            score -= 12.0; // gap is reusable by next item
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // penalize wasteful placement into a roomy bin.
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste * 30.0;

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: base cost so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Large items justify a fresh bin more than small ones.
        score -= (item_size as f64 / 100.0) * 20.0;
        // Late in the stream, avoid proliferating bins.
        score += progress * 15.0;
    }

    // Slight preference for bins below mean residual (filling emptier bins).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(2);

    // Reward perfect fit
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when next item matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-diff / 20.0).exp();
        // Penalize if next item cannot follow into this bin's residual
        if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Compare residual against mean residual: prefer bins with below-average residual (tighter bins)
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin only when lookahead suggests a better pairing with next item
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 15.0;
        }
        if post_residual < 20 {
            score -= 10.0;
        }
    }

    // Progress-based tightening: later in stream, be more conservative with residuals
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 10.0; // near-miss wastes future opportunity
        }
        // Perfect pairing: item + next item exactly fills the bin
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make it unattractive
    // unless the item fits nowhere well (large item, few fitting bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 45.0;
        // Large items relative to capacity benefit from fresh bins early on.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            penalty -= 30.0 * (item_size as f64 / bin_capacity as f64);
        }
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        penalty += 20.0 * progress;
        // Many open bins with slack mean we should use them instead.
        if mean_residual > item_size as f64 {
            penalty += 15.0;
        }
        score += penalty;
    }

    // Mild penalty for very full open bins compared to mean residual state:
    // prefer to drain bins that deviate from the mean to keep the pool balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with more residual among equally tight fits
    // (keeps large residual bins from lingering).
    score -= 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item / cap;
    let post_norm = post / cap;

    // Base: post residual (tighter fit -> lower score)
    let mut score = post;

    // Smooth quadratic coupling of post-residual with stream progress:
    // late in the stream, dead space is increasingly penalized.
    let progress_sq = progress * progress;
    score += 40.0 * progress_sq * post_norm * post_norm;

    // Reward tight fits (small post residual) more strongly as stream advances.
    score -= 30.0 * progress * (1.0 - post_norm) * (1.0 - post_norm);

    // Lookahead: penalize leaving residual that cannot fit the next item,
    // reward residual that can accommodate it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - post / cap) * (nxt / cap);
        } else {
            score += 6.0 * (1.0 - post / nxt.min(cap)) * progress;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist, but relax as stream progresses
    // or when the item fits poorly everywhere (post residual would be large anyway).
    if bin_residual == bin_capacity {
        let waste = 1.0 - fit_ratio;
        score += 35.0 * (1.0 - progress) * waste * waste;
        score += 10.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Mild penalty for scattering across many bins with large residuals.
    score += 0.5 * (mean_residual / cap) * (1.0 - post_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fill (0) is perfect,
    // tiny unusable slivers are the worst dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Dead-space penalty grows as residual becomes an unusable sliver.
        // Class boundaries via harmonic fractions of capacity.
        let pr = post_residual as f64;
        if pr < cap * 0.05 {
            score += 45.0; // sliver: almost certainly wasted
        } else if pr < cap * 0.10 {
            score += 25.0;
        } else if pr < cap * 0.20 {
            score += 8.0;
        } else if pr < cap * 0.35 {
            score -= 4.0;
        } else {
            score -= 10.0; // roomy leftover can host future items
        }

        // Modulo coupling: residuals matching common item-size residues
        // (multiples of 10 / 5) are more reusable.
        let m10 = post_residual % 10;
        if m10 == 0 {
            score -= 6.0;
        } else if m10 == 5 {
            score -= 2.0;
        } else {
            score += (m10 as f64) * 0.4;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < cap * 0.05 {
                score -= 12.0; // near-exact chain
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: leftover likely dead
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a neutral baseline.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad the
        // alternatives look and how crowded the open-bin pool is.
        score = cap * 0.5
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64) * 1.5
            + (mean_residual / cap) * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big item first favors fresh-bin packing
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        return score;
    }

    // Tight-fit reward: item fills most of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item (below the minimum item size) are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 {
        score += 50.0; // unusable sliver -> heavy penalty
    }

    // Tight fit reward: the smaller the post_residual, the better,
    // but with a non-linear bonus for near-perfect packing.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize mid-range dead space that is too small for large items
    // but wastes capacity (e.g. residual in [1..25] that won't fit a 30+ item).
    if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items
    // across bins; prefer consolidating into already-open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large post_residual waste avoided by fresh capacity) or late in stream
    // with large mean residual spread. Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_capacity - item_size) as f64;
        let spread_penalty = (mean_residual - fit_quality).abs();
        score += 60.0 + open_bins_count as f64 * 3.0 - spread_penalty * 0.5;

        // Lookahead: if the next item could use the leftover of this bin,
        // opening a new bin is less attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 25.0;
        }
    } else {
        // Lookahead synergy: reward placing item so that the next item
        // exactly fits the remaining residual.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 35.0;
            } else if next_item_size > post_residual {
                score += 8.0; // leftover won't serve next item
            }
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e. closer to being "finished"), to close bins out cleanly.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Perfect closure: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact 2-step lookahead match: bin + next item perfectly fills this bin.
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits: reward tighter leftover gaps (near-match bonus).
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + gap * 0.15);
        } else {
            // Next item cannot fit: residual risks becoming dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 + gap * 0.5;
            if post_residual < 15 {
                // Near-unusable sliver: extra penalty.
                score += 60.0;
            }
        }
    }

    // Prefer bins tighter than the mean residual; keep loose bins flexible for big items.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Mild bonus for the sole open bin that fits, discouraging needless new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Brand-new empty bin candidate: default penalty so it loses to decent fits.
    if bin_residual == bin_capacity {
        score += 250.0 - progress * 50.0;

        // Strong case: this item plus the next item would perfectly fill a fresh bin.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 700.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    }
    // Penalize leaving residual that almost-but-not-quite fits the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bonus: this is the only open bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer filling bins that are already relatively full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Global dispersion: if this bin's residual deviates strongly from the mean,
    // slightly discourage it (favor consolidation of similar residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0;

    // New-bin candidate handling: an empty bin is a fallback; make it mildly
    // attractive early (flexibility) but costly late or when good fits exist.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        score = 45.0 + 2.0 * open_pressure - 20.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pair fits comfortably in a fresh bin
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, but with diminishing returns (non-linear)
    let mut score = post.powf(1.35);

    // Tightness coupling: reward near-full fills more aggressively as stream progresses
    let tightness = 1.0 - (post / cap).powf(2.0);
    score -= 60.0 * tightness * (0.5 + progress);

    // Dead-space penalty: residuals too small for typical items are wasted
    let dead = if post_residual > 0 && post_residual < 10 { (10 - post_residual) as f64 } else { 0.0 };
    score += 25.0 * dead / cap;

    // Lookahead: if the next item could exactly fill this bin's post residual, strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-diff / 15.0).exp() * (1.0 + progress);
    }

    // Last chance: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: prefer reusing existing ones over opening new; scale with open count
    if bin_residual == bin_capacity {
        score += 45.0 + 8.0 * (open_bins_count as f64).powf(0.7);
    } else {
        score -= 5.0 * (1.0 + (open_bins_count as f64).powf(0.5));
    }

    // Mean residual coupling: bins deviating from mean residual are less attractive late
    score += 0.15 * (post - mean_residual).abs() * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify dead space into buckets ---
    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residual fragments that are hard to fill later.
    // Small fragments (1..=9) are nearly useless -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }
    // Medium fragments (10..=19): marginal, mild penalty.
    else if post_residual < 20 {
        score += 12.0;
    }
    // 20..=39: still useful for small items, neutral to slight bonus.
    else if post_residual < 40 {
        score -= 3.0;
    }
    // Large leftovers (>=40): very reusable, reward.
    else {
        score -= 15.0;
    }

    // --- Modulo arithmetic on capacity fractions ---
    // Bins whose residual lies on "harmonic" fractions of capacity pair well
    // with common item sizes (multiples of 10, quarters, thirds).
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let quarter = cap / 4.0;
    let third = cap / 3.0;
    let half = cap / 2.0;
    let tol = 1.0;

    if (post_f - half).abs() < tol {
        score -= 20.0; // half-full bin: maximal flexibility
    } else if (post_f - quarter).abs() < tol || (post_f - 3.0 * quarter).abs() < tol {
        score -= 10.0;
    } else if (post_f - third).abs() < tol || (post_f - 2.0 * third).abs() < tol {
        score -= 8.0;
    }

    // Integer-division threshold classes on post_residual (multiples of 10).
    let decile = post_residual / 10;
    score -= (decile as f64) * 2.0; // coarser alignment => slightly better reuse

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        // Perfect pairing: this bin's post_residual exactly hosts the next item.
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Next item fits into the leftover: strong reward proportional to fit quality.
        else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 60.0; // near-perfect chain
            } else {
                score -= 25.0 - slack * 0.3; // decaying reward
            }
        }
        // Next item does NOT fit here: if this placement creates tiny dead space,
        // penalize, since the chain breaks and fragment is wasted.
        else {
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 18.0; // agonizing near-miss
            }
        }
    } else {
        // Last item in stream: any residual is pure waste; prefer tightest fill.
        score += 5.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that can take the item; using it avoids a new bin.
        score -= 30.0;
    }

    // --- Contextual modulation ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Late in the stream, closing bins tightly matters more.
    score *= 1.0 + 0.15 * progress;

    // Spread pressure: many open bins -> prefer filling existing ones over new bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: if this bin is far below the mean residual it is
    // already "dense"; reward keeping dense bins dense.
    let dev = mean_residual - post_f;
    if dev > 0.0 {
        score -= dev * 0.1;
    } else {
        score += (-dev) * 0.05;
    }

    // --- New-bin candidate handling ---
    // An empty bin has post_residual == bin_capacity. It should only win when
    // no open bin offers a decent fit. Give it a middling score: worse than a
    // good fit, better than a wasteful tiny-fragment placement.
    if bin_residual == bin_capacity {
        score = 50.0 + 10.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Empty bin can always chain with the next item: mild discount.
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap below the minimum item size (1..10)
    // is nearly worthless; penalize it heavily so near-full fills win.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64 / 10.0;
    }
    // Perfect fill is gold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize moderately large dead space quadratically (wasted capacity).
    if post_residual >= 10 {
        score += 0.02 * (post_residual as f64).powi(2);
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening yet another.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (6.0 + 0.8 * open_bins_count as f64);

    // New-bin candidate should only win if the current fit is genuinely poor
    // (large post_residual). If fit is decent, make new bin unattractive.
    if new_bin && post_residual <= 20 {
        score += 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item fits within post residual, mild reward; otherwise mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is below average
    // (consolidate space into fewer bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early in stream, be slightly more willing to open bins to build a diverse pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= new_bin * 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits too, but with slack: mild reward proportional to tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: cannot fit next item. Penalize small unusable gaps harder.
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 20.0;
        } else {
            score += 8.0 * (gap / 40.0).min(1.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer filling it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin by default.
        score += 15.0;
        // But if the item fills the fresh bin nearly perfectly and current bins
        // would waste a lot, opening is reasonable: soften the penalty.
        let waste = (bin_capacity - item_size) as f64;
        if waste < 5.0 {
            score -= 40.0;
        } else if waste < 15.0 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight preference for bins that become exactly zero (perfect closure).
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post-residual is small.
    let fit_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a decisive bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that no plausible item (>=1) can use well:
    // small residuals (1..10) are actually valuable (likely fillable), mid residuals less so.
    if post_residual >= 1 && post_residual < 10 {
        score -= 8.0;
    } else if post_residual >= 40 && post_residual < 60 {
        score += 6.0; // awkward leftover zone
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let slack = post_residual as f64 - nx;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mildly penalize consuming space it could have used
            let gap = (next_item_size as u32).saturating_sub(post_residual);
            score += 0.05 * gap as f64;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, prefer it over opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when decent fits exist; scale with stream progress
        // and number of open bins (bin consolidation matters more later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 14.0 * progress + 0.6 * open_bins_count as f64;
        // But if the item is huge relative to mean residual space, opening may be wise:
        if (item_size as f64) > mean_residual * 0.95 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Lookahead: if next item is large and this bin would be nearly full, opening is fine
        if next_item_size >= 70 && post_residual < 30 {
            score -= 10.0;
        }
    }

    // Mild global pressure: when many bins are open, favor filling existing ones.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time-horizon term: early in the stream, be conservative (keep bins flexible);
    // later, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Mean-residual coupling: if average residual is high, prefer bins below the mean
    // (concentrate packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with a mild convex (quadratic) shaping
    // so mid-range residuals are penalized progressively more.
    let mut score = post + 40.0 * norm_post * norm_post;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, tight packing matters slightly less; late, dead space hurts more.
    let progress_coupling = 30.0 * norm_post * progress * (1.0 - progress) * 4.0;
    score += progress_coupling;

    // Interaction: post residual vs mean residual — placing into a bin whose
    // residual is far from the mean is penalized smoothly (quartic blend).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 + progress);

    // Lookahead: reward if next item fits the post residual (smooth cosine-like bump),
    // penalize if post residual is small but nonzero (fragmentation).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            let waste = (nxt - post) / cap;
            score += 10.0 * waste * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is good only when the item leaves a tight fit
        // (small post residual) or few bins fit the item elsewhere.
        let tightness = 1.0 - norm_post; // high when post residual small
        score = cap * 0.9 - 60.0 * tightness * tightness - 10.0 * (fitting_bins_count as f64).recip();
        // Late in the stream, slightly discourage proliferating bins.
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item granularities) are preferred.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Tight fit reward: nearly full bins are excellent placements.
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 5 {
        score -= 15.0;
    }

    // Penalize dead space: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 20.0; // dead-space penalty for tiny unusable slivers
    }

    // Lookahead coupling: reward if next item fits exactly or well in leftover.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect follow-up fit
        } else if next_item_size <= pr {
            score -= 8.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // leftover can't host next item: mild penalty scaled by wasted fraction
            score += ((next_item_size - pr) as f64 / cap) * 10.0;
        }
    }

    // Harmonic / modulo classes on post_residual
    let usable_class = (pr % 10 == 0) as i32 + (pr % 20 == 0) as i32 + (pr % 25 == 0) as i32 + (pr % 50 == 0) as i32;
    score -= usable_class as f64 * 4.0;

    // Integer-division thresholds: leftover that can hold "medium" chunks
    let q = pr / 30; // how many ~30-sized chunks still fit
    score -= q as f64 * 3.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make it unattractive unless current open bins
    // are all poor fits (high mean residual fragmentation or no fitting bins).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap + 10.0;
        // discount if the item fits poorly everywhere anyway
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // only one fitting bin: open new bin only if that fit is very tight already
            let tightness = item_size as f64 / bin_residual as f64;
            if tightness < 0.5 {
                score -= 25.0; // poor fit available, prefer fresh bin
            }
        }
        // late in stream, fewer bins is better; slightly discourage new bins early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    } else {
        // Prefer filling bins with larger relative occupancy
        score -= (item_size as f64 / cap) * 6.0;

        // Slight preference to spread across bins when many open bins have high residual
        if mean_residual > 0.5 * cap {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable dead space.
    // Penalize post_residual values that fall into the "dead zone" (0 < post < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Tight-but-usable residual: mildly reward.
        score -= 12.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 80.0;
    }

    // Coupling: residual utility depends on how much of the bin was consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            // Next item would create dead space here; penalize.
            score += 30.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 8.0 * open_pressure;
    } else {
        // New-bin candidate: only attractive when few open bins or this bin is
        // the last chance and the fit is poor.
        let last_chance = fitting_bins_count <= 1 && bin_residual != bin_capacity;
        let poor_fit = post_residual > 0 && post_residual < 10;
        if !(last_chance && poor_fit) {
            score += 15.0 + 10.0 * open_pressure;
        } else {
            score += 3.0;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is a
    // fragmented bin; prefer filling fragmented bins to consolidate.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.5 * dev;
    } else {
        score += 0.25 * (-dev);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: post_residual exactly matches next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * slack;
        } else {
            // Next item won't fit here; penalize wasted residual relative to next item
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 8.0 * waste.min(4.0);
        }
    } else {
        // Last item: prefer exact fill
        score -= 20.0 * tightness;
    }

    // Compare post_residual against mean residual: avoid creating outlier dead space
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // slightly reward below-mean residual
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless item is large / residual elsewhere is small
        let pressure = (item_size as f64 / bin_capacity as f64) * 20.0;
        let mean_pressure = mean_residual / bin_capacity as f64;
        score += 30.0 - pressure - 10.0 * (1.0 - mean_pressure);
    }

    // Mild reward for consolidating many open bins
    score -= 0.2 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer filling bins tightly (reward small post_residual more);
    // late in the stream, tolerate slack since bin count is nearly fixed.
    let tightness = (post / cap).powi(2);
    score += tightness * (1.0 - progress) * 40.0;
    score -= (post / cap) * progress * 10.0;

    // Dead-space penalty: residual too small to fit plausible future items.
    let dead = ((post - 10.0).max(0.0) / cap).powi(2);
    score += dead * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - post / cap);
    }

    // New-bin candidate: penalize opening a new bin smoothly, more when
    // other bins fit and mean residual is still usable.
    if bin_residual == bin_capacity {
        let usable = mean_residual / cap;
        score += 60.0 + 40.0 * (1.0 - progress) + 30.0 * (usable * (1.0 - usable) * 4.0).min(1.0);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0;
    }
    // If next item would leave this bin stranded, mild penalty.
    if next_item_size > 0 && (next_item_size as f64) > post && post < 10.0 {
        score += 8.0;
    }

    // Slight preference for bins with below-average residual (compact usage).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional class of post_residual relative to capacity.
    let post_frac = post / cap;

    // Harmonic class thresholds on post_residual (integer division buckets).
    let bucket = post_residual / 10; // 0..=10
    let bucket_penalty = match bucket {
        0 => -40.0,               // near-perfect fit: strongly favored
        1 => -25.0,               // excellent
        2 => -12.0,
        3 => -5.0,
        4 => 0.0,
        5 => 4.0,                 // half-empty: mildly bad
        6 => 8.0,
        7 => 12.0,
        8 => 16.0,
        9 => 20.0,
        _ => 0.0,                 // empty/new bin bucket handled below
    };
    score += bucket_penalty;

    // Modulo-3 class of post_residual: residuals divisible by 3 pair better
    // with typical item sizes; slight nudge.
    if post_residual % 3 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        if next_item_size == post_residual {
            score -= 25.0; // perfect chained fill
        }
        // next item leaves a small residue too
        let next_post = post_residual - next_item_size;
        if next_post <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits this bin now but not after placing current item:
        // mild penalty for blocking.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only good if current item is large relative
        // to capacity or existing residuals are all poor fits.
        // Penalize new bins moderately; tight fits in existing bins should win.
        score += 30.0;
        // Large items pack better fresh: reduce penalty for big items.
        let big = item_size as f64 / cap;
        if big > 0.7 {
            score -= 20.0 * (big - 0.7) / 0.3;
        }
        // If many bins are open with high mean residual, new bin is fine.
        if mean_residual > 0.5 * cap && open_bins_count > 3 {
            score -= 10.0;
        }
    }

    // Prefer filling nearly-full bins over sparse ones: compare against mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Early stream: be slightly more conservative (keep bins flexible).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.2 {
        score += 3.0 * post_frac;
    } else {
        // Late stream: squeeze hard, dead space matters more.
        score += 6.0 * post_frac;
    }

    // Tiny dead space is golden regardless of phase.
    if post_residual <= 5 && post_residual > 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it can't hold the next item (or the smallest plausible item).
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful {
        // Dead space: penalize proportionally to how much capacity is wasted.
        score += 25.0 + 0.5 * post_residual as f64;
    } else {
        // Reward tight fits (small but usable residual).
        score -= (min_useful as f64 - post_residual as f64).abs().min(5.0) * 0.5;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting the next item too (chained fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + progress);
    score += pressure * 0.5;

    // Penalize bins far from mean residual (avoid creating outliers).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is bad (large post_residual)
    // or dead space would be created; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0;
        if bad_fit {
            score -= 20.0; // opening fresh bin beats wasting space
        } else {
            score += 30.0 + open_bins_count as f64 * 2.0; // keep using open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), slightly superlinear.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Perfect match for next item -> strong bonus.
            score -= 40.0 * (-gap / 10.0).exp();
        } else {
            // Next item cannot fit here; mild penalty proportional to shortfall.
            score += 0.15 * (nxt - pr);
        }
    }

    // Relative-to-mean residual coupling: bins with residual near mean are
    // "typical"; extreme residuals (very full or very empty) are handled specially.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    score += 0.05 * dev.abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // But penalize if next item would be stranded badly.
        if next_item_size > 0 && post_residual < next_item_size as f64 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when item leaves huge dead space
        // in every open bin, or when many bins are already open and stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        // Default: discourage new bins.
        score += 30.0;
        // Encourage new bin if open bins would leave lots of unusable waste.
        score -= 0.5 * waste_elsewhere;
        // Early in stream with few bins, slightly cheaper to open.
        score -= 10.0 * (1.0 - progress) / (open_bins_count.max(1) as f64);
        // If item exactly fills half of new bin and next item matches, encourage.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Prefer consolidating into bins that are already quite full (fewer partly-filled bins).
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize creating dead space that is too small for typical future items:
    // a residual that cannot hold even a mid-size item is likely wasted.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted chain potential.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, greedily fill bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state coupling: when many bins are open with large mean residual,
    // discourage new-bin behavior implicitly by rewarding filling existing bins more.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * spread;

    // Slight preference for bins with residual close to item_size (perfect-ish fit).
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.1 * fit_gap;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Base penalty for opening a new bin.
        score += 25.0;
        // But if existing bins are very full or this is the only option, relax penalty.
        score -= 30.0 * pressure * mean_fullness;
        // Late in stream, opening fresh bins is fine for large items.
        if item_size > 60 {
            score -= 10.0 * progress;
        }
        // If next item is large and this item is small, a fresh bin keeps flexibility.
        if next_item_size > item_size && item_size < 30 {
            score -= 5.0;
        }
    }

    // Mild reward for using bins that are getting full (consolidation).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping
    let mut score = norm_pr + 0.9 * norm_pr * norm_pr + 0.6 * norm_pr.powi(3);

    // Smooth interaction of post-residual with stream progress:
    // later in the stream, waste is penalized more strongly
    score *= 1.0 + 0.8 * progress * (1.0 - progress + 0.25);

    // Dead-space penalty: residuals too small for typical future items
    let dead = ((25.0 - pr).max(0.0)) / cap;
    score += 1.5 * dead * dead;

    // Lookahead coupling: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let slack = ((pr - nx).max(0.0)) / cap;
        // reward if next item fits exactly-ish, mild penalty for large slack
        score -= 1.2 * fits_next * (1.0 - slack).max(0.0);
        score += 0.4 * slack * slack * fits_next;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate: penalize opening a bin unless current fits are bad
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).ln1p();
        score += 3.0 + 0.5 * crowded;
        // if many bins can fit, opening new is wasteful
        score += 0.3 * (fitting_bins_count as f64);
        // but late in stream with no good fits, allow it more readily
        score -= 2.0 * progress * (1.0 - (fitting_bins_count as f64).min(3.0) / 3.0);
    }

    // Mild preference toward fuller bins relative to mean residual
    score -= 0.15 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no future item (1..100)
    // can fill is worse than space that some class can still fill.
    let pr = post_residual;
    let usable = if pr == 0 {
        1.0
    } else if pr >= 50 {
        0.9
    } else if pr >= 34 {
        0.6
    } else if pr >= 26 {
        0.45
    } else if pr >= 20 {
        0.35
    } else if pr >= 10 {
        0.25
    } else {
        0.05
    };
    score -= usable * 60.0;

    // Modulo-10 harmonic bonus: residuals that are multiples of 10 are
    // classic "friendly" sizes for future items.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Penalty for tiny unusable slivers (dead space)
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 120.0;
        } else if gap < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item would NOT fit here, slightly penalize (chain break)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are very full
    // or the item simply does not leave a good residual anywhere.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 15.0 {
            score -= 25.0;
        } else {
            score += 30.0 + pressure * 2.0;
        }
        // Late in the stream, avoid spawning bins with small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 30 && progress > 0.5 {
            score += 20.0;
        }
    }

    // Prefer tighter bins overall: closeness of fit
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Mild preference to keep mean residual balanced
    if (bin_residual as f64 - mean_residual).abs() < 10.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (1..10) are heavily penalized.
    if post_residual >= 1 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < item_size {
        // Gap too small for even the current item class family: mild dead-space tax.
        score += 3.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 2.0;
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild pressure to prefer already-open bins over spawning new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with open bins and stream progress.
        score = bin_capacity as f64 * (1.0 + 0.02 * open_bins_count as f64 + 0.3 * progress);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 4.0; // fresh bin can host both current and next item
        }
    } else {
        score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    // Slight preference for bins with residuals near the mean (balance preservation).
    score += 0.02 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 300.0;
        } else if post_residual < next_item_size {
            // Dead space relative to the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable;
    // waste less on them. Prefer placing into looser-than-average bins when
    // the fit is poor, but tighten preference when fit is good.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 50.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 20.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize moderately so it is chosen only when no
    // open bin offers a decent fit (decent = small post_residual reward).
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if the item is huge relative to capacity and nothing chains,
        // the penalty stays; if next item is large, a fresh bin is useful.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 100.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (keeps
    // flexibility); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 80.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) with a non-linear penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residuals too small for the smallest item (1..100 range, min ~1).
    // Penalize residuals that are unlikely to be useful later (very small).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after this placement: mild reward, scaled by
            // how much slack would remain (prefer leaving versatile residuals).
            let rem = post_residual - next_item_size;
            score -= 10.0 - (rem as f64 / 100.0) * 5.0;
        } else {
            // Next item won't fit here: slight penalty proportional to overshoot.
            let over = next_item_size - post_residual;
            score += (over as f64).min(60.0) * 0.15;
        }
    }

    // Last-chance logic: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; make it attractive only when the item
        // is large or no good fits exist. Penalize opening bins when item is small
        // and other bins fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin.
        score += 40.0;
        // Large items justify new bins more.
        score -= item_frac * 35.0;
        // If existing fits are bad (post_residual large elsewhere is reflected in
        // comparison), a fresh bin with post_residual == capacity - item is clean.
        // Encourage when mean residual across open bins is high (bins fragmented).
        score -= (mean_residual / bin_capacity as f64).powi(2) * 10.0;
        // Late in the stream, avoid opening bins unless necessary.
        score += progress * 15.0;
        // If many bins open already, slight reluctance to add more.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into bins (penalize leaving bins untouched is not possible here,
    // but reward choosing bins with residual near mean to balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for bins with less residual overall (fill fuller bins first
    // keeps many mid-size residuals available).
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tighter fits (low post_residual) are strongly preferred; non-linear reward.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * cap * 0.01;

    // Dead-space penalty: residual that is too small for typical items is wasted.
    let dead_zone = ((post - 20.0) / cap).max(0.0).min(1.0);
    let unusable = if post > 0.0 && post < 20.0 { (20.0 - post) / 20.0 } else { 0.0 };
    score += 30.0 * unusable * unusable;
    let _ = dead_zone;

    // Perfect fit bonus (smooth).
    let perfect = 1.0 - (post / cap).abs();
    let near_perfect = (-((post as f64 - 0.0).powi(2)) / 25.0).exp();
    score -= 20.0 * near_perfect;
    let _ = perfect;

    // Lookahead: reward if next item fits the post residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (-slack * 8.0).exp();
        } else {
            score += 10.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Stream progress coupling: later in the stream, prefer packing tighter (lower post).
    score += 8.0 * progress * (post / cap);

    // Mean residual coupling: when mean residual is high (fragmentation), prefer bins below mean.
    score += 5.0 * (post - mean_residual) / cap;

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (post / cap);

    // New-bin candidate: post == item_size complement; make new bins attractive only when
    // post_residual is large (poor fits elsewhere) — naturally handled since post is large,
    // but add a slight opening cost that shrinks with progress.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;
    score -= tight;

    // Perfect fit extreme reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Harmonic classes: classify post_residual into modulo classes of 10.
    // Residuals in [1,9] are dead space for items >=10; residuals in classes
    // like 10-19, 20-29 etc. determine future usability.
    let cls = post_residual / 10; // integer division class
    match cls {
        0 => score += 40.0,               // unusable sliver
        1 => score += 15.0,               // only tiny items fit
        2 => score += 5.0,
        3 => score += 0.0,
        4 => score -= 5.0,
        _ => score -= 10.0,               // large residual, versatile
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 150.0;
        } else if gap < 10 {
            score -= 60.0;
        } else {
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a stranded medium residual.
        if post_residual >= 10 && post_residual < 30 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin when nothing fits or only poor fits exist.
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if post_residual >= 50 {
            // Only one fitting bin with big leftover: consider fresh bin.
            score -= 10.0 + mean_residual * 0.3;
        } else {
            // Default: discourage opening new bins when decent fits exist.
            score += 150.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Stream progression: early on, be more selective (penalize loose fits);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferating bins relative to mean residual.
    score += 0.05 * open_bins_count as f64;
    score -= 0.1 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small but nonzero are
    // nearly unusable "dead space" (items are >= 1, but practically small gaps
    // below ~15 rarely get filled). Penalize them super-linearly.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 4.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: extra dead-space penalty.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one;
    // the empty-bin candidate gets penalized so consolidation wins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 30.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits well (large dead space would result),
        // opening fresh is fine: reduce penalty.
        if post_residual == bin_capacity as f64 as u32 && item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Filling an existing bin reduces open-bin pressure slightly.
        score -= 0.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is above the mean
    // (they are "loose" bins; filling them preserves tight bins for big items).
    if bin_residual as f64 > mean_residual + 5.0 {
        score -= 3.0;
    } else if (bin_residual as f64) < mean_residual - 5.0 {
        score += 3.0;
    }

    // Late-stream consolidation: near the end, close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 0.15 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 30.0; // perfect 2-step match: bin becomes exactly full next step
        } else if post_residual as u32 >= next_item_size {
            // next item can also fit here; prefer leaving a good residual
            score -= (post_residual as f64 - next_item_size as f64) * 0.15;
        } else {
            // dead space: next item cannot use the leftover
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Penalize residuals that are hard to fill (small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward filling bins tightly relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can serve the lookahead item too
        }
    }

    // Late in stream: prefer closing bins out, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits into the post-residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let combo_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * (1.0 - combo_tightness);
        } else {
            // Next item cannot follow here: slight penalty, scaled by how close it was.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, unless the item is huge
    // relative to all residuals (then new bin is natural).
    if bin_residual == bin_capacity {
        let fit_pressure = item_size as f64 / mean_residual.max(1.0);
        if fitting_bins_count > 0 && fit_pressure < 0.9 {
            score += 35.0 * (1.0 - fit_pressure);
        }
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Slight preference for bins whose residual is below the mean (consolidating small ones).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Reward using bins that are already fairly full (small residual before placement).
    let pre_frac = bin_residual as f64 / bin_capacity as f64;
    score += 10.0 * pre_frac * pre_frac;

    // Mild bonus when many open bins exist (encourage closing them out).
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 + 1.5 * progress * progress);
    score += 40.0 * poly;

    // Reward tight fits, more aggressively later in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.6 + 0.8 * progress);

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: bonus if the next item can use the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack_fit = (post_residual - next_item_size) as f64 / cap;
            score -= 18.0 * (1.0 - slack_fit) * (1.0 + 0.5 * progress);
        } else {
            // Dead space risk: post residual too small for next item.
            score += 12.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Penalize opening a new bin when other bins fit, scaled by stream progress.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 35.0 + 45.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Slight penalty for deviating from mean residual (balance load).
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // --- Harmonic class logic on post_residual (integer division thresholds) ---
    // Exact fit is golden.
    if pr == 0 {
        score -= 50.0;
    } else {
        // Class post_residual into deciles of capacity; small leftovers are
        // valuable only if usable, large leftovers are wasteful but flexible.
        let class = (pr * 10 / bin_capacity.max(1)) as i64; // 0..10 harmonic class
        score += match class {
            0 => -12.0, // 0-10% left: near-perfect fill
            1 => -6.0,  // 10-20%: good fill
            2 => -1.0,
            3 => 2.0,
            4 => 4.0,
            5 => 5.0,
            6 => 5.0,
            7 => 4.0,
            8 => 3.0,
            _ => 2.0,   // nearly empty bin: little value gained
        };
    }

    // Dead-space penalty: leftover that likely cannot serve future items.
    if pr > 0 && next_item_size > 0 && (pr as u32) < next_item_size {
        score += 6.0 * (1.0 - pr as f64 / cap);
    }
    // Lookahead bonus: next item fits into the leftover.
    if next_item_size > 0 && pr >= next_item_size && pr > 0 {
        score -= 8.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; discourage unless it is the only option.
        score += 28.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        } else if fitting_bins_count == 1 {
            // Only one open bin fits: compare against that bin's quality.
            // If that fit would be very tight (post_residual small), opening
            // a fresh bin may still be worse; keep penalty high.
            score += 6.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 22.0;
    }

    // Prefer bins whose residual matches the item closely (tight coupling).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.06;

    // Mean-residual coupling: if this bin is much roomier than average,
    // deprioritize it (save roomy bins for big items).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / cap;
        let mrel = mean_residual / cap;
        score += (rel - mrel) * 10.0;
    }

    // Stream progression: pack tighter as the stream advances.
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score -= prog * 6.0 * (1.0 - pr as f64 / cap);

    // Congestion: many open bins -> favor consolidating into existing ones.
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count.min(20) as f64) * (1.0 - pr as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are nearly worthless, so penalize them disproportionately.
    let min_item = 1u32;
    let dead_threshold = next_item_size.max(min_item);
    if post_residual < dead_threshold {
        // Dead space that cannot fit the next item: quadratic penalty scaled
        // by how close it is to being truly wasted.
        let waste_ratio = 1.0 - (post_residual as f64 / dead_threshold.max(1) as f64);
        score += 40.0 + 60.0 * waste_ratio * waste_ratio;
    } else {
        // Reward residuals that remain usable for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
            // Perfect chain fit: item + next item exactly fills the bin.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        }
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).sqrt() * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: placing into a bin with above-average residual
    // is more valuable (balances the fleet of open bins).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin is a fallback. Prefer it only
    // when every open bin would leave severe dead space or item is huge.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (next_item_size > 0 && item_size + next_item_size > bin_capacity
                && fitting_bins_count <= 1);
        if poor_fit_elsewhere {
            score -= 45.0; // open a new bin
        } else {
            score += 55.0; // prefer reusing an open bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    if bin_residual < bin_capacity {
        // Existing bin candidate.
        if next_item_size > 0 {
            // Perfect 2-step match: post_residual exactly fits next item.
            if post_residual == next_item_size {
                score -= 60.0;
            } else if post_residual >= next_item_size {
                // Next item can still fit here afterwards.
                let leftover = post_residual - next_item_size;
                score -= 25.0 - 0.3 * leftover as f64;
                if leftover == 0 {
                    score -= 30.0;
                }
            } else {
                // Next item won't fit here; penalize proportionally to gap.
                let gap = (next_item_size - post_residual) as f64;
                score += 0.4 * gap;
            }
        }

        // Reward using bins that are already fairly full (waste little).
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;

        // Last-chance bin: strong bonus to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Compare against mean residual: prefer bins with residual near mean
        // (keeps residual distribution balanced) but reward tighter-than-mean fits.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 0.1 * (post_residual as f64 - mean_residual);
        }

        // Penalize creating tiny unusable residuals (< 10, min item size).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // Early in stream: slightly prefer filling existing bins to limit bin count.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    } else {
        // New empty bin candidate: only attractive when no good existing fit exists.
        score = bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        } else if fitting_bins_count == 1 {
            score += 10.0; // mild preference to keep last-chance bin usable
        } else {
            score += 40.0; // prefer existing bins when several fit
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.1 * next_item_size as f64;
        }
        // Late in stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect/near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.2 * next_item_size as f64;
        } else {
            // Dead space relative to next item: penalize unusable gap size.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 0.4 * gap;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Fragmentation pressure: when many bins are open with high mean residual,
    // encourage consolidating into fuller bins (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = (open_bins_count as f64 / 20.0).min(1.0) * (mean_residual / bin_capacity as f64).min(1.0);
    score += consolidation * 6.0 * (1.0 - progress);

    // Late in the stream: be greedier about filling bins tightly to avoid
    // opening new bins for few remaining items.
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: default neutral-ish; open a new bin only when it
    // beats all existing fits. Penalize new bins early (waste of capacity),
    // and when the current item is small (large item deserves fresh space).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - progress) - 20.0 * item_frac * progress;
        // If no existing bin fits, this call is the only option anyway;
        // fitting_bins_count includes only open bins, so keep it competitive
        // but not automatically winning when a tight fit exists.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Big items benefit from fresh bins to avoid stranding residual space.
        if item_size >= 50 {
            score -= 8.0;
        }
    }

    // Slight preference for bins whose residual is "awkward" (hard to fill later).
    let r = post_residual as f64;
    if r > 0.0 && r < 20.0 {
        // small awkward gaps: mildly penalize leaving them, unless item exactly fills
        score += 0.15 * (20.0 - r);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;

    // Base: normalized post-residual (tight packing preferred)
    let mut score = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (penalize waste quadratically)
    let prn = pr / cap;
    score += 0.8 * prn * prn * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Reward last-chance bins (avoid opening a new bin when only one fits)
    if fitting_bins_count == 1 {
        score -= 1.5;
    } else {
        // mild penalty scaling with number of fitting alternatives
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.6 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);
        } else {
            // post-residual unusable by next item: penalize smoothly
            score += 0.4 * (pr / cap) * (pr / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin, more so early/mid stream
    if bin_residual == bin_capacity {
        score += 1.2 + 0.8 * (1.0 - progress);
        // but if no existing bin fits, opening is fine
        if fitting_bins_count == 0 {
            score -= 2.0;
        }
    }

    // Slight reward for bins that are already partially filled (use them up)
    score -= 0.1 * (1.0 - res / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: harmonic classes of post_residual.
    // Post-residuals that are multiples of small harmonic classes (<=20) are
    // still reusable by typical small items; larger dead space is penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit is always best
    } else {
        // Harmonic class: how many "typical" item sizes could still fit.
        let class = match pr {
            0..=10 => 5,
            11..=20 => 4,
            21..=35 => 3,
            36..=50 => 2,
            _ => 1,
        };
        score -= 8.0 * class as f64;

        // Modulo arithmetic on capacity fractions: bins whose residual sits
        // near a capacity fraction (25/50/75) are easier to pair with.
        let frac = (pr as f64) / (bin_capacity as f64);
        let frac_pen = (frac - (frac * 4.0).round() / 4.0).abs();
        score += 30.0 * frac_pen;
    }

    // Lookahead: reward bins that leave room for the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0); // exact match best
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Reduce penalty late in stream or when bins are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * progress;
        if mean_residual < 20.0 {
            score -= 30.0; // open bins nearly full; new bin reasonable
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open
        }
    }

    // Mild preference to fill already-open bins to reduce bin count.
    if bin_residual < bin_capacity {
        score -= 5.0 + 0.05 * open_bins_count as f64;
    }

    // Small tie-break toward fuller bins (smaller residual).
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post_residual that is too small to be useful later
    // (items are >= 1, but small gaps < 10 are near-unusable given typical sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // next item cannot use the leftover gap: penalize proportional dead space
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Penalize the fresh bin mildly so it is chosen
    // only when open bins score badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, fewer open bins => new bin less wasteful.
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Open-bins pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that nothing can use (items >= 1).
        // Dead space smaller than the minimum item size is pure waste.
        if post_residual < 1 {
            score += 500.0;
        }
        // Sharp penalty for leaving very small unusable gaps.
        if post_residual <= 3 {
            score += 150.0 * (4.0 - post_residual as f64);
        }
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Reward leaving room for the next item, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer tight fits relative to current bin residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 80.0 * tightness;

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // unless this is the last fitting bin.
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score += 12.0 * (resid_f - mean_residual) / bin_capacity as f64;
    } else {
        score -= 12.0 * (mean_residual - resid_f) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the lookahead suggests a better future packing.
    if bin_residual == bin_capacity {
        score += 300.0;
        // Allow new bin if lookahead item is huge and nothing fits well.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 350.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * (1.0 - progress);
    }

    // Mild penalty per open bin to consolidate packing.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1).
    if post_residual > 0 && post_residual < 5 {
        score += 15.0; // tiny slivers are nearly useless
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    // (chaining placements in the same bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for leaving mid-range gaps.
        score += 0.02 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin starts at full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing residuals are large relative
        // to the item (poor fits everywhere) or when many bins are already open.
        let avg_fit_gap = mean_residual - item_size as f64;
        if avg_fit_gap > 20.0 {
            score -= 10.0 + 0.2 * avg_fit_gap;
        } else {
            // Default: prefer filling existing bins; penalize new bin mildly.
            score += 20.0;
        }
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Reward bins whose residual is close to the item (best-fit flavor),
        // scaled by how "scarce" fitting bins are.
        let tightness = (bin_residual - item_size) as f64;
        score += 0.05 * tightness;
        if fitting_bins_count > 3 {
            score += 3.0; // many options: be pickier, prefer tightest
        }
    }

    // Global state coupling: when mean residual across open bins is low,
    // existing bins are nearly full — favor any existing bin that fits.
    if bin_residual != bin_capacity && mean_residual < 15.0 {
        score -= 5.0;
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: dead space penalized more as stream progresses
    let dead_weight = 0.5 + 1.5 * progress * progress;
    score += dead_weight * norm_pr * norm_pr * cap;

    // Reward tight fits, amplified late in the stream
    let fill_ratio = item_size as f64 / cap;
    score -= 4.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate: prefer it only when post_residual would be highly usable
    if bin_residual == bin_capacity {
        let usable = (norm_pr * (1.0 - progress)).powi(2);
        score -= 6.0 * usable;
        score += 1.0;
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 1.5 * (gap / cap);
        } else {
            score += 0.5 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Mild dispersion penalty relative to mean residual
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Slight pressure against bin proliferation early on
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual ---
    // Residuals are bucketed by integer division into "usable" bands.
    // Band 0: post_residual < 10  -> near-dead space, heavily penalized.
    // Band 1: 10..25              -> only fits the smallest items, penalized.
    // Band 2: 25..50              -> moderately useful.
    // Band 3: >=50                -> highly reusable, reward.
    let band = post_residual / 25;
    let dead = (post_residual < 10) as u32;
    score += dead as f64 * 40.0;
    match band {
        0 => score += 8.0,          // tiny leftover, wasted
        1 => score += 3.0,          // marginal utility
        2 => score -= 2.0,          // good reusable space
        _ => score -= 5.0,          // large leftover, very reusable
    }

    // Harmonic (modulo) coupling: reward when post_residual and the next item
    // fall into compatible classes (next item divides into leftover cleanly).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect lookahead fit
        } else if next_item_size <= post_residual {
            // compatibility via integer-division quotient
            let q = post_residual / next_item_size;
            score -= 4.0 * q as f64;
            // modulo class match: leftover after hypothetically placing next item
            let r2 = post_residual % next_item_size;
            score += (r2 < 10) as u32 as f64 * 6.0;
        } else {
            // next item cannot use this residual; residual class wasted for k=2
            score += 2.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is usually worse than using an existing one;
        // penalize, but less when the item is huge and fit is scarce.
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let big_item = (item_size >= 70) as u32 as f64;
        let penalty = 30.0 - 12.0 * big_item - 15.0 * scarcity;
        // If post_residual is tiny (item ~ capacity), a fresh bin wastes little.
        let waste = (post_residual < 15) as u32 as f64 * 10.0;
        score += (penalty - waste).max(-5.0);
    } else {
        // Last-chance bonus: if this is the only bin that fits, avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Progress-adaptive tightness: as the stream advances, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Mild pressure to fill fuller bins when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Pull toward the mean residual: bins deviating far below mean are precious.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small unusable gaps are the worst outcome.
        // Anything <= 10 can never hold another item (min item size 1 assumed small,
        // but tiny gaps relative to mean item size are waste).
        if post_residual < 10 {
            score += 250.0; // unusable sliver: heavily penalize
        } else if post_residual <= 15 {
            score += 90.0;
        } else if post_residual <= 25 {
            score += 35.0;
        }

        // Reward residuals that can still fit the lookahead item (k=2 lookahead)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
            // Extra reward if post_residual is a snug fit for the next item
            let snug = (post_residual as f64 - next_item_size as f64).abs();
            if snug <= 5.0 {
                score -= 25.0;
            }
        } else if next_item_size > 0 && post_residual > 0 {
            // post_residual cannot hold the next item: mild penalty
            score += 15.0;
        }

        // Reward tightness of the current placement relative to item size
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 40.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; favor filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 2.0 * progress);
    score += pressure * 0.8;

    // Mean-residual coupling: if this bin's residual is far below mean, it is a laggard bin — prefer filling it
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.6 * (mean_residual - residual_f);
    } else {
        score += 0.3 * (residual_f - mean_residual);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    // Empty bin has full residual; make it moderately costly so it is chosen
    // only when open bins would create large dead space or none fit.
    if bin_residual == bin_capacity {
        let base = 120.0;
        // cheaper to open a new bin when open-bin count is low (early stream)
        let discount = 60.0 * (1.0 - progress);
        // expensive when many bins already open and item is small
        let small_item_penalty = if item_size <= 30 { 80.0 } else { 0.0 };
        score = base + pressure * 1.5 - discount + small_item_penalty;
        // if the previous item would leave a sliver in an existing bin, opening is fine
        if fitting_bins_count >= 1 && post_residual == bin_capacity {
            score += 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: next item exactly fills remaining space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Partial lookahead reward: next item fits tightly after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * tightness;
    }
    // Penalize creating dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0 + post_residual as f64 * 0.05;
    }

    // Best-fit bias relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it costly unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin if this item is huge and would leave awkward residue anyway.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual is already the base; amplify it).
    score *= 1.0 + (item_size as f64 / bin_capacity as f64);

    // Penalize leaving dead space that likely cannot be reused.
    if post_residual > 0 {
        let waste_risk = (post_residual as f64 / 100.0).powi(2);
        score += 20.0 * waste_risk;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for fragmenting.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins whose residual deviates below the mean (fill fuller bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative about opening bins;
    // late in the stream, allow new bins since leftovers matter less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: penalize opening a new bin, more so early on,
    // but relax the penalty if this bin is a last resort or the fit is bad elsewhere.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            new_bin_penalty *= 0.3;
        }
        // If the item is large relative to capacity, packing it fresh is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            new_bin_penalty *= 0.5;
        }
        score += new_bin_penalty;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.1 * open_bins_count as f64 * progress;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);

    let mut score = post;

    // Tightness: reward small post_residual non-linearly (waste minimization).
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Relative fill ratio of the bin after placement: reward fuller bins.
    let fill = (resid / cap).clamp(0.0, 1.0);
    score -= 6.0 * fill * fill * (1.0 - fill);

    // Dead-space penalty: post_residual too small for the smallest plausible item
    // (smooth soft threshold around 10-12 units).
    let dead = ((12.0 - post) / 12.0).clamp(0.0, 1.0);
    score += 9.0 * dead * dead;

    // Last-chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0;
    } else {
        // Mild dispersion penalty: many fitting bins -> prefer the best-fitting one anyway.
        score += 0.4 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        let fit_next = (1.0 - (gap.abs() / cap)).clamp(0.0, 1.0);
        if gap >= 0.0 {
            score -= 7.0 * fit_next * fit_next;
        } else {
            // Post residual slightly below next item: small penalty scaled by shortfall.
            score += 4.0 * ((-gap) / cap).clamp(0.0, 1.0);
        }
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (consolidate emptier space).
    let dev = (mean_residual - post) / cap;
    score += 3.0 * dev * dev - 1.5 * dev;

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well.
    let is_new_bin = (bin_residual as u32 == bin_capacity) && (item_size <= bin_capacity);
    if is_new_bin {
        // Base cost of a new bin grows with stream progress (fewer chances to reuse it).
        score += 22.0 + 10.0 * progress + 0.5 * (open_bins_count as f64);
        // Allow new bin if current item is large relative to capacity (poor fit elsewhere).
        score -= 12.0 * (item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item-size divisors.
    // Residuals in {0} are perfect; small residues (1..10) are dead space; residues
    // matching typical item sizes (10,20,25,50) are reusable "harmonic" slots.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score += 25.0; // tiny dead space, unusable
    } else {
        // Reusability bonus: residual divisible by common class sizes
        for &cls in &[10u32, 20, 25, 50] {
            if pr % cls == 0 {
                score -= 8.0 + (pr / cls) as f64 * 3.0;
                break;
            }
        }
        // Harmonic penalty: prime-ish / awkward residues
        if pr % 10 != 0 && pr % 5 != 0 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= 18.0 - gap as f64;
            } else {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's remainder; residual value drops
            score += 4.0;
            if pr < 10 {
                score += 10.0; // stranded residue
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it is only
    // chosen when all open bins score poorly (large waste / stranded residue).
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for tighter (fuller) bins overall.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Tie-break toward bins below mean residual (keeps large residuals available).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here: chain reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 + 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            let dead = post_residual as f64;
            score += 30.0 + 20.0 * (dead / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize new-bin candidate unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred when reasonable.
        score += 200.0;
        // But if many bins fit the item, opening a new bin is even less attractive.
        score += 15.0 * fitting_bins_count as f64;
        // If the item is large relative to mean residual, opening a fresh bin
        // may be better: reduce penalty.
        let tight = mean_residual / bin_capacity as f64;
        if (item_size as f64) > tight + 0.25 * bin_capacity as f64 {
            score -= 90.0;
        }
    }

    // Slight preference for bins tighter than the mean (fill fuller bins first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progression (dynamic time horizon).
    let t = step_index as f64 / (total_items.max(1) as f64);

    let is_new_bin = bin_residual == bin_capacity;

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            // Reward bins that can also host the next item;
            // stronger reward when the next item is large (scarce capacity).
            score -= 6.0 + 5.0 * (nxt / cap);
        } else if post_residual < 10 {
            // Small dead space is nearly unusable: mild penalty.
            score += 2.0;
        }
    }

    // ---- Progressive fill pressure ----
    // Favor bins that are already heavily loaded; pressure grows over the stream.
    score -= (bin_capacity - post_residual) as f64 * 0.05 * (0.5 + t);

    // ---- Mean-residual global context ----
    // If this bin's post_residual sits well below the fleet mean, it's a good consolidation.
    score += 0.03 * (mean_residual - post_residual as f64).max(-30.0).min(30.0);

    if is_new_bin {
        // New-bin candidate: penalize unless opening is genuinely justified.
        let f = fitting_bins_count as f64;
        // Availability of alternatives: 0 alternatives -> no penalty; many -> heavy penalty.
        let avail = if f > 0.0 { 1.0 - 1.0 / (1.0 + f) } else { 0.0 };
        let mut pen = 25.0 + 55.0 * avail;

        // If the next item would fit in the fresh bin's residual, opening is more attractive.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            pen -= 12.0;
        }

        // Late in the stream, with many bins open, avoid bin proliferation.
        pen += 25.0 * t * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

        // If the item is large relative to capacity, a fresh bin is a natural host.
        pen -= 10.0 * (item_size as f64 / cap);

        score += pen;
    } else {
        // Last-chance bin among open bins: strong bonus to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 6.0;
        } else if fitting_bins_count == 2 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Core: quadratic penalty on wasted space, sharpened late in the stream.
    let mut score = post * (1.0 + 0.9 * post / cap) + 40.0 * progress * (post / cap) * (post / cap) * cap;

    // Reward tight fits (small post_residual relative to item).
    score -= 12.0 * (1.0 - post / cap) * (1.0 - fit_frac);

    // Non-linear coupling of post_residual with stream progress.
    score += 8.0 * (post / cap) * (1.0 - progress) * (post / cap).sqrt() * cap * 0.1;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Many fitting bins: slight penalty to encourage diversity of residual sizes.
    if fitting_bins_count > 2 {
        score += 3.0 * ((fitting_bins_count - 2) as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits perfectly in post_residual, reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (1.0 - diff / cap).max(0.0);
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening a new bin, more so late in the stream,
    // but less when the item is large (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 30.0 + 20.0 * progress - 20.0 * fit_frac;
        score += new_bin_penalty.max(5.0);
    }

    // Tie-breaker: prefer filling bins with larger residual (more open space used).
    score -= 0.01 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds on capacity fractions.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual in 1..=10 (tight fit, low dead space) -> reward.
    // Class 2: post_residual in 11..=25 (medium) -> neutral.
    // Class 3: post_residual in 26..=50 (half-ish leftover) -> mild penalty.
    // Class 4: post_residual > 50 (large leftover) -> strong penalty (wasteful).
    let cls = if post_residual == 0 {
        0u32
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else if post_residual <= 50 {
        3
    } else {
        4
    };

    // Modulo-style coupling: residual that is a multiple of common small sizes
    // (10, 20, 25, 50) is more reusable -> subtract a bonus.
    let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0) || (post_residual == 50);
    if reusable && post_residual > 0 {
        score -= 6.0;
    }

    match cls {
        0 => score -= 40.0,
        1 => score -= 18.0,
        2 => score -= 4.0,
        3 => score += 8.0,
        _ => score += 20.0,
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fills it exactly (chained perfect fit).
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space the next item cannot use; penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // item is huge relative to residuals and no tight fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: high, so it only wins for genuinely bad fits.
        score += 30.0;
        // If item is large (>60) or stream is early, new bins are more acceptable.
        if item_size > 60 {
            score -= 12.0;
        }
        if open_bins_count > 12 {
            score += 5.0 * ((open_bins_count as f64 - 12.0).min(8.0)) * 0.5;
        }
    } else {
        // Mild preference for fuller bins: tighter residual = better choice.
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= fill * 8.0;
    }

    // Progress-based calibration: late in the stream, favor closing bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * cls as f64 * -0.5;

    // Deviation from mean residual: prefer bins deviating downward (fuller than average).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but dead space below a
    // "unusable gap" threshold is disproportionately expensive.
    let gap_threshold = 10.0f64; // smallest item is ~10; gaps below this are dead
    if (post_residual as f64) < gap_threshold {
        score += 50.0; // near-perfect fit bonus
    }

    // Penalize gaps that cannot fit the next item (lookahead dead space),
    // but only if they also can't fit a typical small item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) < nr && (post_residual as f64) < gap_threshold {
            score += 30.0;
        } else if (post_residual as f64) >= nr {
            score -= 15.0; // this bin can still absorb the lookahead item
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins and avoid opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when item is large and
        // existing bins would leave big dead space; penalize otherwise.
        score += 20.0 + pressure;
        if item_size as f64 >= 0.5 * bin_capacity as f64 {
            score -= 15.0;
        }
        if (post_residual as f64) < gap_threshold {
            score -= 40.0; // filling a fresh bin almost perfectly is great
        }
    } else {
        // Reward using existing bins, scaled by how much they'd be wasted.
        score -= 10.0;
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_ratio * waste_ratio; // quadratic dead-space penalty
        if (bin_residual as f64) < mean_residual {
            score -= 8.0; // prefer bins already tighter than average
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (small dead space is disproportionately bad).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else {
        // Penalize large unusable leftovers super-linearly.
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 15.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap == 0.0 {
            score -= 40.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            score -= (1.0 - gap / (bin_capacity as f64)) * 12.0;
        } else {
            // leftover can't host next item: penalize proportionally to the shortfall
            score += gap * 0.3;
        }
    } else {
        // Last item: strongly prefer tightest final fill.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: only this bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default slightly unattractive; make it attractive only
    // when the current item is large (big items deserve fresh bins) or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 30.0 - large_item * 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin can host the item
        }
        // If the next item is also large, a fresh bin is even more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild stream-progression pressure: as the stream nears its end, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits: the smaller the post_residual relative to item, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0;
        }
        // Reward leaving room for next item exactly.
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // Early in the stream, opening bins is cheaper (build inventory of residuals).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 {
            score -= 10.0 * (1.0 - progress);
        }
        // If mean residual across open bins is small, a fresh bin is more attractive.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Slight preference for filling existing bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate large residuals).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.1 * dev;
    }

    // Mild penalty when many open bins already exist (encourage consolidation).
    if open_bins_count > 5 {
        score += 0.5 * ((open_bins_count as f64) - 5.0).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post_residual (tight fit), scaled non-linearly.
    let norm_pr = pr / cap; // 0..1
    let mut score = 2.0 * norm_pr + 1.5 * norm_pr * norm_pr;

    // Smooth non-linear coupling with stream progress:
    // early on, tolerate slack (future items may use it); late, punish dead space harder.
    score *= 0.75 + 0.75 * progress * progress;

    // Reward using a bin whose residual closely matches the item (near-perfect fill),
    // via smooth saturating term.
    let fill = it / bin_residual.max(1) as f64;
    score -= 1.2 * fill * fill * (1.0 - fill * 0.5);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when the item leaves a very large,
    // hard-to-fill gap in every existing bin, or stream is early with slack demand.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bin by default proportional to how well it fits (perfect fit in new bin = wasteful).
        score += 4.0 * (1.0 - fill) * (1.0 - fill);
        // But relax the penalty when existing bins would leave big dead space:
        // compare this bin's would-be post_residual (cap - it) against mean residual.
        let new_post = cap - it;
        if new_post > mean_residual {
            score -= 0.8 * (new_post - mean_residual) / cap;
        }
        // Early stream: new bins are cheap investments; late stream: avoid sprawl.
        score += 2.0 * progress;
        // Many open bins already: discourage opening more.
        score += 0.05 * open_bins_count as f64;
    } else {
        // Mild bonus for preferring existing bins over new ones.
        score -= 0.3;
        // Lookahead: if the next item would fit exactly in the resulting residual, reward.
        if next_item_size > 0 {
            let diff = (pr as i64 - next_item_size as i64).abs() as f64;
            score -= 0.6 * (1.0 - diff / cap).max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins where the item leaves little dead space.
    score -= (post_residual as f64).sqrt() * 2.0;

    // Harmonic lookahead: reward if the next item's size class can still fit
    // in the post-placement residual (modulo-style bucketing on next_item_size).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here afterward: strong reward, scaled by how much slack remains.
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Next item won't fit: penalize creating a trap for the lookahead item.
            score += 8.0;
        }
        // Class bonus: next item in the "small" harmonic class (<= 25) keeps flexibility cheap.
        if next_item_size <= 25 && post_residual >= 25 {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate penalty: discourage opening a fresh bin unless fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.4 * item_size as f64;
        // But if no open bin can fit (this is the only candidate), the penalty is moot anyway.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Slight pull toward bins below the mean residual (balance load across bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Progress coupling: late in the stream, be greedier about tight fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps that no item (min size 1..100) can plausibly
    // fill are the worst outcome. Penalize gaps that are nonzero but tiny.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // mildly awkward gap
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill, strongly preferred
    }

    // Large leftover space is valuable: reward bins that keep flexible capacity.
    if post_residual >= 40 {
        score -= 10.0 + (post_residual as f64 - 40.0) * 0.2;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (already via post_residual),
        // but add slight pressure to disperse load.
        score += open_bins_count as f64 * 0.15;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // More attractive if mean residual of open bins is small (they're full-ish)
        // and the item is large.
        score -= mean_residual * 0.15;
        score -= item_size as f64 * 0.1;
        // If the next item also fits nicely after this placement, new bin is good.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item exactly fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Late in the stream, waste matters more (no future to amortize dead space).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Aggressive 2-step lookahead: perfect match with next item is gold
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 200.0; // exact 2-step chain: fill bin completely next round
        } else {
            let gap = (post_residual as f64 - next).abs();
            // reward post_residual close to next_item_size
            score -= 60.0 * (-gap / 20.0).exp();
        }
        // Penalize dead space next item cannot use
        if (post_residual as u32) < next_item_size {
            score += 25.0 + post_residual as f64 * 0.3;
        }
    } else {
        // Last item: strongly prefer zero post_residual
        if post_residual == 0 {
            score -= 250.0;
        }
    }

    // Compare against mean residual of open bins
    score -= 10.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // late in stream, opening new bin is safer
        let progress = step_index as f64 / total_items as f64;
        score -= 20.0 * progress;
    }

    // Mild penalty for very small unusable post_residual (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score toward zero for small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    }
    // Penalize post_residual that becomes dead space (too small for anything useful).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins close to the mean (balanced packing)
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large relative to a fresh bin.
    if bin_residual == bin_capacity {
        let scarcity_bonus = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        let big_item_bonus = if item_size as f64 / bin_capacity as f64 > 0.6 { 4.0 } else { 0.0 };
        score += 10.0 - scarcity_bonus - big_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on wasted space, growing with stream progress
    let norm_waste = pr / cap;
    score += 12.0 * norm_waste * norm_waste * (0.5 + t);
    score += 6.0 * norm_waste * norm_waste * norm_waste;

    // Coupling with mean residual: prefer bins whose residual deviates favorably from the mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev - 3.0 * dev;

    // Lookahead: reward bins whose post-residual can still host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - pr / cap);
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 9.0 + 6.0 * t;
    }

    // New empty bin candidate: penalize so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 14.0 + 18.0 * t + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: class 0 = perfect fit.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if class == 0 {
        score -= 60.0;   // decade-aligned residual is highly reusable
    } else if class >= 8 {
        score += 25.0;   // sliver dead space (1..2 units) is nearly useless
    }

    // Integer-division threshold on usable slack: reward residuals that can
    // still host common item sizes (>=10).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0; // unusable dead space
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
            // harmonic match: next item also lands on a decade boundary
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 40.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Empty new-bin candidate: only attractive when no open bin fits well
    // (large item, few fitting bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64) / (bin_capacity as f64);
        if open_bins_count == 0 || (scarcity > 0.0 && big_item > 0.6) {
            score -= 150.0 + 100.0 * (1.0 - progress);
        } else {
            score += 200.0; // discourage wasting a fresh bin when fits exist
        }
    }

    // Mild preference toward fuller bins (tight packing) via mean residual coupling.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Late-stream consolidation: prefer reusing existing bins near the end.
    if step_index + 1 >= total_items.saturating_sub(1) && bin_residual < bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // New empty bin candidate: score it by the waste it would start with,
    // plus a mild pressure term so it only wins when existing fits are bad.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 * 1.2 + 40.0;
        // Late in the stream, opening a new bin is less attractive (few future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 60.0;
        return score;
    }

    // Dead-space avoidance: a gap smaller than the current item is likely unusable.
    if post_residual < item_size {
        // The smaller the dead gap relative to capacity, the worse.
        let dead_ratio = post_residual as f64 / bin_capacity as f64;
        score += dead_ratio * 300.0;
    }

    // Prefer bins whose leftover can still hold the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 35.0; // creates a gap the next item cannot use
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Mild pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins tighter than average (below-mean residual = well-filled bin).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chained fit
        } else if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
            if leftover_after_next < 10 {
                score -= 10.0; // leaves nearly-zero dead space after chain
            }
        } else {
            // next item cannot fit here after placement: penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    } else {
        // last item: minimize post_residual hard
        score += post_residual as f64 * 0.5;
    }

    // Compare post_residual relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (dead space < 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: neutral-ish score; only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        // opening a new bin is penalized when good fits exist elsewhere
        score = 50.0 + post_residual as f64 * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else if next_item_size > 0 && (bin_residual as f64 - mean_residual) > 30.0 {
            score -= 10.0; // existing bins are quite full; fresh bin may be better
        }
    }

    // Slight late-stream tightening: consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this placement
    // (chaining placements into the same bin is good).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Even better: next item fills the bin nearly exactly.
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next < 10 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; mildly penalize leaving a large awkward gap.
            if post_residual > 30 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    } else {
        // Last item: prefer the absolute tightest bin.
        score -= 15.0 * tightness;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate unless it's genuinely better
    // (e.g., item is large and no good fit exists, or residuals are all large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a bin is expensive; require a big item to justify it.
        score += 18.0;
        // Large items benefit from fresh bins, more so early in the stream.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 22.0;
        score -= large_item_bonus * (1.0 - 0.5 * progress);
        // If existing bins have lots of mean residual, a new bin is less costly.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 8.0;
        // Avoid opening new bins when plenty of bins can already fit the item.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins with scattered residuals.
    if bin_residual != bin_capacity && (post_residual as f64) > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic polynomial in normalized post-residual
    let x = post / cap;
    let mut score = 4.0 * x * x - 2.0 * x + 0.5 * post;

    // Cubic coupling with stream progress: early on prefer tight fills,
    // later tolerate larger residuals less aggressively
    let prog_term = (1.0 - progress) * (x * x * x) * cap * 0.8
                  - progress * (x * (1.0 - x)) * cap * 0.6;
    score += prog_term;

    // Reward using nearly-full bins (small post residual)
    score -= (cap - post).min(cap) * 0.3;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 30.0 + 0.5 * post;
    }

    // Penalize bins far from mean residual (keeps residuals homogeneous)
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: reward if next item fits into resulting residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 0.1 * (next_item_size as f64 - post);
    }

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (post_residual == 0 already minimal, add extra pull)
    if post_residual == 0 {
        score -= 8.0;
    }

    // Dead space: residual too small for the minimum item size is wasted forever
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Harmonic class: residuals that are multiples of 10 are more reusable
    // (items drawn near multiples of 10 align with them). Penalize odd remainders.
    let harmonic_residue = post_residual % 10;
    score += harmonic_residue as f64 * 0.35;

    // Integer-division thresholds on post_residual: coarse classes of leftover space.
    // Class 0 (0-9): dead, class 1 (10-24): only tiny items fit, class 2 (25-49): medium,
    // class 3 (50+): generous. Penalize the awkward middle classes extra.
    let class = post_residual / 25;
    match class {
        1 => score += 6.0,
        2 => score += 3.0,
        _ => {}
    }

    // Lookahead coupling: reward if the next item can also fit in the leftover space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // extra reward for a chained near-perfect fit
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover can't host the next item: mild penalty scaled by how close it is
        let gap = (next_item_size - post_residual) as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin when alternatives exist
    if bin_residual == bin_capacity {
        score += 22.0;
        if fitting_bins_count >= 1 {
            score += fitting_bins_count as f64 * 4.0;
        }
        // But if the item is huge relative to capacity, opening a fresh bin keeps
        // flexibility for large future items late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 70 && progress < 0.6 {
            score -= 10.0;
        }
    }

    // Prefer bins below the mean residual early (keep big holes open), and above
    // the mean late (drain the emptier bins first).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) > mean_residual {
        score += progress * 4.0;
    } else {
        score -= (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize creating a gap just below the next item (blocking lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets a penalty scaling with open_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Mild bonus for filling fuller bins (tighter packing).
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
        // Prefer bins below mean residual when many bins are open (balance pressure).
        if open_bins_count > 4 && (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Early stream: be conservative, keep bins flexible; late stream: pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in leftover: reward proportionally to how well it fills.
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 30.0 * fill;
        } else {
            // Next item cannot use the leftover: penalize dead space a bit.
            score += 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post residual stays near the
    // open-bin mean (avoids isolating one bin with huge residual while others fill).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and can still absorb the item
    // reasonably (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin is only attractive if the item fits poorly everywhere else.
        let waste_if_open = (bin_capacity - item_size) as f64;
        // Make new bin costly unless the item is huge (would leave tiny dead space anyway).
        if item_size < bin_capacity / 2 {
            score += 40.0;
        } else {
            score += 5.0 + 0.2 * waste_if_open;
        }
    }

    // Mild preference to fill bins that are already mostly full (compactness).
    let used_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * used_frac;

    // Late in the stream, consolidate: slightly favor existing bins over new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: minimize post_residual relative to capacity
    let fit_ratio = post / cap; // 0 = perfect fit
    score += 6.0 * fit_ratio;

    // Reward near-exact fills strongly
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Dead-space penalty: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin by default,
    // but relax when existing bins fit poorly (large post_residual) or
    // when many bins fit (fragmentation risk is low).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 22.0;
        // If the best existing fit would waste a lot, opening fresh is fine
        new_bin_penalty -= 10.0 * fit_ratio.min(1.0);
        // If item is large, a fresh bin is more attractive
        new_bin_penalty -= 6.0 * (item_size as f64 / cap);
        // Early in stream, more freedom to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 15.0 * progress;
        // If few bins fit, prefer reusing
        if fitting_bins_count <= 1 {
            new_bin_penalty += 8.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Global state: when mean residual across open bins is high, spread load;
    // prefer filling bins with below-average residual less aggressively.
    if bin_residual != bin_capacity {
        let res = bin_residual as f64;
        if res > mean_residual {
            score -= 2.0 * ((res - mean_residual) / cap).min(1.0);
        } else {
            score += 1.5 * ((mean_residual - res) / cap).min(1.0);
        }
    }

    // Many open bins: encourage consolidation (reuse over sprawl)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = post / cap; // 0..1 leftover fraction

    // Base: reward tight fits (low post_residual), with non-linear shaping.
    let mut score = post;

    // Smooth non-linear coupling: quadratic in normalized leftover, modulated by stream progress.
    // Early on, slightly tolerate leftovers (more items to come that may fill them);
    // late in the stream, penalize leftover space more aggressively.
    let progress_boost = 1.0 + 1.5 * progress * progress;
    score += 40.0 * fit_norm * fit_norm * progress_boost;

    // Dead-space penalty: leftover too small for any plausible item (items >= 1).
    // Smoothly ramp penalty as post_residual approaches unusable-but-nonzero territory.
    if post > 0.0 {
        let dead = (1.0 - (post / 20.0)).clamp(0.0, 1.0);
        score += 25.0 * dead * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax the penalty
    // when the fit in existing bins would be terrible (large post_residual) and
    // when lookahead suggests a fresh bin is useful.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 45.0;
        // If placing here would waste a lot of capacity anyway, opening fresh is less bad.
        new_bin_penalty -= 0.35 * post;
        // Lookahead synergy: if next item fits well in a fresh bin's residual, favor new bin.
        if next_item_size > 0 {
            let next_post = post - next_item_size as f64;
            if next_item_size as f64 <= post {
                new_bin_penalty -= 15.0 * (1.0 - (next_post / cap).abs().min(1.0));
            }
        }
        // Late in the stream, avoid opening bins that will go nearly unused.
        new_bin_penalty += 30.0 * progress * progress;
        score += new_bin_penalty.max(0.0);
    }

    // Slight preference for consolidating into bins below mean residual
    // (fill the emptier bins first, keeping tight bins for tight fits).
    let res_norm = bin_residual as f64 / cap;
    score += 8.0 * (res_norm - mean_residual / cap).abs();

    // Mild pressure to use existing bins as open-bin count grows.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.95;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // (1..=12 range) are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * (13.0 - post_residual as f64) * 1.5;
    }
    if post_residual == 0 {
        // Perfect fill is the ideal outcome.
        score -= 40.0;
    } else if post_residual < item_size {
        // Gap too small for even this item class again; mild extra penalty.
        score += 6.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few bins, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / 10.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // post_residual it leaves is large and useful, or the current fit is bad.
    if bin_residual == bin_capacity {
        // Neutral baseline: score by post_residual (already included), but
        // discourage opening new bins when decent fits exist.
        score += 14.0 + 0.15 * open_bins_count as f64;
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // If the next item could use the leftover of this placement in the
        // new bin, slightly encourage opening it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 22.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., closer to being filled) when the stream is progressing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits in the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (post_residual as f64 - next_item_size as f64).sqrt() * 2.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space relative to its size.
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Penalize small unusable post-residuals (dead space) more than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 - post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is above the mean (keeps mean residual balanced).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) >= 0.0
            && (next_item_size == 0 || post_residual < next_item_size as u32 as f64);
        // Base penalty for opening a new bin; reduced if item is large / fit is bad.
        let mut penalty = 18.0;
        if item_size > 60 { penalty -= 6.0; }
        if fitting_bins_count <= 1 { penalty -= 10.0; }
        if poor_fit { penalty -= 5.0; }
        if open_bins_count == 0 { penalty = -100.0; }
        score += penalty * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose leftover is small but usable.
    if post_residual > 0 {
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        // Perfect fill is ideal.
        score -= 25.0;
    }

    // Penalize leaving dead space that likely cannot fit a future item
    // (items are >= 1, but small leftovers are wasteful when next item is big).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Dead space relative to lookahead: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size && post_residual > 0 {
            // Bin can still host the next item: reward.
            score -= 4.0;
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        if mean_residual < item_size as f64 * 1.5 {
            score -= 5.0 * (1.0 - progress);
        }
        // Slight preference for bins below mean residual (balance residuals).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0 + 8.0 * (1.0 - progress);
        // Acceptable only if item is large relative to capacity or no real alternative.
        let large_item_bonus = if item_size as f64 > 0.6 * bin_capacity as f64 { -10.0 } else { 0.0 };
        let scarcity_bonus = if fitting_bins_count == 0 { -20.0 } else { 0.0 };
        score += base_penalty + large_item_bonus + scarcity_bonus;
    }

    // Mild reward for using bins early in the stream (keep future flexibility).
    if bin_residual != bin_capacity {
        score -= 2.0 * (1.0 - progress);
    }

    // Waste measure: fraction of capacity wasted by this placement.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: tight fits rewarded, dead space penalized more as stream progresses
    let tightness = 1.0 - (pr / cap).powi(2);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize residuals that are too small to ever be useful (quadratic dead-space term)
    let small = (item_size as f64).powi(2);
    score -= small * 0.02 * (1.0 - progress);

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving residual that still fits the next item
    if next_item_size > 0 && post_residual as u64 >= next_item_size as u64 {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr).max(0.0) * 0.05;
    }

    // Mild penalty for opening a brand-new bin when open bins are plentiful
    if bin_residual as f64 == cap {
        score += 4.0 + 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    // Divergence from mean residual: prefer bins near average fill
    score += ((pr - mean_residual) / cap).abs() * 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals that are "usable"
    // (large enough to likely host a future item, small enough to be tight fit).
    let post_i = post_residual;
    let class = post_i / 10; // integer division class bucket
    match class {
        0 => score -= 25.0,          // near-perfect fit (0..10 dead space)
        1 => score -= 15.0,          // good
        2 => score -= 8.0,           // decent
        3 => score -= 3.0,           // fair
        4 => score += 2.0,           // half-full-ish, mediocre
        5 => score += 6.0,
        6 => score += 10.0,
        7 => score += 14.0,
        _ => score += 18.0,          // large residual kept => bin barely used
    }

    // Modulo-10 harmonic coupling: residual divisible structure pairs well
    // with next item when post_residual % 10 aligns with next_item_size % 10.
    if next_item_size > 0 {
        let next = next_item_size;
        if next <= post_i {
            // Next item fits in this bin's future residual: strong reward.
            score -= 10.0;
            // Tight secondary fit bonus (post_residual - next small)
            let gap = post_i - next;
            if gap <= 5 {
                score -= 8.0;
            } else if gap <= 15 {
                score -= 4.0;
            }
            // Harmonic alignment: (post - next) % 10 near 0 => reusable class
            let rem = gap % 10;
            if rem == 0 {
                score -= 3.0;
            } else if rem >= 8 {
                score -= 1.5;
            }
        } else {
            // Next item won't fit here; penalize unless this bin is last chance.
            score += 4.0;
            let rem = post_i % 10;
            if rem >= 1 && rem <= 3 {
                score += 3.0; // awkward dead-space class
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // real fits, but keep it competitive when current bin wastes lots of space.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_i as f64 > cap * 0.6 {
            score -= 6.0; // big item: fresh bin is reasonable
        }
    }

    // Progress-aware tightening: late in stream, dead space matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post / cap) * 8.0;

    // Crowd control: many open bins -> prefer consolidating into existing ones.
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * (post / cap) * 3.0;
    }

    // Mean-residual anchor: bins far from mean residual get slight pull.
    score += (post - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward good fits relative to bin space (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 25.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> prefer compacting into existing ones.
    score += open_bins_count as f64 * 1.5;
    // But penalize bins that are already tight relative to the mean residual
    // (prefer filling bins that are already low when many bins are open).
    if (bin_residual as f64) < mean_residual && post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item almost fits (small miss), slight penalty for stranding space.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this call's post_residual is large relative to item) or bins are scarce.
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin has full capacity; make it moderately attractive
        // so it beats bins with terrible fits, but loses to decent fits.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
        // Many open bins: discourage opening yet another unless necessary.
        score += open_bins_count as f64 * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base score).
    // But penalize dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead bonus: bin can host the next item too.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.08;
        } else {
            // Post residual is dead space relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // Last item: prefer perfect fill.
        score += post_residual as f64 * 0.5;
    }

    // Exact fit jackpot.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize bins far below mean residual (they're the roomy ones others should use first? No:
    // prefer packing into bins below mean residual to consolidate).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item barely fits nothing well.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { next_item_size } else { 0 };
        // Default penalty; waived when item is large relative to capacity.
        score += 18.0;
        if item_size >= 60 && post_residual < 40 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= best_possible {
            score -= 10.0;
        }
    }

    // Late in stream: consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Many open bins: encourage filling existing ones harder.
    if open_bins_count > 4 {
        score -= open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space non-linearly; small residuals are hard to reuse
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64 * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving residual that can fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx && pr < nx + 10.0 {
            score -= 25.0; // residual almost exactly fits next item
        } else if pr >= nx {
            score -= 10.0 * (nx / (pr + 1.0));
        } else {
            // residual too small for next item: penalize proportionally to dead-ness
            score += 8.0 * (1.0 - pr / nx.max(1.0));
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let crowding = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        // Base penalty so new bins aren't opened frivolously
        let mut nb = 55.0;
        // If mean residual across open bins is small (bins nearly full), new bin is fine
        nb -= 45.0 * (1.0 - crowding.min(1.0));
        // Large items late in stream: slightly favor fresh bins
        nb -= 10.0 * item_frac * progress;
        // If no other bin fits at all, new bin is necessary
        if fitting_bins_count == 0 {
            nb -= 100.0;
        }
        score = nb;
    }

    // Mild global pressure: many open bins -> prefer filling existing ones
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Time horizon: early in stream, keep bins flexible (avoid ultra-tight fits
        // that strand space); late in stream, pack aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual polynomial in stream progress
    let poly = fit_frac * fit_frac * (1.0 - progress) + fit_frac * progress * progress;
    score += 12.0 * poly - 6.0 * fit_frac * (1.0 - progress);

    // Penalize dead space that can't fit the lookahead item (smooth gate via sigmoid-like term)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let tight = 1.0 - (pr / nx).min(1.0);
        score += 8.0 * tight * tight * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress) + 8.0;
    }

    // Mild penalty when bin residual deviates from mean residual (balance smoothing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate handling: penalize opening a new bin early, allow it late
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 10.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) > fit_frac * cap {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are hard to fill later
    // (small but nonzero leftovers) should be penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Class B: tiny dead space (1..=5) -> heavy penalty
    else if post_residual <= 5 {
        score += 25.0;
    }
    // Class C: awkward mid sliver (6..=9) -> moderate penalty
    else if post_residual <= 9 {
        score += 12.0;
    }
    // Class D: residue in (10..=19] can host small items -> mild reward
    else if post_residual <= 19 {
        score -= 4.0;
    }

    // Modulo arithmetic on capacity fractions: post_residual close to
    // common item sizes (multiples of 10) is reusable.
    let mod10 = post_residual % 10;
    if post_residual >= 10 && mod10 == 0 {
        score -= 6.0; // round residue likely reusable by harmonic items
    } else if mod10 >= 1 && mod10 <= 2 && post_residual > 10 {
        score += 5.0; // just-above-round residues are awkward
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain placement possible: reward proportionally
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 + 10.0 * chain_fit;
        } else {
            // next item cannot follow here: mild penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over.min(40.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets baseline near capacity,
    // discouraged unless open bins are congested.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 20.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else {
            // encourage new bin when existing residuals are small/fragmented
            let congestion = (mean_residual < 25.0) as i32 as f64;
            score -= 30.0 * congestion;
            // late in stream, prefer consolidation into open bins
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * progress;
        }
    }

    // Prefer tighter (fuller) bins generally
    score -= 0.1 * (cap - bin_residual as f64);

    // Mild preference for bins below mean residual (balance fragmentation)
    score += 0.05 * (bin_residual as f64 - mean_residual).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 19 {
        // Mid-range gaps are mildly penalized but can still fit small items.
        score += 12.0;
    }

    // Reward tight fits: post_residual near zero (but not dead space) is great.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Reward filling the bin proportionally (large item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: more open bins -> discourage spreading.
    score += 2.5 * open_bins_count as f64;

    // Compare against mean residual: placing into a below-average residual bin
    // (i.e., a fuller bin) is preferred.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if next item would fit exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no good placement exists
    // (i.e., this empty bin's baseline is high unless current bins are crowded).
    if bin_residual == bin_capacity {
        score = 110.0 - 1.5 * fitting_bins_count as f64 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when next item exactly fills post_residual (perfect 2-step chain)
    if next_item_size > 0 {
        if next_item_size == post_residual {
