    }

    // Penalize opening a new bin when decent fits exist, unless residual would be tiny
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive only if it enables a near-perfect chain
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 70.0;
        } else {
            score += 15.0;
        }
    }

    // Late in stream: consolidate, avoid spreading across bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Mild super-linear penalty for leftover dead space.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.05 * next_item_size as f64;
    }
    // Penalize bins that would strand a gap too small for the next item.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize so tight existing fits win,
    // but let it win when no open bin fits well (it will be the only sane choice).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.25 * item_size as f64;
        // Late in the stream, opening bins is less costly than fragmenting.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual_frac = pr / cap;

    // Base: prefer minimal post residual, but with diminishing returns (sqrt-like shaping)
    let mut score = pr * (1.0 + 0.35 * residual_frac);

    // Tight-fit reward: strong non-linear bonus as post_residual approaches zero
    let tightness = 1.0 - residual_frac.min(1.0);
    score -= 12.0 * tightness.powi(3);

    // Penalize dead space that is too small to be useful later (below min item size ~1..100 scale)
    let dead = residual_frac * (1.0 - residual_frac);
    score += 6.0 * dead * (1.0 - progress);

    // Stream progress coupling: early on, keep bins flexible (penalize low residuals mildly);
    // late in the stream, squeeze hard (reward low residuals).
    let flex_penalty = 8.0 * (1.0 - progress) * residual_frac * residual_frac;
    let squeeze_bonus = 10.0 * progress * (1.0 - residual_frac).powi(2);
    score += flex_penalty - squeeze_bonus;

    // Lookahead coupling: if the next item fits into the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 9.0 * fit_quality * (1.0 - 0.5 * progress);
        } else {
            // next item cannot follow here: penalize proportionally to wasted potential
            score += 4.0 * (1.0 - progress) * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fitting bins exist
    // and many bins are already open (amortization of open-bin overhead).
    if bin_residual == bin_capacity {
        let open_factor = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + 3.0 * open_factor + 10.0 * (1.0 - progress);
        // But allow new bin if mean residual of open bins is nearly exhausted
        score -= 0.15 * mean_residual.max(0.0).min(30.0);
    }

    // Mild penalty for bin proliferation relative to items processed
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // "harmonic" and more likely to accept future items -> reward them.
    let post = post_residual;
    let class = if post == 0 {
        0.0 // perfect fit, best possible outcome
    } else if post % 10 == 0 {
