    } else {
        10.0 // awkward class, penalize
    };
    score += class;

    // Dead-space penalty: tiny unusable slivers (post_residual < 10 means
    // nothing in [1..100] range can... but sizes >=1, so weight by how small).
    if post > 0 && post < 5 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chain fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            // next item fits, reward proportionally to how well it uses post space
            let slack = (post - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty scaled by post size
            score += (post as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post residual would be tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post > 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing existing bins when they leave decent residuals.
        // Opening a new bin is attractive only when the item is large and
        // existing fits would waste space, or when many bins are open.
        score = (bin_capacity - item_size) as f64 + 12.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        } else if item_size >= 60 {
            score -= 15.0; // big items pack well into fresh bins
        }
        if open_bins_count > 0 && mean_residual > (item_size as f64) + 10.0 {
            score += 20.0; // existing bins have room; discourage new bin
        }
        // harmonic class of the would-be residual
        let would_be = bin_capacity - item_size;
        if would_be % 10 == 0 {
