        }
    }

    // Progression: late in the stream, be more conservative with new bins.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= 3.0 * t * (mean_residual / bin_capacity as f64);
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - post as f64) * 0.0; // no-op guard
    score -= (mean_residual - post as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 120.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 60.0;
        } else if post_residual < 30 {
            score += 25.0;
        } else {
            score -= 15.0; // large residual may still be usable
        }
    } else {
        score -= 200.0; // perfect fill
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New empty bin candidate: penalize unless current fit is very poor
    // or post_residual would be a dead sliver.
    if bin_residual == bin_capacity {
        score += 90.0 + 2.0 * open_bins_count as f64;
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 20.0; // next item cannot use the leftover
    }

    // Mean residual coupling: prefer bins deviating favorably from mean.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Early stream: be slightly more conservative with bin openings.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward bins whose post_residual matches the next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Perfect match: next item exactly fills the leftover space.
            let match_gap = pr - nxt;
            score -= 30.0 * (1.0 - match_gap / (bin_capacity as f64)) * (1.0 - 0.5 * progress);
            // Extra bonus if next item fits exactly (post_residual == next_item_size)
            if match_gap == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot use this residual: dead-space penalty scaled by gap.
            let gap = nxt - pr;
            score += 0.6 * gap.min(nxt);
        }
        // If next item exactly fits current residual BEFORE placement, i.e. bin_residual
        // matches next size, placing the current item creates a complementary fit.
        if bin_residual as f64 >= nxt && (bin_residual as u32).saturating_sub(item_size) >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: strongly prefer tightest fit (smallest post_residual).
        score += 25.0;
    }

    // --- Relative residual vs mean: prefer bins tighter than average ---
    score += 0.4 * (post_residual as f64 - mean_residual).max(-20.0);

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 12.0 * (1.0 - 0.3 * progress);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large relative to capacity
        // and existing bins have poor fits (high mean residual).
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 15.0;
        score += 40.0 - large_item_bonus - 0.15 * mean_residual;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 10.0 * (1.0 - progress);
        // If many bins already fit the item, discourage a new bin.
        score += 2.0 * fitting_bins_count as f64;
    }

    // --- Penalize creating very small unusable residuals (dead space) ---
    let cap = bin_capacity as f64;
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 8.0; // tiny slivers are wasted space
    }

    // Mild preference for fewer open bins (bin consolidation pressure).
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (low post_residual) nonlinearly.
    let tightness = 1.0 - post / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post >= ni {
            score -= 12.0;
            let slack = post - ni;
            if slack < 10.0 { score -= 8.0; } // next item nearly fills leftover
        } else {
            score += 6.0 * (ni - post) / cap; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or existing bins fit poorly (high mean residual fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let load = item_size as f64 / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let penalty = 55.0
            - 30.0 * load
            - 15.0 * fragmentation
            - 10.0 * (1.0 - progress);
        score += penalty.max(5.0);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress:
    // early on, compactness matters less; late, prefer tight fills aggressively.
    let poly = 1.0 + 1.6 * progress - 0.9 * progress * progress;
    score *= poly;

    // Reward last-chance bins (avoid opening a new bin when only one fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // Penalize near-full residuals that become dead space: quadratic dead-space term.
    let dead = pr / cap;
    score += 6.0 * dead * dead;

    // Lookahead: if next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let snug = 1.0 - ((post_residual as i64 - next_item_size as i64).abs() as f64 / cap);
        score -= 10.0 * fits_next * (0.5 + snug);
    }

    // New-bin candidate: penalize opening a new bin unless current residual is hopeless.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress) - 0.05 * bin_residual as f64;
    }

    // Mild preference for bins below mean residual (consolidate emptier space usage).
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space ---
    // Classify post_residual by capacity-fraction bands and modulo structure.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Dead-space bands: tiny leftovers are wasted capacity.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // nearly unusable sliver
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 35 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 120.0; // perfect packing reward
    }

    // Modulo arithmetic on post_residual: leftovers that align with common
    // item-size residues (multiples of 10 / 5) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 18.0;
    } else if post_residual % 5 == 0 {
        score -= 7.0;
    }
    // Odd, awkward leftovers get penalized.
    if post_residual % 2 == 1 && post_residual < 40 {
        score += 12.0;
    }

    // Integer-division thresholds: leftover big enough to hold a
    // half-capacity or quarter-capacity chunk is valuable.
    let quarters = post_residual / (bin_capacity / 4);
    score -= quarters as f64 * 15.0;

    // --- Fit quality relative to the incoming item ---
    // Reward tight fits (small post_residual already dominates, add coupling).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 30.0;

    // --- Lookahead: does the next item fit the leftover? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 45.0; // chain-friendly placement
            // Harmonic bonus if next item's size divides the leftover well.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot use the leftover: leftover risks becoming dead space.
            let overshoot = (next_item_size - post_residual) as f64;
            score += (overshoot / cap).min(1.0) * 22.0;
        }
    } else {
        // Last item in stream: minimize leftover aggressively.
        score += frac * 40.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0; // strongly prefer using the only fitting bin
    } else if fitting_bins_count > 1 {
        // With many options, prioritize the tightest, but keep ordering by score.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost so it only wins when fits are bad.
        score += 130.0;
        // Early in the stream, opening bins is cheaper (builds a portfolio).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
        // Few open bins -> new bin less costly.
        if open_bins_count <= 2 {
            score -= 30.0;
        }
        // If the item is large relative to capacity, a fresh bin is natural.
        if (item_size as f64) > 0.6 * cap {
            score -= 25.0;
        }
        // Next item is huge and this fresh bin would be the only one able
        // to host it after this placement? Keep fresh-bin attractive.
        if next_item_size > 0 && next_item_size >= post_residual && post_residual >= 0 {
            score -= 10.0;
        }
    } else {
        // Slight preference for reusing already-open bins over opening new ones.
        score -= 5.0;
        // Prefer bins whose residual is below mean (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // --- Stream-phase modulation ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Late in the stream, avoid spreading: penalize large leftovers more.
    score += frac * (10.0 + 30.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap in (0, 10) is essentially dead space (min item size is 1..100, but
    // small gaps rarely reusable) -> quadratic penalty on near-misses.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 - 4.0 * post_residual as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // the item is large or the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.5 * bin_capacity as f64;
        let bad_gap = post_residual > 0 && post_residual <= 12;
        if large_item || bad_gap {
            score -= 30.0; // prefer opening a fresh bin
        } else {
            score += 45.0; // prefer reusing an existing bin
        }
    }

    // Lookahead: if next item could use the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // residual too small for next item -> mild penalty
    }

    // Mean-residual coupling: bins far below mean residual are "almost full",
    // favor closing them out.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Late-stream tightening: as the stream progresses, be more aggressive
    // about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
