pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post residual close to 0 or small dead space)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize creating dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual (chaining)
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 12.0 - slack * 0.15;
        } else {
            // Next item won't chain here; penalize proportionally to wasted potential
            score += 3.0;
        }
        // Perfect chain: next item exactly fills the bin
        if post_residual as u32 == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 30.0;
        // Cheaper to open new bins early in the stream (long horizon to amortize)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // More open bins -> prefer consolidation into existing bins
        score += (open_bins_count as f64).min(20.0) * 0.8;
        // If mean residual is large, existing bins have room; discourage new bin
        score += mean_residual * 0.25;
        // If this is the only fitting bin and it's full-ish, opening a bin is fine
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Mild preference for filling already-partly-used bins (best-fit bias)
        score += (bin_residual as f64) * 0.05;
        // Favor bins with residual close to item (tightness)
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.02;
    }

    // Late-stream urgency: prefer closing bins tightly as stream ends
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        score += post_residual as f64 * 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tightness of post-fit residual, normalized.
    let mut score = pr / cap;

    // Smooth non-linear coupling: quadratic in normalized post residual,
    // modulated by stream progress. Small residuals are rewarded more
    // strongly as the stream progresses (consolidate late).
    let x = pr / cap;
    score += 0.6 * x * x * (0.5 + progress);

    // Cubic dead-space penalty: heavily penalize leaving awkward gaps
    // (residuals that nothing typical can use).
    score += 0.35 * x * x * x;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Lookahead coupling: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 0.5 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Post residual cannot host next item: mild penalty scaled by gap.
            let gap = (nxt - pr) / cap;
            score += 0.3 * gap;
        }
    }

    // Bin diversity pressure: when many bins are open, slightly prefer
    // filling existing ones over opening new ones.
    let ob = open_bins_count as f64;
    score += 0.05 * (ob / (ob + 5.0));

    // New-bin candidate handling (bin_residual == bin_capacity): it should
    // only win when no open bin offers a decent fit. Give it a baseline
    // penalty that shrinks as progress advances (late stream, prefer fresh
    // bins for large items rather than fragmenting).
    if bin_residual == bin_capacity {
        let base = 1.2 - 0.4 * progress;
        // Large items into a fresh bin are less wasteful.
        let size_rel = item_size as f64 / cap;
        score += base - 0.8 * size_rel * size_rel;
    }

    // Mean-residual coupling: if this bin is far from the mean residual,
    // small nudge to keep residual distribution balanced.
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but heavily reward exact fills.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Harmonic class of post_residual: classify dead space into buckets.
        let pr = post_residual;
        let class = match pr {
            0..=5 => 0.0,
            6..=15 => 1.0,
            16..=29 => 2.0,
            30..=49 => 3.0,
            _ => 4.0,
        };
        score += class * 12.0;

        // Modulo arithmetic on post_residual: residuals that are "nice"
        // (multiples of 10, or small primes) are more likely reusable.
        let m10 = (pr % 10) as f64;
        score += m10 * 1.5;

        // Lookahead: if next item exactly fits post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 400.0;
            } else if next_item_size <= pr {
                // Next item fits: the closer, the better.
                let slack = (pr - next_item_size) as f64;
                score -= 150.0 - slack * 2.0;
            } else {
                // Next item cannot use this residual: penalize small residuals
                // that block the next item from this bin entirely.
                score += 40.0;
            }
        }

        // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 80.0;
        }

        // New-bin candidate: neutral-ish baseline, but discourage opening new bins
        // early in the stream or when few bins are open.
        if bin_residual == bin_capacity {
            score += 60.0 + 0.5 * open_bins_count as f64;
            // Late in stream, opening new bins is relatively cheaper.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 50.0 * progress;
        }

        // Prefer filling bins whose residual deviates below the mean residual
        // (concentrate packing into emptier bins).
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;

        // Integer division threshold: large items should go into bins with
        // residual just above them (harmonic size classes).
        let size_class = item_size / 20; // 0..4
        let resid_class = bin_residual / 20;
        if size_class == resid_class {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 && post_residual > 0 {
        // Dead space penalty scaled by how dead it is (smaller gap = worse).
        score += 200.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward tight fits: post_residual close to zero relative to bin capacity.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 80.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: keep it mediocre unless open bins are crowded.
        score = bin_capacity as f64 * 0.75 + 60.0;
        if post_residual == 0 { score -= 500.0; }
        if open_bins_count == 0 {
            score -= 300.0;
        } else {
            // Penalize new bins more when mean residual is high (existing space wasted).
            score += mean_residual * 1.5 + (open_bins_count as f64) * 8.0;
            // But if existing bins would leave tiny dead gaps and this bin could host next item well,
            // opening a fresh bin can be attractive.
            if post_residual < 10 && post_residual > 0 {
                score -= 120.0;
            }
        }
    }

    // Lookahead: if next item fits into the resulting residual, reward; if it would be dead space, penalize.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 40.0;
        } else if post_residual > 0 {
            score += 25.0;
        }
    }

    // Mild progression term: early on, keep bins flexible; late, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 - progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item (perfect chaining), penalize near-misses.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 1.5;
        if post_residual == next_item_size {
            score -= 30.0; // perfect lookahead match
        }
        // If next item cannot fit in post_residual, this bin becomes dead space
        // for the next step unless post_residual is small.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative to mean residual: prefer bins whose post_residual is below
    // the mean residual (compacting space into fewer bins).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and leaves a useful residual for the next item.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 50 {
            score -= 55.0; // big items deserve a fresh bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild stream-progress term: later in the stream, be slightly more
    // conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Tie-break: prefer bins with larger pre-fit residual when all else equal
    // (fills emptier bins first, keeping tight bins for small items).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Penalize dead space that is too small for the smallest plausible item,
    // scaled by how much of the stream remains.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 1.0 - progress;
    if post_residual > 0 && post_residual < 10 {
        score += 18.0 * horizon;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward for a near-perfect pairing with the next item.
            let pair_waste = (post_residual - next_item_size) as f64;
            if pair_waste < 5.0 {
                score -= 8.0;
            }
        } else {
            // The next item won't fit here; mild penalty if this placement
            // strands a large residual.
            score += 4.0 * horizon;
        }
    } else {
        // Last item: any bin that fits is fine; prefer the emptiest use.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global congestion: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so post_residual
    // is large for it; add extra penalty proportional to congestion).
    let congestion = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual == bin_capacity {
        score += 12.0 + 15.0 * congestion + 10.0 * (1.0 - horizon);
        // Exception: allow opening a new bin when the item is huge and
        // nothing else fits well.
        if item_size >= 80 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer placing into bins whose residual is already below the mean
    // (consolidate toward fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Prefer using bins with smaller current residual (best-fit flavor).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / (total_items as f64).max(1.0)).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * (1.0 - norm_post));

    // Smooth polynomial coupling with stream progress: tighter packing matters more later.
    score += 12.0 * norm_post * norm_post * (progress * progress);

    // Dead-space penalty: residuals too small for typical items are wasted.
    let dead_threshold = 0.35 * cap;
    if post > 0.0 && post < dead_threshold {
        let t = post / dead_threshold;
        score += 10.0 * (1.0 - t) * (1.0 - t);
    }

    // Lookahead: reward if next item fits into the post residual (chained packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            // Penalize if the leftover is just barely unable to host the next item.
            let miss = (nxt - post) / cap;
            score += 6.0 * miss * (1.0 - miss);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, encouraging bin consolidation.
        score += 1.5 * ((fitting_bins_count - 1) as f64).min(4.0);
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and future flexibility matters.
    if bin_residual == bin_capacity {
        let mean_res_norm = mean_residual / cap;
        let flexibility_benefit = 3.0 * (1.0 - progress) * (1.0 - progress);
        score = 0.55 * cap + flexibility_benefit + 4.0 * mean_res_norm;
        // If this bin is the only fitting option, opening a new bin is rarely needed.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: rewards residuals that sit in "usable" classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes on post_residual: residuals divisible by common item granularities
    // (e.g. multiples of 10) are more likely reusable by future items.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 10 == 0 { score -= 6.0; }
        else if pr_u % 5 == 0 { score -= 3.0; }
        if pr_u % 20 == 0 { score -= 3.0; }
        // Penalize awkward small dead zones (1..10) that no item (min size 1..) can fill well
        if pr_u < 10 { score += 8.0; }
    } else {
        // Perfect fill is ideal
        score -= 25.0;
    }

    // Integer-division threshold coupling: post_residual vs next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= pr_u {
            // Next item fits here: strong reward, scaled by tightness of the fit
            let slack = (pr_u - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / cap);
            if slack == 0.0 { score -= 10.0; } // perfect two-item fill
        } else {
            // Next item cannot use this residual: penalize proportionally
            score += 4.0 + 6.0 * (nxt / cap);
        }
        // Harmonic class match: residual in same decade-class as next item
        if pr_u >= next_item_size && (pr_u / 10) == (next_item_size / 10) {
            score -= 2.5;
        }
    }

    // Tightness reward: small post_residual relative to capacity is good (if not dead zone)
    score += 5.0 * (pr / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing ones,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure terms
        score += 12.0 + 2.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper; late, expensive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If mean residual across bins is large, avoid new bin
        score += 0.15 * mean_residual;
        // If next item is large, a fresh bin is attractive
        if next_item_size >= 60 { score -= 8.0; }
    } else {
        // Existing bin: reward when open bins are numerous (consolidation)
        score -= 0.5 * open_bins_count as f64;
        // Favor bins whose residual is below mean (fill the emptiest-relative bins last)
        if (bin_residual as f64) > mean_residual { score += 2.0; } else { score -= 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: reward when the leftover space matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits perfectly into this bin's leftover: strong reward.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize proportionally to waste.
            score += 0.5 * gap;
        }
        // Perfect closure: bin becomes exactly full after next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Penalize creating dead space far below any plausible future item (min size 1, typical >=10).
    let small_dead = if post_residual < 10 { 1.0 } else { 0.0 };
    score += 25.0 * small_dead;

    // Relative-to-mean coupling: bins with residual below mean are "denser" — using them
    // consolidates waste; bins above mean should be saved for large future items.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Neutral base cost for opening a new bin.
        score = bin_capacity as f64 * 0.75;
        // If this is the last chance bin is actually a new bin and no open bin fits,
        // make it competitive but still slightly costly.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        // Lookahead: if next item is large and this bin is fresh, mild discount.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: as the stream nears its end, prefer closing bins
    // tightly rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing (min item 1..100) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Penalize leaving residual that blocks the next item but is too small to matter.
            if post_residual < next_item_size && post_residual < 20 {
                score += 6.0;
            }
        }
    }

    // Time horizon: early in the stream, be conservative with tight fits (keep flexibility);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fill_ratio;

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count.min(20) as f64).ln();
    }

    // Global residual pressure: if mean residual is low, cherish bins with large residuals.
    if mean_residual < 20.0 {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: opening a new bin is generally costly;
    // only attractive when no good fit exists (this call's score competes with open bins).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 - 0.5 * item_size as f64;
        // If the item fits poorly anywhere else, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream with many open bins, avoid spawning bins.
        score += 25.0 * progress + 0.8 * open_bins_count as f64;
        // Large items relative to capacity favor a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post_residual, mildly compressed non-linearly
    let mut score = pr + 0.15 * (pr * pr) / cap;

    // Small post-residuals are dead space -> penalize quadratically near zero
    let dead = (cap - pr) / cap; // fill fraction
    score += 30.0 * (1.0 - dead) * (1.0 - dead) * (pr / cap).max(0.0);

    // Stream progress coupling: late in stream, prefer tighter packing (lower post_residual)
    score *= 1.0 + 0.8 * progress * (1.0 - dead);

    // Reward large fill (low post_residual) with smooth polynomial interaction
    score -= (it / cap) * (it / cap) * 20.0 * (1.0 + progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - (pr / cap));
    }

    // Mean residual alignment: prefer bins near mean residual (keeps flexibility)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New empty bin candidate: penalize unless no real alternative benefit
    if bin_residual == bin_capacity {
        score = pr + 60.0 + 20.0 * progress - (fitting_bins_count as f64) * 5.0;
        if fitting_bins_count == 0 {
            score -= 80.0; // no open bin fits, must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "reusable"
    // (large enough for typical next items) get a bonus.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quarter-capacity classes: leftover >= 25 keeps bin usable.
    let quarter = cap_f / 4.0;
    if pr >= quarter {
        score -= 6.0 * (pr / cap_f);
    } else if pr > 0.0 {
        // Dead-space penalty for tiny unusable leftovers.
        score += 4.0 * (1.0 - pr / quarter);
    }
    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo-10 class of post_residual: leftovers that are multiples of 10
    // align with the classic item grid and are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Integer-division threshold on next_item_size: if the lookahead item
    // fits exactly into the post residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this leftover: slight penalty proportional
            // to how much of the leftover would be wasted.
            score += 2.0 * (next_item_size as f64 / cap_f);
        }
        // Harmonic class: next item leaves a multiple-of-10 residual too.
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins
    // are truly bad (their scores stay below this unless heavily penalized).
    if bin_residual == bin_capacity {
        score = cap_f * 1.5;
        // Late in the stream, or when few bins fit, opening fresh is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= cap_f;
        }
        // If mean residual of open bins is too small for the item, new bin helps.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Prefer tighter existing bins slightly.
        score += 0.5 * (bin_residual as f64 / cap_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a future item (min item size = 1) are still wasteful if they
    // fall in a "gap band" that is unlikely to be filled exactly.
    if post_residual > 0 {
        // Penalize tiny unusable slivers heavily (dead space).
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }
        // Penalize mid-range gaps that rarely match future item sizes.
        if post_residual > 10 && post_residual < 25 {
            score += 8.0 * (25.0 - post_residual as f64) / 15.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless the fit
    // is excellent; encourage consolidation when many bins are open.
    score += 2.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than the mean
    // (concentrating fill), discourage leaving very loose bins looser.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (creates a good chain); if not, penalize slightly.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0;
        } else {
            score += 5.0;
        }
    }

    // Early in the stream, be more willing to open/consolidate; late in the
    // stream, be strict about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress);

    // New-bin candidate handling: an empty bin has zero post-fit utility
    // knowledge; make it attractive only when no good fit exists, by
    // penalizing it mildly so it wins only against bad fits.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Reward closeness of the match: tighter leftover after next item is better.
            let after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportional dead space created.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    } else {
        // Last item: simply minimize leftover.
        score += 0.0;
    }

    // Compare against mean residual: bins already tight (below mean) are
    // good targets; bins far above mean waste capacity.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.5 * (mean_residual - resid);
    } else {
        score += 0.2 * (resid - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current
    // item is large (poor fit elsewhere) or no good chaining exists.
    if bin_residual == bin_capacity {
        let waste_elsewhere = if next_item_size > 0 && post_residual > 0 {
            // Opening new bin wastes potential of existing residual space.
            20.0
        } else {
            0.0
        };
        score += 25.0 + waste_elsewhere;
        // Large items justify a new bin more readily.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Late in the stream, consolidate: fewer open bins is better, so
    // slightly favor reusing existing bins over spawning new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward leaving post_residual that can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Dead space penalty if leftover can't fit the next item.
            score += 4.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // the item is large relative to capacity or fits are scarce.
    if bin_residual == bin_capacity {
        let base_penalty = 15.0;
        let scarcity_bonus = if fitting_bins_count <= 1 { 25.0 } else { 0.0 };
        let big_item_bonus = if item_size >= 70 { 10.0 } else { 0.0 };
        score += base_penalty - scarcity_bonus - big_item_bonus;
    } else {
        // Mild penalty for wasting a very large bin on a small item.
        if item_size < 30 && bin_residual > 80 {
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be more willing to consolidate
    // (keep bins balanced); late, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual as f64 - mean_residual).signum() * 2.0;
    score += progress * (post_residual as f64) * 0.05;

    // Encourage filling bins when many are already open (bin sprawl control).
    score += open_bins_count as f64 * 0.1;

    // Small structural tie-break: prefer bins whose residual is close to mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap; // normalized fill after placement

    // Base: prefer small post_residual (tight packing), scaled by progress pressure
    let mut score = post * (1.0 + 0.5 * progress);

    // Smooth non-linear reward for high fill: quadratic coupling with stream progress
    score -= 30.0 * fill * fill * (0.6 + 0.8 * progress);

    // Dead-space penalty: tiny residuals are hard to reuse (smooth cubic falloff)
    let dead = post / cap;
    score += 25.0 * (1.0 - dead) * (1.0 - dead) * (1.0 - dead) * dead;

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 12.0 * snug * snug;
        } else {
            // penalize leaving a residual that wastes the next item
            score += 8.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, less so late in stream or when
    // item fits existing bins poorly (post_residual would be very small anyway).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 18.0 + 10.0 * (1.0 - progress) + 0.8 * openness;
        // but if item is large relative to capacity, new bin is fine
        score -= 10.0 * (item / cap) * (item / cap);
    }

    // Mild penalty for bins far below mean residual (keeps bin residuals balanced)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good; add quadratic bonus
    // so going from 5 -> 0 residual matters much more than 95 -> 90.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    // Residuals in (0, 10] are "dead space" (no future item 10..80 fits except tiny ones
    // under the interface range 1..100, so weight by next_item_size usability instead).
    let class = post_residual / 10; // integer division harmonic class 0..10
    score -= match class {
        0 => 12.0,           // near-perfect fill
        1 => 6.0,
        2 => 3.0,
        3 => 1.0,
        4 => 0.0,
        5 => 1.0,
        6 => 2.0,
        7 => 4.0,
        8 => 6.0,
        9 => 8.0,
        _ => 10.0,
    };

    // If next item can exactly fill the resulting residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial credit: next item fits but leaves another leftover; scale by fit ratio.
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * fit_ratio;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this residual at all -> leftover likely wasted.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin (penalize alternatives implicitly by rewarding this one).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate detection: bin_residual == bin_capacity means empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // But if the item is large relative to capacity, a fresh bin is fine since
        // the leftover will be small anyway; rebate proportional to item size.
        let item_frac = item_size as f64 / cap;
        score -= 20.0 * item_frac * item_frac;
        // If the next item is small and this item leaves a big residual, opening
        // a new bin wastes usable space that an existing bin could provide.
        if next_item_size > 0 && next_item_size < post_residual {
            score += 6.0;
        }
        // Late in the stream, avoid proliferating bins with big residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress * ((post_residual as f64) / cap);
    }

    // Mild pressure against bins whose residual deviates far from the mean residual
    // (keeps bin states homogeneous, reducing fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins that are already partially filled when many bins
    // are open (encourage closing bins out rather than spreading items thinly).
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 2.0 * fill * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (<10, minimum item size) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Gaps too small for the lookahead item are semi-dead if nothing small may come.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bins pressure: discourage spreading across many bins; keep consolidation.
    score += open_bins_count as f64 * 2.0;

    // Slightly favor bins tighter than the mean residual (better fits).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progress.
        score = bin_capacity as f64 + 80.0 + (step_index as f64 / total_items.max(1) as f64) * 50.0;
        // If this is a last-chance situation, opening a new bin is acceptable.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // If lookahead item is large, a fresh bin can host it after this one.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead fit: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead fit: next item can fit snugly with small waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    }

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fills relative to mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly
    // (large post_residual waste) or no good fit exists.
    if bin_residual == bin_capacity {
        score = 0.0;
        // Penalize opening a bin when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual <= 20 {
            score += 50.0;
        }
        // Mildly discourage proliferation of open bins.
        score += open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact packing is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio * fit_ratio;
    }

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // small gap nearly useless, but at least it was tight
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocked lookahead
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should generally lose unless
    // open bins have poor fit or are congested.
    if bin_residual == bin_capacity {
        score += 80.0 + 2.0 * open_bins_count as f64;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 50.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If mean residual is large, existing bins have room; avoid new bins.
        score += 0.3 * mean_residual;
    } else {
        // Prefer bins with residual below capacity (i.e., already partially used).
        score -= 5.0;
        // Slight preference for fuller bins (smaller residual) to consolidate.
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Global load balancing: with many open bins, favor filling existing ones.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Core: post-residual, with smooth non-linear waste pressure
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Tight-fit reward: strongly favor small post_residual, smoothly amplified
    let tightness = 1.0 - norm_post;
    score -= 18.0 * tightness * tightness * tightness;

    // Dead-space penalty: residuals too small for typical future items
    let dead = ((25.0 - post).max(0.0)) / cap;
    score += 40.0 * dead * dead;

    // Stream-progress coupling: later in the stream, waste matters more
    score += 12.0 * progress * norm_post;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count <= 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        // crowding pressure: many fitting bins -> prefer the best fit only
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * norm_post;
    }

    // Mean-residual coupling: prefer bins below mean residual (use fragmented space first)
    score += 0.25 * (mean_residual - post).max(0.0);

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= post {
            let slack = post - ns;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 3.0 * (ns - post) / cap;
        }
    }

    // New-bin candidate: mildly penalize opening a new bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 classes of 10 units.
    let post_class = (post_residual / 10) as f64;
    // Reward low post_residual classes nonlinearly (tight packing favored).
    score += post_class * post_class * 2.5;

    // Perfect fit bonus (post_residual in tiny dead-space class).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Harmonic coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            // modulo-style closeness of next item to residual
            let m = post_residual % next_item_size.max(1);
            if m == 0 {
                score -= 40.0; // exact division: future perfect fit possible
            } else {
                score -= 15.0;
            }
            // penalize if next item leaves a large dead class again
            let next_post = post_residual - next_item_size;
            score += (next_post / 10) as f64 * 8.0;
        } else {
            // next item cannot use this residual: penalize large residual classes
            score += post_class * 12.0;
        }
    } else {
        // last item: prefer any bin, reward using existing bins
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // spread: prefer bins with tighter residual among many options
        score += (bin_residual as f64 - mean_residual) * 0.6;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 70.0;
        // cheaper to open a new bin late in the stream? no: cost stays, but
        // cheaper when many items remain to fill it
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0; // opening late is wasteful
        // opening early is cheaper
        score -= (1.0 - progress) * 10.0;
        // if the next item is small, a fresh bin is attractive for pairing
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 25.0;
        }
        // if next item is huge, fresh bin risky
        if next_item_size > 70 {
            score += 20.0;
        }
    } else {
        // reward using already-open bins to keep open_bins_count low
        score -= open_bins_count.min(50) as f64 * 0.4;
    }

    // Mild penalty for very large residuals left in mid-stream (dead space class 7+)
    if post_class >= 7.0 && next_item_size > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual matches typical item sizes (usable leftovers).
    let usable = post_residual >= 10 || post_residual == 0;
    if usable {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if post-residual could have fit next item but we waste it on a bad gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Open-bins pressure: with many open bins, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when open count high.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a new bin
        } else {
            // discourage opening new bin when existing bins can fit,
            // unless all fits would be terrible (large dead space everywhere).
            let poor_fit = post_residual >= item_size && item_size <= 30;
            if poor_fit {
                score -= 5.0; // item is small; a fresh bin keeps flexibility
            } else {
                score += 12.0 + open_bins_count as f64 * 0.5;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but soften via mean residual comparison
    let residual_f = post_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { residual_f };

    // Reward bins whose post residual is below the mean (tight packing)
    score -= 0.5 * (mean - residual_f).max(0.0);
    // Penalize bins whose post residual is above the mean (wasteful)
    score += 0.3 * (residual_f - mean).max(0.0);

    // 2-step lookahead: strongly reward when next item exactly fills post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fits, punish large slack
            score -= 12.0 - slack.min(12.0);
            score += 0.2 * slack;
        } else {
            // next item won't fit: dead-space risk grows with small post_residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(40.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: make empty bin attractive only when current fits are poor
    if bin_residual == bin_capacity {
        // penalize opening new bin mildly; overcome only by very poor fits elsewhere
        score += 15.0;
        // but if item is large and next item is also large, new bin is fine
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > 60 {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer reusing existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (open_bins_count as f64).recip().min(1.0);

    // Slight preference for bins with larger residual pre-fit (keeps flexibility)
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Squared penalty on wasted space, scaled by how much slack the system has.
        let waste = post_residual as f64;
        let slack_scale = (mean_residual / bin_capacity as f64).max(0.05);
        score += 0.15 * waste * waste / (bin_capacity as f64 * slack_scale.max(0.3));
    }

    // Lookahead: if the next item fits in the post-residual, reward keeping this bin alive.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 8.0 + 0.25 * gap as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; penalize leaving awkward slivers.
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; make it costly unless
    // there are no alternatives or the current fit is terrible.
    if is_new_bin {
        let mut open_cost = 45.0;
        if fitting_bins_count == 0 {
            open_cost = -10.0; // no open bin fits: must open
        } else if fitting_bins_count == 1 {
            open_cost = 30.0; // one alternative exists: be cautious
        }
        // Late in the stream, avoid opening bins that will be nearly empty forever.
        open_cost += 10.0 * progress;
        // If mean residual across open bins is large, opening a new bin wastes capacity.
        open_cost += 0.3 * mean_residual;
        // If next item is huge and would need a fresh bin anyway, opening now is fine.
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            open_cost -= 15.0;
        }
        score += open_cost;
    } else {
        // Mild preference for bins that are already well-filled (fragmentation control).
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
        // Spread load when many bins are open and residuals are homogeneous.
        if open_bins_count > 4 && (bin_residual as f64 - mean_residual).abs() < 5.0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap; // normalized fill after placement

    // Base: prefer tight fits, with a non-linear (quadratic) reward on fill.
    let mut score = pr - 2.5 * fill * fill * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space hurts more; reward low post_residual extra.
    let t = progress;
    let coupling = (pr / cap) * (pr / cap) * (0.5 + 2.0 * t) * cap;
    score += coupling;

    // Penalty for leaving residual that no typical next item can use,
    // smoothly weighted by how much slack remains relative to capacity.
    let waste_risk = (pr / cap).powi(3) * cap * (0.3 + 0.7 * t);
    score += waste_risk;

    // Lookahead: reward if next item fits the post residual (smooth bell shape).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        let bell = (-gap * gap / (2.0 * 25.0 * 25.0)).exp();
        score -= 6.0 * bell * (1.0 - 0.5 * t);
    }

    // Last chance: strongly favor using the only bin that fits (smooth reward).
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * t;
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit
    // in existing bins is poor. Smoothly scaled by stream progress.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (item_size as f64 / cap);
        // Tight fits (large items) justify a fresh bin more readily late in stream.
        score += 15.0 * (1.0 - tightness * (0.4 + 0.6 * t));
    }

    // Mild preference for bins whose residual is near the mean (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (0.5 + t);

    // Slight penalty for proliferation of open bins, smoothed by progress.
    score += 0.02 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post_residual (tight fit).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residual classes that are
    // "dead space" (below the minimum item size) are heavily penalized,
    // while classes that commonly recombine are rewarded.
    let cls = (post_residual % 10) as f64;
    if post_residual < 10 && post_residual > 0 {
        // Unusable sliver: pure dead space.
        score += 40.0 - cls;
    } else if post_residual == 0 {
        // Perfect closure — strongly reward.
        score -= 60.0;
    } else {
        // Class-based affinity: residuals divisible by 5 pair well with
        // typical item sizes; odd awkward classes get a mild penalty.
        if post_residual % 5 == 0 {
            score -= 6.0;
        }
        if post_residual % 10 == 0 {
            score -= 4.0;
        } else if post_residual % 2 == 1 {
            score += 2.5;
        }
        // Integer-division thresholds: coarse buckets of remaining space.
        let bucket = post_residual / 20; // 0..=5
        score -= bucket as f64 * 1.5; // larger usable residual is mildly better
    }

    // Lookahead coupling: reward residuals that exactly fit the next item,
    // penalize residuals just barely too small for it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Harmonic class match on modulo 10 between leftover and next item.
            if post_residual % 10 == next_item_size % 10 {
                score -= 8.0;
            }
            score -= 2.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 5.0; // next item cannot use this bin anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current fit is poor, otherwise discourage spreading.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly worse than a perfect fit, better than dead space.
        score = 45.0 + item_size as f64 * 0.1;
        if fitting_bins_count == 1 {
            // If only the new bin "fits" alongside one open option, tip toward
            // using the existing bin: make new bin less attractive.
            score += 20.0;
        }
        // If many open bins and mean residual is high, opening fresh is fine.
        if mean_residual > (bin_capacity as f64) * 0.6 {
            score -= 10.0;
        }
        return score;
    }

    // Mild pressure against proliferating bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.05 * progress;

    // Small tie-breaker: prefer bins whose residual is close to mean (balance).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual that cannot fit the smallest possible item (1) is fine (perfect fit),
    // but gaps that are too small for typical items are dead weight.
    if post_residual > 0 {
        // Gap is "dead" if it's smaller than half the item size (unlikely to be filled well)
        if post_residual < item_size / 2 {
            score += 25.0 + (item_size as f64 - post_residual as f64) * 0.5;
        }
        // Very small residual that can't fit the next item either: strong penalty
        if next_item_size > 0 && post_residual < next_item_size as u32 {
            score += 15.0;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits: small post_residual relative to bin capacity
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count
        score += open_bins_count as f64 * 8.0;
        // But if this bin is the only fitting option, new bin is competitive
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward using it, especially when few bins fit
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Slight reward for using bins with lower residual (tighter packing)
        score -= (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 5.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 10.0;
    }

    // Late stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 2.0;

    // Mean residual coupling: if mean residual is high, prefer bins below mean (tighter)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits leaving small usable slack.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 60.0 - slack * 3.0; // tighter slack rewarded more
        } else {
            score -= 20.0; // still a decent lookahead fit
        }
    }
    // Next item will NOT fit in this bin after placement: dead space risk.
    else if next_item_size > 0 && post_residual < next_item_size {
        // Small dead space is tolerable; large dead space is bad.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.8;
        if post_residual < 10 {
            score += 15.0; // sliver unusable for typical items
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good fits),
    // but avoid creating extreme outliers far below mean.
    let pr = post_residual as f64;
    if pr > mean_residual + 5.0 {
        score -= (pr - mean_residual).min(50.0) * 0.4; // roomier than average: fine
    } else if pr < mean_residual - 20.0 {
        score += (mean_residual - pr - 20.0) * 0.5; // much tighter than average: mild penalty
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current placement would waste a lot (large dead space) or item is huge.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral post_residual, but discourage when a
        // reasonable fit exists in an open bin.
        score += 25.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 500.0; // fresh bin perfectly staged for the next item
        }
    }

    // Late in the stream: prefer closing bins tightly (less fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 10.0 * (1.0 - progress); // slivers worse early, acceptable late
    }

    // Many open bins: consolidate into existing ones rather than spreading.
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count.min(20) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is naturally better, but amplify.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that likely becomes unusable for future items
    // (items >= 10 in classic streams; interface allows 1..100, use fraction).
    let dead_threshold = bin_capacity as f64 * 0.10;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0; // small unusable sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins -> encourage consolidation into existing bins.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score -= 4.0 * pressure * tightness;

    // Mean residual coupling: if this bin is below average residual (fuller),
    // it's more valuable to keep filling it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: late in the stream, avoid opening new bins; early, allow
    // exploration of new bins for large items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New-bin candidate: penalize so it wins only when open bins are bad fits.
        score += 20.0 + 30.0 * progress;
        // Large items may justify a fresh bin early on.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 18.0;
        }
        // If next item is huge and this item would leave a big residual,
        // a fresh bin pairs well.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    // Small extra: prefer bins whose residual stays "composable" (multiple of
    // common small sizes) — mild shaping only.
    if post_residual % 5 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping.
    let post_n = post / cap;
    let mut score = post + 25.0 * post_n * post_n + 10.0 * post_n * post_n * post_n;

    // Smooth stream-progress coupling: tighten packing as stream advances.
    let tighten = 1.0 + 0.6 * progress * progress;
    score *= tighten;

    // Reward filling bins nearly exactly (post residual near zero) with a smooth bump.
    let near_fit = (-post_n * 4.0).exp();
    score -= 8.0 * near_fit;

    // Lookahead coupling: penalize leaving residual that cannot fit next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (post - nxt).max(0.0);
        let unusable = (1.0 - (waste / cap).exp()) * (waste / cap);
        score += 20.0 * unusable;
        // Smooth bonus if post residual still accommodates next item.
        let fits_next = 1.0 - (1.0 - (post / nxt.max(1.0))).clamp(0.0, 1.0);
        score -= 6.0 * fits_next * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it (avoid opening new bin) with smooth decay.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - post_n);
    }

    // Mean-residual coupling: penalize adding to bins far above mean residual (smooth).
    let dev = (mean_residual - post) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Mild penalty for crowding many open bins late in stream.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * progress;

    // New-bin candidate: make it unattractive unless residual is large and stream is early.
    if bin_residual == bin_capacity {
        let early = (1.0 - progress) * (1.0 - progress);
        score += 30.0 - 25.0 * early;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by large chunks are reusable
    let pr = post_residual;
    let class = if pr == 0 { 0 } else if pr % 50 == 0 { 1 } else if pr % 25 == 0 { 2 } else if pr % 10 == 0 { 3 } else if pr % 5 == 0 { 4 } else { 5 };
    score -= match class { 0 => 400.0, 1 => 60.0, 2 => 40.0, 3 => 25.0, 4 => 12.0, _ => 0.0 };

    // Penalize dead space too small for the minimum plausible item
    if pr > 0 && pr < 10 {
        score += 150.0;
    }

    // Lookahead: does next item fit exactly or well into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let diff = pr - next_item_size;
            if diff == 0 {
                score -= 500.0; // chain of perfect fits
            } else if diff < 10 {
                score -= 80.0;
            } else {
                // harmonic coupling: reward if diff lands on a coarse class
                if diff % 25 == 0 { score -= 45.0; }
                else if diff % 10 == 0 { score -= 20.0; }
                score += diff as f64 * 0.5;
            }
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        score += 300.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // late in stream, opening bins is cheaper than wasting space
        if progress > 0.8 { score -= 120.0; }
        if mean_residual > 40.0 { score += 100.0; } // plenty of room in open bins: don't open
    }

    // Prefer tighter (smaller residual) bins generally
    score += (bin_residual as f64) * 0.1;
    // Slight preference for bins with low residual relative to mean
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap that is smaller than the minimum item size (1) can't happen,
    // but gaps too small for typical items are dead space.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(next_item_size as f64);
        if next_item_size > 0 && (post_residual as f64) < dead_threshold {
            // Gap cannot fit the lookahead item -> likely dead space.
            score += 60.0 + (dead_threshold - post_residual as f64) * 4.0;
        }
        // General small-gap penalty: tiny leftovers waste capacity.
        if (post_residual as f64) < 8.0 {
            score += 25.0;
        }
    }

    // Reward bins whose residual after placement still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when current placement
    // would create severe dead space or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Pressure grows with number of open bins.
        score += open_bins_count as f64 * 2.5;
        // If the current bin would leave a bad gap, opening a new bin is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= 70.0;
        }
        // If next item fits perfectly in the fresh bin, mildly encourage it.
        if next_item_size > 0 && next_item_size == item_size {
            score -= 20.0;
        }
    } else {
        // Mild reward for filling existing bins tightly (larger item share).
        score -= (item_size as f64) * 0.15;
        // Slight preference for bins with below-mean residual (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidate harder: avoid spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead reward: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack * 0.15);
    }
    // Penalize blocking the lookahead item (dead space it can't use)
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Penalize tiny unusable post-residual (dead space) unless it exactly matches lookahead
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only one bin fits, prefer using it over opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more when good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * (1.0 + 0.35 + 0.25 * progress);
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still serves lookahead well
        }
        return score;
    }

    // Mild coupling with mean residual: prefer bins tighter than average
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Prefer filling larger fraction of the bin
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual is better, but over-reward near-zero waste.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that cannot fit the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot fit here; slight penalty for fragmenting space
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.2;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 12.0 + 20.0 * (1.0 - progress);
        // If open bins are fragmented (mean residual low relative to item), opening new bin is fine.
        if (mean_residual as u32) < item_size + 5 {
            new_bin_cost -= 10.0;
        }
        // If many open bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            new_bin_cost += 15.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
        }
        score += new_bin_cost;
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.15;

    // Encourage packing into already-open bins as stream progresses (avoid bin proliferation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Nonlinear coupling: penalize bins whose post-residual is awkwardly between 20 and 40
    // (hard-to-fill zone for typical item distributions).
    if post_residual >= 20 && post_residual <= 40 {
        score += 8.0 * (1.0 - ((post_residual as f64 - 30.0).abs() / 10.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post residual), with a smooth polynomial bias
    // toward very small residuals as the stream progresses.
    let mut score = post * (1.0 + 0.6 * progress * norm_post);

    // Non-linear penalty for leaving "awkward" mid-range dead space, amplified late in stream.
    let awkward = norm_post * (1.0 - norm_post); // peaks at post = C/2
    score += 18.0 * awkward * (0.4 + progress);

    // Reward tight fits: subtract when post residual is small relative to capacity.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Coupling with mean residual: prefer bins whose residual deviates from mean
    // in the direction of a better fit (smaller residual than average).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 8.0 * dev.max(0.0) * (0.3 + progress);

    // Lookahead: reward placements that leave room for the next item exactly,
    // penalize placements that strand the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        if post >= nxt {
            // exact match leaves zero slack next round
            score -= 10.0 * (-8.0 * diff.abs()).exp();
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Mild preference to fill existing bins rather than open new ones,
    // scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score -= 2.0 * (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic classes: classify residual into well-known "friendly" sizes
    // that future items (10..80) can combine into. Residuals in {0, 20, 25,
    // 30, 40, 50, 60, 70, 80} are more reusable than odd leftovers.
    let residual = post_residual;
    let harmonic = match residual {
        0 => true,
        r if r % 10 == 0 => true,
        r if r % 25 == 0 => true,
        _ => false,
    };
    if harmonic {
        score -= 12.0;
    } else {
        score += 8.0;
    }

    // Dead space: residuals too small for the minimum item size (1..100 now,
    // but weight small leftovers harshly since they waste capacity).
    if residual < 10 {
        score += 60.0 + (10 - residual) as f64 * 4.0;
    } else if residual < 25 {
        score += 18.0;
    }

    // Tightness reward: filling most of the bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Harmonic coupling: if next item fits exactly in the post residual,
    // strongly prefer this bin (sets up a perfect second placement).
    if next_item_size > 0 && next_item_size == residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= residual {
        // Next item fits: check if resulting double-post residual is harmonic.
        let post2 = residual - next_item_size;
        if post2 % 10 == 0 || post2 == 0 {
            score -= 25.0;
        }
        // Penalize leaving a sliver that neither item can use later.
        if post2 < 5 {
            score += 25.0;
        }
    }

    // Modulo-class lookahead: prefer residuals whose class matches the next
    // item's class (both multiples of 10, or both multiples of 25).
    if next_item_size > 0 {
        let cls_next = next_item_size % 25;
        let cls_res = residual % 25;
        if cls_next == cls_res && next_item_size <= residual {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: opening a new bin should only win when the item is
    // large and no good fit exists. Penalize new bins by default; relax the
    // penalty for large items.
    if bin_residual == bin_capacity {
        score += 70.0 - fill_ratio * 90.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
        // Late in the stream, prefer consolidating rather than spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Mild pressure toward bins below mean residual (rebalance toward
    // emptier bins keeps future options open).
    let res_f = residual as f64;
    if res_f > mean_residual {
        score += (res_f - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - res_f) * 0.05;
    }

    // Small bonus for using bins early in the stream (fewer open bins
    // overall tends to reduce total count).
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin: only attractive when item is large (leaves a useful
        // large residual) or late in the stream; otherwise keep open bins preferred.
        score += 35.0 - 0.25 * (item_size as f64) + 10.0 * progress;
    } else {
        // Strict dead-space avoidance: small non-zero gaps are nearly useless
        // since items are >= 1 but often mid-sized.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 + 2.0 * (10 - post_residual) as f64;
        }
        // Perfect fit is excellent.
        if post_residual == 0 {
            score -= 20.0;
        }
        // Last chance bin: strongly prefer to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 22.0;
        }
        // Mild pressure against proliferating open bins.
        score += 0.06 * open_bins_count as f64;
        // Lookahead coupling: reward if next item can use the leftover space.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 9.0;
            } else {
                score += 5.0;
            }
        }
        // Slightly prefer bins tighter than the fleet average.
        score += 0.08 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact matches between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0) * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: next item exactly fills bin after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item won't fit after this placement, penalize dead space growth.
        if post_residual < next_item_size && post_residual > 0 {
            score += 6.0 * (post_residual as f64 / 100.0);
        }
    }

    // Compare post_residual against mean residual: leave residuals near the mean
    // (keeps flexibility), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits overall.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // New-bin candidate: make it unattractive unless current bins are very full
    // or this is a poor fit everywhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if mean_residual < 25.0 {
            score -= 15.0; // open bins nearly full -> new bin reasonable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins that end up nearly full.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Lookahead: penalize dead space that cannot host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for the lookahead item; penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.9 * waste;
        } else {
            // Space remains useful for the next item: reward.
            score -= 0.35 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    } else {
        // Last item: aggressively prefer fullest packing.
        score -= 25.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good fit (large mean residual spread / poor fits).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_pressure = if fitting_bins_count == 0 {
            1.0
        } else {
            (item_size as f64 / bin_residual as f64).max(0.0)
        };
        // Cost of a new bin decays with progress; penalize early opening.
        score += 30.0 * (1.0 - 0.5 * progress) - 25.0 * (1.0 - fit_pressure);
        // Many open bins with slack => discourage opening yet another.
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for bins below mean residual (balance slack across bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Fragmentation guard: residuals in awkward mid-range are less valuable later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);
    score -= 25.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // penalize tight fits more late in the stream (dead space risk)
    score += 10.0 * (1.0 - progress) * (-norm_pr * 4.0).exp();

    // lookahead coupling: reward bins whose post_residual can hold next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * progress * (next_item_size as f64 - pr).abs() / cap;
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - fit);
    }

    // mild dispersion penalty relative to mean residual
    score += 2.0 * (pr - mean_residual) / cap;

    // new-bin candidate: prefer opening only when fits are poor or stream is late
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress) - 10.0 * (1.0 - fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10
    let pr = post_residual;
    let class = pr % 10;

    // Dead-space penalty: small nonzero post_residual is unusable
    if pr > 0 && pr < 10 {
        score += 40.0;
    } else if pr == 0 {
        score -= 60.0; // perfect closure
    } else if class == 0 {
        score -= 15.0; // multiple of 10 aligns with typical item sizes
    } else if class <= 5 {
        score += 8.0;
    }

    // Lookahead coupling: next item fits perfectly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr && pr > 0 {
            score -= 80.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            if slack < 10.0 {
                score -= 25.0;
            } else {
                score += slack * 0.15;
            }
        } else {
            // next item cannot use this residual anyway
            score += 5.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize wasting a nearly-empty (fresh) bin on a small item
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac < 0.5 {
            score += 70.0;
        } else {
            score += 25.0;
        }
        // but if nothing else fits, opening is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer filling fuller bins tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / cap) * 10.0 * (1.0 - progress);

    // Mild dispersion penalty: avoid fragmenting when many bins open
    if open_bins_count > 4 {
        let dev = (mean_residual - post_residual as f64).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept another item (given typical item sizes) are heavily penalized.
    let min_useful_gap = 10.0_f64.min(bin_capacity as f64);
    if (post_residual as f64) < min_useful_gap && post_residual > 0 {
        score += 60.0; // dead space: gap below smallest possible item
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize moderate leftover gaps that likely become dead space later:
    // a residual that cannot fit the lookahead item is a warning sign.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 12.0;
    }

    // Open-bins pressure: when many bins are open, prefer packing tightly
    // into existing bins; subtract a pressure term to favor reuse.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Deviation from mean residual: prefer bins whose residual is already
    // small (tight bins) to consolidate waste.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin mildly, but waive the
    // penalty when the current item would leave an awkward gap in any bin.
    if bin_residual == bin_capacity {
        let awkward = next_item_size > 0 && post_residual >= 1 && post_residual < 20;
        if open_bins_count > 0 && !awkward {
            score += 25.0;
        } else if open_bins_count > 0 && awkward {
            score -= 15.0; // opening fresh is fine when fits are terrible
        }
    }

    // Mild lookahead synergy: if the next item fits exactly into the
    // post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-match reward: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize leaving dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 * (gap / 100.0);
    }

    // Prefer filling bins whose residual is below mean (tight bins first)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in the stream, consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // Brand-new bin candidate: mild penalty so it's chosen only when open bins are bad fits
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize dead space relative to item size: small leftover after a large item is fine,
    // small leftover after a small item is wasteful.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving awkward gaps.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are congested (high mean fill)
    // or many bins fail to fit the item.
    if bin_residual == bin_capacity {
        let congestion = 1.0 - mean_residual / bin_capacity as f64;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 40.0; // base cost of opening a new bin
        score -= 35.0 * congestion;
        score -= 25.0 * scarcity;
        // Early in the stream, opening bins is cheaper (builds a portfolio).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If item is large, a fresh bin guarantees fit quality.
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild preference for bins tighter than the average residual (best-fit flavor).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Slight penalty when many bins are open, encouraging consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), smoothly normalized.
    let mut score = pr / cap;

    // Non-linear dead-space penalty: residuals that are small but unusable
    // (below the minimum conceivable item size) are heavily punished via a
    // smooth saturating term rather than a hard threshold.
    let unusable = (1.0 - pr / cap).max(0.0);
    score -= 0.6 * unusable * unusable * (1.0 - progress);

    // Smooth interaction: reward placements whose post-residual still matches
    // the lookahead item (k=2), using a Gaussian-like coupling.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        score -= 0.5 * (-gap * gap * 40.0);
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin, more strongly when alternatives exist and
    // early/mid stream where consolidation still matters.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let alt_pressure = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 1.5 + 2.0 * alt_pressure * (1.0 - progress);
    } else {
        // Last-chance bonus: if this is the only fitting bin, strongly favor it
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 1.2 * (1.0 - progress * 0.5);
        }
        // Mild pull toward bins whose residual is close to the stream mean,
        // smoothing residual distribution across open bins.
        let dev = (pr - mean_residual) / cap;
        score += 0.15 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues that are "usable" by typical
    // item sizes (multiples of 5 and 10) are less penalized.
    let pr = post_residual;
    let res_mod10 = (pr % 10) as f64;
    let res_mod5 = (pr % 5) as f64;
    score += res_mod10 * 1.5 + res_mod5 * 0.8;

    // Dead-space thresholds via integer division: post_residual below small
    // item minimum is nearly dead space.
    if pr < 10 && pr > 0 {
        score += 60.0;
    } else if pr < 20 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host next_item_size.
    if next_item_size > 0 {
        let n = next_item_size;
        if pr >= n {
            // harmonic match quality: closeness of pr to n via quotient classes
            let diff = (pr - n) as f64;
            let q = (pr / n.max(1)) as f64;
            score -= 40.0 / (1.0 + diff * 0.1) + 5.0 * (q % 2.0);
        } else {
            // cannot host next item: penalize proportional to shortfall class
            let short = (n - pr) as f64;
            score += 10.0 + (short / 20.0).floor() * 8.0;
        }
        // modulo harmony between next item and post residual
        if n % 10 == pr % 10 && pr >= n {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it mildly
    // attractive only when current bin would leave bad residue or item is huge.
    if bin_residual == bin_capacity {
        score = 90.0
            - 20.0 * (item_size as f64 / cap)
            + (fitting_bins_count as f64) * 6.0;
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 25.0 * progress * (post_residual as f64 / cap);

    // Slight preference to spread load when many bins open with high mean residual.
    if mean_residual > 40.0 && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize gaps that cannot fit the known next item (unusable for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect-fill candidate: bin residual exactly equals item.
    if bin_residual == item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New empty bin candidate: must only win when the fit into open bins is terrible.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 0.25 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        }
        if post_residual > 0 && post_residual < 10 {
            score += 60.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Mild preference toward fuller bins relative to mean residual.
        score -= 0.05 * (mean_residual - post).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact or near-exact match of post_residual to next item (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - match_quality / 60.0).max(0.0);
    }

    // Penalize dead space: post_residual too small for anything useful (min item 1, but
    // small leftovers under ~12 are hard to fill).
    if post_residual < 12 {
        score += 25.0;
    }

    // Reward tight fits relative to the mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).max(0.0) * tightness;

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the stream is early or current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        let penalty = 35.0 + 45.0 * (1.0 - progress) + 60.0 * (1.0 - crowding);
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strong preference for minimal wasted space
    score -= 3.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64);

    // Dead-space penalty: small post_residuals that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin by default
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if lookahead item is large and current item is small,
        // opening a fresh bin can be advantageous
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 18.0;
        }
        // Late in stream, prefer compacting into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 12.0;
    }
    // Penalize if next item cannot fit into post_residual (fragmentation risk)
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 2.0;
    }

    // Prefer bins with residual below mean (consolidate fuller bins)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage filling existing ones to limit bin sprawl
    score += 0.05 * open_bins_count as f64;

    // Early stream: slight preference for balanced packing (keep residuals flexible)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 0.3 * post_residual as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear shaping
    let mut score = post;
    score += 40.0 * pr * pr * (1.0 - pr); // penalize mid-range waste, favor tight fits

    // Polynomial coupling of post residual with stream progress:
    // early on, tolerate slack; late, demand tight fits
    let coupling = 2.0 * progress * progress - 3.0 * progress + 1.0; // 1 -> 0 quadratic
    score += coupling * 30.0 * pr;
    score -= progress * progress * 25.0 * pr * (1.0 - pr);

    // Lookahead: reward if next item fits into post residual
    let nxt = next_item_size as f64;
    if nxt > 0.0 && nxt <= post {
        let fill = nxt / post.max(1.0);
        score -= 20.0 * fill * (1.0 - fill) * 4.0 * fill; // smooth reward for good chained fit
        if post - nxt < 10.0 {
            score -= 12.0; // near-perfect chain fill
        }
    } else if nxt > post && post > 0.0 {
        // next item won't fit here; mild penalty for leaving large unusable-ish gap
        score += 8.0 * pr * pr;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early and when fits exist
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 60.0 + 40.0 * (1.0 - progress) * scarcity;
        if post_residual == 0 {
            score -= 45.0; // perfect fill with a fresh bin is fine
        }
    }

    // Mild preference to balance residuals across bins
    score += 5.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), superlinear pressure.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Harmonic class of post_residual: classify by integer division thresholds.
    // Dead-space classes: residuals in (0,10) are nearly useless; (10,20) risky.
    let cls = post_residual / 10; // 0..10 harmonic class
    match cls {
        0 => {
            if post_residual == 0 {
                score -= 30.0; // perfect closure
            } else {
                score += 25.0; // tiny dead space, worst outcome
            }
        }
        1 => score += 12.0,          // 10..19: risky fragment
        2 => score += 4.0,           // 20..29: usable for small items
        3 | 4 => score -= 3.0,       // 30..49: healthy mid residual
        _ => score -= 5.0,           // 50+: large residual, flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 22.0; // chains a perfect closure
        } else if slack <= 10 {
            score -= 8.0; // next item leaves small but tolerable slack
        } else {
            score -= (slack as f64).sqrt() * 1.5;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual: dead space penalty scaled by item size.
        score += (next_item_size.min(30) as f64) * 0.4;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: mild bonus, selection driven by fit quality.
        score -= 2.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // penalize by current congestion and stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 14.0 + open_bins_count as f64 * 1.2 + progress * 6.0;
        // But if the item is large, the new bin will hold a big chunk nicely.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If next item is large too, a fresh bin can host the pair.
        if next_item_size > bin_capacity / 2 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Mean residual context: when average residual is already large, prefer
    // consolidating into tight bins rather than spreading.
    if mean_residual > 40.0 && post_residual < 20 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals too small to be useful are heavily punished.
    // A residual is "dead" if it cannot hold even a small item (threshold ~10)
    // or is in an awkward small-gap band (10..=25).
    if post_residual == 0 {
        score -= 30.0; // perfect fill is ideal
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual <= 25 {
        score += 12.0; // awkward gap, likely dead space
    } else {
        score -= 4.0; // decent usable residual
    }

    // Reward tight fit: small relative post_residual.
    score -= 20.0 * (1.0 - post / cap);

    // Reward exact-looking matches: post_residual divisible into small chunks.
    if post_residual > 0 && (100 % post_residual.max(1)) == 0 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item won't fit here; deprioritize
    }

    // Open-bin pressure: penalize creating many open bins slightly,
    // but when this bin is the last chance, strongly favor using it.
    score += 0.35 * open_bins_count as f64;
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 35.0 + 10.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.8 * cap {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // This bin can also host the next item: reward proportionally.
            score -= 0.4 * nxt;
        } else if post_residual > 0 {
            // Leftover dead space that blocks the next item: penalize the gap.
            score += 0.15 * (nxt - pr);
        }
    }

    // --- Relative-to-mean coupling ---
    // Tighter-than-average bins should be consumed first; roomy bins
    // (including the fresh-bin candidate) are kept for larger future items.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.2 * diff;
    } else {
        score += 0.1 * (-diff);
    }

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild penalty so a new bin only wins when fits into open bins are poor.
        score += 3.0 + 2.0 * progress;
    } else if fitting_bins_count == 1 {
        // Last chance: using this bin avoids opening a new one.
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize wasted space, with diminishing returns for very tight fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (cap - pr).max(0.0) * 0.01;

    // Reward tight fits: fill fraction of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 18.0 * fill * fill;

    // Penalize leaving dead space that likely no future item (>=1) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 3.0; // next item won't fit here; bin likely closes anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item is large
    // relative to capacity (poor fit prospects elsewhere) or many bins are already open.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_penalty = 30.0
            - 20.0 * size_frac
            - 10.0 * (1.0 - progress)
            - 2.0 * open_bins_count as f64;
        score += new_bin_penalty.max(-15.0);
        // An empty bin leaves residual == capacity; if item is huge, residual after is small.
        if post_residual <= 20 {
            score -= 8.0; // big item nearly fills a fresh bin: good
        }
    } else {
        // Compare against mean residual: prefer bins with below-average residual (tighter bins)
        // to consolidate space into fewer, fuller bins.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0 * ((bin_residual as f64 - mean_residual) / cap);
        }
    }

    // Late-stream consolidation: as the stream ends, prefer fuller bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = base * (1.0 + 0.6 * progress * base);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= (1.0 - base) * (1.0 - base) * (0.5 + 0.8 * progress);

    // Penalize dead space that cannot fit the next item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 1.4 * gap * gap * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.8;
    }

    // New-bin candidate: mildly penalize unless residuals across bins are low
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.9 - 0.7 * tightness * tightness + 0.15 * progress;
    }

    // Mild penalty for large spread of this bin residual vs mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.2 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(2.0));

    // Harmonic class of post_residual: modulo classes of capacity fractions.
    // Residuals that are "usable" (>= 10, multiples of 10) are less penalized.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 25.0; // perfect closure: excellent
    } else if class == 0 {
        score -= 8.0; // round residual: easy to fill later
    } else if class <= 3 {
        score += 6.0; // small dead space risk
    } else {
        score += 3.0;
    }

    // Integer-division thresholds: residual buckets via pr / 20.
    let bucket = pr / 20; // 0..=5
    score += bucket as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let nxt_class = (pr - next_item_size) % 10;
            score -= 12.0;
            if nxt_class == 0 { score -= 5.0; }
        } else {
            score += 5.0; // next item cannot use this residual
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a penalty unless item is large
    // or few bins are open (avoid bin proliferation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size > bin_capacity / 2;
        let mut new_bin_penalty = 35.0;
        if large_item { new_bin_penalty -= 25.0; }
        if open_bins_count == 0 { new_bin_penalty -= 40.0; }
        new_bin_penalty += 15.0 * progress;
        if next_item_size > 0 && next_item_size > item_size && item_size > bin_capacity / 3 {
            new_bin_penalty -= 10.0; // next bigger item may need fresh space anyway
        }
        score += new_bin_penalty;
    }

    // Slight bias by mean residual: if open bins are already tight, prefer
    // spreading (favor this bin less if its residual is above mean).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are nearly unusable later.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 20 {
            score += 25.0;
        }
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Pressure from number of open bins: discourage spreading into many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this gap: penalize moderately
        score += 8.0;
    }

    // Prefer bins below mean residual (consolidate fullness).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly prefer filling a bin exactly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Usable leftover for the next item: mild reward scaled by tightness.
            score -= 80.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space relative to the next item: penalize more as step advances.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 60.0 * (1.0 - post_residual as f64 / next_item_size as f64) * (0.5 + progress);
        }
    }

    // Relative to mean residual: prefer bins already tighter than average (packing dense bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item would leave
    // an awkward residual everywhere (implicit via the above bonuses). Base penalty:
    if bin_residual == bin_capacity {
        score += 200.0;
        // But if next item is large and would fit in a fresh bin's residual, soften slightly.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 100.0;
        }
    }

    // Mild preference for keeping the number of open bins low (favor existing bins).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins that absorb a large fraction of their remaining space (tight fit).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill_ratio;

    // Lookahead chaining: if the next item also fits here, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 9.0;
        // Extra reward if next item nearly fills what remains (perfect chain).
        let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 4.0 * chain_tightness;
    } else if next_item_size > 0 {
        // Dead-space penalty: leftover space the known next item cannot use.
        let dead = post_residual as f64;
        score += 0.04 * dead * dead / 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize the brand-new empty bin candidate unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // If mean residual is small, open bins are tight -> new bin is reasonable.
        score += 14.0 - 10.0 * fragmentation.min(1.0);
    }

    // Coupling with global state: prefer placing into bins whose residual deviates
    // from the mean (consolidate extremes, reduce fragmentation).
    let dev = (mean_residual - post_residual as f64).abs();
    score += 0.08 * dev;

    // Dynamic time horizon: later in the stream, be slightly greedier about tight fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * t;

    // Mild penalty for very small unusable leftovers (< 10 cannot hold any item).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = it / cap;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.35 * fit_ratio * (1.0 - pr_norm));

    // Non-linear polynomial coupling of post_residual with stream progress:
    // mid-stream, tightening is rewarded more strongly; late stream, exact fits dominate.
    let coupling = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 40.0 * coupling * (0.4 + 1.2 * progress);

    // Tightness reward: superlinear preference for small post-residual
    score -= 12.0 * (1.0 - pr_norm).powi(3) * (0.5 + progress);

    // Penalize leaving dead space that likely cannot fit future items
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0 + 10.0 * (1.0 - pr_norm);
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: strongly discouraged unless item is huge relative to capacity
    if bin_residual == bin_capacity {
        let size_pressure = ((it - 1.0) / 99.0).powi(2);
        score = 60.0 + 30.0 * (1.0 - size_pressure) - 20.0 * size_pressure * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base preference: minimize wasted space, but avoid leaving tiny unusable slivers.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // Dead space: a sliver no item (min size 1..10) may use efficiently.
        score += 12.0 * (10.0 - pr) / 10.0;
    }

    // Harmonic class logic: classify post_residual into modulo-classes of common item sizes.
    // Items 1..100: good residuals are those matching typical next-item sizes.
    let class_bonus = |r: u32| -> f64 {
        if r == 0 { return 6.0; } // perfect fit
        // reward residuals that are "harmonious" with common item magnitudes
        let m10 = (r % 10) as f64;
        let harmonious = if r % 25 == 0 { 4.0 }
        else if r % 20 == 0 { 3.0 }
        else if r % 10 == 0 { 2.0 }
        else if m10 >= 5.0 { 0.5 }
        else { 0.0 };
        harmonious * (r as f64 / cap)
    };
    score -= class_bonus(post_residual);

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size < post_residual {
            // reward proportional closeness of fit for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; residual is pure waste relative to lookahead
            score += 0.03 * pr;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only good when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Default penalty so we prefer reusing open bins with decent fits.
        let mut penalty = cap * 0.55;
        // If no other bin fits, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            penalty = -5.0;
        } else {
            // If the best alternative leaves lots of waste, allow opening a new bin.
            // Approximate: if item is large relative to mean residual slack.
            let mean_slack = mean_residual - item_size as f64;
            if mean_slack < 0.0 {
                penalty = -3.0; // nothing really fits well
            } else if (mean_slack - post_residual as f64).abs() < 5.0 && post_residual < 15 {
                penalty -= 4.0; // current fits are equally bad; fresh bin gives full flexibility
            }
            // Early in stream, fresh bins are cheap; late, conserve.
            let progress = step_index as f64 / total_items.max(1) as f64;
            penalty += 20.0 * progress;
        }
        score += penalty;
    }

    // Mild preference to fill bins with larger residual spread (balance across bins).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large ones.
    let usable = post_residual >= next_item_size && next_item_size > 0;
    if next_item_size > 0 && !usable {
        // Gap too small for the next item: heavy penalty scaled by gap smallness.
        let gap_ratio = post_residual as f64 / next_item_size as f64;
        score += (1.0 - gap_ratio).max(0.0) * 40.0 + 10.0;
    }

    // Reward very tight fits (low waste) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmentation;
    // with few open bins, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (1.0 + progress) * 2.0;

    // New-bin candidate: baseline attractiveness so a new bin is chosen only
    // when all open bins look bad (their dead-space penalties push below this).
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post-residual space -> moderate reward, scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.15;
    }
    // Next item cannot use the leftover space -> penalize dead space, worse for tiny leftovers.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Penalize small unusable residuals (dead space < minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (better fits).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Late in the stream, avoid opening new bins; early, allow consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when other bins fit.
        score += 35.0 + 40.0 * progress;
    }

    // Mild preference for filling already-open bins when many are open.
    if open_bins_count > 4 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space nonlinearly
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // Reward tight fits (small post_residual relative to bin)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 50.0 * tightness * tightness;

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // Wasted capacity for the known next item
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    // and no good alternatives exist (encourage consolidation for small items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is cheap for big items late in the stream, expensive for small ones
        score += 300.0 - 250.0 * item_frac - 100.0 * progress;
        // If many bins are open already, opening yet another is worse
        score += 5.0 * open_bins_count as f64;
        // If few bins can fit the item, opening fresh is more acceptable
        score -= 40.0 * (fitting_bins_count as f64);
    }

    // Global state coupling: prefer bins with residual far from the mean
    // (normalize outliers toward balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Time horizon: late in stream, be more greedy about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * tightness;

    // Slight preference for bins with less residual generally (fill fuller bins first)
    score += 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post residual, with non-linear squashing
    let mut score = post * (1.0 + 0.6 * (post / cap).powi(2));

    // Reward tight fits (fit_ratio near 1) via smooth coupling with progress
    score -= 12.0 * fit_ratio.powi(3) * (1.0 + progress);

    // Penalize very small post residuals that create dead space unless fit is tight
    let dead = (post / cap).powi(2);
    score += 20.0 * dead * (1.0 - fit_ratio);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean residual coupling: prefer bins below mean residual (consolidation)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits the post residual, reward; else penalize
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0 * (1.0 - (next_item_size as f64 / post.max(1.0)));
        } else {
            score += 5.0 * ((next_item_size as f64 - post) / cap);
        }
    }

    // Stream progress: later in stream, be greedier about tight fits
    score *= 1.0 - 0.15 * progress * (post / cap);

    // New-bin candidate: discourage unless it's genuinely attractive
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress + (open_bins_count as f64) * 0.5;
        // If no existing bin fits, the new-bin call is the only option anyway
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Small classes (tiny leftovers) are good.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if frac <= 0.10 {
        score -= 120.0;
    } else if frac <= 0.25 {
        score -= 40.0;
    } else if frac <= 0.5 {
        score -= 10.0;
    } else {
        // Large leftover: dead-space penalty, worse for big items wasted.
        score += 20.0 + 0.5 * (item_size as f64);
    }

    // Harmonic integer-division classes of post_residual (mod arithmetic).
    let class = post_residual / 10; // 0..=10 harmonic bucket
    score -= (10 - class as i32) as f64 * 2.0;

    // Lookahead coupling: reward leaving a residual that the next item can use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain: next item exactly fills the remainder.
            if slack == 0.0 {
                score -= 250.0;
            } else if slack <= 10.0 {
                score -= 60.0;
            } else {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += 0.3 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 0.2 * (bin_residual as f64);
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scaled by how many bins already fit.
        let mut new_bin_score = cap * 0.9; // start high
        if fitting_bins_count == 0 {
            new_bin_score -= 400.0; // must open a bin
        } else if fitting_bins_count == 1 {
            // Compare: only open if the existing candidate leaves bad residue.
            new_bin_score -= 50.0;
        } else {
            // Many alternatives: opening new bins fragments capacity.
            new_bin_score += 30.0 * (open_bins_count as f64).sqrt();
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 100.0 * progress;
        // If mean residual across open bins is large, opening a bin is wasteful.
        new_bin_score += 0.5 * mean_residual;
        score = score.min(new_bin_score) * 0.0 + if bin_residual == bin_capacity { new_bin_score } else { score };
    }

    // Mild preference for tighter (more filled) bins overall.
    score -= 0.1 * ((bin_capacity - bin_residual) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // minimum item (1..=10) are pure waste. Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    }

    // Gaps below the current item size that also can't fit the next item
    // are doubly useless; add a coupling penalty.
    if post_residual > 0 && post_residual < item_size as u32 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 8.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer compacting into existing bins
    // rather than spreading out; new-bin candidate gets penalized.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 1.5;
    } else {
        score -= open_bins_count as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 5.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = score * (1.0 + 0.005 * (item_size as f64));

    // 2-step lookahead: reward when post_residual exactly matches next item,
    // or when next item can fit into the post residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let p = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step match: chain placement
        } else if post_residual >= next_item_size {
            // reward proportional closeness of match
            score -= 25.0 * (1.0 - ((p - n) / bin_capacity as f64));
        } else {
            // next item won't fit here; penalize leftover dead space
            score += 8.0 * (n - p).min(60.0) / 10.0;
        }
        // Bonus if next item fits and post_residual is small but usable
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    } else {
        // Last item: minimize post residual strongly
        score += 20.0;
    }

    // Relative to mean residual: bins with residual far below mean are tight; prefer them.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless current item is large relative to capacity
    // or no good fits exist (fitting_bins_count small).
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty when many bins already open and this placement wastes space
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect fill
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward dead zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residuals (non-linear).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating dead space that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.25;
    }
    // Reward leaving space exactly usable by the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as f64 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: discourage opening a new bin when a
    // reasonable fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Large items (hard to place later) justify a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Global balance: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, preserving future flexibility).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    // Mild preference for fuller bins (smaller residual before placement).
    score += (bin_capacity - bin_residual) as f64 * -0.05;

    // Slight pressure to keep the number of open bins manageable.
    score += open_bins_count as f64 * 0.02;

    // Lookahead coupling: if the next item is large, avoid leaving
    // medium-size gaps; either leave a lot or a little.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if gap > next_item_size as f64 && gap < next_item_size as f64 + 15.0 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: post-residual normalized by capacity, warped polynomially
    let pr_norm = post_residual as f64 / bin_capacity as f64;
    let warp = pr_norm * pr_norm * (3.0 - 2.0 * pr_norm); // smoothstep-like in [0,1]
    score += 8.0 * warp * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - warp) * (0.5 + progress);

    // Penalize bins whose residual deviates from the mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 6.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - gap * gap);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; slight penalty scaled by overshoot
        let over = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 5.0 * over;
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 3.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quarter-classes of capacity.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..=4
    let next_class = next_item_size / quarter; // 0..=4 (0 means no lookahead)

    // Reward tight fits (small post_residual) strongly, non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 40.0 * tightness * tightness;
    }

    // Harmonic coupling: if the next item fits exactly in the post-residual,
    // big reward; if post-residual is a "dead class" (too small for any item
    // of size >= 1 but next item doesn't fit), penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can follow into this bin: reward proportional to fit quality.
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 - (slack_after_next as f64) * 0.2;
        } else {
            // Post-residual becomes dead space relative to the next item.
            // Penalize dead space in harmonic classes: class 0 (tiny) is worst.
            let dead = post_residual;
            let class_penalty = match post_class {
                0 => 30.0,
                1 => 18.0,
                2 => 10.0,
                _ => 4.0,
            };
            score += class_penalty + (dead as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new empty bin mildly; the empty-bin candidate gets
    // score = post_residual (= capacity - item), so we bias open bins to win
    // when their post_residual is not much worse.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open,
        // and to how "early" in the stream we are (encourage consolidation later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 8.0 * (1.0 - progress);
    } else {
        // Existing bin: small reward scaled by how much better than mean residual.
        if (post_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Modular threshold: post_residual divisible by 10 tends to be reusable
    // for round item sizes; give a small harmonic bonus.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Integer-division threshold: avoid leaving residuals in (0, 10) — unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using existing bins (penalize opening new bins) proportional to open bin pressure.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize more when many bins are already open.
        score += 25.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 8.0;
        // Last-chance bin: strongly favor filling it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if post-residual is too small for the next item (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight late-stream tightening: prefer compact usage as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: strongly reward perfectly filling a bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead matching: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement; reward tighter residual that still fits next item.
            score -= 40.0 + 0.5 * (bin_residual - post_residual) as f64;
            // Extra reward if next item exactly fills the bin afterwards.
            if post_residual == next_item_size {
                score -= 120.0;
            }
        } else {
            // Penalize creating dead space that cannot host the next item,
            // scaled by how much of the next item would be wasted.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Small-residual penalty: discourage leaving tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // penalize consuming them unless the fit is good.
    let mean_r = mean_residual.max(0.0);
    if (bin_residual as f64) < mean_r {
        score += 0.3 * (mean_r - bin_residual as f64);
    } else {
        score -= 0.15 * (bin_residual as f64 - mean_r);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score slightly above
    // post_residual, so it only wins when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * item_size as f64;
        // Late in the stream, be more willing to open new bins (keeps options open).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
    }

    // Many open bins: mild pressure to consolidate into existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        // If current bin is a poor fit (large post_residual), new bin becomes better.
        if post_residual > 40 {
            score -= (post_residual as f64 - 40.0) * 0.8;
        }
        // Fewer open bins => opening is cheaper.
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // Late in stream, prefer packing into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Global state: when mean residual is high, prefer filling the fullest bins
    // (small residual) to consolidate; when mean residual is low, be lenient.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth progress coupling: late in the stream, compactness matters more.
    let late = progress * progress;
    score -= 8.0 * late * norm_item * (1.0 - norm_post);

    // Reward near-perfect fits with a smooth bump.
    let tight = 1.0 - norm_post;
    score -= 12.0 * tight * tight * tight;

    // Lookahead: reward leaving space usable by the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (norm_post - norm_next).abs();
        score -= 6.0 * (1.0 - gap) * (norm_next * (1.0 - norm_next));
    }

    // Penalize deviating too far from the mean residual of open bins (balance pressure).
    score += 3.0 * (norm_post - mean_norm).abs();

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + late);
    }

    // Mild pressure against proliferating bins early.
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate handling: empty bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - tight) - 10.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // This open bin is the only existing bin that can take the item
    // (the residual < capacity check excludes the brand-new-bin candidate).
    let last_chance = fitting_bins_count == 1 && bin_residual < bin_capacity;

    // Harmonic stacking class: does the lookahead item also fit here after placement?
    let stackable = next_item_size > 0 && post_residual >= next_item_size;

    let mut score;

    if stackable {
        // Tier 1: both current and next item fit in this bin.
        // Dominant tier: stacking two items into one bin beats splitting them
        // across bins whenever it is feasible (concentrates free space).
        score = post - 1000.0;
        // Perfect pairwise fill: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // Tier 2: next item cannot follow into this bin.
        // Base: best-fit on post residual. The uniform +nxt shift raises the
        // whole tier above any stacking bin (incl. a fresh bin where the next
        // item would fit), without distorting ranking inside the tier.
        score = post + nxt;
        // Harmonic class tiebreak: round residual classes (multiples of 10)
        // are marginally more reusable by future items.
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 0.75;
        }
    }

    // Last-chance reward: strongly prefer consuming the final fitting open bin
    // over fragmenting capacity into a new bin (unless tier-1 stacking overrides).
    if last_chance {
        score -= 40.0;
    }

    // Negligible consolidation tiebreak: mildly favor bins tighter than the mean.
    score += (mean_residual - bin_residual as f64) * 1e-4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest possible item (1) are pure waste; residuals below the
    // lookahead item are likely dead too.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // likely dead for the next item
    }

    // Reward tight fits (small fill ratio of leftover).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, tolerate opening new bins less.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: neutral-ish base, only attractive when all open bins
    // would create dead space or the fit is poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 + 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere, must open
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // room for lookahead pairing
        }
    }

    // Slight preference for bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in the stream: prioritize closing bins out (zero residual) harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strongly favor.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 40.0;
        } else if diff <= 5 {
            score -= 20.0 - 2.0 * diff as f64;
        } else {
            // Penalize residuals too small for the next item (dead space risk).
            if post_residual < next_item_size {
                score += 0.5 * (next_item_size - post_residual) as f64;
            } else {
                score += 0.1 * (post_residual - next_item_size) as f64;
            }
        }
    }

    // Relative to mean residual: bins below mean residual are tighter, prefer them.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residual would be tiny unusable waste
    // or when many bins are open with slack. Penalize opening new bins mildly.
    if bin_residual == bin_capacity {
        let waste = if next_item_size > 0 && post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += 25.0 - 0.8 * waste;
        score += 0.2 * open_bins_count as f64;
    }

    // Progression: slightly prefer consolidation early, tighter fits later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Progress of the stream (0..1), guarded against division issues.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Base: prefer leaving small post-residual (tight fit).
    let mut score = post;

    // Tightness reward: extra bonus when the item nearly fills the bin.
    let fill_ratio = item / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space: residuals in a "dead zone"
    // (small but nonzero) are hard to reuse for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: reward if the next item can exactly use the
    // post-residual; penalize if next item cannot fit into it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < f64::EPSILON {
            score -= 25.0; // perfect chaining
        } else if nxt > post {
            score += 6.0 * (nxt - post) / cap; // dead space for lookahead
        } else {
            score -= 4.0 * (post - nxt) / cap; // next item still fits
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global state: if many bins are open with slack, discourage opening
    // new bins; handled via new-bin penalty below and mild reward here
    // for consolidating into existing slack.
    let mean_res = mean_residual;
    if bin_residual != bin_capacity {
        // Using an existing bin: reward proportional to how much slack
        // this bin has relative to the mean slack (consume the outliers).
        score -= 5.0 * (res - mean_res) / cap;
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases as stream progresses
        // (late in the stream, consolidation matters more, so keep the
        // cost higher then).
        let mut new_bin_cost = 30.0 + 25.0 * progress;

        // If several bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            new_bin_cost += 20.0 * (fitting_bins_count as f64 - 1.0);
        }

        // A brand-new bin is attractive when the item is huge and would
        // leave unusable slivers everywhere, or when it's a perfect fit.
        if post_residual == 0 {
            new_bin_cost -= 40.0; // perfect fit in fresh bin
        } else if item_size >= 60 {
            new_bin_cost -= 15.0; // large items pair well with fresh bins
        }

        // If the only fitting bin is nearly full and the item barely fits,
        // allow a new bin.
        if fitting_bins_count == 1 && item_size > 70 {
            new_bin_cost -= 10.0;
        }

        score += new_bin_cost;
    }

    // Mild time-horizon shaping: early in the stream, be slightly more
    // liberal with tight fits (exploration); late, be conservative and
    // prioritize zero-waste placements more strongly.
    score -= 8.0 * (1.0 - progress) * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr as f64;

    // Smooth non-linear penalty on large dead space (quartic-ish growth).
    score += 12.0 * norm_pr * norm_pr * cap;

    // Polynomial coupling with stream progress: later in the stream,
    // waste matters more (fewer chances to fill gaps).
    let progress_coupling = (progress * progress * (3.0 - 2.0 * progress)); // smoothstep
    score += 20.0 * progress_coupling * norm_pr * cap;

    // Reward using nearly-full bins (small residual) more strongly.
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // More alternatives -> slight penalty for consuming a scarce-fit bin.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits, but leaves waste; mild reward scaled by fit quality.
        let fit_quality = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * fit_quality;
    } else if next_item_size > post_residual {
        // Post-residual too small for next item: penalize dead space creation.
        score += 6.0 + 0.15 * pr;
    }

    // Interaction with mean residual: placing into a bin well below the mean
    // residual helps balance open bins; slight reward.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * dev;

    // New empty bin candidate: penalize unless it's early or item is huge
    // (poor fit everywhere). Smooth gating via item size and progress.
    let is_new_bin = (bin_residual as u32 == bin_capacity) && (item_size as u32 != bin_capacity || bin_residual == bin_capacity);
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let openness = 1.0 - progress_coupling;
        score += 35.0 - 25.0 * size_frac * size_frac - 15.0 * openness;
        // If only this bin fits, opening a new one is forced anyway.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional capacity class of the post-residual (harmonic classes)
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize post-residuals that fall into "dead zone" classes: too small
    // to accept typical future items but too large to call the bin full.
    if post_residual > 0 {
        // Harmonic class via integer division thresholds on post_residual
        let class = post_residual / 10; // classes: 0..9
        // Dead-space classes: residuals 1..=9 and 11..=19 are hard to reuse
        if class == 0 {
            score += 30.0; // tiny unusable sliver
        } else if class == 1 {
            score += 12.0;
        } else if class == 2 {
            score += 5.0;
        } else if class >= 3 && class <= 5 {
            score -= 3.0; // reusable mid-range residual
        } else if class >= 6 && class <= 8 {
            score -= 6.0; // large reusable residual
        } else {
            score -= 2.0; // class 9: nearly empty bin, fine
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit: subtract proportional bonus, stronger if exact-ish
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty scaled by how close we were
            score += 4.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Spread pressure: when many bins are open, prefer bins below mean residual
    // (keeps residuals balanced, avoiding many half-full bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev * (0.5 + 0.5 * progress);

    // New-bin candidate handling: only attractive when no open bin is decent
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let pressure = if fitting_bins_count == 0 {
            60.0
        } else if fitting_bins_count == 1 {
            // competing with a last-chance bin: keep new bin mildly unattractive
            10.0
        } else {
            25.0
        };
        // Late in the stream, opening new bins is less costly
        score = pressure - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // A post_residual that is too small for typical future items (<= ~15)
    // is nearly guaranteed dead space, so penalize it hard.
    let dead_threshold = 15.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0; // unusable sliver penalty
    }

    // Reward tight fits (small positive post_residual that is still usable).
    if pr > 0.0 && pr >= dead_threshold {
        score -= (bin_capacity as f64 - pr) * 0.15; // prefer fuller bins
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let open_pressure = (open_bins_count as f64) * 2.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, plus expected waste.
        score += 40.0 + open_pressure;
        // If item would leave a large gap in a fresh bin relative to residual
        // pattern of open bins, penalize slightly.
        if (pr > 0.0 && pr < dead_threshold) && fitting_bins_count >= 1 {
            score += 20.0; // fresh bin would also create a sliver
        }
        // If next item fits the post_residual of this fresh placement, soften.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 15.0;
        }
    } else {
        // Existing bins get a small bonus to be preferred over new bins.
        score -= 10.0;
        // Reward leaving room for the lookahead item when possible.
        if next_item_size > 0 {
            let n = next_item_size as f64;
            if n <= pr {
                score -= 8.0;
            } else if pr > 0.0 {
                score += 5.0; // blocks the lookahead item
            }
        }
        // Slight preference for bins below mean residual (balance load).
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual is already low score).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: residual too small for any plausible item (min size 1, but
    // practically items >= 10 in classic streams; use a soft threshold around 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - next_fit / (bin_capacity as f64));
        // Bonus if next item fills the bin almost perfectly (chain packing).
        if next_fit < 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally to next item size.
        score += 0.10 * next_item_size as f64;
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    // (low residual relative to mean means this bin is a good "closer").
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative to capacity
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score += 18.0;
        // Large items justify a fresh bin (avoid fragmenting open bins).
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 22.0;
        }
        // If many bins fit the item, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64);
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild penalty per open bin: discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high residual utilization efficiency quadratically.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item fits within post residual, mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 8.0;
    }
    // If next item would NOT fit in post residual but this bin is nearly full anyway, small bonus.
    if next_item_size > post_residual && post_residual < 15 {
        score -= 5.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    // or the current item leaves awkward space in existing bins.
    if bin_residual == bin_capacity {
        // Base new-bin score: keep it competitive but slightly worse than a good fit.
        score = (bin_capacity - item_size) as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early on, opening bins is cheap; later, prefer squeezing into existing bins.
        score -= 20.0 * (1.0 - progress);
        // If many bins are open with high mean residual, prefer reusing them.
        if open_bins_count > 0 {
            score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        }
        // If no existing bin leaves room for the next item after this placement, favor new bin.
        if next_item_size > 0 {
            let needs_new = fitting_bins_count == 0
                || (fitting_bins_count == 1 && bin_residual - item_size < next_item_size);
            if needs_new {
                score -= 15.0;
            }
        }
    }

    // Global pressure: when many bins are open, discourage wasting space in existing bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is far above mean residual, it's a good target.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 6.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = pr / cap;
    let tightness = 1.0 - fit_norm;

    // Base: reward small post-residual, with non-linear (quadratic) shaping
    let mut score = pr * (1.0 + 0.5 * fit_norm * fit_norm);

    // Tight fits are disproportionately valuable: subtract a smooth cubic reward
    score -= 20.0 * tightness.powi(3);

    // Stream progress coupling: later in the stream, tolerate larger residuals less
    // (dead space is costlier as the stream ends), smooth polynomial interaction
    score += pr * 0.8 * progress * progress;

    // Interaction: perfect fit reward grows with progress
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - fit_norm);
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 18.0;
        } else if nxt <= pr {
            // next item fits: mild reward proportional to how well it uses the space
            score -= 8.0 * (nxt / pr.max(1.0));
        } else {
            // next item won't fit: penalize leaving a residual just below next size
            let waste = (nxt - pr) / cap;
            score += 12.0 * (1.0 - waste).max(0.0);
        }
    }

    // Mean residual context: prefer bins whose residual is close to the mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for spreading across too many open bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate handling: only attractive for large items with poor fits elsewhere
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        score += 15.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 and mod 20.
    // Small post_residuals are "tight fits" -> reward them strongly.
    let cls10 = post_residual % 10;
    let cls20 = post_residual % 20;

    // Tight-fit reward: post_residual in {0,1,2} is nearly perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals in (10, 20) exclusive cannot hold the
    // smallest item (size >= 1 guaranteed, but typical min ~10 in streams with
    // large items); penalize unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Modulo-20 harmonic alignment: residuals that are multiples of 20 pair
    // well with mid-size items.
    if cls20 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if cls10 == 5 && post_residual >= 15 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack <= 5 {
            score -= 18.0;
        }
        // Next item leaves a good harmonic residual too.
        if slack % 10 == 0 && slack > 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty proportional to overshoot class.
        let over = (next_item_size - post_residual) / 10;
        score += (over as f64) * 3.0;
    }

    // Last-chance bonus: this is the only fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin gets a neutral-ish baseline.
    // Only prefer opening a new bin when the item is large relative to capacity
    // (poor fit anywhere) and many bins are open (fragmentation risk).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if frac > 0.5 && open_bins_count > 3 {
            score -= 10.0 + 15.0 * frac + 10.0 * progress;
        } else {
            score += 12.0; // discourage wasting a fresh bin on easy fits
        }
    }

    // Mild pressure toward consolidation as the stream progresses.
    score += 0.02 * (step_index as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps smaller than the minimum item size
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Non-linear dead-space penalty: small residuals are hard to fill
    let pr = post_residual as f64;
    score += 40.0 * (1.0 - pr / bin_capacity as f64).powi(4);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Pressure from many open bins: discourage opening new bins when bins are plentiful
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Mild preference for bins below mean residual (tighter bins)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Progress-coupled tightening: as stream advances, penalize waste more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post-residual can at least fit the next item: mild reward scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * (post_residual - next_item_size) as f64;
    }
    // Post-residual is nonzero but too small for the next item: dead-space penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * post_residual as f64;
    }
    // Zero post-residual is a perfect fill: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: bins with residual below mean are "tighter",
    // prefer filling tighter bins to consolidate waste.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Progress factor: late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Brand-new empty bin candidate: penalize opening a new bin unless it enables
    // a good lookahead chain or existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fills (high fill ratio subtracts from score).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * cap * 0.6;

    // Lookahead: penalize leaving residue that cannot host the next item,
    // mildly reward residues close to next_item_size (usable space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 6.0 + 0.1 * (nxt - post_residual as f64);
        } else {
            score -= 0.05 * (post_residual as f64 - nxt).abs().min(30.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New empty bin candidate: penalize mildly, discount for large items
    // and when few bins fit the item (poor alternatives).
    if bin_residual == bin_capacity {
        score += 10.0
            + 0.15 * open_bins_count as f64
            - 0.08 * item_size as f64
            - 5.0 * (fitting_bins_count as f64).min(3.0);
    }

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing bins (penalize new space creation).
    score += 0.02 * mean_residual;
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0).min(10.0);
    }

    // Time horizon: later in the stream, weight tightness more aggressively.
    score *= 1.0 + 0.25 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post; // base: prefer tight fits

    // Non-linear coupling: reward small post_residual super-linearly
    let x = post / cap; // normalized post residual
    score += 12.0 * x * x * (1.0 - x) * cap * 0.1;

    // Penalize large dead space quadratically, modulated by progress
    score += 0.05 * x * x * cap * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin, more when open bins fit
    if bin_residual == bin_capacity {
        score += 40.0 + 15.0 * (open_bins_count as f64).sqrt();
        // But if this bin would otherwise be a poor fit elsewhere, relax penalty
        let waste = (post - next_item_size as f64).max(0.0);
        if next_item_size > 0 && waste < 5.0 {
            score -= 30.0;
        }
    }

    // Lookahead: penalize leaving residual that barely fails next item
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score += 8.0 * (1.0 - gap / 10.0);
        }
        // Reward residual that fits next item exactly-ish
        if gap >= 0.0 && gap < 3.0 {
            score -= 6.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are hard to fill later -> penalize.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty: residue below the smallest plausible item (<=10)
    // is pure waste; residues in [1,10] get escalating penalties.
    if pr == 0 {
        score -= 40.0; // perfect fit is always excellent
    } else if pr < 10 {
        score += (10 - pr) as f64 * 6.0; // tiny dead space is very bad
    } else if pr < 20 {
        score += 8.0;
    } else if pr < 35 {
        score += 2.0;
    }

    // Modulo-10 harmonic class: residues divisible by 10 pair well with
    // typical item granularities -> reward them.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Integer-division thresholds: can the next item fit here afterward?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits in the post residual: chain two placements.
            let chained = pr - next_item_size;
            score -= 12.0;
            // Extra reward if the double placement leaves near-zero waste.
            if chained == 0 {
                score -= 15.0;
            } else if chained < 10 {
                score += 5.0; // but avoid triple-dead-space creation
            }
            // Harmonic class match: next_item and item share residue class
            if next_item_size % 10 == item_size % 10 {
                score -= 3.0;
            }
        } else {
            // Next item cannot follow here; if this bin is the only option,
            // using it now is forced -> mild reward to avoid new bin.
            if fitting_bins_count == 1 {
                score -= 10.0;
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bin logic: strongly prefer consuming nearly-full bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when open bins are tight or item is large.
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap; // fraction of space left on average
        let item_frac = item_size as f64 / cap;
        if open_bins_count == 0 {
            score -= 50.0; // must open a bin
        } else if item_frac > 0.6 {
            // Large items fit poorly in fragmented bins; fresh bin is good.
            score -= 18.0 * item_frac;
        } else if tight < 0.25 {
            // Open bins nearly full overall -> new bin reasonable.
            score -= 8.0 * (0.25 - tight) * 4.0;
        } else {
            // Plenty of room elsewhere -> discourage opening a new bin.
            score += 25.0 * tight;
        }
    }

    // Progress-based shaping: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (prf / cap) * 5.0;

    // Mild tie-break toward bins tighter than average (best-fit flavor).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (min item size is small, but tiny gaps rarely get matched). Penalize
    // gaps in the "dead zone" super-linearly.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64);
    } else if post_residual > 15 && post_residual <= 25 {
        score += 10.0;
    }

    // Reward tight fits (exact or near-exact fill).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 15 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual <= 15 {
        // Next item can't use this gap: dead space confirmed.
        score += 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or
        // late in the stream; also penalize if any open bin could fit.
        score += 30.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Opening a bin is fine if it promises a good future pairing.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    } else {
        // Mild reward for using already-open bins proportional to crowding.
        score -= 0.5 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (drain the fullest bins first, keep average low).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (zero dead space).
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item cannot use (dead space).
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Compare against mean residual: prefer bins tighter than average.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // New bin is acceptable if the item leaves a useful remainder for lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Slight preference for packing into bins with more open bins (consolidation).
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space: residuals just above small-item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 6.0; // awkward gap zone
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.15 * next_item_size as f64;
    }
    // If next item would NOT fit here but this bin could still hold it now,
    // slight penalty for leaving a stranded mid-size gap.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.08 * post_residual as f64;
    }

    // Prefer filling bins with larger residual when many bins are open (consolidation).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Penalize opening new bins when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (future items can use them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    } else {
        // Mild preference for using existing bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Slight penalty when many bins are open: encourage closing bins out.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fits win (post_residual small => low score).
    let mut score = pr;

    // Non-linear coupling: squared residual normalized, weighted by stream progress.
    // Late in the stream, dead space becomes more costly.
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress) * cap * 0.1;

    // Reward near-perfect fits with a smooth cubic dip.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits exactly (or well) into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let next_fit = 1.0 - ((pr - nxt) / cap);
            score -= 6.0 * next_fit * next_fit;
        } else {
            // Next item won't fit here: penalize proportionally to leftover unusability.
            let gap = (nxt - pr) / cap;
            score += 5.0 * gap * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Coupling with mean residual: placing into a bin far below mean residual wastes spread space.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev.abs();

    // New-bin candidate handling: empty bin gets a moderate default score so it only wins
    // when all open bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space class penalty: residuals that can never fit the smallest item (<=10)
    // are worthless. Use modulo/harmonic classes on post_residual.
    let small_item_floor = 10u32;
    if post_residual < small_item_floor {
        score += 40.0 + (small_item_floor - post_residual) as f64 * 2.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // granularity classes (multiples of 10) are preferred.
    let class = post_residual / 10;
    score -= (class % 3) as f64 * 1.5;

    // Tight fit reward: post_residual near zero but still >= smallest item is ideal.
    if post_residual >= 1 && post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward; if next item cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += ((next_item_size - post_residual) as f64).min(25.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item would leave a very awkward residual in every existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 30.0;
        // Reward new bin when item is large relative to capacity (better to
        // give big items fresh space) or when no bin fits well.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.6 {
            score -= 20.0 * fill_frac;
        }
        if post_residual >= small_item_floor && post_residual < 25 && fitting_bins_count >= 1 {
            // existing bins would leave a mid-range awkward residual -> prefer new bin
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    } else {
        // Mild preference for filling existing bins as stream matures.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress;
    }

    // Mean-residual coupling: penalize bins that deviate badly from the mean
    // (keeps residual distribution balanced across open bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Modulo threshold on item_size: items in awkward harmonic classes
    // (e.g. 25, 35, 45... leaving 5-class residuals) prefer tighter bins.
    if item_size % 10 == 5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for even the smallest item are pure waste.
    let dead_threshold = 3u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0;
    } else if post_residual >= dead_threshold && post_residual < 10 {
        score += 18.0; // risky small gap
    }

    // Reward tight fits (low post residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 20.0;
        } else if gap_after_next < dead_threshold {
            score += 10.0; // chains into a dead gap
        } else {
            score -= 5.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual context: if this bin is far above mean residual, it is a natural host.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // New empty-bin candidate: neutral base cost so it is chosen only when all fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, adjusted by context.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when current item barely fits anywhere anyway,
        // or when no open bin fits (fitting_bins_count would be 0 for open bins).
        score = bin_capacity as f64 * 0.75;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
        return score;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect match: post_residual exactly equals next item size.
        let diff = (pr - nxt).abs();
        score -= 60.0 / (1.0 + diff);

        // Post residual large enough for next item: good, small penalty for slack.
        if pr >= nxt {
            score -= 20.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // Next item won't fit here: dead space penalty scaled by gap.
            score += 0.5 * (nxt - pr);
        }
    } else {
        // Last item: minimize post residual (tight fit).
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: bins with more residual than average are
    // preferred targets (reduce score), tight bins penalized slightly.
    score -= 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Dead-space penalty for very small leftover space that is likely unusable
    // (small leftovers relative to typical item sizes).
    if post_residual > 0 && post_residual < 12 {
        score += 6.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this bin
    // (chaining placements); if not, slightly penalize leaving a "next-shaped" hole.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // This bin could have hosted the next item but we are blocking it
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when many items remain and few bins are open,
        // but expensive when it would fragment capacity late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = (open_bins_count as f64) / 10.0;
        // Base penalty so a new bin is only chosen when it beats poor fits.
        score += 8.0;
        // Late in the stream, or with many open bins, discourage new bins.
        score += 15.0 * progress + 10.0 * openness;
        // If a future item (lookahead) is large and this new bin would be the only
        // way to keep a big contiguous hole, mildly encourage it early on.
        if next_item_size > 0 && next_item_size > post_residual && progress < 0.5 {
            score -= 4.0;
        }
        // A new bin is attractive if the current item is large (poor fit anywhere).
        if item_size > bin_capacity / 2 {
            score -= 3.0;
        }
    } else {
        // Reward using bins that are already partly filled when the fit is decent,
        // scaled by how far below the mean residual this bin sits (prefer compacting
        // the emptiest-feeling bins to consolidate space).
        let gap = mean_residual - bin_residual as f64;
        score -= 2.0 * gap.max(0.0) / (bin_capacity as f64);
    }

    // Mild global pressure: with many open bins, favor filling existing ones.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Smooth stream-progress coupling: penalize residual more as stream matures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of residual with progress.
    let poly = 1.0 + 0.8 * progress + 1.6 * progress * progress;
    score *= poly;

    // Quadratic dead-space penalty: small residuals are disproportionately bad.
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Lookahead: reward bins whose post-residual fits the next item (smoothly).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            score -= 6.0 + 0.25 * slack * (0.5 + 0.5 * progress);
        } else {
            score += 4.0 + 0.15 * (-slack);
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 18.0 + 0.3 * (item_size as f64);
    }

    // Prefer tighter bins relative to the mean residual (smooth coupling).
    let mr = mean_residual.max(0.0);
    score -= 0.35 * (mr - pr) * (1.0 + progress);

    // Mild penalty for spreading across many open bins when bin is loose.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make it unattractive unless residual is tiny (poor fit fallback).
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class A: post_residual == 0 (perfect closure) -> huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }
    // Class B: dead zone (1..=9) -> unusable slivers, penalize quadratically.
    if post_residual >= 1 && post_residual <= 9 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 2.0;
    }
    // Class C: harmonic remainder classes mod 10: residuals congruent to small
    // values are hard to fill with typical items; odd classes are worse.
    let r10 = (post_residual % 10) as f64;
    score += r10 * 1.5;
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 4.0;
    }
    // Class D: integer-division thresholds: post_residual in [10,20) is a
    // "half-decade" pocket that many small items (10..20) can still fill.
    if (10..20).contains(&post_residual) {
        score -= 12.0;
    }
    // Residuals in [25,50) pair well with mid items.
    if (25..50).contains(&post_residual) {
        score -= 6.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how well it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + (20.0 - slack.min(20.0));
        } else {
            // Next item won't fit: penalize leaving a gap it almost fits.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += gap * 3.0;
            }
        }
    }

    // --- Last chance: only fitting bin -> prefer using it over new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }
    // Crowding: many fitting bins -> less urgency, mild penalty.
    if fitting_bins_count > 2 {
        score += 8.0 * (fitting_bins_count as f64).ln().max(1.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: only beats open bins that score badly.
        score = 60.0 + cap * 0.3;
        if next_item_size > 0 && next_item_size >= 40 {
            score -= 10.0; // big next item favors fresh bin
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open first bin
        }
    }

    // --- Stream progression: late in stream, close bins more aggressively ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // already "junk"; penalize adding to junk, reward filling rich bins.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res_f) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Strict dead-space penalty: gaps too small to hold the smallest possible item (size 1..min_size)
    // are pure waste; penalize them superlinearly.
    let min_item = 1u32;
    if post_residual < 10 && post_residual >= min_item {
        // unusable-ish gap under typical min item size
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Penalize post_residual values that can't fit the lookahead item if it could have fit here
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Reward leaving exactly enough room for the next item (chain fit)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins,
    // i.e., penalize the new-bin candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 18.0 + 2.5 * open_bins_count as f64;
    } else {
        // small reward for using existing bins when many are open
        score -= 0.3 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "scrap" bin; using it consolidates waste.
    let residual_f = bin_residual as f64;
    if residual_f + 0.5 < mean_residual {
        score -= (mean_residual - residual_f) * 0.8;
    } else {
        score += (residual_f - mean_residual) * 0.4;
    }

    // Early stream: be a bit greedy about opening bins; late stream: consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly (small leftover).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover <= 10 {
            score -= 35.0 - leftover as f64;
        } else {
            score -= 8.0;
        }
    }
    // Next item does not fit: penalize creating dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
        if post_residual < 10 {
            score += 10.0; // tiny dead space is nearly unusable
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Reward using bins whose residual is already below average (tightening).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when current bin is a bad fit
    // (large item, high post_residual spread) — otherwise discourage opening.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && post_residual == bin_capacity - next_item_size {
            score -= 45.0; // fresh bin perfectly fits next item too
        }
        if item_size > 70 {
            score -= 20.0; // big items benefit from a fresh bin
        }
    }

    // Late-stream consolidation: prefer tightest packing as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted if we place here (post_residual / capacity).
    let waste_frac = post_residual as f64 / bin_capacity as f64;

    // Non-linear waste penalty: quadratic in wasted space.
    score += 40.0 * waste_frac * waste_frac;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_tight = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - lookahead_tight / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving space the next item can't use (dead space risk).
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap * (1.0 + open_bins_count as f64 / 20.0) * (0.5 + progress);

    // New-bin candidate logic: empty bin scores as a fallback.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in the stream
        // and when existing bins are crowded.
        let mut new_bin_cost = 55.0;
        new_bin_cost -= 20.0 * progress;
        // If few bins fit the item, opening a new bin is cheaper.
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        } else if fitting_bins_count == 1 {
            new_bin_cost += 15.0;
        }
        // If mean residual of open bins is large, prefer reusing them.
        new_bin_cost += 0.2 * mean_residual;
        // Large items relative to capacity: a fresh bin is fine.
        new_bin_cost -= 0.1 * item_size as f64;
        score = new_bin_cost + post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear (quadratic) coupling
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in the stream, tighter fits matter more
    score *= 1.0 + 0.8 * progress * (1.0 - norm_pr);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 12.0 * (waste / cap) * (1.0 + progress);
    }
    // Reward leaving room exactly for the next item
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild pressure against scattering across many open bins with high mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap) * (0.5 + progress);

    // New-bin candidate: make it unattractive unless it is genuinely needed
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 && next_item_size > 0 && (next_item_size as f64) > pr {
            score -= 30.0; // allow new bin only if no open bin fits well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartiles
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let cls = post_residual % quarter;
    match post_residual / quarter {
        0 => score -= 14.0,                       // tiny leftover: near-perfect fit
        1 => score -= 4.0,                        // half-ish leftover
        2 => score += 2.0,
        _ => {}
    }
    // penalize awkward dead space within the class (avoid residuals like 1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // fractional capacity coupling
    let frac = post_residual as f64 / cap;
    score += (frac * std::f64::consts::PI).sin() * 3.0;

    // lookahead: if next item fits perfectly in post_residual, reward strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 { score -= 10.0; }
        } else {
            // next item won't fit here; slight penalty for leaving big gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // new-bin candidate handling
    if bin_residual == bin_capacity {
        // opening a new bin is good only if item is large or fit elsewhere is poor
        let tight_elsewhere = fitting_bins_count <= 1;
        let big_item = item_size > half;
        if tight_elsewhere || big_item {
            score = 1.0 + (item_size as f64) * 0.01;
        } else {
            score = cap + 50.0; // discourage opening when existing bins fit fine
        }
        return score;
    }

    // stream progression: early on, prefer tight packing exploration; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (mean_residual / cap);

    // spread penalty: bins far from mean residual are less attractive
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 12 {
        // gap too small for the smallest conceivable future item -> dead space
        score += 40.0 * (12.0 - pr) / 12.0;
    } else if post_residual >= 12 && post_residual < 30 {
        // awkward mid-range gap: mild penalty
        score += 6.0 * (30.0 - pr) / 18.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (new-bin candidate gets a boost that grows with open_bins_count).
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when item leaves a healthy
    // gap for the lookahead item or open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let gap_ok = next_item_size > 0 && post_residual >= next_item_size as u32;
        if gap_ok {
            score -= 10.0;
        } else {
            score += 20.0;
        }
        // scale new-bin attractiveness with fragmentation
        score -= 0.10 * mean_residual;
    }

    // Lookahead coupling: if this bin can also host the next item afterwards,
    // reward preserving that possibility.
    if next_item_size > 0 && post_residual >= next_item_size as u32 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward bins whose post_residual exactly fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            score -= 30.0; // perfect chain: current item + next item fill bin exactly
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit in this bin's leftover: dead space penalty scaled by leftover size
            score += 4.0 * (post_residual as f64 / 100.0) * (nxt / 100.0);
        }
    }

    // Compare post_residual relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline score so it's chosen only
    // when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 35.0;
        // late in the stream, opening new bins is less attractive (waste at end)
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 40.0 * progress;
        }
    }

    // Prefer placing into bins with larger current residual among similar fits
    score -= 0.05 * bin_residual as f64;

    // Mild penalty for scattering across many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual, reward; if it would
    // be blocked, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // alternatives exist or many bins are already open.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge and nothing else fits well, opening a bin
        // is fine; relax the penalty for large items.
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins whose residual deviates from the mean (consolidate
    // small residuals rather than spreading space evenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Mild preference for bins with small residual overall.
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, waste is penalized more aggressively (quadratic growth)
    let progress_coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress * progress);
    score += 40.0 * progress_coupling;

    // Smooth interaction: residual tightness vs mean residual across bins
    // bins below mean residual are "tighter" -> slightly favored via polynomial term
    let mean_term = (mean_residual - pr) / cap;
    score += 8.0 * mean_term * mean_term * mean_term.signum();

    // Lookahead: if next item fits exactly into the post-residual, reward strongly (smooth bump)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let bump = (-(gap / 25.0) * (gap / 25.0)).exp();
        score -= 30.0 * bump;
    }

    // Last-chance bin: penalize opening a new bin when only this bin fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize smoothly, less so late in stream or when fill is poor
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let fill = item_size as f64 / cap;
        let penalty = 60.0 * (1.0 - fill) * (1.0 - fill) * (1.0 + progress);
        score += penalty;
        // allow new bin late when many bins are open and fragmented
        score -= 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic class: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i32; // 0..10 decile class
    score -= (10 - class) as f64 * 1.5;

    // Penalize post_residual in "dead zones": residues that few item sizes can fill.
    // Sizes 1..100 unknown; residues below 10 are hard to fill (min item 10 historically).
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
    }

    // Harmonic coupling with next item: reward if next_item_size exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // modulo harmonic: how well next item divides into post residual
            let m = post_residual % next_item_size.max(1);
            score -= (post_residual - m) as f64 * 0.15;
        } else {
            // next item cannot use this bin anyway; slight penalty for stranding space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; keep it competitive only against wasteful fits.
        score += 35.0;
        // If stream is early, allow new bins more readily to build diversity.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // If many open bins already, discourage proliferation.
        score += open_bins_count as f64 * 1.2;
    }

    // Prefer bins with below-mean residual (denser bins) for better packing.
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are nearly
    // unusable for future items (items >= 1 but practically >= 10 in classic
    // streams, and small leftovers rarely match). Penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Medium gaps (11..=20) are risky too: only small items can use them.
    if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    if bin_residual > 0 {
        let waste_frac = post_residual as f64 / bin_residual as f64;
        score += waste_frac * 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit into post_residual but could fit elsewhere,
    // mild penalty for blocking a useful chain.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; penalize placements that leave bins idle.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible (post_residual small).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "junk" bin; filling it is good. If far above mean, slight
    // penalty to keep a large residual bin available.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // New-bin candidate handling: empty bin has residual == capacity.
    // Its post_residual == capacity - item_size is naturally large, so the
    // base score is already high. Add extra penalty so a new bin is only
    // opened when every open bin would produce a very small unusable gap.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        // But if no open bin fits at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream pressure: near the end, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            // Reward closeness of leftover to next item (encourages chain filling).
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 120.0 * (waste / bin_capacity as f64);
        }
    }

    // Penalize small unusable residuals relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative-to-mean coupling: prefer bins already below mean residual
    // (tighter bins), mildly.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits poorly.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: only attractive if best alternative is bad.
        score += 80.0;
        // Lookahead makes a fresh bin attractive if next item also fits well after.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0;
        }
    }

    // Slight preference for fuller bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.3;

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, with mild superlinear penalty on large dead space.
    let pr = post_residual as f64;
    score += 0.15 * (pr * pr) / bin_capacity as f64;

    // Lookahead: reward bins whose post residual can host the next item (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Exact-ish chain fit is gold; scale reward by how snugly next item fits.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.2 * chain_waste;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual too small for next item: mildly penalize creating tiny dead space.
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin starts at high residual; penalize opening a new
    // bin unless this bin's fit is poor (large post residual) or the item barely fits elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: proportional to wasted capacity of this placement.
        score += (bin_capacity - item_size) as f64 * 0.9;
        // Early in stream, opening new bins is cheap (many items to come, future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // If many open bins already have large mean residual, discourage new bins.
        score += 0.4 * mean_residual;
        // If no existing bin can even fit the item, this call is the only option anyway
        // (fitting_bins_count would be 0 for others), soften penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Reusing an existing bin: reward using bins with low residual (tight packing),
        // i.e., bins that are already nearly full.
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness;

        // Reward closing out bins: if item nearly fills bin, big bonus.
        if post_residual <= 5 {
            score -= 35.0;
        } else if post_residual <= 15 {
            score -= 15.0;
        }

        // Late in stream, avoid leaving many fragmented open bins: favor bins whose
        // post residual is unusable for typical items (small dead space is fine, mid is bad).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if post_residual >= 10 && post_residual <= 25 {
            score += 10.0 * progress;
        }

        // If many bins fit the item, prefer the tightest; add small penalty scaled by
        // abundance of alternatives to sharpen discrimination.
        if fitting_bins_count > 1 {
            score += 2.0 * (fitting_bins_count as f64).ln();
        }
    }

    // Global fragmentation guard: penalize placements that leave post residual far from
    // both 0 and the typical next-item size band.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.05 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize leftover space, with a smooth non-linear (quartic) coupling
    let mut score = pr * (1.0 + 0.9 * (pr / cap).powi(4));

    // Stream-progress coupling: early on, tolerate residual; late, penalize waste more
    let progress_term = 0.35 * pr * (progress * std::f64::consts::PI).sin().abs();
    score += progress_term;

    // Interaction of post_residual with mean residual: prefer bins whose leftover
    // deviates smoothly from the mean (avoid fragmenting many similar bins)
    let dev = (pr - mean_residual) / cap;
    score += 0.25 * pr * dev * dev;

    // Lookahead coupling: smooth reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr - nx).max(0.0) / cap;
        let tight = 1.0 - (fits / (1.0 + fits));
        score -= 0.45 * tight * (nx / cap) * (1.0 - progress);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.6 * (1.0 + 0.5 * (item_size as f64 / cap));
    }

    // Mild penalty for spreading across many bins (encourage consolidation)
    score += 0.05 * (open_bins_count as f64).powi(2) / cap;

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 2.0 + 0.5 * (pr / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but treat "perfect-ish" residuals specially.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: classify leftover into residue classes mod 10.
    // Residuals in {0} are perfect; small classes (1..=5) are near-perfect; mid classes
    // (6..=20) are the most dangerous "dead space" zone; large residuals stay usable.
    let r = post_residual;
    if r == 0 {
        score -= 40.0; // perfect packing, strongly reward
    } else if r <= 5 {
        score -= 15.0; // near-perfect, effectively dead but tiny
    } else if r <= 20 {
        // dead-space zone: penalize heavily, scaled by how dead it is
        score += (20 - r) as f64 * 1.5;
    } else {
        // larger residual: mildly reward, since future items (>=1) can still fit
        score -= 5.0;
    }

    // Harmonic class via integer division thresholds on residual capacity fraction.
    let frac = r as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as u32; // 0..=9 tenths of capacity
    score += match class {
        0 => -10.0,           // <10% left
        1 => 8.0,             // 10-20%: awkward
        2 => 6.0,
        3 => 0.0,
        4 => -4.0,
        5 => -6.0,
        6 => -4.0,
        7 => -2.0,
        8 => 0.0,
        _ => 2.0,             // near-empty bin placement: wasteful
    } * (1.0 + 0.5 * progress);

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // great: chain continues in this bin
            let slack = (r - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic bonus if next item lands residual in a good class
            let nr = r - next_item_size;
            if nr % 10 == 0 { score -= 6.0; }
        } else {
            // next item won't fit here; penalize more if this bin becomes isolated
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    } else if fitting_bins_count > 3 {
        // many options: be picky, reward tight fits more
        score -= (bin_residual - r) as f64 * 0.05;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item is
    // large and no good fits exist, or late in stream with many bins open.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let pressure = if mean_residual > 0.0 { (item_size as f64) / mean_residual } else { 1.0 };
        // cost of a fresh bin, discounted if current alternatives are bad
        score = 55.0 - 20.0 * big_item - 10.0 * (pressure.min(3.0) / 3.0) + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin anyway
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin can also host the next item
        }
    }

    // Mild tie-break: prefer bins whose residual deviates favorably from mean.
    score -= 0.02 * (mean_residual - r as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    } else if post_residual < 20 {
        score += 25.0 - (post_residual as f64);
    } else if post_residual > 60 {
        // Very loose fit: bin becomes a dumping ground; mild penalty.
        score += 8.0;
    } else {
        // Tight-but-usable fits are rewarded.
        score -= 6.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits (small miss), penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size.saturating_sub(5) {
        score += 5.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bin pressure: many open bins -> discourage spreading; few bins -> encourage filling.
    let obp = open_bins_count as f64;
    score += obp * 0.6;

    // Mean residual coupling: prefer bins below mean residual (tighter bins get priority).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate logic: empty bin should only win when it leaves a large,
    // versatile residual that current open bins cannot offer, or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base handicap so open bins are preferred unless fit is bad.
        score += 18.0;
        // Early stream: opening fresh bins is cheaper (future items can use space).
        score -= (1.0 - progress) * 12.0;
        // If item fills a fresh bin well, opening is attractive.
        if post_residual <= 20 {
            score -= 20.0;
        }
        // Many open bins already: opening yet another bin is costly.
        score += obp * 1.5;
        // If other bins fit but are poor, new bin gains appeal when it leaves big residual.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space that is too small for the next item (unusable gap),
    // but only when it's not a perfect match (handled above).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space penalty scaled by how close we are to a wasted sliver.
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward leaving room that can still fit the next item partially well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Prefer tighter fits overall: closeness of post_residual to zero.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter",
    // favor them mildly; bins far above mean are looser, penalize slightly.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Early in the stream, encourage consolidation; later, allow more freedom.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // New-bin candidate handling: an empty bin is a fallback; make it less
    // attractive unless open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If next item would fit perfectly in the new bin too, keep fallback mild.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the leftover, the better (best-fit core).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Dead space too small for any item (min size 1): nearly perfect.
        score -= 15.0;
    } else if post_residual < 20 {
        // Small but potentially usable residual: mild penalty for waste.
        score += 3.0;
    }

    // Lookahead coupling: favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainability bonus scaled by how snugly the next item would fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Post-residual can't host next item: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    } else {
        // Last item in stream: closing bins tightly is all that matters.
        score -= 10.0 * tightness;
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual > 60 {
            // Very poor fit in the only available bin; soften the bonus so a
            // fresh bin can win if it would produce a much better packing.
            score += 0.25 * (post_residual as f64 - 60.0);
        }
    }

    // New-bin candidate handling: an empty bin competes with open bins.
    if bin_residual == bin_capacity {
        // Base handicap: prefer filling existing bins when reasonable.
        score += 18.0;
        // Opening a new bin is more attractive when few bins fit the item
        // (i.e. the item is awkward for current open bins).
        if fitting_bins_count >= 1 {
            score += 6.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // If open bins are already crowded on average, a fresh bin is cheap.
        score -= (mean_residual / 10.0).min(8.0);
        // Early in the stream, keep the bin count lean; later, spreading is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // Large items relative to capacity benefit from a fresh bin.
        score -= 0.1 * item_size as f64;
    }

    // Mild pressure against bin sprawl when many bins are open.
    score += 0.02 * open_bins_count as f64;

    // Slight preference for bins with residuals far from the mean (diversity
    // of residual sizes helps future items find tight homes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate looser fits; late in stream, punish dead space harder.
    let tightness = (post / cap).powi(2);
    score += 30.0 * tightness * (0.3 + 0.7 * progress);

    // Lookahead: reward leaving space that the next item can still use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = ((post - nxt) / cap).powi(2);
            score -= 12.0 * (1.0 - slack_fit) * (1.0 - 0.5 * progress);
        } else {
            // post_residual too small for next item: penalize proportionally.
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (item_size as f64 / cap);
    }

    // Contextual terms: many open bins with large mean residual → encourage consolidation.
    let mean_term = (mean_residual / cap - 0.5).abs();
    score += 4.0 * mean_term * (open_bins_count as f64).sqrt().ln().max(0.0);

    // New-bin candidate (empty bin): neutral-ish base but discourage when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
        // If item is large relative to capacity, opening a fresh bin is more attractive.
        score -= 8.0 * (item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic class of post_residual: classify residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i64; // 8 harmonic classes: 0..=7
    match class {
        0 => score += 20.0,          // nearly full: great, but tiny residual handled above
        1 => score -= 6.0,           // ~1/8..2/8 residual: decent
        2 => score -= 10.0,          // ~2/8..3/8: sweet spot for mid items
        3 => score -= 4.0,
        4 => score += 2.0,
        5 => score += 4.0,
        6 => score += 6.0,
        _ => score -= 3.0,           // near-empty bin: fine, fresh space
    }

    // Integer-division threshold coupling with lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the next item (chain packing).
            score -= 8.0;
            // Extra reward if next item fills bin almost exactly after this one.
            let post2 = post_residual - next_item_size;
            if post2 < 10 {
                score -= 10.0;
            }
        } else {
            // Penalize leaving residual that next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Modulo-class match: if next_item_size falls in same harmonic class band as residual, bonus.
        let next_class = ((next_item_size as f64 / cap) * 8.0).floor() as i64;
        if next_class == class && class >= 1 && class <= 3 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline neutral score; adjust with stream state.
        score = 60.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score += 20.0; // last-chance bin exists; avoid opening
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins with slack: discourage new bin.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 12.0;
        }
    } else {
        // Mild preference for fuller bins among open ones.
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
        // Open-bin count pressure: with many open bins, favor consolidation.
        if open_bins_count > 6 {
            score -= 1.0;
        }
    }

    // Small tie-break jitter via deterministic hash of residuals (no RNG state).
    let h = (bin_residual.wrapping_mul(2654435761).wrapping_add(item_size.wrapping_mul(97))) % 7;
    score += h as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few bins,
    // filling existing bins is fine.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item is close to post-residual but slightly larger, mild penalty
    // (creates near-dead space for the future item).
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 8.0;
    }

    // Prefer bins tighter than the mean residual (waste-aware selection).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when current fit is bad or no real bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 }
            + if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 - 20.0 * bad_fit + 5.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect two-item packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the leftover space.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score += diff * 0.8;
        }
        // If next item can't fit here, mildly penalize creating dead space
        // relative to mean residual of open bins.
        if (next_item_size as u32) > post_residual {
            score += 10.0 + (post_residual as f64 - mean_residual).abs() * 0.3;
        }
    }

    // Penalize creating unusable tiny residuals (< 10) that waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless it is
    // genuinely better than all existing fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Extra penalty when other bins can fit the item.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Slightly cheaper to open new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall (small residual before placement).
    score += bin_residual as f64 * 0.05;

    // Slight coupling to mean residual: favor bins below mean residual
    // (tighter than average) to consolidate packing.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Quadratic dead-space penalty: small residuals are disproportionately wasteful.
    let pr = post_residual as f64;
    score += 0.08 * pr * pr / bin_capacity as f64;

    // Progress ratio for time-varying behavior.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: penalize opening a new bin by default,
    // but soften when no good fit exists elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 40.0 + 0.3 * next_item_size as f64;
        if fitting_bins_count == 0 {
            penalty -= 45.0; // no alternative, allow opening
        }
        if fitting_bins_count == 1 {
            penalty -= 15.0; // only one fitting bin: prefer using it, but not always
        }
        score += penalty * (1.0 - 0.25 * progress);
    } else {
        // Last-chance bonus: this is the only bin that can take the item.
        if fitting_bins_count == 1 {
            score -= 30.0;
        } else if fitting_bins_count == 2 {
            score -= 10.0;
        }

        // Lookahead coupling: reward residuals that can host the next item,
        // penalize residuals that strand the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0 + 0.1 * next_item_size as f64;
            } else if post_residual > 0 {
                score += 5.0 + 0.15 * (next_item_size - post_residual) as f64;
            }
        }

        // Global state: when mean residual is high, prefer absorbing into
        // already-loose bins; when tight, prefer tightest fits.
        score += 0.05 * (mean_residual - pr);

        // Slight preference for filling fuller bins early in the stream,
        // leaving large residual bins flexible later.
        score -= (1.0 - progress) * 0.1 * item_size as f64;
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.3 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fills; later, punish dead space quadratically.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += post * (2.5 * prog2 + 3.0 * prog3);

    // Reward near-perfect packing more strongly as stream advances (smooth bump).
    let tightness = 1.0 - post / cap;
    score -= 15.0 * tightness.powi(3) * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // Penalize opening a new bin when existing bins fit reasonably.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual.max(0.0);
        score += 8.0 + 0.5 * avg_fit + 12.0 * (1.0 - progress) * (1.0 - progress);
        // If no open bin could otherwise fit, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let kernel = (-gap * gap / (2.0 * 400.0)).exp();
        score -= 6.0 * kernel * (0.4 + 0.6 * progress);
    }

    // Mild pressure against bin proliferation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

