        score -= 300.0;
    } else {
        // penalize dead space that is too small for typical future items
        if post_residual < 20 {
            score += 40.0;
        }
        // modulo classes: residuals near multiples of common sizes are reusable
        let r = post_residual;
        for m in [10u32, 20, 25, 50] {
            if r % m == 0 {
