        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for next item: penalize proportionally
        score += (post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // attractive early or when existing fits are poor, unattractive otherwise
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 + 100.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 250.0; // don't abandon the last fitting bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0; // fresh bin accommodates lookahead
        }
    }

    // mild pressure to consolidate when many bins are open
    if bin_residual < bin_capacity {
        score += open_bins_count as f64 * 0.5;
        if (bin_residual as f64) > mean_residual {
            score -= 10.0; // prefer bins with above-average space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
