    } else if post_residual < 10 {
        // Small nonzero leftover is practically unusable dead space:
        // penalize proportionally to how close it is to zero.
        score += (10 - post_residual) as f64 * 12.0;
    }

    if !is_new_bin {
        // Last-chance pressure: if this is the only open bin that fits,
        // strongly favor it to avoid opening a new bin (more so late in stream).
        if fitting_bins_count == 1 {
            score -= 40.0 + 20.0 * progress;
        }

        // Lookahead (k=2): reward leaving a gap the next item can use.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                score -= next_item_size as f64 * 0.6 - slack * 0.1;
            } else {
                // Leftover cannot fit the next item: mild penalty.
                score += 5.0;
            }
        }

        // Mild consolidation: prefer bins whose residual is near the mean residual.
        score += (mean_residual - bin_residual as f64).abs() * 0.05;
    } else {
        // New-bin candidate: penalize by open-bin pressure and stream progression
        // so a new bin is only chosen when all open fits are poor.
        score += open_bins_count as f64 * 3.0 + 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer filling bins tightly (low post_residual).
    // Lookahead: if the next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        let next_fits = (post_residual as u32) >= next_item_size;
        if next_fits {
            // Perfect chain: post_residual == next_item_size is ideal.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 40.0 - slack.min(40.0) * 0.5;
        } else {
            // Dead space for next item: penalize proportionally to wasted gap.
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap.min(50.0) * 0.6;
        }
    }

    // Relative to mean residual: bins with residual below mean are "denser",
    // favor packing into them rather than spreading.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (residual_f - mean_residual) / mean_residual;
        score += rel * 15.0;
    }

    // Last-chance bin: if this is the only bin that can fit, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize leaving very small unusable fragments (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: only prefer opening a new bin when current open bins
    // would create large dead space. Make empty-bin score moderately high by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item fits poorly everywhere else, a fresh bin is fine:
        if fitting_bins_count <= 1 && post_residual as f64 > 30.0 {
            score -= 70.0;
        }
    }

    // Slight preference to use more of the stream progression to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: nearly exact fills are excellent.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if next_item_size <= post_residual {
            // Next item chains perfectly: big reward, more so if residual is tight.
            let slack = pr - nxt;
            score -= 20.0 - slack.min(20.0) * 0.4;
        } else {
            // Dead space risk: penalize leftover space the next item can't use,
            // scaled by how much of the residual is wasted.
            let waste = pr / bin_capacity as f64;
            score += waste * 12.0;
            // If next item is large and this bin would leave big unusable gap, extra penalty.
            if nxt > pr && pr > 0.0 && pr < nxt * 0.5 {
                score += 6.0;
            }
        }
    }

    // Time horizon: early in the stream, prefer keeping bins flexible (avoid
    // committing capacity); late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading out.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= (mean_residual / 100.0) * 6.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins. Penalize proportional to aggregate stranded capacity, but
    // allow it when no open bin fits well (post_residual would be tiny).
    if bin_residual == bin_capacity {
        let stranded = mean_residual * open_bins_count as f64;
        let base_penalty = 15.0 + stranded * 0.08;
        // If current item leaves a huge hole in a fresh bin, discourage more.
        score = base_penalty + post_residual as f64 * 0.5;
        // Late in stream, new bins are cheaper (less future to waste).
        score -= progress * 10.0;
        // If open bins would leave very poor fits, opening new bin is fine.
        if fitting_bins_count > 0 {
            let best_possible_waste = (bin_residual - item_size) as f64;
            if best_possible_waste > 40.0 {
                score -= 20.0;
            }
        }
    }

    // Small nudge toward bins with less residual overall (best-fit flavor).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr + 40.0 * norm_pr * norm_pr + 30.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling: as stream progresses, tighter fits matter more.
    score *= 1.0 + 0.8 * progress * (norm_pr * (1.0 - norm_pr) * 4.0);

    // Perfect-fit reward (smooth Gaussian-like dip).
    let perfect = (pr / cap) * (1.0 - pr / cap) * 4.0; // peaks at pr=0
    score -= 25.0 * (1.0 - perfect) * (1.0 - perfect) * (pr as f64).min(1.0).max(0.0) * 0.0; // placeholder-free
    score -= 25.0 * (1.0 - perfect) * (1.0 - perfect) * (if pr == 0 { 1.0 } else { 0.0 });

    // Reward bins that also fit the lookahead item smoothly.
    let fits_next = (next_item_size > 0 && post_residual >= next_item_size) as f64;
    score -= 12.0 * fits_next * (1.0 + progress);

    // Last-chance bonus: few fitting bins -> favor using this one.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly early, less late (consolidation phase).
    score += is_new_bin * (30.0 + 40.0 * (1.0 - progress)) - is_new_bin * 25.0 * progress;

    // Slight preference for bins below mean residual (tighter bins).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base: heavily penalize opening a new bin when open bins could fit.
        let mut s = 220.0;
        // If the item is much larger than the average open residual, opening
        // a fresh bin is more attractive (existing bins would be wrecked).
        if (item_size as f64) > mean_residual + 15.0 {
            s -= 45.0;
        }
        // Harmonic lookahead: if the post-residual exactly complements the
        // next item, a fresh bin sets up a perfect pairing.
        if next_item_size > 0 && next_item_size == post_residual {
            s -= 70.0;
        }
        // Late in the stream, avoid spreading across new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        s += progress * 20.0;
        return s;
    }

    // ---- Harmonic classes on post_residual ----
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strong reward.
        score -= 18.0;
    } else {
        // Exact complement of the next item: reserve this space.
        if next_item_size > 0 && pr == next_item_size {
            score -= 28.0;
        }
        // Dead space: post_residual too small for the next item.
        if next_item_size > 0 && pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        // Class thresholds: unusable slivers are heavily penalized.
        if pr < 10 {
            score += 35.0;
        } else if pr < 20 {
            score += 10.0;
        } else if pr < 30 {
            score += 3.0;
        }
        // Round harmonic class (multiples of 10) slightly favored:
        // future items from typical distributions align better.
        if pr % 10 == 0 {
            score -= 2.5;
        }
        // Integer-division class: pr / item_size ratio shaping.
        if item_size > 0 && (pr / item_size) >= 2 {
            score -= 4.0; // bin can still host multiple future items
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Mild tie-break: prefer bins tighter than the mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly worthless.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead); // tiny unusable gap: heavy penalty
        } else if dead < 20.0 {
            score += 15.0 * (20.0 - dead) / 10.0; // likely dead space
        }
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item is large relative to mean residual or many bins exist).
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let pressure = open_bins_count as f64;
        let tight = (bin_residual as f64 - item_size as f64).max(0.0);
        score += 30.0; // base cost of opening a bin
        score -= pressure * 0.5; // slight relief of open-bin pressure
        // If the next item could combine with the leftover, opening is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // If this item leaves a big usable gap, opening a fresh bin is bad.
        score += (item_size as f64 / 10.0) * 2.0;
        let _ = tight;
    }

    // Mild open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.15;

    // Prefer bins with residual close to the item (tight packing).
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += slack * 0.3;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 5.0; // leftover too small for next item: dead space
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - match_quality / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize bins that leave post_residual too small for the next item (dead space).
        score += 8.0 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin opening when decent fits exist, unless residual is very tight overall.
    if bin_residual == bin_capacity {
        let tightness = mean_residual / bin_capacity as f64;
        if tightness < 0.25 {
            score -= 5.0; // open a new bin when open bins are mostly full
        } else {
            score += 20.0; // discourage wasting a fresh bin
        }
    }

    // Late-stream bias: consolidate more aggressively as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: larger items consuming the bin are valuable.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Prefer fuller bins relative to the fleet average.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item cannot fit in the leftover space,
    // this placement "closes" the bin usefully — reward it.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score -= 8.0;
        } else {
            // Next item still fits: leftover space retains future utility,
            // penalize slightly, more so if the leftover is large.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // is genuinely good (large item) or alternatives are scarce/poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        score -= 25.0 * tightness;                 // big items justify opening bins
        score += 6.0 * fitting_bins_count as f64;  // many alternatives -> avoid new bin
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * (1.0 - progress);           // early on, opening bins is cheaper
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;                          // new bin can also host the next item
        }
    }

    // Mild penalty for creating awkward dead space (small but non-zero leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space (wasted capacity) with a non-linear (quadratic) term.
    let mut score = post * (1.0 + 0.02 * post / cap);

    // Smooth stream-progress coupling: as the stream advances, tighter packing is preferred.
    let tightness = 1.0 - (post / cap);
    score += (0.5 + 2.0 * progress) * tightness * tightness * cap * 0.1;

    // Reward filling a bin nearly exactly (smooth exponential decay of post_residual).
    score -= 30.0 * (-post / 10.0).exp();

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mildly penalize leaving awkward residuals.
        score += 4.0 * (1.0 - post / cap);
    }

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (compact bins absorb items, keeping looser bins flexible).
    score += 0.15 * (mean_residual - post);

    // New-bin candidate penalty: opening a fresh bin is only attractive when the
    // current item is large relative to capacity (poor fit elsewhere).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score = cap * 0.8 - 60.0 * large_item * large_item + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into classes mod 10.
    // Small post-residuals (dead space) are penalized super-linearly.
    let pr = post_residual;
    let class = pr % 10;
    let dead = if pr == 0 { 0.0 } else if pr < 10 { 60.0 } else if class == 0 { 0.0 } else { (10 - class) as f64 * 1.5 };
    score += dead;

    // Exact fit is golden.
    if pr == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual (chained placement).
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0 + (pr - next_item_size) as f64 * 0.3;
    }
    // Penalize if next item is large and this bin wastes capacity that could hold it.
    if next_item_size > pr && next_item_size > 0 {
        score += (next_item_size - pr) as f64 * 0.2;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral-ish baseline; only attractive when item is large
    // (few future fits likely) or open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        score = item_size as f64 * 0.5 + open_bins_count as f64 * 1.0;
        if item_size >= 60 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer tightening existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0 * (mean_residual / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Gaps that are too small to hold even the smallest item (1..=10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    }
    // Small usable-but-awkward gaps (10..=25) are semi-dead unless next item fits.
    if post_residual >= 10 && post_residual < 25 {
        let awkward = 15.0 * (1.0 - (post_residual as f64) / 25.0);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= awkward; // lookahead can consume the gap
        } else {
            score += awkward;
        }
    }

    // --- Tight fit reward: near-zero post_residual is excellent ---
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        // Reward proportional fit quality (fraction of bin used)
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fill_ratio;
    }

    // --- Last-chance bonus: only fitting bin, avoid opening a new bin unnecessarily ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when current bin residuals are large and fragmented,
        // or when this item is big and would leave a dead sliver in any open bin.
        let sliver_risk = post_residual > 0 && post_residual < 10;
        if sliver_risk {
            score -= 50.0; // prefer fresh bin over creating dead space
        }
        // Mild pressure: discourage hoarding many open bins early.
        score += 2.0 * open_bins_count as f64;
        // Prefer new bin when mean residual is high (open bins still roomy).
        score += 0.3 * mean_residual;
    } else {
        // Open-bin pressure: with many open bins, prefer reusing fuller bins.
        let pressure = 0.05 * open_bins_count as f64;
        score -= pressure * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // --- Lookahead coupling: if next item exactly fits the post gap, big bonus ---
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }

    // --- Slight stream-progression tiebreak for determinism ---
    score += 0.001 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward a perfect match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item is extremely valuable.
        if diff == 0.0 {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits: reward proportionally to closeness.
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit: penalize dead space, worse if tiny leftover.
            let dead = post_residual as f64;
            score += 12.0 * (1.0 - dead / 30.0).max(0.0);
        }
    } else {
        // Last item: prefer the tightest possible fit.
        score += 5.0;
    }

    // Reward tight packing relative to the mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless the fit would be very loose (wasteful).
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - item_size as f64;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
        score += 20.0;
        // New bin becomes attractive when it would be filled very tightly
        // or when existing bins are nearly full (high mean residual usage).
        if waste < 10.0 {
            score -= 45.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 10.0;
        }
        score += 2.0 * pressure.min(5.0);
    }

    // Mild preference for using fuller bins (smaller residual before placement).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= 0.35 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 20.0;

    // Penalize unusable dead space: post_residual too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0;
    } else if post_residual < 10 {
        score += 8.0; // likely dead space
    } else if post_residual <= 20 {
        score -= 5.0; // small leftover may still be useful
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // or all open bins are nearly full (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let crowded = mean_residual < 0.25 * bin_capacity as f64;
        if large_item || crowded {
            score -= 40.0;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Prefer bins whose residual is close to the item (perfect-ish fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness;

    // Global balance: mildly prefer bins with residual below mean (consolidate fullness).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: as the stream progresses, be slightly more conservative about
    // wasting space (dead space penalty grows).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: penalize leftover space, with non-linear scaling
    let mut score = x * (1.0 + 0.8 * x * (1.0 - x));

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - x;
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 6.0 * progress_coupling * tightness * tightness;

    // Reward near-perfect fits more aggressively as stream advances
    score -= 4.0 * (1.0 - x * x) * progress;

    // Penalize bins that are much worse than the mean residual (non-linear divergence)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 3.0 + 5.0 * progress_coupling;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill = nxt / pr.max(1.0);
            score -= 5.0 * fill * fill * (0.5 + 0.5 * progress);
        } else {
            score += 2.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for many open bins (encourage consolidation early)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // --- Harmonic class of the post residual (decimal digit bands) ---
    // Residuals that are "round" multiples of 10 are the most reusable;
    // near-miss residuals (1 or 9 mod 10) are almost as good;
    // mid-band residuals (4..6 mod 10) are the worst dead space.
    let cls = post_residual % 10;
    score -= match cls {
        0 => 3.0,
        1 | 9 => 2.0,
        2 | 8 => 1.0,
        3 | 7 => 0.0,
        _ => -1.0, // 4,5,6 mod 10 -> add penalty instead
    };

    // --- Dead-space penalty: leftover that the lookahead item cannot use ---
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * post_residual as f64;
    }
    // Reward when the next item fits exactly into the leftover (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
        if post_residual == next_item_size {
            score -= 6.0; // perfect chain: residual fully consumed next step
        }
    }

    // --- Tight fit bonus (near-exact packing) ---
    if post_residual <= 4 {
        score -= 10.0;
    } else if post_residual <= 10 {
        score -= 4.0;
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 2.0 * progress;
    }

    // --- New-bin candidate: mildly penalized so it is only chosen when
    // every open bin would create worse (dead / mid-band) residual ---
    if bin_residual == bin_capacity {
        score += 1.5;
        // A new bin is attractive if its post-residual is a large,
        // round, reusable chunk (e.g. item_size near a multiple of 10).
        if post_residual % 10 == 0 && post_residual >= 20 {
            score -= 2.0;
        }
    }

    // --- Global context coupling: when mean residual across open bins is
    // high, prefer consolidating into existing bins (favor small post-residual) ---
    score += 0.02 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, tighten everything: waste hurts more.
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Dead space that cannot fit the smallest plausible next item (1..100 unknown
    // distribution, so weight by whether the lookahead item fits).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual relative to bin_residual).
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_residual as f64);
    score -= fill_ratio * 30.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // truly cannot fit well anywhere (large item, poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + open_bins_count as f64 * 2.0;
        // Large items near the end benefit from a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 20.0 + progress * 10.0;
        }
        // If the lookahead item is large and this bin would leave a gap the
        // lookahead cannot use, fresh bin is more attractive.
        if next_item_size > post_residual {
            score -= 15.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual deviates from the mean (keep residuals uniform
    // so future items fit predictably).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins where the next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact 2-step match is gold: subtract heavily.
            let slack2 = (post_residual - next_item_size) as f64;
            score -= 60.0 + 40.0 * (1.0 - slack2 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted chain potential.
            score += 0.35 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 5.0;
    }

    // Tightness reward relative to mean residual: filling an unusually full bin is good.
    let tightness = (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.25 * tightness;

    // Penalize creating very small unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default is neutral (score == capacity residual scale);
    // make it slightly unattractive unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0;
        // During late stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If next item is large and this new bin would fit it perfectly, encourage opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Mild penalty for hoarding many open bins when a tight fit exists elsewhere.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale penalty by relative fill of the bin.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio * (item_size as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item can use the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize dead space proportionally.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be pickier about wasted space (long future to regret it);
    // late in the stream, favor using existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.15 * post_residual as f64;
    score -= progress * 8.0;

    // Global state: many open bins with large mean residual -> discourage opening/using
    // bins that leave big residuals; few open bins -> prefer spreading load.
    if open_bins_count > 0 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.05 * spread;
        if mean_residual > bin_capacity as f64 * 0.5 && post_residual > 20 {
            score += 3.0;
        }
    }

    // New-bin candidate tuning: empty bin gets a mild penalty unless current bin would be nearly full.
    if bin_residual == bin_capacity {
        score += 10.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base scaling: prefer tight fits, amplified as the stream progresses.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * (0.5 + progress);

    // Non-linear coupling: post_residual vs stream progress (quadratic interaction).
    let pr_norm = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * pr_norm * pr_norm * (1.0 - progress);
    score -= 6.0 * pr_norm * progress * (1.0 - progress);

    // Reward if the lookahead item fits exactly into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64) * (0.4 + 0.6 * progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that cannot host the next item: penalize smoothly.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly early, allow late when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        score += 20.0 - 18.0 * progress - if poor_fit { 6.0 } else { 0.0 };
        // Encourage a fresh bin when existing mean residual is fragmented.
        score += 5.0 * (mean_residual / bin_capacity as f64).min(1.0) * progress;
    }

    // Mild penalty for scattering across many open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space (decile classes)
    let class = (post_residual % 10) as f64;
    let decile = (post_residual / 10) as f64;

    // Reward small, well-aligned leftovers (post_residual % 10 == 0 is "perfect")
    score -= (10.0 - class) * 0.8;
    if class == 0.0 {
        score -= 6.0;
    }

    // Penalize large dead space (high decile leftovers are wasteful)
    score += decile * decile * 0.35;

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly reward this bin; if next item cannot use the leftover, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= frac * 12.0;
            // harmonic alignment of next item with leftover
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 3.0;
        }
    } else {
        // Last item: prefer tightest fill overall
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate detection: residual == capacity means empty bin.
    // Its post_residual = capacity - item_size, typically large -> penalize,
    // unless the fit in existing bins is terrible (post residual huge anyway)
    // or many bins are open (consolidation pressure low).
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
        // Early in stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 && item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Prefer bins with below-mean residual (tighter bins get filled first)
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Slight preference to keep fewer open bins when many are open
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since items are >= 1 but typical usable chunks are larger.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger post-residuals are progressively less attractive than tight fits.
        score += 0.15 * post_residual as f64;
    }

    // Prefer filling bins that are already fairly full (small bin_residual).
    score += 0.05 * bin_residual as f64;

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !new_bin_candidate {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the gap; penalize creating stranded space.
        score += 10.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // post_residual can host next item: reward closeness of the leftover-after-next
        let after_next = post_residual - next_item_size;
        score -= 40.0 - (after_next as f64).min(40.0);
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize proportionally to the gap
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Reward tight fits relative to current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize dead space far from mean residual (fragmentation control)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if item is huge relative to capacity
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        if size_frac > 0.8 {
            score -= 50.0;
        } else {
            score += 25.0 * (1.0 - size_frac);
        }
    }

    // Slight preference early in stream to consolidate into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalization grows with wasted space.
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * pr;

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.10 * (next_item_size as f64);
        } else {
            // Penalize creating dead space that cannot fit the lookahead item.
            score += 3.0 * (1.0 - (next_item_size as f64 - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual <= 10 {
            score -= 8.0; // near-perfect closure bonus
        }
    }

    // New-bin candidate handling: only attractive when the stream is early
    // or current open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        // Early stream: opening bins is cheap; late stream: prefer packing.
        score = 55.0 + 60.0 * progress - 30.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && bin_residual as f64 >= next_item_size as f64 {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading load across many open bins late in stream.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    // Prefer bins below mean residual (more usable space than average) slightly.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Quadratic/cubic shaping of dead space, amplified late in the stream
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * pr_norm);
    score += 40.0 * poly * (0.4 + progress);

    // Tight fits rewarded: subtract for small post_residual (smooth, non-piecewise)
    score -= 25.0 * (-pr / 15.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild penalty proportional to abundance of alternatives
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: prefer residual that can still fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fits_next = (pr >= ni) as i32 as f64;
        score -= 18.0 * fits_next * (ni / cap) * (1.0 - 0.5 * progress);
        // penalize residuals just barely below next item (awkward dead space)
        if pr < ni {
            score += 8.0 * (1.0 - pr / ni.max(1.0)) * (1.0 - progress);
        }
    }

    // Mean-residual dispersion term: encourage bins deviating from the mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev * cap;

    // New-bin candidate: penalize mildly so it wins only when open bins are poor
    if bin_residual == bin_capacity {
        score += 55.0 + 30.0 * (1.0 - progress);
        // but if nothing else fits well, new bin is attractive: reduce penalty
        score -= 40.0 * (1.0 - (fitting_bins_count.min(4) as f64) / 4.0);
    }

    // Slight preference for filling fuller bins early (best-fit flavor)
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band does it fall in?
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Dead-space penalty: residuals in (0, 10) are unusable for any item (min size 1..100,
    // but small slivers rarely fit). Penalize non-zero tiny residuals heavily.
    if post_residual > 0 && post_residual < 8 {
        score += 45.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic modulo classes on post_residual: residuals that are multiples of
    // common item sizes are more likely reusable later.
    let harmonics: [u32; 6] = [10, 20, 25, 30, 40, 50];
    for h in harmonics {
        if post_residual >= h && post_residual % h == 0 {
            score -= 6.0 + (h as f64) * 0.15;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // Reusable for the next item: reward proportional to leftover after next item.
            let after_next = post_residual - next_item_size;
            score -= 12.0 - (after_next as f64) * 0.08;
        } else {
            // Next item cannot use this bin's leftover: penalize proportional to waste.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Fractional capacity band penalties: mid-range residuals (0.35..0.6 of capacity)
    // are awkward; near-full residuals are good; tiny ones bad.
    if frac > 0.35 && frac < 0.6 {
        score += 10.0 * (1.0 - (frac - 0.475).abs() * 8.0).max(0.0);
    }
    if frac >= 0.6 && frac <= 0.95 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: discourage spreading, favor consolidation.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.8;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // pushing toward filling fuller bins first.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Stream progression: late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate calibration: an empty bin gets post_residual == bin_residual == 100.
    // Its raw score is 100 minus bonuses; ensure it only wins when open-bin fits are bad
    // by penalizing the empty-bin option slightly via a residual-size tilt.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize unusable dead space: gaps smaller than the smallest possible
        // future item are worthless; the smaller the gap, the higher the penalty.
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += (10.0 - pr) * 40.0; // dead space penalty
        } else {
            // Mild preference for tight fits among usable gaps.
            score += (100.0 - pr) * 0.05;
        }
        // If lookahead item can exactly use the post residual, reward heavily.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Post residual cannot host the next item: penalize proportionally.
            score += pr * 0.3;
        } else if next_item_size > 0 {
            // Next item fits in the gap: reward tightness of that chaining fit.
            score -= (post_residual - next_item_size) as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 5.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (consolidating space).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (bin_residual - item_size) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual) are good.

    if next_item_size > 0 {
        // Perfect 2-step chain: item leaves exactly room for next item -> big reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; reward proportionally to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space, scaled by
            // how far below the next item the leftover falls.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(40.0);
        }

        // Compare post_residual against mean residual: leaving a post_residual
        // far below the mean creates an outlier dead bin; leaving near mean
        // keeps flexibility.
        let dev = post_residual as f64 - mean_residual;
        if dev < -20.0 {
            score += 0.3 * (-dev - 20.0);
        } else if dev > 20.0 {
            score -= 0.15 * (dev - 20.0).min(30.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to what any open bin can absorb comfortably, or late in stream with
    // many open bins. Penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin
        }
        if item_size >= 60 {
            score -= 8.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        if open_bins_count > 4 {
            score += 2.0;
        }
    }

    // Mild penalty for wasting very large residuals on tiny items.
    if item_size <= 15 && post_residual >= 70 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Lookahead coupling: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 6.0;
        } else if (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
            // Penalize dead space the next item cannot use.
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Last item: prefer zero residual aggressively.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is a fallback, not a preference.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin only wins when all fits are poor.
        score += 14.0;
        // More open bins => spreading is cheaper, slightly encourage consolidation instead.
        score += 0.3 * open_bins_count as f64;
        // Late in the stream, opening new bins wastes capacity; penalize more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is actually reasonable.
        score -= 0.1 * item_size as f64;
    }

    // Global state: high mean residual means open bins have slack; favor using them.
    score -= 0.05 * mean_residual;

    // Small dynamic time-horizon modulation: early stream, be flexible; late stream, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.03 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fills (small post_residual) matter more.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Reward using the last bin that can fit the item (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize leaving dead space that can't fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            // smooth reward when next item still fits
            score -= 6.0 * (1.0 - pr / cap) * (1.0 - pr / cap);
        }
    }

    // Penalize spreading across many open bins when mean residual is large.
    let mean_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score += 4.0 * mean_tight * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate: empty bin has large post_residual; add smooth penalty
    // proportional to wasted capacity so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item-size classes (multiples of 10, 25, 50) are more reusable.
    let cap_frac = bin_capacity as f64;
    if post_residual == 0 {
        score -= 200.0; // perfect fit: always excellent
    } else {
        if post_residual % 10 == 0 {
            score -= 12.0;
            if post_residual % 50 == 0 { score -= 8.0; }
            if post_residual % 25 == 0 { score -= 4.0; }
        } else if post_residual % 5 == 0 {
            score -= 5.0;
        } else {
            score += 6.0; // odd leftover: likely dead space
        }
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reusability of leftover w.r.t. lookahead item (harmonic divisibility).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size.max(1) == 0 {
            score -= 10.0; // leftover is an exact multiple of next item
        }
        score -= 4.0; // can at least host the next item
    } else if next_item_size > post_residual {
        score += 3.0; // next item won't fit here
    }

    // Last-chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = (open_bins_count as f64) / (10.0 + mean_residual.abs());
    score += crowd * 5.0 * (0.5 + progress);

    // Tightness reward: placing into a well-filled bin (small relative residual).
    let tight = 1.0 - (bin_residual as f64) / cap_frac;
    score -= tight * 15.0;

    // New-bin candidate: only attractive when current bin would leave a
    // badly-harmonized leftover and the item is large.
    if bin_residual == bin_capacity {
        let bad_leftover = post_residual > 0 && post_residual < 10;
        let big_item = item_size > bin_capacity / 2;
        if bad_leftover || (big_item && fitting_bins_count > 2) {
            score -= 18.0;
        } else {
            score += 40.0; // prefer reusing an open bin by default
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Dead-space penalty: gaps too small to fit any plausible item (min size 1, but
    // practically below next_item_size become unusable unless a tiny item arrives).
    if post_residual > 0 && next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
        // This bin's leftover cannot host the next item => strict dead-space penalty.
        score += 22.0 + 0.5 * (post_residual as f64);
    }
    // Gaps far below the smallest conceivable item are permanently dead.
    if post_residual > 0 && post_residual < 8 {
        score += 18.0;
    }

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 14.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open;
    // for the new-bin candidate (residual == capacity) post_residual is large,
    // so this mainly biases toward reusing open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open or many items remain.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * (1.0 - progress);
        // But if the item would leave a bad gap in every open bin, opening a fresh
        // bin is fine: soften the penalty when mean residual is very low.
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 8.0;
        }
    } else {
        // Reuse reward, stronger when bin count is high (consolidation).
        score -= (open_bins_count.min(20) as f64) * 0.6;
    }

    // Slight preference for bins with residual close to item (best-fit flavor).
    score += 0.10 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match strongly rewarded
        score -= 120.0 / (1.0 + gap);
        // Exact match for the next item
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // If next item fits exactly after this placement, big reward
        if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // Dead space unusable by next item penalized, scaled by dead amount
            score += 0.8 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let dev = mean_residual - post_residual as f64;
    score -= 0.5 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize the brand-new empty bin candidate unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 40.0;
        // Opening a new bin is attractive if item is large and would leave tiny unusable residual elsewhere
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 60.0;
        }
    }

    // Mild penalty for very small post residuals that can't fit typical items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual super-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio * item_size as f64;

    // Penalize dead space: post_residual too small to fit any plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        score -= 8.0; // perfect fit bonus
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + open_bins_count as f64 * 2.0;
        let waste = (bin_capacity - item_size) as f64;
        score = base_penalty + waste * 0.5;
        // If lookahead item is large and current bin would leave awkward space, new bin less bad.
        if next_item_size > 0 && next_item_size as f64 >= waste {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item fits into this bin's post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 5.0 + 0.1 * next_item_size as f64;
    }
    // If next item would NOT fit post_residual but fits mean residual elsewhere, mild penalty.
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 && post_residual > 0 {
        score += 2.0;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 && bin_residual != bin_capacity {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }
    // Late in stream: be more conservative with new bins.
    if progress > 0.7 && bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;

    // Base: normalized post residual (waste) with quadratic shaping.
    let x = post / cap; // 0..1
    let mut score = (x * x * (3.0 - 2.0 * x)) * cap; // smoothstep waste curve

    // Non-linear coupling: waste matters more as stream progresses (less chance to fill dead space).
    score += 12.0 * progress * x * x * cap;

    // Reward tight fits (small post residual) with a smooth exponential bonus.
    score -= 8.0 * (-(post * post) / (2.0 * (item + 5.0) * (item + 5.0))).exp();

    // Penalize bins whose residual is far above the mean residual (bad global fit), smooth cubic.
    let d = (residual - mean_residual) / cap;
    score += 6.0 * d * d * d.abs().max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate handling: penalize opening a new bin smoothly,
    // unless the item fits poorly everywhere (post residual would be large relative to capacity).
    let is_new_bin = bin_residual as u32 == bin_capacity && item < cap;
    if is_new_bin {
        // Base penalty for opening a new bin, reduced when the fit is very tight elsewhere is impossible.
        let mut penalty = 15.0 + 10.0 * (1.0 - progress);
        // If next item is large and this item leaves a residual that fits it, opening is more attractive.
        let nxt = next_item_size as f64;
        if nxt > 0.0 && post >= nxt {
            penalty -= 6.0 * (post - nxt) / cap;
        }
        // If many bins are already open, mild extra reluctance to open more.
        penalty += 1.5 * (open_bins_count as f64).ln().max(0.0);
        score += penalty;
    }

    // Lookahead: reward leaving a residual that can host the next item (smooth kernel).
    let nxt = next_item_size as f64;
    if nxt > 0.0 && post >= nxt {
        let slack = (post - nxt) / cap;
        score -= 5.0 * (-slack * slack * 20.0).exp();
    } else if nxt > 0.0 {
        // Penalize leaving a residual just below the next item (dead space trap), smooth bump.
        let gap = (nxt - post) / cap;
        score += 6.0 * (-(gap * cap * gap * cap) / 50.0).exp();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // ---- Perfect and near-perfect fits (harmonic tightness classes) ----
    if post_residual == 0 {
        score -= 1000.0; // exact fill: always take
    } else if post_residual <= 5 {
        score -= 120.0; // dead space negligible
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // ---- Modulo / integer-division harmonic classes on post_residual ----
    // Residuals that are "nice" divisors of 100 (multiples of 10 or 25) are
    // more likely to be reused by future items; reward them mildly.
    let pr = post_residual;
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0;
    }
    if pr > 0 && (pr % 25 == 0 || pr % 20 == 0) {
        score -= 6.0;
    }
    // Small odd residuals (< 10, non-zero) are dead weight; penalize slightly.
    if pr > 0 && pr < 10 && pr % 2 == 1 {
        score += 6.0;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size > pr {
            // Next item cannot use leftover: this bin becomes dead space.
            // Penalize proportionally, but tiny leftovers are cheap.
            let waste = (next_item_size - pr) as f64;
            score += 0.35 * waste;
            if pr >= 10 {
                score += 15.0; // a usable-sized chunk stranded
            }
        } else {
            // Next item fits in the leftover: reward chained packing,
            // strongest when it nearly fills the residual.
            let chain_fill = next_item_size as f64 / pr as f64;
            score -= 10.0 + 25.0 * chain_fill;
        }
    }

    // ---- Last-chance bonus: only this bin can fit the item ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // ---- Congestion-aware scaling ----
    // With many open bins, prefer consolidating into tight fits.
    let congestion = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    score *= 1.0 + 0.5 * congestion;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is good only for perfect fits or when the item
        // is large enough that leftover space stays structured.
        if item_size as f64 >= 0.9 * cap {
            score -= 200.0; // large items: fresh bin is fine
        } else {
            // Penalize so a new bin is chosen only over genuinely bad fits.
            score += 40.0 + 0.4 * (cap - item_size as f64);
            if pr % 10 == 0 {
                score -= 25.0; // clean divisible residual offsets the penalty
            }
        }
    }

    // ---- Mild alignment with mean residual state ----
    score += 0.05 * (mean_residual - pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..=10)
    // are wasted space; penalize hard, but an exact fit (0) is perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight packing quadratically as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Last fitting bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate spreading.
    let pressure = (open_bins_count as f64 / (1.0 + total_items as f64 / 20.0)).min(3.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item won't fit here; slight penalty for stranding capacity
            score += 4.0;
        }
    }

    // Brand-new bin candidate: neutral baseline with mild penalty so it is
    // chosen only when existing bins have bad fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 8.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin accommodates lookahead comfortably
        }
    }

    // Late-stream consolidation: near the end, avoid leaving many tiny gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 && progress > 0.8 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to tightness of the pair
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize leaving a gap smaller than next item
            let gap = (post_residual - next_item_size) as f64;
            score += 50.0 * (1.0 - gap.abs() / bin_capacity as f64);
        }
    }

    // Penalize large post residual relative to mean residual (wasteful bin)
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when item is large and no tight fit exists
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size >= 50 {
            score -= 100.0;
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here anyway; slight penalty for large dead space.
            score += 0.1 * post_residual as f64;
        }
    }

    // Penalize placements into bins that are much tighter than the average
    // when many bins are open (encourage spreading into roomy bins).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // New-bin candidate: only attractive when current item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size > bin_capacity / 2;
        let crowded = fitting_bins_count == 0 || (fitting_bins_count == 1 && item_size < 40);
        if large_item || crowded {
            score -= 12.0 + 10.0 * (item_size as f64 / bin_capacity as f64);
        } else {
            score += 25.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer wasted residuals).
    score += 0.2 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = (1.0 - progress) * norm_pr * norm_pr * cap + progress * norm_pr * cap * 0.5;
    score += poly;

    // Reward tight fits more strongly later in the stream
    score -= progress * (cap - pr) * norm_item * 2.0;

    // Penalize dead space that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let gap = (pr - norm_next * cap).max(0.0) / cap;
        score += gap * gap * cap * (0.5 + progress);
    }

    // Last-chance bonus: smooth function of fitting scarcity
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= scarcity * cap * 0.3 * (0.5 + 0.5 * progress);

    // Mild preference to fill bins below mean residual (balance avoidance)
    score += 0.1 * (mean_residual - pr) / cap * cap * 0.1;

    // Discourage opening new bins early unless residual is large
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += cap * (1.0 - progress) * 0.6 + norm_item * cap * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).

    // Harmonic class of post_residual: modulo classes w.r.t. capacity fractions.
    // Dead space classes: post_residual in 1..=9 is nearly unusable (min item 1, but
    // practically hard); treat small-but-nonzero residuals as dead space.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead harmony: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // partial harmony: reward if post_residual - next_item_size lands in a good class
            let chain = post_residual - next_item_size;
            if chain == 0 {
                score -= 45.0;
            } else if chain <= 9 {
                score += 15.0; // chains into dead space, penalize
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual; penalize large residuals less if
            // they can still absorb typical items later, but penalize mid residuals
            if post_residual >= 50 {
                score -= 5.0;
            } else if post_residual >= 10 {
                score += 8.0;
            }
        }
    }

    // Integer-division thresholds on post_residual: classify into capacity fractions.
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50
    if post_residual >= half {
        score -= 12.0; // roomy bin still useful
    } else if post_residual >= quarter {
        score += 4.0;  // mid residual: moderate
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly: penalize so it is chosen only when open bins fit badly.
        score += 55.0;
        // But if many bins are open and mean residual is low, new bin is more attractive.
        score -= (open_bins_count as f64).sqrt() * 2.0;
        if mean_residual < 15.0 {
            score -= 10.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 15.0;
        }
    }

    // Prefer filling bins that are already partially loaded (reduce bin count pressure).
    if bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Mild tie-break: earlier bins (fewer open bins) preferred slightly.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
