pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step chain: next item exactly fills this bin's remainder
            score -= 40.0;
        } else if next_item_size > post_residual {
            // Next item cannot use the leftover -> dead space; small leftovers hurt more
            score += (20.0f64 - (post_residual.min(20) as f64)) * 0.5;
        } else {
            // Next item fits but leaves further waste
            score += (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    if is_new_bin {
        // Default penalty for opening a new bin, softer late in the stream
        score += 10.0 - progress * 5.0;
        // But strongly favor a new bin if the item + next item exactly fill it
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 50.0;
        }
    } else {
        // Last-chance bin: avoid opening a new bin unnecessarily
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // Reward bins whose residual is below the mean (tight bins first)
        score += (mean_residual - post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize small dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        if fit_ratio > 0.6 && fitting_bins_count >= 1 {
            score += 60.0; // opening new bin when a decent fit exists is bad
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0 * (1.0 - (bin_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64);
        }
    }

    // Global state coupling: prefer filling bins below mean residual (balancing).
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early on, be conservative (penalize fragmentation);
    // later, prioritize closing out bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.1 * post_residual as f64;
    score -= t * 8.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of residual.
    let mut score = norm_post * norm_post * (2.0 - norm_post);

    // Smooth progress coupling: later in stream, penalize larger residuals more strongly.
    score += norm_post * (0.5 + 1.5 * progress * progress);

    // Interaction: post_residual * item_size normalized — big items into big-residual bins.
    let item_n = item_size as f64 / cap;
    score -= item_n * norm_post * 0.8;

    // Last-chance bonus: only one fitting bin, avoid opening new bin.
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 0.4 * snug;
        } else {
            // Next item won't fit here: slight penalty proportional to wasted gap.
            score += 0.15 * (nxt - pr) / cap;
        }
    }

    // Mean-residual deviation coupling: bins far below mean residual are less attractive.
    let dev = (mean_residual - pr) / cap;
    score += 0.1 * dev * dev;

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // when no good alternatives exist (post_residual here equals capacity).
    if bin_residual == bin_capacity {
        score += 0.9 + 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
