    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.75;
        // If existing bins are tight on options, opening is less bad.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If the item fits a small residual elsewhere harmonically, discourage new bin.
        if next_item_size > 0 && next_item_size == post_residual {
            score += 20.0;
        }
    }

    // Slight preference for filling already-open bins when many are open.
    score += open_bins_count as f64 * 0.5 * (bin_residual as f64 / bin_capacity as f64);

    // Progress-scaled tiebreak to stabilize late-stream choices.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.01 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    // Quadratic penalty concentrated in the small-gap zone (0..=12).
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * (13.0 - post_residual as f64) * 0.9;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of the bin's usable space consumed.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many bins open, discourage spreading; with few bins,
    // allow consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (1.5 + progress);

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size == 0 {
            score -= 35.0; // chain of perfect fits
        } else if post_residual - next_item_size <= 12 {
            score += 15.0; // would create dead space next step
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate: only attractive when existing fits are poor.
    // Base cost of opening a bin, discounted early in the stream.
    if bin_residual == bin_capacity {
        let opening_cost = 45.0 - 20.0 * progress;
        // If this bin is the last chance, opening a new bin is comparatively bad.
        let last_chance_tax = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        score += opening_cost + last_chance_tax;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Reward closeness so the leftover after next placement is minimal.
            let leftover_after_next = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - leftover_after_next / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 8.0 * (shortfall / bin_capacity as f64);
        }
    }

    // Penalize very small unusable post_residual (dead space), unless it's zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Compare against mean residual: prefer consuming bins with above-average residual,
    // keep tight bins (below-mean residual) for later small items.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // Early in the stream, be more willing to open new bins (keep options open);
    // later, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later and when many bins open.
        score -= 20.0 * (1.0 - progress);
        score += 15.0 * progress;
        score += 2.0 * open_bins_count as f64;
        // Don't open a new bin when a near-perfect fit exists elsewhere.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 && (next_item_size as u64) <= post_residual as u64 {
        score -= 5.0 + 0.05 * next_item_size as f64;
    }
    // Penalize when next item could have fit before placement but not after.
    if next_item_size > 0 && (next_item_size as u64) <= bin_residual as u64 && (next_item_size as u64) > post_residual as u64 {
        score += 8.0;
    }

    // New-bin candidate handling: prefer new bin only when it genuinely helps.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 30.0;
        // If existing bins are fragmented (low mean residual), a fresh bin is attractive.
        score -= (cap - mean_residual).max(0.0) * 0.35;
        // Few fitting bins -> new bin more acceptable.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // Large current item into a fresh bin is efficient (post_residual = cap - item).
        score -= 0.1 * item_size as f64;
    }

    // Prefer filling bins that are already well-used (small residual) over near-empty ones.
    score += 0.08 * (bin_residual as f64 - post_residual as f64).signum() * (bin_residual as f64 / cap) * 4.0;

    // Mild pressure against leaving many half-empty bins open.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let residual_norm = post / cap;

    // Base: prefer minimal post residual, with mild non-linear inflation
    let mut score = post + 12.0 * residual_norm * residual_norm * (1.0 - progress);

    // Reward tight fits (small post_residual) increasingly as stream progresses
    let tightness = 1.0 - residual_norm;
    score -= 18.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small to be useful (coupled with mean residual)
    let mean_norm = mean_residual / cap;
    let dead = residual_norm * (1.0 - residual_norm);
    score += 10.0 * dead * (1.0 - mean_norm);

    // Lookahead coupling: if next item fits the post residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 * (1.0 - progress) * ((next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 6.0 * progress * ((next_item_size as f64) / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening bins, more so when open bins fit well
    if bin_residual == bin_capacity {
        score += 14.0 + 6.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0 * (1.0 - residual_norm);
        }
    }

    // Mild crowding penalty: many open bins -> prefer filling existing ones
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * residual_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Reward residuals that fall into "usable" harmonic classes (multiples of
    // common item sizes / capacity fractions), penalize dead space in between.
    let class = (post_residual % 10) as f64;
    score += class * 1.5; // misalignment with 10-grid is dead space

    // Strong reward for near-perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if pr <= quarter {
        // Small residual class: usable only by tiny items; mildly penalize.
        score += 8.0;
    } else if pr <= 2.0 * quarter {
        // Half-capacity class: highly reusable.
        score -= 12.0;
    } else if pr <= 3.0 * quarter {
        score -= 4.0;
    }

    // Integer-division threshold on post_residual: residuals that can host
    // typical next items are valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward if residual also fits next item with tight slack.
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Post residual cannot host next item: penalize proportionally.
        score += (next_item_size as f64 - pr) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the item
    // is large or all existing fits are poor.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        // Opening fresh is good for big items (large post_residual usable later),
        // bad for small items that should patch existing bins.
        score = cap - (fill * 45.0);
        if fill > 0.6 {
            score -= 20.0;
        }
        if fitting_bins_count > 0 && fill < 0.35 {
            score += 30.0; // discourage new bin for small items
        }
    }

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / cap);

    // Slight preference for bins below mean residual (use lopsided bins first),
    // keeping balanced bins for future items.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Penalize waste relative to capacity fraction classes (harmonic scaling).
    score += (pr / cap) * (pr / cap) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gap creation).
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits: the smaller the post_residual relative to capacity,
    // the better the packing.
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 8.0;

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; mild penalty scaled by number of open bins.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot use this gap; penalize leaving a gap smaller
            // than the next item.
            score += 3.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., already well-filled bins) to consolidate packing.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate handling: an empty bin gets a base cost so it is only
    // chosen when existing fits are poor; but if no open bin fits, opening a
    // new bin is necessary (fitting_bins_count==1 covers the only-fit case,
    // and the empty bin itself is the only candidate then).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening new bins is less costly than leaving
        // many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            // Next item can follow directly: reward tight chain fits.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            // Perfect follow-up (post_residual == next_item_size) gets big bonus.
            if diff < 1.0 {
                score -= 45.0;
            }
        } else {
            // Next item cannot follow: penalize leftover dead space,
            // scaled by how large the unusable gap is.
            score += 8.0 * (nxt - post) / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: avoid leaving
    // residuals far above the mean (fragmentation risk).
    let post_f = post_residual as f64;
    if post_f > mean_residual {
        score += 0.6 * (post_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_f);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Penalize opening a new bin when decent existing bins exist,
    // but allow it when the item is large and fit is tight elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline score = full capacity residual.
        // Subtract a small amount so it beats very bad fits, but keep
        // it worse than good chain matches.
        score -= 10.0;
        if next_item_size > 0 && next_item_size as f64 > post_f {
            score -= 12.0; // fresh bin suits a large upcoming item
        }
    }

    // Slight preference for tighter fits overall.
    score += 0.25 * (post_f / bin_capacity as f64) * 10.0;

    // Late-stream consolidation: as the stream nears its end,
    // prefer filling existing bins more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 6.0 * progress * (1.0 - post_f / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Penalize exact-fit waste only mildly; reward near-perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Bonus scaled by how well the next item fills the leftover.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * next_fit;
        } else {
            // Leftover too small for next item: dead-space penalty grows with stream progress.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer the bin with the smallest residual among them.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Global state coupling: when mean residual is high, prefer filling fuller bins.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate handling: penalize opening a new bin, unless the item
    // cannot fit any open bin well (this call would be the empty-bin call).
    if bin_residual == bin_capacity {
        let base_penalty = 20.0 + open_bins_count as f64 * 1.5;
        if fitting_bins_count == 0 {
            // No open bin fits: opening is necessary, mild penalty.
            score += base_penalty * 0.2;
        } else {
            // An open bin fits; only open new bin if existing fits are terrible
            // (very small residuals left elsewhere) — approximate via mean_residual.
            if mean_residual < item_size as f64 * 0.5 {
                score += base_penalty * 0.3;
            } else {
                score += base_penalty;
            }
        }
    }

    // Slight preference for bins with more residual used so far (consolidation).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Small time-horizon modulation: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= tightness * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = item_size as f64 / cap;
    let tight = 1.0 - pr / cap;

    // Base: post-residual with smooth non-linear shaping (quadratic in tightness)
    let mut score = pr * (1.0 + 0.6 * tight * tight);

    // Progress-coupled polynomial: late in stream, favor tighter fills more strongly
    let p2 = progress * progress;
    score -= 25.0 * p2 * (1.0 - (1.0 - tight) * (1.0 - tight)) * fit;

    // Coupling with mean residual: penalize bins far from mean (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 + progress);

    // Lookahead interaction: reward leaving room for next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        let k = (-gap * gap * 12.0).exp();
        score -= 18.0 * k * (nx / cap);
        // penalize near-exact but wasteful matches for next item
        score += 6.0 * (1.0 - k) * fit * fit;
    }

    // Last-chance bonus: strongly favor using the only fitting bin (smooth)
    let last = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 30.0 * last * (0.5 + 0.5 * fit);

    // Discourage opening new bins when good fits exist: penalize empty-bin candidate smoothly
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score += 15.0 + 20.0 * (1.0 - progress) + 10.0 * fit;
        // allow new bin only if current bin would leave very small dead space elsewhere
        score -= 12.0 * (tight * tight) * (1.0 - fit);
    }

    // Mild penalty for many open bins (encourage consolidation), smooth in count
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - fit);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual ---
    // Class items into capacity-fraction bands: (0,10], (10,25], (25,50], (50,100)
    let residual_class = if post_residual == 0 { 0u8 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward exact / near-exact fills heavily
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize "dead space": residual too small for the smallest plausible item (1)
    // but too awkward for typical classes; scale penalty by residual class
    match residual_class {
        1 => score -= 5.0,                 // small leftover is fine
        2 => score += 8.0,                 // moderate leftover is wasteful
        3 => score += 18.0,                // large leftover: could have held more
        4 => score += 30.0,                // half-empty bin: bad choice
        _ => {}
    }

    // --- Modulo / integer-division harmonic coupling ---
    // Reward when post_residual is divisible by common item granularities (5, 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Penalize prime-ish awkward residuals
    if post_residual % 10 != 0 && post_residual % 5 != 0 && post_residual > 0 && post_residual < 20 {
        score += 4.0;
    }

    // --- Lookahead: can next item exactly fill the post residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;                 // perfect chain: reserve this bin
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // next item won't fit here: penalize proportionally
            score += 10.0;
        }
    }

    // --- Last-chance bonus: only this bin fits; avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    // Brand-new empty bin: only attractive when current bin would be badly fragmented
    if bin_residual == bin_capacity && bin_capacity == 100 {
        // Base cost of opening a new bin
        score = 45.0;
        // Attractive if the item is large (fills new bin well) or lookahead is large
        score -= 0.5 * item_size as f64;
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Discourage opening new bins when a good fit exists elsewhere
        if post_residual_class_good(item_size) {
            score += 25.0;
        }
        // Early in stream, bins are cheap to open (exploration)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // Many open bins already: prefer consolidation
        score += 2.0 * open_bins_count as f64 * 0.5;
    }

    // --- Mean residual context: prefer bins near the mean (balanced packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild tie-breaker: prefer fuller bins
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

#[inline]
fn post_residual_class_good(item_size: u32) -> bool {
    // item sizes that pair well with typical residuals in a fresh bin
    item_size >= 60
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space (min item size 10)
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Medium gaps that only fit very small items are also poor.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    }
    // If next item cannot fit in the gap, the gap is likely dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage filling existing ones tighter (prefer smaller post_residual anyway).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Slight preference for bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: make it moderately attractive only when it beats a bad fit.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Perfect chain fit: post residual exactly matches next item
            if gap == 0 {
                score -= 500.0;
            } else {
                // Reward closeness of chain fit
                score -= 200.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit here: penalize wasted residual
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when good fits exist (new-bin candidate baseline)
    if bin_residual == bin_capacity {
        score += 250.0;
        // Late in the stream, avoid opening new bins even more
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 150.0;
        }
    }

    // Slight preference for bins with less residual overall (tight packing)
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.91;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let res = bin_residual as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear fill ratio coupling: reward high utilization quadratically
    let fill = (cap - pr) / cap;
    score -= 18.0 * fill * fill;

    // Polynomial interaction of post_residual with stream progress:
    // early on, tolerate loose fits (future items may fill gaps);
    // late, penalize dead space more strongly.
    let prn = pr / cap;
    score += 30.0 * prn * prn * (0.3 + 0.7 * progress);

    // Dead-space hazard: residuals too small for likely future items
    let small_threshold = 10.0;
    if pr < small_threshold {
        score += 8.0 * (small_threshold - pr);
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize empty bin unless item is large
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 6.0 + 10.0 * (1.0 - it / cap);
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (prn - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Harmonic dead-space classes: small unusable fragments are worse than exact closure.
    let pr = post_residual;
    score += (pr % 10) as f64 * 0.35;
    score += match pr {
        0 => -9.0,          // perfect closure: best possible outcome
        1..=5 => -2.5,      // near-perfect, tiny dead space
        6..=10 => 1.5,      // awkward fragment class
        _ => 0.0,
    };

    // Lookahead coupling: reward bins whose post-residual harmonically matches next item.
    if next_item_size > 0 {
        let gap = pr.saturating_sub(next_item_size);
        if pr >= next_item_size {
            score -= 2.5;
            score += (gap % 20) as f64 * 0.06; // coarse class penalty on leftover
        }
        if gap <= 3 {
            score -= 3.0; // next item closes this bin almost exactly
        }
        // Penalize leaving a residual just barely below the next item (worst class).
        if pr > 0 && pr < next_item_size && pr < 10 {
            score += 2.0;
        }
    }

    // Last-chance bin before opening a new one: strong reward (but not for the fresh bin).
    let is_new_bin = bin_residual == bin_capacity;
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 6.0;
    }

    // New-bin candidate: penalize so existing bins are preferred, easing up late in stream.
    if is_new_bin {
        score += 12.0 - 6.0 * progress;
        // If the item is huge, a fresh bin is less bad.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 4.0;
        }
    }

    // Mild penalty for scattering residual far above mean (fragmented capacity).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum plausible
    // future item are "dead" and get a heavy nonlinear penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to bin_residual).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += 25.0 * fit_ratio * fit_ratio;

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new ones.
    let pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0));
    score += 15.0 * pressure;

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (a nearly-full bin), favor finishing it off.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.15 * dev;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists (large post_residual elsewhere
    // or the item barely fits anywhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progression.
        score = bin_capacity as f64 + 10.0 * (step_index as f64 / (total_items as f64).max(1.0));
        // If the item is large relative to capacity, opening fresh is safer.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead: post_residual == next_item_size => perfect pair.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // exact match: place here
        } else {
            score += diff * 0.6; // penalize mismatch
        }
        // If next item fits exactly in post_residual region but not this bin, mild bonus
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: minimize waste, prefer tightest fit
        score += 0.0;
    }

    // Penalize leaving dead space far below mean residual (fragmentation risk)
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.3;
    } else {
        score -= (pr - mean_residual) * 0.15;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // Opening a new bin wastes (capacity - item) potential; make it costly
        score += 45.0;
        // But if item is huge relative to capacity and no open bin fits well, allow it
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Late in stream, new bins are cheaper (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Small reward for using emptier bins when many are open (bin consolidation)
    if open_bins_count > 4 {
        let rel_fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= rel_fullness * 5.0;
    }

    // Penalize very small post_residuals that are unusable dead space
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual gets quadratic bonus).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (pr / cap);
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: residual too small for typical items (1..100).
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow here; slight penalty for wasting space
            score += 10.0 * (1.0 - (pr / cap));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to prefer exactness among many candidates
        score += 3.0 * (fitting_bins_count as f64);
    }

    // Global state: if many open bins with slack, discourage hoarding new bins.
    let mean_r = mean_residual;
    if bin_residual as f64 > mean_r {
        score -= 8.0 * (bin_residual as f64 - mean_r) / cap;
    } else {
        score += 8.0 * (mean_r - bin_residual as f64) / cap;
    }

    // Time horizon: early in stream, be conservative (avoid fragmenting bins);
    // late in stream, pack greedily into anything available.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fit_ratio;

    // New-bin candidate handling: neutral baseline, penalized when good fits exist
    // among open bins, but attractive when the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score = 35.0 - 30.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 10.0; // big pair coming: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base cost: quadratic penalty on wasted residual space.
    let mut score = post * post / cap;

    // Reward tight fits: small post_residual relative to capacity.
    score -= (1.0 - post / cap) * 20.0;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (poly interaction).
    let prog2 = progress * progress;
    score += post * (0.15 + 0.85 * prog2);

    // Cubic coupling: extreme residuals late in the stream are heavily penalized.
    score += (post / cap).powi(3) * 40.0 * (0.3 + 0.7 * progress);

    // Next-item lookahead: bonus if post_residual can fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_ratio = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack_ratio);
    } else if next_item_size > 0 {
        // Smooth penalty for blocking the next item, scaled by how close it was.
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 8.0 * gap;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage filling existing bins rather than spreading.
    let open_norm = (open_bins_count as f64).ln().max(0.0);
    score += open_norm * (post / cap) * 6.0;

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += (post - mean_residual) * 0.25;

    // New-bin candidate: penalize opening a new bin, more so early/mid stream
    // and when other bins can fit the item; relax late in stream.
    if bin_residual == bin_capacity {
        let base_open = 30.0 + 40.0 * (1.0 - progress);
        let fitting_pressure = if fitting_bins_count > 0 { 25.0 } else { 0.0 };
        // If the item is large relative to capacity, opening fresh may be fine.
        let size_relief = (item_size as f64 / cap) * 20.0;
        score += base_open + fitting_pressure - size_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod-10 classes over capacity 100) ---
    // Residuals that are "harmonically useful" (divisible into common item sizes)
    // should be rewarded. Dead-space classes (tiny residuals) penalized.
    let pr = post_residual as i64;
    let class = pr % 10;
    let class_bonus: f64 = match class {
        0 => -6.0, // residual is a multiple of 10: maximally reusable
        5 => -4.0, // multiple of 5: still quite reusable
        2 | 4 | 6 | 8 => -2.0, // even residuals pair well with even items
        _ => 2.5,  // odd residuals: awkward dead space
    };
    score += class_bonus;

    // Integer-division thresholds: residual "tiers" by quarter capacity
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 8.0; // nearly dead bin: heavy penalty
    } else if post_residual <= 2 * quarter {
        score -= 1.0; // half-ish residual: fine
    } else {
        score -= 3.0; // roomy residual: good target
    }

    // --- Lookahead coupling: does this placement leave room for next item? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic check: post_residual - next_item_size lands in a good class
        let nxt = (post_residual - next_item_size) as i64;
        if nxt % 10 == 0 {
            score -= 10.0;
        } else if nxt % 5 == 0 {
            score -= 6.0;
        }
        score -= 4.0; // general reward for keeping next item placeable
    } else if next_item_size > 0 {
        score += 3.0; // kills the next item's fit in this bin
    }

    // --- Last-chance bin: strongly favor using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: moderate.
        score += 15.0;
        // But if existing bins would leave awful residuals (poor fit), new bin wins.
        // Detect poor fit: item barely fits / leaves tiny residue elsewhere.
        if post_residual > 0 && post_residual < item_size / 3 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheap (future items need homes).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Many open bins with slack: discourage yet another bin.
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 12.0;
        }
    }

    // --- Tight-fit reward: near-perfect packing ---
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Small regularization toward mean residual to balance bin usage.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are almost unusable
    // for future items (min item size ~10 in classic regime). Penalize them hard,
    // but a perfect fit (post_residual == 0) is ideal.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 12.0; // dead-space penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // Usable leftover: mild reward for leaving room, scaled by how well the
        // residual could host the lookahead item.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 6.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when few
    // bins are open, opening a new one is cheaper so slightly favor tight fits there.
    let obp = open_bins_count as f64;
    score += obp * 0.35;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it attractive
    // only when the current fit would be terrible (huge dead space) or when the
    // lookahead item would be stranded.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        let stranded_lookahead = next_item_size > 0
            && next_item_size <= bin_capacity
            && post_residual > 0
            && post_residual < next_item_size
            && (next_item_size as f64) <= mean_residual;
        if bad_fit || stranded_lookahead {
            score -= 45.0;
        } else {
            score += 15.0; // keep using existing bins by default
        }
    }

    // Mean-residual coupling: high average leftover space means capacity is being
    // wasted across the fleet; nudge toward bins that consume more of it.
    score -= (mean_residual - pr) * 0.25;

    // Stream progression: late in the stream, avoid opening new bins at all costs
    // (fewer future items to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Aggressive 2-step lookahead: reward when next_item_size fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let match_quality = 1.0 - gap / (bin_capacity as f64);
        score -= 10.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to wasted capacity
        let overshoot = (next_item_size - post_residual) as f64;
        score += 0.15 * overshoot;
    } else {
        // Last item: pure tight-fit preference
        score -= 4.0 * tightness;
    }

    // Relative to mean residual: bins with residual far below mean are precious (compact bins);
    // placing into them is good if it closes them out
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= 2.0 * (mean_residual - res_f) / (bin_capacity as f64);
    } else {
        score += 1.5 * (res_f - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a very poor fit
    if bin_residual == bin_capacity {
        score += 25.0;
        // But allow new bin if lookahead promises a perfect two-item pairing
        if next_item_size > 0 && next_item_size + item_size == bin_capacity {
            score -= 30.0;
        }
        // Late in stream with many open bins, avoid spreading
        if open_bins_count > 4 {
            score += 5.0;
        }
    }

    // Penalize leaving dead space below the minimum item size (1..100 unknown; use small threshold)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that is hard to reuse (post_residual just above tiny-item range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize leaving large residual only mildly
            score += 3.0;
        }
    }

    // Last-chance bonus: this is the only fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in stream, opening bins is cheap; late in stream, prefer reusing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If many bins are open with lots of slack, discourage a new one.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += (mean_residual / bin_capacity as f64).max(0.0) * 8.0;
    }

    // Mild penalty for leaving residual far from typical reusable sizes.
    let mid = 25.0;
    if post_residual > mid {
        score += 0.08 * (post_residual as f64 - mid);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), non-linearly.
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = x * x * (3.0 - 2.0 * x) * cap; // smoothstep-shaped penalty on wasted space
    score += 0.35 * post;

    // Coupling: waste matters more as the stream progresses (fewer chances to reuse dead space).
    score *= 1.0 + 0.8 * progress * x;

    // Penalize bins far from the mean residual (fragmentation avoidance), smooth quadratic.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item; penalize when post_residual
    // is just barely too small for it (blocking) or excessively large (wasteful).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // smooth reward for compatibility with the next item
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // near-miss penalty: smooth rise as post approaches nxt from below
            let miss = (nxt - post) / cap;
            score += 10.0 * (1.0 - miss) * (1.0 - miss);
        }
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty when
    // the item fits no open bin well (fitting_bins_count small) or many bins are open.
    if bin_residual == bin_capacity {
        let escape = 1.0 / (1.0 + fitting_bins_count as f64);
        score = cap + 0.5 * cap * (1.0 - escape) - 0.3 * open_bins_count as f64;
        // late in the stream, new bins are less attractive
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic classes: post_residual divisible by small sizes stays usable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0; // residue in the classic harmonic set
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else if pr % 2 == 0 {
            score -= 1.5;
        } else {
            score += 3.0; // odd awkward residues are dead space
        }
        // Integer-division threshold: large residue classes are "half-empty" bins.
        if pr / 2 >= 25 {
            score += 6.0; // leaving >25 unused is wasteful unless unavoidable
        }
    }

    // Reward filling bins that are already mostly full (small residual).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // no open bin fits well (this call has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // If the next item is large, a fresh bin may be justified.
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item exactly fills the post-residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual && (post_residual - next_item_size) % 5 == 0 {
            score -= 6.0;
        } else if next_item_size > post_residual {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    // Slight stream-phase modulation: prefer tight packing early.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - phase);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold even the smallest plausible item
    // are worthless. Penalize small-but-nonzero post residuals extra hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver = dead space
    } else if post_residual < 20 {
        score += 15.0; // risky gap: only tiny items can use it
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but only when the fit is mediocre (post_residual large).
    score += (open_bins_count as f64) * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Progression: early in the stream, keep residual space flexible
    // (penalize very tight fits slightly); late in the stream, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's an outlier bin — using it consolidates fragmentation.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.2 * (bin_res_f - mean_residual);
    }

    // New-bin candidate: make an empty bin attractive only when the item is
    // large relative to capacity (poor fit candidates elsewhere) — its raw
    // post_residual is already high, add a mild penalty so it loses to good fits.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0 + (next_item_size as f64) * 0.5;
        // exact match of post_residual to next item is a double win
        if post_residual == next_item_size {
            score -= 250.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space that cannot host the next item
        let waste = post_residual as f64 - (bin_capacity as f64 - next_item_size as f64).max(0.0).min(post_residual as f64);
        score += waste * 0.15;
    }

    // Small post-residual is generally good (tight packing)
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if next item is large and post_residual matches it, new bin is fine
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64) == next_item_size as i64 {
            score -= 100.0;
        }
        // open fewer bins when many bins already open with high mean residual
        if mean_residual > item_size as f64 * 1.5 {
            score += 50.0;
        }
    }

    // Compare against mean residual: bins tighter than mean are more valuable to preserve
    if (bin_residual as f64) < mean_residual {
        score -= 40.0;
    } else {
        score += 20.0;
    }

    // Late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: bonus if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 * next_fit;
        } else {
            // Next item cannot use this residual; penalize wasted space proportionally.
            score += 0.05 * post_residual as f64;
        }
    }

    // New-bin candidate logic: empty bin starts with high score unless open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.6 + 10.0;
        // If existing bins are fragmented (mean residual small), opening new bin is fine.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 12.0;
        }
        // Early in stream, prefer opening bins (more flexibility later).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is less justified.
        score += 2.0 * (fitting_bins_count as f64).powf(1.3);
    } else {
        // Prefer bins whose residual is close to item size (best-fit style).
        let gap = (bin_residual - item_size) as f64;
        score += 0.02 * gap * gap;
        // Late in stream, be greedy: fill existing bins harder.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
        // Mild penalty when many open bins exist, encouraging consolidation.
        score += 0.1 * open_bins_count as f64;
    }

    // Global fragmentation pressure: if mean residual is high, reward filling bins.
    score -= 0.03 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) coupling
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Tight fit reward: strongly reward near-perfect packing
    let tightness = 1.0 - norm_pr;
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    let dead = if next_item_size > 0 && (next_item_size as f64) > pr {
        (next_item_size as f64 - pr) / cap
    } else if next_item_size == 0 {
        pr / cap
    } else {
        0.0
    };
    score += 25.0 * dead * dead * cap;

    // Lookahead coupling: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - diff / cap).max(0.0);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in stream
    if bin_residual == bin_capacity {
        score += 50.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Mild penalty when bin residual deviates from mean residual (balance bins)
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Smooth stream-progress interaction: late in stream, prefer filling bins tighter
    score *= 1.0 - 0.2 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers in a "tight" class (small) are good.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left

    // Class boundaries: 0, 10, 20, 30, 50, 70, 100 (harmonic thresholds)
    let class = if post_residual == 0 { 6.0 }
        else if post_residual <= 10 { 5.0 }
        else if post_residual <= 20 { 4.0 }
        else if post_residual <= 30 { 3.0 }
        else if post_residual <= 50 { 2.0 }
        else if post_residual <= 70 { 1.0 }
        else { 0.0 };

    // Reward tight fits strongly (lower score for smaller class index)
    score -= class * 4.0;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo-style harmonic bonus: post_residual divisible by small steps
    // (10, 20, 25) suggests future items may tile the leftover cleanly.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 1.5; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // next item fits: leftover after chain matters
            let chain_left = post_residual - next_item_size;
            if chain_left <= 10 { score -= 6.0; }
        } else {
            // next item cannot use the leftover; penalize large stranded space
            if post_residual < next_item_size && post_residual > 0 {
                score += 0.05 * (post_residual as f64);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 15.0;
        // Large items: starting a fresh bin is fine (they leave big residue anyway)
        if item_size >= 50 {
            score -= 10.0;
        }
        if item_size >= 70 {
            score -= 5.0;
        }
        // Late in the stream, fewer open bins means consolidation matters less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
        // If open bins are fragmented (high mean residual spread), new bin ok
        if mean_residual < (cap - item_size as f64) {
            score -= 3.0;
        }
    }

    // Mild penalty for wasting a nearly-empty bin on a tiny item
    if item_size <= 20 && post_residual >= 70 {
        score += 6.0;
    }

    // Prefer placing into bins with below-average residual (consolidate fullness)
    score += 0.02 * (mean_residual - (bin_residual as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: residuals too small to hold the smallest item (1) are
    // not possible here, but tiny residuals (< 20) are unlikely to be reused.
    let r = post_residual as f64;
    if post_residual > 0 && post_residual < 20 {
        // Unusable small gap: heavy penalty proportional to how much we "wasted".
        score += (20.0 - r) * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward leaving residuals that can plausibly fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Leaving a gap that cannot hold the next item: mild penalty.
        score += 5.0;
    }

    // Reward tight fits relative to the bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        // Using an existing bin relieves open-bin pressure.
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (larger residual than average is more valuable to fill).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be more conservative about filling bins tightly
    // (keep flexibility); later, maximize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that cannot fit the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact chain fits: post_residual == next_item_size is ideal.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 6.0 * waste / bin_capacity as f64;
        }
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * tightness * tightness;

    // Penalize bins far below mean residual (fragmented outliers),
    // reward bins above mean residual (consolidating space).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this placement would leave an awkward residual. The empty-bin call has
    // post_residual == bin_capacity - item_size; make it competitive only when
    // the current fit is poor (large post_residual relative to item size).
    if bin_residual == bin_capacity {
        // Slight default penalty so tight fits into open bins win.
        score += 4.0;
        // But if the item is large relative to residual, a fresh bin is fine:
        // (empty bin already yields minimal post_residual for large items).
        if item_size >= 60 {
            score -= 6.0;
        }
        // Late in the stream, prefer closing out open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early phase favors consolidation, late phase favors tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits: quadratic penalty on wasted space relative to bin.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Reward filling a bin substantially (large item into this bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item can use the post-residual, reward leaving
    // exactly that much space; penalize residuals that are too small for the next item.
    if next_item_size > 0 {
        let next_fits = (post_residual as u32) >= next_item_size;
        if next_fits {
            // Reward leaving space usable by next item, scaled by how snug it is.
            let snug = 1.0 - ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
            score -= 15.0 * snug;
        } else {
            // Dead space for the next item: penalize proportionally to how far off it is.
            let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 10.0 * gap;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than fragmenting.
    let consolidation_pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= 2.0 * consolidation_pressure.min(20.0);
    }

    // New-bin candidate handling: empty bin should only win when the item is large
    // (poor fit elsewhere is likely) or late in the stream when consolidation is done.
    if bin_residual == bin_capacity {
        let size_pressure = (item_size as f64 / bin_capacity as f64).powi(2);
        score += 45.0 - 40.0 * size_pressure - 20.0 * progress;
        // If no open bin can fit, new bin is mandatory anyway; soften penalty.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping
    let mut score = post * (1.0 + 0.8 * norm_post) + 45.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: later in stream, more value on tight fits
    score *= 1.0 + 0.5 * progress * norm_post;

    // Dead-space penalty: post_residual too small to ever fit another item (min item 1)
    if post > 0.0 && post < 1.0 {
        score += 0.0;
    }

    // Reward exact fits strongly
    if post == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item could use post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // post residual likely wasted relative to next item
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    } else {
        // mild penalty when many bins compete, encouraging consolidation
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual, prefer it (fills emptier bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 5.0 * dev;

    // New-bin candidate: penalize opening a new bin unless it is genuinely better
    if bin_residual == bin_capacity {
        score += 55.0 - 20.0 * progress + (open_bins_count as f64) * 0.5;
        // opening a new bin is fine if item is huge relative to typical residual
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in 1..=10 are nearly unusable (items >= 10).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Harmonic class of post_residual: modulo-10 buckets.
    let class = (post_residual % 10) as f64;
    score += class * 0.4;

    // Lookahead: reward if next item fits into post_residual, penalize blocking it.
    if next_item_size > 0 && next_item_size <= 100 {
        if next_item_size <= post_residual {
            // Next item can use leftover: reward proportionally to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): only attractive when residuals are fragmented
    // or the fit is bad. Base cost of opening a bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        // More attractive late in stream with many open bins? Penalize extra.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If item leaves big residual in fresh bin and next item is large, mild bonus.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Prefer bins tighter than the mean (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Mild preference to fill bins with large residual fraction used.
    let used_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Near-perfect fit: residual < 10 is essentially dead space eliminated.
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        // Mid-sized gap: partially usable, mild penalty relative to raw residual.
        score += 15.0;
    } else if post_residual > 50 {
        // Large leftover: wasteful unless a new bin (handled below).
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate penalty: only allow opening a bin if no open bin fits decently.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Lookahead: if the next item can use the leftover of this fresh bin, soften penalty.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 18.0;
        }
        // If this is the only option anyway, neutralize the penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Lookahead synergy: current leftover exactly hosts the next item.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }

    // Mild pressure scaling with number of open bins: discourage spreading when many bins open.
    score += (open_bins_count as f64) * 0.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-step match: post_residual exactly accommodates next item.
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Slack after next item fits: mildly penalize large leftover.
            let slack = post - nxt;
            score -= 25.0 - 0.35 * slack;
        } else {
            // Next item won't fit here: dead space penalty grows with gap.
            score += 0.9 * (nxt - post);
        }

        // Relative-to-mean coupling: bins tighter than the mean are more valuable.
        let mean = if mean_residual.is_finite() { mean_residual } else { post };
        let rel = (post - mean) / (bin_capacity as f64);
        score += rel * 12.0;
    } else {
        // No lookahead: pure tight-fit objective.
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is terrible or
    // item is large and would leave a near-empty awkward residual.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Big items justify a fresh bin; small items should go into open bins.
        score = score * 0.9 + (1.0 - fill_ratio) * 55.0;
        // Fewer open bins -> cheaper to open another.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Slight late-stream conservatism: consolidate as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 24.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: post residual below the minimum item size is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 20.0 * lookahead_tightness;
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty for blocking tight residual.
        score += 6.0;
    }

    // New-bin candidate handling: empty bins should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when open-bin scores are bad.
        score += 15.0;
        // Later in the stream, more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins are already open, discourage another.
        score += 0.5 * open_bins_count as f64;
        // If the item is huge relative to capacity, a fresh bin is more attractive.
        score -= 0.2 * item_size as f64;
    }

    // Global residual pressure: when mean residual across open bins is small,
    // prefer spreading items (avoid fragmenting scarce space).
    if mean_residual < item_size as f64 * 1.5 {
        score += 8.0;
    }

    // Mild time-horizon exploration: early in the stream, experiment more with
    // less-obvious placements by flattening differences; late, be greedy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 0.8 + 0.4 * progress;

    // Small preference for bins with larger residual when late in stream
    // (keeps flexible space around for awkward items).
    score -= 0.05 * progress * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual), scaled non-linearly.
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste matters more -> amplify post_residual penalty.
    let amp = 1.0 + 2.0 * progress * progress;
    score += 0.8 * (post / cap) * (post / cap) * amp * cap * 0.1;

    // Reward filling bins deeply (large item relative to residual).
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when open bins exist that could fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    // Lookahead: if next item would fit the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize leaving awkward dead space.
        score += 2.0 * (post / cap);
    }

    // Prefer bins whose residual is near the mean residual (balanced packing).
    score += 0.05 * (post - mean_residual).abs();

    // Mild pressure against accumulating many open bins.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Perfect fit: strongest reward ---
    if post_residual == 0 {
        score -= 500.0;
    }

    // --- Dead-space penalty: unusable slivers (space < smallest item) ---
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // --- Harmonic class of post_residual modulo item_size ---
    // Residuals that are multiples of the item size are "harmonic" and
    // likely reusable by future same-class items.
    if item_size > 0 && post_residual % item_size == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // --- Capacity-fraction classes: reward leaving well-known reusable gaps ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    for &frac in &[0.25f64, 0.5, 0.75] {
        let target = frac * cap;
        if (post - target).abs() < 5.0 {
            score -= 30.0;
        }
    }

    // --- Integer-division thresholds: post_residual bucket ---
    let bucket = post_residual / 20; // 0..5 harmonic bucket
    score -= bucket as f64 * 8.0; // larger usable residual is generally better

    // --- Lookahead: if next item fits into post_residual, this bin stays useful ---
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 35.0;
        // extra harmony: next item exactly fills remaining space
        if next_item_size == post_residual {
            score -= 60.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this bin; slight penalty unless residual tiny
        if post_residual >= 10 {
            score += 10.0;
        }
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish base (post_residual == capacity),
        // penalize mildly so it's chosen only when open bins fit poorly,
        // but reward when few bins are open (early stream) or item is large.
        score += 40.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 30.0; // late in stream, prefer consolidating into open bins less
        if item_size >= 50 {
            score -= 20.0; // large items pair well in fresh bins
        }
    }

    // --- Congestion: many open bins with high mean residual -> prefer filling existing bins ---
    if bin_residual != bin_capacity {
        score -= (mean_residual - post as f64).abs() * 0.1;
        if open_bins_count > 5 && post_residual < 30 {
            score += 15.0; // avoid scattering small residuals across many bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fill is highly desirable.
        score -= 40.0;
    } else {
        // Usable residual: mildly reward larger usable leftover capacity
        // only if it can host the lookahead item; otherwise slight penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 {
            score += 6.0;
        }
    }

    // Tightness bonus: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.6 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: placing into a bin whose residual is far below
    // the mean (i.e., nearly full bin) is good consolidation.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit (post_residual would be small everywhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins already fit.
        score += 20.0 + 5.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin leaves room for the next (large) item:
            // slightly cheaper to open.
            score -= 12.0;
        }
        // Later in the stream, opening new bins is more wasteful.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
