    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Base: prefer bins left with small (but usable) residual after placement.
    let mut score = post;

    // Reward tight fits: the more of the bin's current space the item consumes,
    // the better (reduces fragmentation). Scale by relative fill of the bin.
    let fill_ratio = (bin_capacity - post_residual) as f64 / cap;
    score -= 2.0 * item * (0.5 + 0.5 * fill_ratio);

    // Penalize dead space: residuals too small for the smallest plausible
    // future item are wasted. Threshold adapts to stream horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = 10.0 * (1.0 - 0.5 * progress);
    if post > 0.0 && post < dead_threshold {
        score += 12.0 * (dead_threshold - post) / dead_threshold;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward
    // this placement strongly (creates a perfect pair).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == post {
            score -= 25.0;
        } else if nxt <= post {
            score -= 6.0 * (nxt / post.max(1.0));
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 3.0 * (1.0 - nxt / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is generally costly,
    // but attractive when the current item is large and fits are scarce,
    // or when open bins are all tightly packed (low mean residual).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let tightness = 1.0 - (mean_residual / cap).min(1.0);
        let big_item = item / cap;
        // Cost of a new bin, discounted by scarcity of fits and bin tightness.
        score += 55.0 - 45.0 * scarcity * (0.4 + 0.6 * tightness) - 20.0 * big_item * progress;
        // Late in the stream, avoid spawning bins for small leftovers.
        if item < 25.0 && progress > 0.7 {
            score += 30.0;
        }
    }

    // Mild global-pressure term: many open bins with high mean residual
    // suggests we should consolidate into existing bins.
    if bin_residual < bin_capacity {
        score += 0.05 * open_bins_count as f64 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    score += 20.0 * poly;
    // Reward tight fits more strongly later in the stream
    let tight = (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 15.0 * tight * (0.3 + 0.7 * progress);
    // Penalize dead space relative to mean residual
    let dead = norm_pr - (mean_residual / cap);
    if dead > 0.0 {
        score += 10.0 * dead * dead * (1.0 + progress);
    }
    // Lookahead coupling: penalize leaving residual that cannot fit next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) / cap * (1.0 - progress);
        } else {
            score -= 5.0 * (pr - ns) / cap * (1.0 - progress);
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }
    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).sqrt() * 0.5 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: prefer leftovers that belong to
    // "reusable" residue classes (multiples of common item sizes).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, zero waste
    } else {
        // Modulo-10 harmonic classes: leftovers divisible by 10 are far more
        // likely to be filled by later items.
        if pr % 10 == 0 {
            score -= 12.0;
            if pr % 20 == 0 { score -= 6.0; }
            if pr % 50 == 0 { score -= 4.0; }
        }
        // Integer-division thresholds on the fill fraction.
        let fill_ratio = item_size as f64 / cap;
        if fill_ratio > 0.8 { score -= 20.0; }
        else if fill_ratio > 0.6 { score -= 10.0; }
        else if fill_ratio > 0.5 { score -= 5.0; }
        else { score += 6.0; } // small item into big bin: wasteful pairing

        // Penalize dead space in the awkward (10..20) band — hard to reuse.
        if pr < 10 { score += 15.0; }
        else if pr < 20 { score += 8.0; }
    }

    // Lookahead: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0;
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            if slack <= 10.0 { score -= 10.0; }
            else { score += slack * 0.15; }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large (creates a fresh useful residual) or late in the
    // stream where future reuse is unlikely.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / cap > 0.7;
        if large_item || progress > 0.85 {
            score -= 8.0;
        } else {
            score += 25.0; // keep compacting into existing bins early on
        }
    }

    // Mild pressure to prefer bins below mean residual (tighter bins first),
    // spreading wear across bins via open_bins_count coupling.
    score += (mean_residual - bin_residual as f64) * 0.05;
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for the
    // smallest possible item (1) are pure loss; gaps in a "dead zone"
    // (small but nonzero) are heavily penalized since nothing useful fits.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Reward tight fits strongly (wasted-space efficiency).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual that can't host the next item is likely dead space.
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins;
    // with few open bins, opening a new one is cheaper.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: if the fleet is already fragmented (high mean
    // residual spread), penalize adding to fragmentation.
    if (mean_residual - post_residual as f64).abs() < 5.0 && post_residual > 0 {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when it beats a poor fit.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
