pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100, min item 1)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are nearly useless
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty for leaving medium gaps
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, encourage consolidating into few bins;
    // later, be more tolerant of opening bins to avoid fragmentation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if many bins are open with high mean residual,
    // prefer filling existing bins rather than opening new ones
    if open_bins_count > 2 {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it's only
    // chosen when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
        // but if no open bin can fit the item, new bin is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild penalty when this placement leaves a residual that matches no
    // common item size band (fragmentation avoidance)
    let r = post_residual;
    if r > 0 && r < 100 {
        let band_mismatch = (r as f64 - (r as f64 / 10.0).round() * 10.0).abs() / 10.0;
        score += 1.5 * band_mismatch;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly prefer bins that end with small post_residual,
    // amplified smoothly as the stream progresses.
    let tightness = 1.0 - post / cap;
    score -= 10.0 * tightness * tightness * (1.0 + progress);

    // Dead-space penalty: if the lookahead item cannot use the leftover space,
    // penalize leftover space more heavily early in the stream (when bins are precious).
    if next_item_size > post_residual {
        score += 0.4 * post * (1.2 - progress);
    } else if next_item_size > 0 {
        // Lookahead synergy: reward leaving exactly usable space for the next item.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 6.0 * (1.0 - gap / cap) * (1.0 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only bin that fits, favor using it
    // (avoid opening a new bin unnecessarily), more so late in the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 8.0 * progress;
    }

    // New-bin candidate: mild bias against opening bins, but relax it when the
    // empty bin would offer a good landing zone for the next item.
    if bin_residual == bin_capacity {
        score += 4.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post - next_item_size as f64) / cap);
        }
    }

    // Mean-residual coupling: when open bins are on average very full,
    // slightly discourage spreading into half-empty bins (keeps bins compact).
    score += 0.05 * mean_residual * (1.0 - tightness);

    // Smooth non-linear stream-progress coupling on residual scale.
    score *= 1.0 + 0.15 * (progress * std::f64::consts::PI).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residues in "useful" bands
    let cls = post_residual / 10;
    score += match cls {
        0 => -30.0,  // nearly full bin: excellent
        1 => -18.0,  // small residue, likely reusable by small items
        2 => -6.0,
        3 => 4.0,
        4 => 10.0,
        5 => 14.0,
        6 => 18.0,
        _ => 22.0,   // large waste
    };

    // Lookahead coupling: does the next item fit into the resulting residue?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residue is compatible with the next item: reward proportionally
            score -= 6.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // dead space for the upcoming item: penalize the mismatch
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 28.0; // default: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 80.0; // no open bin fits: must open a new bin
        } else if fitting_bins_count == 1 {
            score -= 10.0; // weak alternative elsewhere
        }
        // large items justify fresh bins more often
        if item_size >= 60 {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(2) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.12;

    // Slight preference for bins below mean residual (balance / fill emptier bins)
    score += (mean_residual - post_residual as f64) * 0.05;

    // Modulo-flavored tiebreak: residues that are multiples of 10 align with
    // typical item granularity, making them more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A post_residual in (0, 10] can almost never host a future item (min size 10),
    // so it is pure waste; larger residuals retain utility.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    } else if post_residual == 0 {
        // Perfect fill is the ideal outcome: strong reward.
        score -= 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal gap: only fits the smallest items, mild penalty.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; favor tighter bins.
    score += open_bins_count as f64 * 0.8;

    // Coupling with mean residual: if this bin's residual is far below the mean,
    // it is one of the "tightest" bins; reward closing it down.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.5;
    } else {
        score += (-diff) * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive early (with few open
    // bins) but should be avoided when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 40.0 + open_bins_count as f64 * 2.5 + progress * 20.0;
        // If any existing bin fits, make the new bin slightly worse than a decent fit.
        score += base + if fitting_bins_count > 0 { 15.0 } else { 0.0 };
        // Early in the stream with few bins, opening fresh bins is cheap.
        if open_bins_count <= 2 && progress < 0.2 {
            score -= 25.0;
        }
    }

    // Small nudge toward tightest fits overall.
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: strongly reward bins whose post_residual exactly
    // matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect 2-step match
        } else if post_residual as u32 >= next_item_size {
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item can't chain here; penalize proportional to dead space
            score += 0.35 * gap;
        }
    }

    // Penalize leaving residuals that are likely unusable (small scraps).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (1.0 - pr / 10.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (tighter bins), keeping loose bins available for future large items.
    score -= 0.5 * (mean_residual - pr);

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is huge relative to typical residuals or the fit here
    // is very poor. Make empty-bin baseline moderately high.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55
            + 0.3 * pr
            - if next_item_size as u32 >= item_size { 8.0 } else { 0.0 };
        // discourage new bins when a decent fit exists elsewhere
        if post_residual as f64 <= mean_residual {
            score += 30.0;
        }
    }

    // Slight late-stream tightening: consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals too small for any item (min size 1..100 unknown, use small threshold)
    let dead_threshold = 10.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 4.0;
    }

    // Reward tight fits (small post residual relative to item)
    let item_f = item_size as f64;
    score -= item_f * 0.15;

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 45.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 12.0;
            // penalize leaving residual that only barely fits next item awkwardly
            let leftover = post - nx;
            if leftover > 0.0 && leftover < dead_threshold {
                score += leftover * 2.0;
            }
        }
        // If next item is large and this bin can't hold it after placement, slight penalty
        if nx > post {
            score += 3.0;
        }
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // If current bin would leave dead space, opening new bin is attractive
        if post > 0.0 && post < dead_threshold {
            score -= 55.0;
        }
        // If no other bin fits, opening is necessary (fitting_bins_count==1 means only this candidate)
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins with high mean residual: better to use them
        score += (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.3;
    }

    // Prefer bins with residual close to item (good fill) when many bins compete
    if open_bins_count > 3 {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= tightness * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual, amplified by stream progress
    let pr = post_residual as f64;
    score -= 1.5 * (1.0 - pr / bin_capacity as f64).powi(2) * (0.5 + progress);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins late in the stream when open bins fit
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Lookahead coupling: reward leaving space that fits the next item
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 18.0;
        } else if gap > 0 {
            // smaller leftover gap after next item is better
            score -= 6.0 * (1.0 - (gap as f64 / bin_capacity as f64));
        } else {
            // next item cannot fit here: mild penalty for dead space
            score += 2.0 * (-gap as f64 / bin_capacity as f64);
        }
    }

    // Penalize bins far from mean residual (prefer balanced packing)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    // Smooth non-linear interaction: post_residual x progress polynomial
    let x = pr / bin_capacity as f64;
    score += 3.0 * x * x * (1.0 - x) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fill
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space (unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic class of post_residual: bins leaving residuals that many future
    // items can fill are good. Reward residuals in "common size" classes.
    let pr = post_residual;
    if pr >= 10 {
        // residual divisible into common item chunks is attractive
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 10.0; }
        else if pr % 5 == 0 { score -= 4.0; }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 500.0;
    }
    // Next item fits comfortably but leaves another usable residual
    if next_item_size > 0 && next_item_size <= pr {
        let second_residual = pr - next_item_size;
        if second_residual % 10 == 0 { score -= 25.0; }
        if second_residual < 10 && second_residual > 0 { score += 15.0; }
    }
    // Next item will NOT fit here: mild penalty for wasting this bin's slot
    if next_item_size > 0 && next_item_size > pr && pr > 0 {
        score += 10.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if mean residual of open bins is small (all bins tight), new bin is fine
        score -= (mean_residual / bin_capacity as f64) * 40.0;
        // If current item is large relative to capacity, opening a fresh bin is natural
        if item_size >= bin_capacity / 2 { score -= 30.0; }
    }

    // Prefer fuller bins early in stream (best-fit bias scaled by tightness)
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Slight preference to consolidate into fewer bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // (very likely to become unusable) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // near-certain dead space
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the next item
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: base score equals capacity; make it attractive only when
    // no open bin offers a decent fit (i.e., all fits are loose) or few bins open.
    if bin_residual == bin_capacity {
        // Neutral base; slight penalty so we prefer reusing bins with tight fits.
        score = bin_capacity as f64 - 5.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits anywhere: definitely open new bin
        } else if post_residual as f64 > mean_residual {
            score += 0.0; // keep default
        }
        // Penalize opening new bins when many bins already exist (fragmentation).
        score += open_bins_count as f64 * 0.5;
    }

    // Mild pressure against accumulating too many open bins for regular bins.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.1;
    }

    // Slight preference for filling bins that are already mostly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still accommodate the next item (loose coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot fit in the remainder.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Penalize creating tiny unusable residuals (below minimum item size 1..100 => < 10 typical).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(10) {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (keeps larger residuals available for larger future items).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early in stream: slightly favor consolidating into existing bins;
    // late in stream: minimize final waste aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when it enables a perfect 2-step chain
    // or when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 55.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 20.0;
        } else {
            score += 10.0; // default: prefer filling existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0.0 -> 1.0)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: the smaller the post residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item could fill this bin's post residual,
    // reward it strongly (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize proportionally
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Global pressure: many open bins with high mean residual -> discourage
    // fragmenting; prefer bins below the mean residual (denser bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early on, keep options open (mild penalty for very full bins),
    // late in the stream, pack aggressively (extra reward for tight fits).
    score += 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64 - 0.5);
    score -= 20.0 * progress * tightness;

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented (large mean residual) and this item is big.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // attractive if open bins are mostly full (high mean residual means
        // little room left overall)
        score -= 0.5 * mean_residual;
        // attractive for large items late in the stream
        score -= 0.2 * item_size as f64 * progress;
        // unattractive if plenty of bins can still fit the item
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post residual with stream progress
    let mut score = x * (1.0 + 0.8 * t * t) + 0.35 * x * x * (1.0 - t);

    // Reward tight fits (low post residual) more strongly late in the stream
    score -= 0.5 * (1.0 - x).powi(3) * (0.5 + t);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 1.2 * gap * gap * (0.6 + 0.8 * t);
        // Reward bins that can also fit the next item
        if pr >= next_item_size as f64 {
            score -= 0.4 * (1.0 - t) * (pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 + t);
    }

    // Mild penalty when many bins are open and residual is far from mean
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev.abs() * (open_bins_count as f64).sqrt() * (1.0 - t);

    // New-bin candidate: prefer it only when item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 0.9 - 0.6 * fill * fill - 0.5 * t * (1.0 - fill);
        if fitting_bins_count <= 1 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by 8 or 16 are more reusable
    let pr = post_residual as u32;
    if pr % 16 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 8 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 4 == 0 {
        score -= 2.0;
    }

    // Penalize tiny dead space that no typical item can use
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Capacity-fraction classes: residuals in [50,100) can host half-size items
    let frac = post_residual as f64 / cap;
    if frac >= 0.5 {
        score -= 8.0;
    } else if frac >= 0.25 {
        score -= 3.0;
    } else if frac > 0.0 {
        score += 5.0;
    }

    // Lookahead: does next item fit in post_residual? (modular threshold coupling)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // bonus if next item is harmonic-friendly size
            if next_item_size % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // dead bin: residual below next item
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fit win
        score += 40.0;
        // but if no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for filling bins with large residuals relative to mean
    if mean_residual > 0.0 {
        score -= (post_residual as f64 - mean_residual) * 0.05;
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead) / 10.0;
    }

    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving gaps that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last chance bin pressure: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when waste is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    score += 0.05 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to the item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        if diff == 0.0 {
            score -= 120.0;
        } else if nr <= pr {
            score -= 60.0 - diff.min(60.0);
        } else {
            // Next item cannot use this leftover: penalize dead space.
            score += (nr - pr).min(50.0) as f64 * 0.8;
        }
    } else {
        // Last item: tightest fit wins.
        score -= 100.0;
    }

    // Penalize leaving tiny unusable slivers (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer tighter fits relative to other bins: small residual vs mean residual.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += (post_residual as f64 - mean_residual).min(40.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // current item is small enough that a fresh bin offers good future packing.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let small_item_bonus = if item_size <= 30 { 20.0 } else { 0.0 };
        score += 30.0 * pressure + (1.0 - progress) * 20.0 + small_item_bonus
            - if fitting_bins_count == 0 { 150.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual dominates small waste.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead-space penalty: residual too small for any realistic item.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; slight penalty for fragmenting space.
            score += 3.0;
        }
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or this bin's fit is poor.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 60.0;
        // Attractive if mean residual across open bins is small (bins nearly full).
        score -= (mean_residual / bin_capacity as f64) * 30.0;
        // Attractive if many bins can't fit the item anyway.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Early stream: cheaper to open bins (more future items to use them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
        // Large items deserve fresh space.
        score -= (item_size as f64 / 100.0) * 20.0;
    } else {
        // Existing bin: mild reward when open_bins_count is high (consolidate).
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Slight preference for fuller bins relative to mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fits)
    let mut score = pr as f64;

    // Non-linear polynomial coupling: tightness reward amplified by stream progress
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * progress * tightness * tightness * cap * 0.1;

    // Penalize dead space that is too small to be useful (non-linear valley)
    let dead = norm_pr;
    let dead_penalty = 4.0 * dead * (1.0 - dead) * (dead - 0.15).abs();
    score += dead_penalty * cap * 0.5;

    // Lookahead coupling: reward if next item fits smoothly into post-residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_q = (pr - ns) / cap;
            score -= 6.0 * (1.0 - fit_q * 4.0).max(0.0);
        } else {
            // next item won't fit here: mild penalty scaled by gap
            score += 2.0 * ((ns - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Mean residual coupling: prefer bins below mean residual (fill fuller bins first)
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev;

    // Slight penalty for proliferating open bins early in stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        // Empty bin: neutral post_residual = cap, so add penalty unless item is small relative to cap
        let fill = item_size as f64 / cap;
        score += 15.0 * (1.0 - fill) * (1.0 - fill) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division.
    let item_class = item_size / 10;
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 10 };

    // Base: prefer minimal post_residual (tight fit), but with diminishing
    // returns so that perfect fits stand out super-linearly.
    score = (post_residual as f64).powf(1.25) / 10.0;

    // Perfect fit reward: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: post_residual too small for the smallest item (1)
    // is fine, but residuals in awkward narrow bands are "dead" because few
    // item classes can use them. Penalize residuals that fall in unusable
    // modulo classes: residual % 10 in 1..=3 with residual < 15.
    if post_residual > 0 && post_residual < 15 && post_residual % 10 != 0 {
        score += 25.0;
    }

    // Harmonic pairing: if the next item can exactly fill this bin's
    // post_residual, strongly reward (complementary classes sum to capacity).
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 400.0;
    }
    // Partial pairing: next item fits exactly into a harmonic subdivision
    // (half or quarter of post_residual).
    if next_item_size > 0 && post_residual >= 2 {
        if next_item_size * 2 == post_residual {
            score -= 120.0;
        }
        if next_item_size * 4 == post_residual {
            score -= 60.0;
        }
    }

    // If next item cannot fit into post_residual, this placement still
    // consumes the bin's last usable space -> mild reward for closing it out.
    if next_item_size > post_residual && post_residual < 20 {
        score -= 30.0;
    }

    // Class-mismatch penalty: placing a large item (high class) into a bin
    // leaving a residual that only small classes can use is wasteful when
    // other bins exist.
    if fitting_bins_count > 1 {
        let small_gap = post_residual < 10 && post_residual > 0;
        if small_gap && item_class >= 5 {
            score -= 15.0; // fine to strand small residual with big item
        }
        if post_residual >= 30 && next_item_size > 0 && next_item_size > post_residual {
            score += 20.0; // leaving a large unusable-for-next gap while other bins exist
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; penalize unless nothing reasonable
        // fits (no other fitting bins) or the fit would be terrible.
        let poor_fit = fitting_bins_count == 0 || post_residual as f64 > 0.6 * bin_capacity as f64;
        if poor_fit {
            score -= 150.0;
        } else {
            score += 120.0 + 8.0 * open_bins_count as f64;
        }
        // Early in the stream, opening bins is cheaper (future items unknown).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.2 {
            score -= 40.0 * (0.2 - progress);
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling below-mean-residual bins balances the pool.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild preference for reusing bins when many are open (contain sprawl).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is worthless
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins with below-average residual (tighter bins) when many bins are open.
    if open_bins_count > 1 {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 35.0;
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // dead space relative to known next item
        }
    }

    // New-bin candidate handling: neutral baseline, opened only when fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0 + 2.0 * open_bins_count as f64;
        // Early in stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can host next item well
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: tightly couple item to residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0; // exact 2-step chain: perfect fit next round
        } else {
            let gap = (pr - nr).abs();
            if gap <= 10.0 {
                score -= 150.0 * (1.0 - gap / 10.0); // near-chain fit
            }
            // Penalize dead space next item cannot use
            if post_residual < next_item_size {
                score += 0.5 * (nr - pr);
            }
        }
        // Bonus when this placement enables a perfect chain and bin is scarce
        if post_residual == next_item_size && fitting_bins_count <= 2 {
            score -= 200.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin when next item is large and residual chain is unlikely
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Prefer filling bins below mean residual (consolidate waste).
    let mr = mean_residual;
    if (bin_residual as f64) > mr + 1.0 {
        score -= 20.0;
    } else {
        score += 15.0;
    }

    // Early in stream: keep flexibility; late: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 30.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 40.0;

    // Large items: prefer tighter bins.
    if item_size >= 60 {
        score += 0.3 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Tightness reward: filling a bin with a large chunk of the item is good.
    score -= (item_size as f64 / cap) * 5.0;

    // Lookahead chaining: if the next item exactly/nearly fits the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let gap = post_residual as f64 - nx;
            score -= 8.0 + nx * 0.06 - gap * 0.15;
        } else {
            // Dead space the next item cannot use: mild penalty.
            score += 2.5;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Global pressure: many open bins with large mean residual -> consolidate,
    // avoid opening new bins.
    let pressure = mean_residual / cap;
    score += pressure * 3.0 * (open_bins_count as f64).sqrt();

    // Time horizon: late in the stream, tighten packing (penalize loose fits more).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += t * 3.0 * (post_residual as f64 / cap);

    // New-bin candidate: strong default penalty so existing bins win when viable;
    // penalty shrinks for very large items where a fresh bin is natural.
    if is_new_bin {
        score += 30.0 * (1.0 - item_size as f64 / cap) + 6.0;
        // If next item is huge and won't fit anywhere anyway, opening fresh is fine.
        if next_item_size > post_residual && next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: tight fit preferred (low post residual)
    let mut score = pr;

    // Non-linear coupling: post residual shaped by stream progress.
    // Late in stream, penalize large residuals more aggressively (quartic-ish).
    let shape = pr_norm * pr_norm * (1.0 + 2.5 * progress * progress);
    score += 60.0 * shape;

    // Reward filling bin deeply relative to item size (smooth interaction).
    score -= 25.0 * fit_ratio * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bonus: only one bin fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 12.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit -> mild penalty proportional to wasted opportunity.
        score += 8.0 * pr_norm;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // New-bin candidate: penalize opening a new bin, unless current residual is large
    // dead space and progress is late (then the penalty softens non-linearly).
    if bin_residual == bin_capacity {
        let dead = mean_residual / cap;
        score += 55.0 - 45.0 * dead * dead * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: small post_residual is good, but dead space that is
    // too small to hold the next item is wasted. Harmonic class of
    // post_residual modulo 10 gives fine-grained tie-breaking.
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let cap = bin_capacity as f64;

    // Reward if post_residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Dead space too small for next item: penalize by how much it leaks.
        score += 2.0 + 0.05 * (next_item_size - post_residual) as f64;
    }

    // Harmonic classes: post_residual in [1..=10] is nearly unusable dead space.
    let class = post_residual / 10;
    match class {
        0 => score += 6.0,          // 0..=9 residual: almost dead
        1 => score += 2.0,          // 10..=19: only tiny items fit
        2 => score += 0.5,          // 20..=29: moderate
        _ => score -= 0.5,          // >=30: flexible residual
    }

    // Modulo-10 resonance between post_residual and next item:
    // if (post_residual - next_item_size) % 10 == 0, the leftover aligns
    // with the coarse granularity of the stream -> bonus.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current fit is poor. Give the empty bin a baseline near the top.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.25 * mean_residual;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Fresh bin cleanly hosts current + next item pair.
            score -= 6.0;
        }
        if fitting_bins_count == 1 {
            // Never open a new bin when this is the only fitting bin.
            score += 25.0;
        }
    }

    // Slight preference to fill bins tightly late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.5 * (post_residual % 10) as f64 * 0.1;

    // Nudge toward bins below mean residual (consolidating emptier bins).
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, the min item size)
    // are pure waste; penalize them heavily.
    if post_residual < 10u32 && post_residual > 0 {
        score += 60.0 - (post_residual as f64) * 3.0; // small gap => big penalty
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize post_residual relative to how well the next item could use it.
        if next_item_size > 0 {
            let gap = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                (next_item_size - post_residual) as f64 * 1.5
            };
            score += gap * 0.4;
        }
    }

    // Perfect fill of a nearly-full bin: strong reward.
    if post_residual == 0 && bin_residual <= bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 4.0;
        // But if only one fitting bin exists and the fit is bad, opening a new
        // bin may be better: soften the penalty.
        if fitting_bins_count <= 1 && (bin_residual - item_size) > 40 {
            score -= 35.0;
        }
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Last-chance bin: strongly favor filling the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly favoring below-mean residuals to keep big gaps for big items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early in the stream, be a bit more willing to open bins (exploration);
    // later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score += progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 900.0;
        } else {
            score -= 200.0 / (gap as f64 + 1.0);
        }
    }

    // Penalize small unusable dead space (waste) when next item can't use it
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let tightness = post_residual as f64 / next_item_size as f64;
        score += 60.0 * (1.0 - tightness);
    }

    // Reward bins tighter than mean residual (good fits)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // New bin candidate: only prefer when current bin would leave big waste
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bin mildly, unless it enables a good 2-step chain
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 250.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Slight penalty for very fragmented open-bin pools
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize dead space quadratically, but more when few bins are open (space is scarce).
    let waste = post_residual as f64;
    let scarcity = 1.0 + 20.0 / (open_bins_count as f64 + 1.0);
    score += 0.012 * waste * waste * (scarcity / 8.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item,
    // penalize bins that leave a residual too small for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0 * (nxt / 100.0);
        } else {
            score += 4.0;
        }
        // Perfect pairing: item + next item exactly filling residual is excellent.
        if (item_size as f64 + nxt - bin_residual as f64).abs() < 0.5 {
            score -= 12.0;
        }
    } else {
        // Last item: maximize fill, any residual is dead weight forever.
        score += 0.5 * waste;
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer consolidating into existing space rather than opening bins.
    score -= 0.15 * mean_residual;

    // New-bin candidate handling: an empty bin is only attractive when no open bin
    // gives a decent fit (large post_residual relative to capacity) or when many
    // bins are open and this item is huge relative to residual.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && (post_residual as f64) > 0.0;
        let poor_fit = decent_fit_exists && (post_residual as f64) > 0.45 * bin_capacity as f64;
        if poor_fit {
            // Opening a fresh bin for a small item into a roomy bin is wasteful.
            score += 30.0;
        } else if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            // Neutral-ish: slightly favor keeping tight fits in existing bins.
            score += 6.0;
        }
        // Late in the stream, opening new bins is less recoverable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for fuller bins (lower residual) to keep small residuals from
    // proliferating across many bins.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear dead-space penalty: small post_residual is good (tight fit).
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / cap); // 1.0 = perfect fit, 0.0 = empty
    score -= 12.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Penalize very small unusable leftovers (dead space) smoothly.
    let dead = (8.0 - pr.min(8.0) as f64) / 8.0;
    score += 15.0 * dead * dead;

    // Reward closing out bins that are nearly full.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (pack tight bins first).
    score += 0.15 * ((mean_residual - bin_residual as f64) / cap);

    // Lookahead: penalize leaving a residual that barely misses the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        if gap < 10.0 {
            score += 6.0 * (1.0 - gap / 10.0);
        }
        // Reward leaving exactly room for the next item.
        if gap == 0.0 {
            score -= 8.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let waste = (cap - item_size as f64) / cap;
        score += 25.0 - 20.0 * poor_fit - 10.0 * waste * (1.0 - progress);
        // Late in the stream, prefer consolidating into open bins.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions / 10
    let cls = post_residual / 10; // 0..=10 harmonic class
    let rem = post_residual % 10;

    // Reward placements landing on "harmonic" boundaries (multiples of 10)
    // and extra reward for exact fit (post_residual == 0).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // small remainder => near-harmonic residual, mildly usable
        score -= (10 - rem) as f64 * 0.6;
        // penalize dead space classes that are hard to fill later
        if cls <= 1 && post_residual > 0 {
            score += 12.0; // residual 1..19 is near-dead space
        } else if cls >= 6 {
            score -= 4.0; // large residual still flexible
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        // reward exact or near-exact lookahead fits
        if slack == 0 {
            score -= 45.0;
        } else {
            score -= slack as f64 * 0.3;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize wasting this bin's potential
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is large
    // relative to capacity (poor fit likely elsewhere) or no open bins.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        if open_bins_count == 0 {
            score -= 100.0;
        } else if big > 0.7 {
            score -= 30.0 * (big - 0.7) / 0.3;
        } else {
            score += 20.0 + 30.0 * (0.7 - big);
        }
        // if nothing open fits (fitting_bins_count refers to open bins only)
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Stream progression: late in stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.1;

    // Mild preference to spread load when many bins open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is king
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // awkward mid gap
    }

    // Reward leaving a gap that the lookahead item can consume.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap that just barely blocks the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);

    // Pull toward the mean residual: avoid fragmenting unusually empty bins.
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // New-bin candidate: only attractive when item is large relative to capacity
    // or all existing fits are poor. Base cost for opening a fresh bin.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= bin_capacity / 2 { 10.0 } else { 0.0 };
        score = (bin_capacity - item_size) as f64 + 20.0 - large_item_bonus;
        if fitting_bins_count <= 2 {
            score -= 15.0; // few alternatives -> new bin is reasonable
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact/near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 30.0 / post_residual as f64;
    }

    // 2-step lookahead: does next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally
            let over = (next_item_size - post_residual) as f64;
            score += 0.6 * over;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize unless item is large or existing fits are bad
    if bin_residual == bin_capacity {
        let base = 150.0
            + 0.8 * open_bins_count as f64
            + 2.0 * (item_size as f64);
        let pressure = if fitting_bins_count == 0 { 400.0 } else { 0.0 };
        let next_pressure = if next_item_size > 0 && next_item_size >= bin_capacity - item_size { 60.0 } else { 0.0 };
        score += base + pressure + next_pressure;
        if post_residual == 0 {
            score -= 1000.0;
        }
    }

    // Slight preference to keep filling older bins as stream progresses
    score += 0.02 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post-residual is already rewarded).

    // Strong reward for perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space that the next item cannot use.
        score += 0.4 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fits are bad (large post-residual relative to capacity).
    if bin_residual == bin_capacity {
        // Mild default penalty so existing good fits win.
        score += 25.0;
        // But if the current item leaves huge dead space in any existing bin,
        // a fresh bin becomes competitive.
        if post_residual as f64 > 0.55 * bin_capacity as f64 {
            score -= 30.0;
        }
        // Early in the stream, keeping bins tight matters less; allow more opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with small mean residual -> pack tighter,
    // penalize bins that deviate from tight packing.
    if open_bins_count > 0 && mean_residual > 0.0 {
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    }

    // Late-stream consolidation: as the stream nears its end, strongly prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    } else {
        score -= 15.0 * progress;
    }

    // Slight preference for bins with larger pre-fit residual when all else
    // is equal (keeps small bins available for small future items).
    score -= 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual scaled by a progress-dependent
    // polynomial factor. Late in the stream, tight fits (small post_residual)
    // become even more valuable, so we amplify the residual penalty.
    let progress_factor = 1.0 + 0.8 * progress * progress + 0.4 * progress * progress * progress;
    score *= progress_factor;

    // Reward near-perfect fits: subtract a smooth superlinear bonus when
    // post_residual is small relative to capacity.
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let fit_bonus = (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);
    score -= 12.0 * fit_bonus;

    // Penalize dead space: quadratic penalty grows as post_residual approaches
    // sizes unusable by typical items (smooth, no piecewise constants).
    let dead = norm_post * norm_post;
    score += 20.0 * dead;

    // Last-chance bonus: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Discard spreading across many bins when mean residual is high; encourage
    // consolidation by penalizing bins whose residual deviates favorably from mean.
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_diff * residual_diff / (bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving space that the next item cannot use.
        score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Mild penalty for opening a new bin when open bins exist and can fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize residuals in "dead zones"
    // (small unusable remainders that no typical item can fill).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = post_residual % 10; // harmonic subclass
    let dead_zone = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead_zone * 12.0; // tiny unusable slivers are wasted space
    score += (post_class as f64) * 0.15; // mild preference for round residuals

    // Integer-division thresholds: how many "typical small items" (size 10)
    // still fit after placement -> reward bins that remain reusable.
    let slots = post_residual / 10;
    score -= (slots.min(4)) as f64 * 3.0;

    // Lookahead coupling: reward when next item fits the post residual exactly well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (next_item_size as f64) / (post_residual as f64);
        score -= 6.0 * tightness; // good chaining bonus
        // Harmonic match: next item divides post residual nicely
        if post_residual % next_item_size == 0 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual -> penalize proportionally
        score += 2.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Last-chance logic: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (open_bins_count as f64) / 10.0;
        let poor_fit_elsewhere = mean_residual < (item_size as f64) * 1.2;
        if poor_fit_elsewhere {
            score -= 10.0 + 5.0 * progress; // open fresh bins when residuals are tight
        } else {
            score += 20.0 + crowding; // discourage opening bins when fits exist
        }
        // exact-fill bonus for new bin with large items
        if item_size == bin_capacity {
            score -= 100.0;
        }
    } else {
        // Reward tight fits in existing bins (Best-Fit core).
        score -= (item_size as f64) * 0.25;
        if post_residual == 0 {
            score -= 8.0; // perfect fill
        }
        // Harmonic exactness: item divides residual exactly
        if bin_residual % item_size == 0 {
            score -= 3.0;
        }
    }

    // Mild mean-residual balancing: prefer bins near the mean to keep
    // residuals homogeneous and packable.
    score += ((post - mean_residual) / cap).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize small "dead space" gaps that are hard to fill later.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_residual as f64) / 15.0);
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item cannot fit into the post residual gap (fragmentation risk).
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size.min(10) {
        score += 10.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Pressure from many open bins: prefer filling existing bins over spreading.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins with below-mean residual (they are "closer to full").
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    // New empty bin candidate: penalize opening a new bin unless residuals
    // of open bins are very tight (little room anywhere).
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * (mean_residual / (bin_capacity as f64));
    }

    // Late in the stream, closing bins out matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more strongly when many bins fit the item.
        let mut s = 45.0 + 8.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            s += 25.0 * (fitting_bins_count as f64 - 1.0).max(0.0);
        }
        // Perfect lookahead fit into a fresh bin is still acceptable late in the stream.
        if next_item_size > 0 && next_item_size + item_size == bin_capacity {
            s -= 30.0;
        }
        return s;
    }

    // 2-step lookahead: reward post_residual that exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 40.0 / (1.0 + diff);
        // Reward ability to fit the next item too.
        if post_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize leaving dead space smaller than the minimum item size (1..100 unknown,
        // so use relative dead-space threshold).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.6 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 30.0;
    }

    // Relative-to-mean-residual term: prefer bins below mean residual (tighter bins),
    // keeping looser bins available for larger future items.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Slight preference for high fill ratio.
    score -= 0.1 * (bin_capacity - post_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-exact fills (small post_residual already low, add extra pull)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward dead space that only very small items could use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space the next item can't use: penalize
        score += 3.0 + 0.05 * (next_item_size as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; make it unattractive by default
        score += 45.0;
        // But if few bins fit the item, or the item is large and would leave bad
        // fragmentation in existing bins, allow opening a new bin
        let fragmentation_risk = if post_residual < 20 { 1.0 } else { 0.0 };
        let relief = 30.0 * fragmentation_risk
            + (fitting_bins_count as f64).recip() * 10.0
            + (item_size as f64 / bin_capacity as f64) * 20.0;
        score -= relief;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins (penalize spreading)
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Late in the stream, closing bins tightly matters more
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, non-linearly (quadratic coupling).
    let mut score = post * (1.0 + 0.012 * post / cap);

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, dead space matters more.
    let tightness = 1.0 - post / cap; // 0..1, higher = tighter fit
    score -= 6.0 * tightness * tightness * (0.5 + 2.0 * progress);

    // Reward near-exact fits with smooth saturating term.
    score -= 4.0 * (post / cap) * (1.0 - post / cap) * (1.0 - post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidate unless it produces a very tight fit,
    // or current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let mean_tight = 1.0 - mean_residual / cap;
        let newbin_tight = 1.0 - post / cap;
        // smooth tradeoff: open new bin only if fit is tight or stream is late
        let penalty = 20.0 * (1.0 - newbin_tight * newbin_tight) * (1.0 - 0.5 * progress) - 10.0 * mean_tight;
        score += penalty.max(-8.0);
    }

    // Lookahead: if next item fits the post-residual well, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let gap = post - next_item_size as f64;
        score -= 5.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty for leaving awkward gap
        score += 2.0 * (post / cap);
    }

    // Mild preference for bins with larger residuals among many open bins.
    score -= 0.02 * (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: modulo arithmetic on 20-wide classes.
    let class = post_residual % 20;
    let class_bonus = match class {
        0 => -25.0,            // perfectly closed or exact class boundary
        1..=9 => 8.0,          // awkward sliver residual
        10 => -12.0,           // half-capacity class, very reusable
        _ => 3.0,              // mid-class, mildly reusable
    };
    score += class_bonus;

    // Integer-division thresholds: residuals divisible by common item sizes are valuable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
    } else {
        score -= 30.0; // exact fill: best possible outcome
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Penalize leaving dead space relative to mean residual (fragmentation pressure).
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only attractive for large items or when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = item_size as f64 / cap_f;
        score = cap_f - item_size as f64;
        score -= 18.0 * tight;                       // large items deserve a fresh bin
        score += 15.0 * (1.0 - progress);            // early stream: consolidation preferred
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0;                            // fresh bin can host the next item too
        }
        if fitting_bins_count == 1 {
            score += 12.0;                           // an existing last-chance bin beats a new bin
        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
    }

    // Mild penalty on excessive open bins to encourage closure.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else {
        // Reward tight fits relative to residual.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * tightness;
    }

    // Post-residual usable if next item fits into it (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for lookahead: mild penalty scaled by gap uselessness.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * (0.5 + progress);

    // New-bin candidate: only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when open bins are numerous/tight.
        score = 40.0 + 0.3 * mean_residual + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin has full room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins whose post-residual exactly matches the next item (2-step lookahead match)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / (bin_capacity as f64)) * (post_residual as f64 / bin_capacity as f64);
        // Strong bonus for perfect chain: item fits now, next item fits perfectly after
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that next item cannot use at all
        if next_item_size > post_residual {
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Penalize small unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to current item
    score -= 10.0 * (item_size as f64 / bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins below-average residual (tighter bins)
    score += 0.15 * (mean_residual - post_residual as f64);

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 40.0 * (0.5 + progress);
    } else {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, but scale non-linearly —
    // small residuals are precious, large ones are cheap.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).sqrt() * pr;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item,
    // punish leftovers that are just barely too small (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 18.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else if post_residual > 0 {
            let waste = post_residual as f64 / nxt;
            score += 25.0 * waste.min(1.5);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Scarcity pressure: many items, few fitting bins → conserve open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let scarcity = (fitting_bins_count as f64).recip().min(3.0);
    score -= 8.0 * scarcity * (0.4 + 0.6 * progress);

    // Global residual alignment: placing into a bin below mean residual
    // balances the pool of open bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * dev;

    // New-bin candidate handling: opening a bin is default-expensive,
    // but attractive for large items early, or when the stream is dense
    // with big items and current bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let mut penalty = 70.0 + 0.4 * post_residual as f64;
        // Late in the stream, avoid opening bins unless item is huge.
        penalty += 90.0 * progress;
        // Large item relative to capacity → new bin is fine.
        penalty -= 0.5 * item_size as f64;
        // If next item is also large, a fresh bin can host both.
        if next_item_size >= 50 && item_size >= 40 {
            penalty -= 45.0;
        }
        // Many open bins already → discourage proliferation.
        penalty += 3.0 * open_bins_count as f64;
        score += penalty.max(0.0);
    } else {
        // Mild reward for using existing bins as open-bin count grows.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Small tie-breaker noise-free determinism: slight preference for
    // bins with residual congruent to common item sizes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post residual (tight packing).
    let mut score = post;

    // Smooth non-linear coupling: post residual normalized, squared and cubed terms
    // reward very tight fits super-linearly.
    let post_norm = post / cap;
    score -= 0.35 * (post_norm * post_norm) * cap;
    score -= 0.15 * (post_norm * post_norm * post_norm) * cap;

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild reward scaled by scarcity of fitting bins.
        score -= 8.0 / fitting_bins_count as f64;
    }

    // Penalty for opening a brand-new bin when it is not necessary:
    // new bin is identified by bin_residual == bin_capacity.
    let is_new_bin = (bin_residual as f64 - cap).abs() < f64::EPSILON;
    if is_new_bin {
        // Penalize more as the stream progresses and open bins exist;
        // relax if the next item is large (future demand justifies a new bin).
        let next_pressure = (next / cap).powi(2);
        score += 25.0 + 45.0 * progress + 10.0 * (open_bins_count as f64).sqrt()
                 - 35.0 * next_pressure;
    }

    // Interaction with mean residual: if this bin is far below mean residual,
    // using it re-balances the pool (slightly favored).
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // Lookahead: penalize leaving post residual that cannot fit next item,
    // reward leaving exactly a usable gap for the next item.
    if next > 0.0 && post > 0.0 {
        if post >= next {
            score -= 6.0 * (1.0 - ((post - next) / cap)).max(0.0);
        } else {
            score += 4.0 * (1.0 - post / next);
        }
    }

    // Small smooth progress tilt: early on, keep bins flexible (favor larger post residual);
    // later, tighten aggressively.
    score += (1.0 - progress) * 8.0 * post_norm * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual in low "harmonic" classes
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Harmonic class penalty via integer division: residual mod thresholds
    let class = pr / 10;
    score += match class {
        0 => -15.0,
        1 => -5.0,
        2 => 0.0,
        3 => 5.0,
        4 => 10.0,
        5 => 15.0,
        6 => 20.0,
        7 => 25.0,
        8 => 30.0,
        _ => 35.0,
    } as f64;

    // Dead-space avoidance: residual too small for typical future items
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= 20.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot fit here: slight penalty proportional to waste
            score += (next_item_size as f64 - pr as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else (large waste) or bins are scarce.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin scales with stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 25.0 * progress;
        // If many bins are open and mean residual is large, discourage new bin
        score += open_bins_count as f64 * 2.0 + mean_residual * 0.2;
        // But if the item is huge and would leave a bad residual elsewhere, ease opening
        if item_size >= 60 && pr == 0 {
            score -= 45.0;
        }
    } else {
        // Slight penalty for leaving very large residual in an existing bin
        if pr > 50 {
            score += 8.0;
        }
    }

    // Mild preference to spread load when few bins are open
    if open_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;

    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let mean = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        0.0
    };

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // If no open bin can take the item, the fresh bin is the only real candidate.
        if fitting_bins_count == 0 {
            return -1000.0 + 0.001 * post;
        }

        let extra_fitting = (fitting - 1.0).max(0.0);

        // If existing residual is already large enough to absorb both the current
        // and next item, opening another bin is usually wasteful.
        let can_pair_existing = next > 0.0 && mean >= item + next;

        // If the residual preserved by NOT using an open bin can take the next item,
        // a fresh bin may be strategically useful.
        let can_preserve_for_next = next > 0.0 && mean >= next && !can_pair_existing;

        // The fresh bin itself can form a tight current+next pair.
        let fresh_pair = next > 0.0 && post >= next && item + next <= cap && next > item;

        // For large lookahead items, a preserved residual slightly larger than the
        // future fresh residual can be valuable.
        let preserved_future_edge = next > 0.0 && mean > cap - next && mean < next;

        let mut pressure = 18.0
            + 1.6 * open
            + 2.5 * extra_fitting
            + 7.0 * progress
            + 0.03 * mean;

        if can_pair_existing {
            pressure += 25.0;
        }

        if can_preserve_for_next {
            pressure -= 7.0;
            if item < next {
                pressure -= 4.0;
            }
        }

        if fresh_pair {
            pressure -= 8.0;
        }

        if preserved_future_edge {
            pressure -= 5.0;
        }

        let mut s;

        if next <= 0.0 {
            s = post;
        } else if can_pair_existing {
            s = post;
        } else if can_preserve_for_next {
            // Opening a fresh bin preserves existing residual for the next item.
            // If the fresh residual is larger than the residual the next item would
            // otherwise create, reward that preservation.
            s = if item < next {
                (2.0 * item - next).max(4.0)
            } else {
                item + (item - next)
            };
        } else if post >= next {
            // The fresh bin can also host the next item.
            s = post - next;
            if post == next {
                s -= 4.0;
            }
        } else {
            // Fresh bin cannot host the next item; rank by remaining usable space.
            s = cap - post + 0.25 * (next - post);
        }

        s + pressure
    } else {
        let mut s;

        if next <= 0.0 {
            s = post;
        } else if post >= next {
            // This bin can host both the current and next item.
            s = post - next;
            if post == next {
                s -= 5.0;
            }
        } else {
            // The next item cannot use this bin after placement.
            // Prefer leaving a larger residual, but account for whether keeping this
            // bin intact would preserve more useful space than opening a new bin.
            s = cap - post + 0.25 * (next - post);

            let future_new_residual = cap - next;

            if bin_residual as f64 <= future_new_residual {
                // Using this bin still leaves at least as much room as opening now.
                s -= 8.0;

                // Do not open a new bin just to avoid a tiny sliver.
                if post <= 5.0 {
                    s -= 80.0;
                }
            } else {
                // Keeping this bin intact may preserve a larger useful gap.
                s += 4.0;
            }

            if mean >= next {
                s -= 6.0 + 0.05 * (mean - next).min(20.0);
            }
        }

        // Strong preference for the last fitting open bin, especially when the fit is tight.
        if fitting_bins_count == 1 {
            let tightness = (1.0 - post / cap).clamp(0.0, 1.0);
            let last_chance_bonus = 8.0 + 18.0 * tightness + 1.1 * open + 9.0 * progress;
            s -= last_chance_bonus;
        } else {
            // General pressure to fill already-open bins.
            s -= 0.25 * open;
        }

        s
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 55.0; // chain of perfect fits
        } else {
            score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: post_residual becomes dead space.
        // Penalize proportionally to how much of the bin is wasted.
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * dead_frac;
        // Extra penalty if the dead space is small but unusable (worst case).
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins below mean residual (keeps larger residuals available for
    // larger future items).
    if (bin_residual as f64) > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Slight penalty for opening new bins when many bins are open and empty-ish.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item fits poorly everywhere.
        // Base penalty so it loses to good fits in open bins.
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin still sets up next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post residual, this is a great placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_gain = (post_residual - next_item_size) as f64;
        score -= 6.0 + 0.08 * chain_gain;
    }
    // If next item would only fit if we leave exactly enough space, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 4.0;
    }
    // Penalize placements that strand space unusable by the known next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Compare against global state: bins with residual far below mean are scarcer space;
    // prefer using bins whose residual is above mean (easy-to-fill elsewhere).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.10 * dev;

    // Penalize creating very small dead space (< 10, unusable by any item).
    if post_residual < 10 && post_residual > 0 {
        score += 5.0;
    }

    // Time horizon: early in stream, be more conservative about filling bins tightly
    // (keep flexibility); late in stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.15 * open_bins_count as f64 * (1.0 - tightness);

    // New-bin candidate handling: an empty bin scores by its raw residual; add a
    // small fixed cost so we only open new bins when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 3.0;
        // If next item is large and current fit is poor, opening fresh can be better.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && item_size > 60 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Core polynomial coupling: post-residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 2.5 * pr * pr);

    // Stream-progress coupling: later in the stream, penalize large residuals more
    score += 3.0 * progress * pr * pr;

    // Tightness reward: smooth cubic that rewards near-perfect fits
    let tight = 1.0 - pr;
    score -= 2.0 * tight * tight * tight;

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 1.5 * (1.0 - slack * slack);
    }

    // Mean-residual deviation: penalize bins far from the mean (creates fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 + 3.0 * progress;
    }

    // Mild pressure from number of open bins: discourage bin sprawl
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space (capacity fractions)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of capacity left

    // Reward tight fits: post_residual in low "dead-space" classes
    if post_residual == 0 {
        score -= 50.0; // perfect packing
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize residuals in awkward harmonic classes (modular logic)
    let cls = post_residual % 10;
    if cls >= 1 && cls <= 3 {
        score -= 3.0; // small awkward remainders still usable for tiny items
    } else if cls >= 7 && cls <= 9 {
        score += 4.0; // near-multiple-of-10 remainders are dead space
    }

    // Lookahead: does next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: reward
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack as f64) * 0.2;
            // exact match of next item is ideal
            if slack == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; residual becomes potential dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: prefer tightest packing overall
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // the item is large relative to remaining open capacity pressure
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 40.0;
        // If item is big and mean residual is small, opening a bin is reasonable
        if item_size as f64 > 0.6 * cap && mean_residual < 0.3 * cap {
            new_bin_penalty -= 25.0;
        }
        // Later in the stream, slightly prefer consolidating into open bins
        new_bin_penalty += 10.0 * progress;
        // If many bins fit the item, no reason to open a new one
        if fitting_bins_count > 2 {
            new_bin_penalty += 20.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference to fill bins with larger residuals when many bins open
    score += (post - mean_residual) * 0.05;

    // Fractional-capacity harmonic coupling: reward residuals near multiples
    // of common item sizes (harmonic classes of 10..80 items)
    for k in [10u32, 20, 25, 40, 50].iter() {
        if post_residual >= *k && post_residual % k == 0 {
            score -= 4.0;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the plausible minimum item size (assume ~10, but adapt via item_size scale)
    // are nearly unusable "dead space" -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Gaps that are large enough to be re-usable are mildly rewarded relative to base.
    if post_residual >= dead_threshold {
        score -= 5.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Tightness reward: reward leaving little-but-usable space ---
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // --- Lookahead coupling ---
    // If the next item fits exactly into the post_residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    }
    // If next item would NOT fit here, this bin's remaining space may become dead later;
    // penalize proportionally when post_residual is small-but-nonzero.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // --- Last-chance logic ---
    // If this is the only bin that can fit the item, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // --- Open-bin pressure ---
    // Prefer reusing existing bins when many bins are open; discourage proliferation.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling: if average residual is large, we have slack capacity
    // spread around; mildly prefer bins whose residual is below the mean (consolidation).
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // --- New-bin candidate handling ---
    // A brand-new empty bin has residual == capacity. Opening a new bin is only
    // justified when current bins would leave terrible fits. Make the empty-bin
    // candidate expensive by default so reuse wins unless dead-space logic dominates.
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64).sqrt() * 5.0;
        // Exception: if the item is large and would leave a tiny unusable gap in
        // every existing bin, opening fresh is fine — approximate via item size.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // Slight stream-progression nudge: later in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near-match lookahead: next item fits snugly (small leftover after next placement).
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next < 10 {
            score -= 30.0 - 3.0 * after_next as f64;
        }
    }
    // Penalize dead space that next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Penalize residuals far below mean (this bin is already tight; prefer spreading).
    score += 0.08 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // (i.e., item barely fits anywhere); otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 1 {
            score += 15.0; // opening new bin wastes the only fitting bin
        }
    }

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post-residual.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last chance: strongly favor the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize if the leftover space would block the next item,
    // reward if the next item could exactly fill the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.5;
            if gap == 0.0 {
                score -= 25.0; // perfect pairing
            }
        } else {
            // post-residual too small for next item: dead space unless tiny
            if post_residual < 10 {
                score -= 10.0; // near-perfect fill
            } else {
                score += (post_residual as f64) * 0.3;
            }
        }
    } else {
        // Last item: minimize waste as much as possible.
        score += (post_residual as f64) * 0.1;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 8.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);
    }

    // New-bin candidate handling: make empty bins unattractive unless
    // existing bins would leave large unusable gaps.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // opening a fresh bin may still pair well
        }
        if fitting_bins_count <= 1 {
            score -= 50.0; // nothing else fits well; new bin is fine
        }
    }

    // Mild time-horizon modulation: early on, be more tolerant of slack;
    // late in the stream, prioritize near-perfect fills.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);

    // Base: normalized post residual, with smooth polynomial shaping.
    let x = pr / cap;
    let mut score = x * (1.0 + 0.8 * x * x);

    // Tight fits are valuable: reward small post_residual non-linearly.
    score -= 0.35 * (1.0 - x) * (1.0 - x);

    // Stream progress coupling: late in the stream, avoid wasting space
    // (dead space costs more when fewer items remain to fill it).
    score += 0.6 * x * x * (0.5 + progress);

    // Lookahead: reward bins whose post_residual can host the next item,
    // penalize post_residuals that are awkward relative to next item.
    if nx > 0.0 {
        let gap = (pr - nx).abs() / cap;
        score += 0.25 * gap * gap;
        if pr >= nx {
            score -= 0.3 * (nx / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.8;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer bins with less residual (tighter fill).
        score += 0.15 * ((bin_residual as f64) / cap);
    }

    // Penalize the brand-new empty bin candidate smoothly: opening a bin is
    // justified only when residual usage here would be very poor.
    if bin_residual == bin_capacity {
        score += 1.2 - 0.9 * (1.0 - x) * (1.0 - x);
    }

    // Mild preference to consolidate into bins whose residual is near the mean
    // (keeps a spread of residuals for future items).
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    // Slight preference for already-open bins vs opening new ones late.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of 10, i.e. post_residual % 10 == 0
    // or small enough to likely absorb future items) are preferred.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 6.0; // perfectly harmonic leftover
    } else if residue_class <= 3 {
        score += 2.0 + residue_class as f64; // dead-space risk
    } else {
        score += (residue_class as f64) * 0.5;
    }

    // Reward if the lookahead item fits into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.1 * next_item_size as f64;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // item fits only before placing current item: mild penalty
            score += 1.5;
        }
        // Harmonic pairing: next item complements post residual to a multiple of 10
        if next_item_size > 0 && (post_residual + next_item_size) % 10 == 0 && next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    // Last chance: only this bin can fit the item -> strong reward.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize wasting a nearly-empty bin on a small item (poor density).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio < 0.35 && bin_residual == bin_capacity {
        score += 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 3.0;
        } else {
            score += 8.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Integer-division threshold: leftover < item_size/2 is likely dead space.
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual < 20 {
        score += 200.0;
    } else if post_residual < 30 {
        score += 80.0;
    }

    // Dead space relative to the lookahead item: if the next item cannot
    // fit in this residual, the leftover is likely wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward exact / near-exact fills (post_residual 0 handled by base term).
    if post_residual == 0 {
        score -= 300.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
