    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        score += 60.0 * open_bins_count as f64;
        // New bin is fine if the fit in existing bins is very poor.
        if post_residual < 10 && bin_residual >= item_size {
            score -= 400.0;
        }
    } else {
        // Mild preference for bins tighter than average (best-fit flavor).
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    // Slight stream-phase modulation: early on, be more willing to open
    // bins (flexibility); late, consolidate tightly.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 50.0 * (1.0 - phase);
    } else {
        score += 30.0 * phase;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            // perfect match: next item exactly fills this bin
            score -= 45.0;
        } else if pr >= nxt {
            // next item still fits: reward closeness to exact match
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // dead space: next item can't use the leftover
            score += (nxt - pr) * 0.6;
        }
    } else {
        // last item: just prefer tightest packing
        score += 2.0;
    }

    // --- last-chance bonus: only bin that fits, avoid opening new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
