    }

    // --- new-bin candidate handling ---
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive for very large items
        // (where post_residual is small) or when existing bins are already tight
        score += 4.0 + mean_residual * 0.03;
        if pr < 20.0 {
            score -= 18.0; // big item barely fits a fresh bin: good
        }
    } else {
        // mild reward for keeping residual small overall
        score += (pr / cap) * 3.0;
    }

    // --- phase-aware nudge: pack tighter toward stream end ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Strong reward for near-perfect fits (post residual small relative to item).
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / item_size as f64;
        score += 8.0 * waste_ratio;
    } else {
        score -= 30.0; // perfect fill
    }

    // Dead-space penalty: residual left too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty proportional to competition, encouraging diversity of usage
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain_fit;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // blocking next item with unusable gap
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Global state coupling: prefer bins below mean residual (consolidate large gaps).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in stream, be more conservative about spreading; early, explore.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: empty bin is a fallback; penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let fallback = 20.0 + 0.5 * open_bins_count as f64;
        // if no open bin fits, opening is necessary (fitting_bins_count counts open bins only)
        if fitting_bins_count == 0 {
            score = -100.0;
        } else {
            score = fallback + 10.0 * (1.0 - fill_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
