    score += 12.0 * progress * norm_pr * norm_pr;

    // Interaction: post_residual vs mean residual — avoid leaving residual far below average (wasted space)
    let dev = (mean_residual - pr) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
