        if pr % 10 == 0 { bonus += 6.0; }
        else if pr % 5 == 0 { bonus += 3.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr >= 90 { bonus += 2.0; }        // nearly-empty class
        if pr <= 5 { bonus -= 12.0; }        // unusable sliver
        else if pr <= 10 { bonus -= 6.0; }   // hard-to-fill class
