    } else {
        score -= 25.0; // perfect closure is excellent
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 { score -= 40.0; }
        else if gap <= 10 { score -= 18.0; }
        else { score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64); }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0; // this bin becomes dead after placement
    }

    // Last-chance bonus: only one open bin can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or this is a large item with poor fit options.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Default penalty keeps items in open bins.
        score += 28.0;
        // Relax when bins are nearly full (little usable residual left)
        // or when the item is huge and late in the stream.
        if pressure < 0.25 { score -= 20.0; }
        if big_item > 0.6 && pressure < 0.4 { score -= 12.0; }
        if progress > 0.8 && fitting_bins_count <= 1 { score -= 8.0; }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64;

    // Slight pull toward bins with residual close to the item (integer-division threshold).
    let quot = bin_residual / item_size.max(1);
    if quot == 1 { score -= 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it's too small for the smallest plausible item (>=1),
    // but practically gaps below ~10 are hard to reuse. Use a soft quadratic
    // penalty concentrated on small post_residuals.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead_zone = 12.0;
        if pr < dead_zone {
            score += (dead_zone - pr) * (dead_zone - pr) * 0.8;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Pressure from number of open bins: prefer bins that reduce bin count growth;
    // when many bins are open, favor filling existing bins over opening new ones.
    let ob = open_bins_count as f64;
    score -= ob.min(20.0) * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves waste; mild reward proportional to leftover.
            let leftover = (post_residual - next_item_size) as f64;
            score -= 20.0 - leftover.min(20.0);
        } else {
            // Next item won't fit in the leftover: penalize small leftovers.
            let pr = post_residual as f64;
            if pr < next_item_size as f64 {
                score += (next_item_size as f64 - pr).min(15.0) * 1.2;
            }
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a "nearly full" bin — finishing it off is good.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff.min(30.0) * 0.6;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable when no open bin fits well:
        // penalize it moderately, more so when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + ob * 0.5 - progress * 10.0;
        // If the item is large, a fresh bin is actually fine.
        if item_size >= bin_capacity * 7 / 10 {
            score -= 25.0;
        }
        // If lookahead item is large too, fresh bin preserves pairing potential.
        if next_item_size >= bin_capacity * 6 / 10 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item (perfect chaining), penalize near-miss dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < f64::EPSILON {
            // Perfect 2-chain: post_residual == next_item_size
            score -= 40.0 + 0.5 * item_size as f64;
        } else if post_residual >= next_item_size {
            // Next item still fits here: partial reward, scaled by tightness
            let tight = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 12.0 * tight;
        } else {
            // Next item cannot fit here: dead space relative to next item
            let gap = nxt - post_residual as f64;
            score += 6.0 * (gap / 100.0).min(1.0);
        }
    }

    // Tight fits are good: small post_residual is naturally rewarded by the base,
    // but add a super-linear penalty for medium dead space (hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny unusable sliver: fine, bin is nearly full anyway
    } else if post_residual >= 10 && post_residual < 30 {
        score += 10.0; // awkward medium dead space
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give it a mild penalty that grows with open bins count,
    // so it wins only when all open-bin scores are poor (large post_residual + gaps).
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if the next item is large and current item is small, a fresh bin
        // can be attractive for future packing.
        if next_item_size > 60 && item_size < 30 {
            score -= 30.0;
        }
    }

    // Late-stream consolidation: as the stream ends, favor filling existing bins
    // over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post residual), with mild non-linearity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space penalty scaled by how much of the residual is wasted
            let wasted = post_residual as f64;
            score += 0.35 * wasted * (1.0 - wasted / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits even more
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: opening a bin is attractive only when the
    // current item leaves a large, reusable residual or few bins fit the item
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheap; later, avoid fragmentation
        let open_cost = 8.0 + 30.0 * progress;
        // If the item is large relative to capacity, a fresh bin is natural
        let size_pull = 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many open bins already fit the item, discourage a new bin
        let crowd = 2.5 * fitting_bins_count as f64;
        // If mean residual across open bins is high, open bins are underused
        let underuse = (mean_residual - item_size as f64).max(0.0) * 0.15;
        score = open_cost - size_pull + crowd + underuse;
        // New bin residual after placement equals capacity - item_size; compare fairly
        score += post_residual as f64 * 0.2;
    }

    // Global state: many open bins -> consolidate into existing ones
    score += 0.4 * open_bins_count as f64 * tightness;

    // Penalize leaving residuals that are awkwardly small (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 9.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: reward tight fits (low post residual), with non-linear (quadratic) emphasis.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Dead-space penalty grows as stream progresses (less future opportunity to reuse space).
    let dead = norm_pr * norm_pr;
    score += 60.0 * dead * (0.5 + progress);

    // Interaction: post residual vs mean residual — penalize bins far from the pack's mean fill state.
    let dev = (pr - mean_residual) / cap;
    score += 25.0 * dev * dev * cap;

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 30.0 * (1.0 - slack * slack);
        } else {
            // Next item can't follow: penalize proportionally to overflow.
            score += 20.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mild penalty for many open bins: prefer consolidation.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate (empty bin): keep its score moderate so it wins only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: residues near capacity thirds/quarters
    // are "harmonic" (easily combined with common item sizes), so reward them.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, always great
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -10.0
    } else if pr <= 9 {
        8.0 // tiny dead space, nearly wasted
    } else {
        0.0
    };
    score += class_bonus;

    // Tightness coupling: reward small post_residual more than linearly.
    let tightness = 1.0 - (post / cap);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here; if this bin would be left with awkward residue, penalize.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large (few future partners) or nothing meaningful is gained by reuse.
    if bin_residual == bin_capacity {
        // Base penalty so reuse of open bins is preferred by default.
        score += 20.0;
        // Large items pair well with a fresh bin.
        if item_size >= 60 {
            score -= 18.0;
        }
        // If the current best fit would leave a large awkward residual, allow new bin.
        if post_residual > 40 {
            score -= 12.0;
        }
        // Late in the stream, consolidation matters more; discourage new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins with high mean residual: prefer packing into them.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild pressure against hoarding many open bins.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: small post_residual gaps that are hard to fill later.
    // Gaps in [1, 15] are "unusable" for typical item ranges -> heavy penalty.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - post_residual as f64 / 15.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger gaps: mildly penalize very large waste beyond what's needed.
        score += 0.05 * post_residual as f64;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, prefer reusing existing bins
    // (penalize the new-bin candidate via its residual == capacity path).
    if bin_residual == bin_capacity {
        // New-bin candidate: score it against current packing state.
        score = 100.0 + 0.5 * open_bins_count as f64;
        // Late in the stream, closing out bins is cheap; opening new bins is fine
        // if the mean residual is small (existing bins nearly full).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If next item would fit in the fresh bin alongside, opening is attractive.
        if (next_item_size as f64) <= (bin_capacity - item_size) as f64 {
            score -= 10.0;
        }
        // If existing bins have plenty of room, discourage opening a new one.
        if mean_residual > item_size as f64 * 1.5 {
            score += 30.0;
        }
    } else {
        // Existing bin: slight preference to keep open_bins_count small by filling
        // bins that are already small-residual.
        score += 0.2 * (bin_residual as f64 - mean_residual).abs();
        // Lookahead: if next item fits exactly in the post residual, reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here anyway; prefer leaving a gap >= next item
            // is impossible, so prefer minimal gap otherwise.
            score += 5.0;
        }
    }

    // Mild preference for bins whose residual is close to item_size (best-fit core).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with a little room left -> moderate reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual as f64 - next_item_size as f64) * 0.3;
    }
    // Next item cannot fit into this bin's post-residual: penalize dead space,
    // especially when the leftover is small (unusable sliver).
    else if next_item_size > 0 {
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 8.0 + gap * 0.25;
    }

    // Penalize tiny unusable leftovers (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward exact fill.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Coupling with mean residual: prefer bins whose fit leaves residual
    // close to the mean (balanced packing), penalize outliers.
    let dr = post_residual as f64 - mean_residual;
    score += 0.15 * dr.abs();

    // Early in the stream, keep bins flexible (favor larger post_residual);
    // late in the stream, prioritize tight fills.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * post_residual as f64 * 0.1;
    score -= progress * (bin_residual - item_size) as f64 * 0.05;

    // New-bin candidate: make it moderately unattractive so we only open a new
    // bin when no open bin offers a decent fit (its score is its post_residual,
    // typically large), but not so high that we're forced into terrible fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the current bin would be a poor host for the next item, allow
        // opening a fresh bin more readily.
        if next_item_size > 0 && post_residual < next_item_size as u32 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by base score.
    // Non-linear bonus for near-perfect packing.
    if post_residual == 0 {
        score -= 60.0; // perfect fill, huge reward
    } else if post_residual <= 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space that no future item can plausibly use.
    // Items are >= 1, but typical useful granularity: residual < smallest plausible item.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0; // almost unusable sliver
    }

    // Lookahead coupling: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.2 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving large-but-not-matching residual
            let gap = (next_item_size - post_residual) as f64;
            if gap < 30.0 {
                score += 0.35 * gap;
            }
        }
    } else {
        // Last item: just minimize post_residual, no future concerns.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate logic: opening a new bin wastes capacity if open bins can fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full residual is high already.
        // Extra penalty scaled by how many bins could take the item and stream progress.
        if fitting_bins_count > 0 {
            score += 35.0 + 8.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than fragmenting space.
    score += 0.05 * mean_residual * (open_bins_count as f64).ln().max(0.0) * 0.1;

    // Mild preference for bins with smaller current residual (denser bins) when
    // multiple bins fit, to keep a spread of residual sizes.
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, be aggressive about filling bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: penalize wasted space, with a non-linear (quadratic) waste curve.
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth polynomial coupling with stream progress: late in the stream,
    // tight fits matter more; early on, be more tolerant.
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Reward filling bins nearly full: subtract a cubic bonus as post -> 0.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bin: strong reward to use it (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.8 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Mean residual deviation: prefer bins whose residual is below average
    // (i.e., nearly full bins), smoothly weighted.
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev;

    // Lookahead: if next item fits exactly in post residual, reward this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as f64 <= post {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (gap / cap);
        }
    }

    // New-bin candidate: keep it attractive only when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 / cap) * 30.0
        };
        score += poor_fit_penalty;
        // Late stream: discourage opening new bins.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: harmonic class of post_residual (buckets of 10 = capacity/10)
    let post_class = post_residual / 10;
    score -= match post_class {
        0 => 45.0,
        1 => 25.0,
        2 => 10.0,
        3 => 3.0,
        4 => 0.0,
        _ => -1.5,
    };

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // dead space penalty scaled by how much next item overflows
        score += (next_item_size as f64 - post).min(40.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // many options: prefer tight fits even more
        score += 2.0;
    }

    // Penalize bins whose residual is far below mean (already well-used but cramped)
    score += (mean_residual - post).clamp(-20.0, 20.0) * 0.15;

    // New-bin candidate handling: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let fit_quality = post / cap; // = 1 - item/cap for empty bin
        let bad_existing = (mean_residual - item_size as f64).max(0.0);
        // default new-bin score: moderately high (worse than decent fits)
        score = 55.0 + fit_quality * 20.0 - bad_existing * 0.4;
        // open a new bin when item is large relative to capacity and existing residuals are poor
        if item_size as f64 / cap > 0.6 && mean_residual < item_size as f64 * 1.05 {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Slight preference early in stream to keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // Harmonic penalty: post_residual divisible by common item sizes is more reusable
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 4.0;
                break;
            }
        }
        // penalize awkward residuals (prime-ish / odd small remainders)
        if post_residual % 2 == 1 && post_residual < 10 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap = wasted capacity
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fill is strongly rewarded.
        score -= 100.0;
    } else if post_residual >= 80 {
        // Large residual keeps the bin flexible.
        score -= 15.0;
    }

    // Reward bins whose residual can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 20.0;
        } else if post_residual > 0 {
            // Residual too small for next item: dead space risk.
            score += 15.0;
        }
        // Bonus for chaining: post_residual exactly fits next item.
        if post_residual == next_item_size as f64 {
            score -= 30.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let open_pressure = open_bins_count as f64 / 10.0;
    if bin_residual < bin_capacity {
        score -= open_pressure * 5.0;
    } else {
        // New-bin candidate: penalize unless current fits are all poor.
        let poor_fit_penalty = if post_residual > 0 && post_residual < 10 { 70.0 } else { 0.0 };
        score += 35.0 + open_pressure * 3.0 - poor_fit_penalty;
    }

    // Mean-residual coupling: high mean residual means slack exists elsewhere;
    // prefer packing into bins with below-average residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, prioritize closing bins out (tight fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly or partially in the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain of perfect fills
        } else if next_item_size <= post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64; // next item fits, prefer tight
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when good fits exist, unless current fits are bad
    if bin_residual == bin_capacity {
        // new bin candidate: neutral post residual, but penalize if any open bin fits decently
        if next_item_size == 0 {
            score += 50.0;
        }
        // discourage new bin unless the best alternative leaves large dead space
        score += 40.0;
        if fitting_bins_count > 0 && (bin_residual - item_size) as f64 >= 0.0 {
            // only open new bin if existing bins would leave very tight/wasteful fits
            score += 20.0 * open_bins_count as f64;
        }
    }

    // Slight preference to fill older bins first (stability)
    score += 0.01 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot host future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Penalize residuals that are just barely too small for the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 0.8 * gap;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes capacity equal to residual left by others.
        let waste = mean_residual.max(0.0);
        score += 60.0 + 0.5 * waste;
        // Early in the stream, new bins are cheaper (exploration).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // If many bins fit the item, no reason to open a new one.
        score += 5.0 * (fitting_bins_count as f64);
    } else {
        // Prefer fuller bins: compare residual against mean residual.
        let diff = (bin_residual as f64) - mean_residual;
        score += 0.15 * diff;
    }

    // Mild preference for using bins when many are open (avoid bin proliferation).
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, scaled by progress
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear coupling: quadratic in normalized post residual
    let prn = pr / cap;
    score += 12.0 * prn * prn;

    // Favor tight fits: reward small post_residual with smooth falloff
    score -= 10.0 * (-prn * 6.0).exp();

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0;
    } else if next_item_size > 0 {
        // Penalize if post residual is dead space for next item but nonzero
        score += 3.0 * (prn * (1.0 - progress));
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: slight penalty to spreading; encourage consolidation
    score += 0.05 * open_bins_count as f64 * prn;

    // Mean residual coupling: prefer bins near mean to keep balance
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make it moderately attractive only when residual space is large
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // ---- NEW-BIN CANDIDATE handling ----
    if bin_residual == bin_capacity {
        // Base penalty: opening a new bin is expensive by default.
        score += cap * 0.8;
        // Reward opening fresh bins for large items (they leave awkward gaps elsewhere).
        score -= item * 0.35;
        // If this is the ONLY bin that can fit, opening is essentially forced.
        if fitting_bins_count <= 1 {
            score -= cap * 0.6;
        }
        // Perfect or near-perfect fit in a fresh bin is attractive.
        if post <= 10.0 {
            score -= 25.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += t * 20.0;
        return score;
    }

    // ---- Dead-space shaping on post_residual ----
    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 18.0;
    } else if post < 10.0 {
        // Tiny unusable slivers are dead space: penalize proportionally.
        score += (10.0 - post) * 1.6;
    }

    // Harmonic class logic: residuals on nice decade boundaries stay reusable.
    let cls = post_residual % 10;
    if cls != 0 && post_residual > 0 {
        score += cls as f64 * 0.45;
    }
    // Half-capacity class residuals are highly reusable.
    if post_residual == bin_capacity / 2 {
        score -= 8.0;
    }

    // ---- Last-chance bin ----
    if fitting_bins_count == 1 {
        score -= 28.0;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also absorb the next item: strong reward.
            score -= 12.0;
            // Extra reward if next item then fits snugly (post2 small).
            let post2 = post_residual - next_item_size;
            if post2 < 10 {
                score -= 6.0;
            }
        } else {
            // Gap too small for the lookahead item: mild penalty by shortfall.
            score += (next_item_size - post_residual) as f64 * 0.22;
        }
    }

    // ---- Tightness preference: favor fullest bins (smallest pre-residual) ----
    score += (bin_residual as f64 / cap) * 9.0;

    // ---- Stream-phase consolidation pressure ----
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 6.0;

    // ---- Global context coupling ----
    // Many open bins with high mean residual: encourage spreading wisely.
    score += (open_bins_count as f64) * 0.06 - mean_residual * 0.06;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Usable medium gap: mild reward.
        score -= 4.0;
    }

    // Dead space that cannot fit the next item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
    }
    // If the leftover can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: when many bins are open,
    // discourage opening a new one; the empty-bin candidate gets penalized.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
        // Opening a new bin is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Prefer larger fill ratio.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
