pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual is already the base).
    let tightness = (item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 8.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize dead space: residuals too small for typical future items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving a moderately-sized orphan residual.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full on average
    // or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / bin_capacity as f64;
        // Reward opening a new bin when existing bins are congested.
        score -= 10.0 * mean_tight;
        // Penalize opening new bins early in the stream when many bins are open.
        score += 0.4 * open_bins_count as f64;
        // Slight time decay: later in the stream, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual deviates below the mean (use up the fullest bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.5;
        } else {
            score += 1.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        }
    }

    // Mild preference for bins that become perfectly full.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (low post residual), with polynomial shaping
    let mut score = post;

    // Non-linear penalty on residual: dead space grows quadratically in value
    score += 12.0 * norm_post * norm_post * cap * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses (commit to compactness)
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly; it should only win when fits are terrible
        score = cap as f64 + 30.0
            - 20.0 * (1.0 - norm_item)
            - 15.0 * progress
            + 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits well in the post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let waste = post - nx;
            score -= 18.0 * (1.0 - waste / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 6.0 * (nx - post) / cap * cap * 0.1;
        }
    }

    // Mild dispersion penalty: bins far from mean residual are less attractive
    score += 0.05 * (post - mean_residual).abs();

    // Slight preference for consolidating into fewer bins early
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "reusable" classes.
    // Class A: post_residual divisible by 10 (clean slots) -> strong reward.
    // Class B: post_residual in [1..=5] (near-perfect fit) -> biggest reward.
    // Class C: post_residual in 6..=9 (awkward dead space) -> penalty.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best outcome
    } else if pr <= 5 {
        score -= 45.0;
    } else if pr % 10 == 0 {
        score -= 25.0;
    } else if pr % 10 <= 3 {
        score -= 10.0;
    } else if pr % 10 >= 6 && pr % 10 <= 9 && pr < 20 {
        score += 15.0; // tiny awkward remainder in a nearly full bin
    }

    // Harmonic pairing with next item: reward if next_item_size fits exactly
    // into post_residual (integer-division match).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // chain: next item perfectly seals this bin
        } else if next_item_size <= pr && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            score -= 20.0; // post_residual is a harmonic multiple of next item
        } else if next_item_size > pr && next_item_size - pr <= 10 {
            score += 8.0; // next item just barely misses: mild penalty
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Default penalty: prefer filling existing bins when fit is decent.
        score += 40.0;
        // But if the item is huge relative to capacity and mean residual is small,
        // opening fresh is fine.
        let fill_frac = item_size as f64 / cap;
        if fill_frac > 0.8 {
            score -= 50.0;
        }
        // If existing bins have very fragmented residuals, new bin is attractive.
        if mean_residual < item_size as f64 * 1.1 && fitting_bins_count > 0 {
            score -= 35.0;
        }
        // Late in the stream, consolidate rather than open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score += 20.0;
        }
    }

    // Mild preference for bins whose residual is already tight (best-fit core),
    // scaled by how many alternatives exist.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight penalty for spreading across many open bins when mean residual is high.
    if open_bins_count > 4 && mean_residual > 40.0 && post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost unusable
    // (min item size ~1..100, but gaps < 20 rarely get filled later).
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 12.0; // heavy penalty for tiny gaps
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is always best
    }

    // Reward tight fits relative to bin residual (waste ratio).
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 25.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage creating more
    // dead space spread across bins; favor consolidating into existing space.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: if average residual is already small, opening
    // a new bin is costly, so penalize the new-bin candidate implicitly via
    // its large post_residual; additionally reward filling bins when mean
    // residual is low.
    if mean_residual < 25.0 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item could use the post_residual, reward leaving
    // exactly that much space; otherwise penalize leaving space that matches
    // nothing.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, prefer closing bins out (fill existing ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match with next item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: item fills bin exactly after next item
        } else if next_item_size < post_residual {
            let slack = post_residual as u32 - next_item_size;
            let tight = slack as f64 / bin_capacity as f64;
            score -= 30.0 * (1.0 - tight); // near-perfect chain reward
        } else {
            // next item won't fit here: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative residual coupling with mean residual.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 6.0 * ((pr - mean_residual) / mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize very small post residuals only mildly (dead space), but
    // a zero residual is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 5.0;
    }

    // New-bin candidate: make opening a new bin moderately unattractive
    // unless open bins are few (early stream) or this is a big item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 30.0;
        nb -= 15.0 * (1.0 - progress); // cheaper to open bins early
        if item_size > bin_capacity / 2 {
            nb -= 10.0; // large items justify fresh bins
        }
        score += nb;
    }

    // Prefer tighter fits overall: residual relative to capacity.
    score += 3.0 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post-residual grows with item size.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * (item_size as f64) * 1.7;

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 45.0 + 0.5 * (item_size as f64);
    }

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.35 * open_bins_count as f64;
        if fitting_bins_count >= 1 && (post_residual as f64) > mean_residual * 0.5 {
            score += 15.0;
        }
        // Early stream: be more willing to open bins; late stream: avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 25.0;
    }

    // Lookahead: if next item could use this bin's post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // Dead space likely: penalize leaving tiny unusable gap.
            score += 20.0 + post_residual as f64;
        }
    } else {
        // Last item: prefer minimal post residual aggressively.
        score += post_residual as f64 * 0.5;
    }

    // Prefer bins below mean residual (filling emptier bins) mildly.
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    // Discourage creating residuals that are awkward sizes (small gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 40.0 * poly;

    // Penalize very tight fits more strongly as stream progresses (dead space risk)
    let tight = 1.0 - pr_norm;
    score += 15.0 * tight * tight * (0.5 + progress);

    // Reward closing bins exactly (post_residual == 0)
    if post_residual == 0 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0 + 20.0 * progress;
    }

    // Lookahead: prefer bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Diversification early on: mildly favor spreading across bins when many open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (filler bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: post_residual in low harmonic classes.
    match post_residual {
        0 => score -= 60.0,                    // perfect fill
        1..=5 => score -= 35.0,                // near-perfect
        6..=10 => score -= 15.0,
        _ => {}
    }

    // Harmonic class of post_residual via integer division thresholds.
    let class = post_residual / 10; // 0..=10
    score += class as f64 * 3.0;

    // Penalize dead space that no future item can plausibly fill.
    // Smallest item is 1, so any residual is technically fillable, but
    // small odd residuals are harder; use modulo structure.
    let odd_penalty = if post_residual % 2 == 1 { 2.0 } else { 0.0 };
    score += odd_penalty;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the leftover
            let frac = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * frac;
        } else {
            // next item cannot use this bin's leftover; slight penalty scaled
            // by how much dead space remains relative to capacity.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base preference for reusing existing bins: new bin is penalized.
        score += 30.0;
        // But if the item is huge and leaves a very small post_residual,
        // opening a fresh bin can still be attractive (rarely overrides).
        if item_size >= 90 && post_residual <= 5 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild pressure when many bins are open: consolidate.
    score += open_bins_count as f64 * 0.3;

    // Deviation from mean residual: prefer bins below mean (tighter bins)
    // so we drain nearly-full bins first.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Small early-stream bonus for filling bins aggressively.
    if step_index < total_items / 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny non-zero gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Gaps in the "dead zone" that nothing (min size 1..100) can use later
    // are penalized; gaps that can still fit the lookahead item are good.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // preserves room for the next item
        } else if post_residual > 0 {
            score += 8.0; // gap too small for lookahead: likely dead space
        }
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): make it less attractive than decent
    // existing fits, but attractive when remaining open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If existing bins are heavily fragmented (high mean residual spread
        // unusable), opening fresh is fine: soften the penalty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 10.0 {
            score -= 10.0 * progress;
        }
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing ones rather than spawning more.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins whose residual is close to the item (tight packing).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: minimize post residual aggressively.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Tightness of the fit relative to bin residual before placement.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly reward this placement (creates a perfect chain).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item fits into post_residual (but not exactly), mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 6.0;
    }
    // Penalize if post_residual is dead space: too small for next item and
    // below a useful threshold relative to mean residual.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.5;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver penalty
    }

    // Relative to mean residual: prefer filling bins that are below-average
    // residual (more full), keeping emptier bins flexible.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and the fit would be near-perfect.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 15.0;
        if waste <= 5 {
            score -= 20.0; // near-perfect fresh-bin fit is great
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // fresh bin can also serve the next item
        }
    }

    // Late in the stream, consolidate harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // When many bins are open, favor tighter packing to close them out.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: residual that can no longer fit typical items is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward residuals that still fit the next item,
    // punish residuals that fit nothing useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect pairing: post residual exactly matches next item size
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less so
    // early in the stream or when many open bins exist with poor fit potential.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 18.0;
        // If item is large and would leave a tiny unusable residual in any bin,
        // opening fresh is attractive.
        if post_residual < 10 {
            new_bin_penalty -= 14.0;
        }
        // Late in the stream, avoid opening bins that can't be filled.
        new_bin_penalty += 10.0 * progress;
        // Many open bins with slack: discourage adding another.
        if mean_residual > 30.0 && open_bins_count > 3 {
            new_bin_penalty += 8.0;
        }
        score += new_bin_penalty;
    } else {
        // Prefer bins with residual close to item_size (near-exact fill).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * gap;
        // Slight preference for bins with larger residuals among equally tight fits.
        score -= 0.02 * bin_residual as f64;
    }

    // Mild global pressure: when few bins are open, consolidate more aggressively.
    let openness = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * openness;

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (balanced load), slight effect.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let pr = post_residual as f64 / bin_capacity as f64;
    // non-linear polynomial coupling of post_residual with progress
    score += 12.0 * pr * pr * (0.5 + progress);
    score -= 8.0 * pr * (1.0 - pr) * (1.0 - progress);
    // penalize near-full waste relative to mean residual
    let md = (pr * bin_capacity as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * md * md.abs();
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual as f64 >= ns {
            score -= 5.0 * (ns / bin_capacity as f64) * (1.0 - progress);
        } else {
            score += 4.0 * (1.0 - ns / bin_capacity as f64) * pr;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }
    // new-bin candidate: penalize mildly so it's only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress) - 3.0 * (mean_residual / bin_capacity as f64);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Harmonic class logic on post_residual: classify leftover space into
    // capacity-fraction buckets; leftovers in "useless" classes (very small
    // slivers that likely can't host future items of size >=10) get penalized.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class_penalty = if pr == 0 {
        -40.0 // perfect fill
    } else if pr < 10 {
        25.0 // dead space: below the minimum plausible item size
    } else if pr < eighth {
        12.0
    } else if pr < quarter {
        4.0
    } else if pr < bin_capacity / 2 {
        -6.0
    } else {
        -2.0
    };
    score += class_penalty;

    // Exact modulo-harmonic bonus: if post_residual is a divisor-like residue
    // (divides capacity or is a multiple of a common item quantum), reward it.
    if pr > 0 && (bin_capacity % pr == 0 || pr % 10 == 0 || pr % 5 == 0) {
        score -= 8.0;
    }
    // Odd, awkward residues get a small harmonic penalty.
    if pr % 2 == 1 && pr > 10 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is an ideal chain placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; leftover should be large enough to be
            // reusable later, otherwise we created waste.
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a reasonable fit. Penalize opening a new bin progressively
    // with the number of open bins and how well existing bins could fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 55.0
            + 8.0 * (open_bins_count as f64).sqrt()
            + 20.0 * (1.0 - progress);
        // If nothing fits well (large item, few fitting bins), soften penalty.
        let poor_fit = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score += new_bin_penalty - poor_fit;
    }

    // Mild preference for bins below the mean residual (keep residuals balanced,
    // preserve large holes for large future items).
    let diff = (post_residual as f64) - mean_residual;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min item size 1, but realistically small gaps)
    // are pure waste. Penalize gaps in the "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 25.0;
    } else if post_residual <= 15 {
        // Tight but usable gap: mild reward relative to base.
        score -= 5.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // This placement strands the next item: penalize.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading items thin,
    // but only mildly, so dead-space logic dominates.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of other bins; make the
        // new bin costly by default. Its post_residual is large, so add
        // a fixed surcharge; it can still win when all open bins are bad.
        score += 18.0 + 0.5 * open_bins_count as f64;
        // But if the item is large and mean residual elsewhere is small
        // (poor fits everywhere), relax the penalty.
        if (mean_residual < item_size as f64 * 0.35) || (fitting_bins_count <= 1 && open_bins_count > 0) {
            score -= 20.0;
        }
    } else {
        // Favor bins whose residual is close to the item (best fit signal).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness * tightness;
        // Slight preference for bins below mean residual (filling the emptier ones
        // consolidates waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Late in the stream, prefer closing bins out (tight fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - tightness_proxy(post_residual, bin_capacity));

    score
}

#[inline]
fn tightness_proxy(post_residual: u32, bin_capacity: u32) -> f64 {
    1.0 - post_residual as f64 / bin_capacity as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fits (small post_residual already does this).

    // Aggressive 2-step lookahead: strongly reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can chain into this bin: subtract bonus proportional to tightness.
            score -= 45.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post-residual is dead space relative to next item: penalize.
            score += 8.0 + 0.25 * gap;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Neutral baseline: new bin costs one bin; slightly discourage unless item is large.
        score = bin_capacity as f64 * 0.55;
        if item_size >= 70 {
            score -= 10.0; // large items start fresh bins more willingly
        }
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 5 {
            score -= 20.0; // two-item chain fits perfectly in a fresh bin
        }
    }

    // Slight progression pressure: early in stream, tolerate opening bins; late, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space ratio.
    let waste_ratio = post_residual as f64 / cap;
    score += 40.0 * waste_ratio * waste_ratio;

    // Lookahead: penalize if the next item cannot fit into the post-residual,
    // but soften when post-residual is already small (dead space anyway).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 12.0 * (nxt - post_residual as f64) / cap;
        } else {
            // Reward reserving space exactly for the next item.
            let gap = post_residual as f64 - nxt;
            score -= 8.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to keep flexibility.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer bins whose residual deviates below the mean (consolidate small leftovers).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when this bin is a last chance
    // or the item is large relative to a fresh bin's usefulness.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (open_bins_count as f64).ln().max(0.5);
        let item_frac = item_size as f64 / cap;
        // Penalize opening a new bin generally; discount late in the stream
        // and for large items that would leave awkward space elsewhere.
        score += 30.0 - 15.0 * progress - 10.0 * item_frac - 3.0 * pressure;
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) < next_item_size as f64 {
            // New bin would leave dead space for the known next item.
            score += 10.0;
        }
    }

    // Mild time-horizon coupling: early on, be greedy about consolidation;
    // later, tolerate fragmentation slightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * waste_ratio * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual [0,1]

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth non-linear coupling of post residual with stream progress:
    // early in the stream, mildly tolerate larger post residuals (bins stay flexible);
    // late in the stream, penalize them more strongly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Non-linear dead-space penalty: residuals that are small-but-unusable
    // (below a smooth soft threshold tied to mean residual) get extra penalty.
    let soft_thresh = (mean_residual / cap).max(0.0) * 0.5;
    let dead = norm_pr - soft_thresh;
    if dead < 0.0 {
        score += 20.0 * dead * dead * cap; // quadratic penalty near unusable zone
    }

    // Reward filling bins snugly: smooth sigmoid-like bonus for low norm_pr
    let snug = 1.0 - norm_pr;
    score -= 15.0 * snug * snug * snug;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // slight penalty when many alternatives exist, scaled smoothly
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // can still fit next item: reward, stronger when gap is small (efficient)
            let g = gap / cap;
            score -= 10.0 * (1.0 - g) * (1.0 - g);
        } else {
            // cannot fit next item: mild penalty proportional to shortfall
            score += 0.3 * (-gap);
        }
    }

    // Mild penalty for opening a brand-new bin when open bins exist,
    // decaying as stream progresses (early on, new bins are cheaper strategically).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 * (1.0 - progress) + 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better (base already does this).
    // But penalize "dead" residuals that are too small to ever be useful (harmonic classes).
    // Class A: post_residual in 1..=9 -> nearly dead space, strong penalty.
    if post_residual >= 1 && post_residual <= 9 {
        score += 18.0 - (post_residual as f64) * 1.5; // worst at 1..2
    }
    // Class B: post_residual in 10..=19 -> only fits tiny items; moderate penalty.
    else if post_residual <= 19 {
        score += 6.0;
    }
    // Class C: post_residual in 20..=29 -> awkward middle zone.
    else if post_residual <= 29 {
        score += 2.0;
    }
    // Class D: post_residual == 0 -> perfect fill, big reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic class of item size via modulo: sizes that divide capacity cleanly are friendly.
    let residue_class = (bin_capacity % item_size.max(1)) as f64;
    score += residue_class * 0.05;

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 9.0 {
            score -= 12.0 - slack; // near-perfect two-item chain
        } else if slack <= 19.0 {
            score -= 3.0;
        }
    }
    // If next item does NOT fit post_residual, this bin's leftover is likely wasted;
    // penalize proportionally to how much would be stranded.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Give it a neutral-ish score so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base score would be 100; re-anchor it to compete with mediocre fits.
        score = 22.0;
        // Opening a new bin is less attractive early (few bins) — reuse existing bins first.
        score += (open_bins_count as f64) * 0.4;
        // If many bins are open with large mean residual, opening new is fine.
        score -= mean_residual * 0.08;
        // Near the end of the stream, avoid spawning bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Mild preference to fill bins with larger residuals when many bins are open,
    // to consolidate load and allow closing bins.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit a future item
    // (items are 1..=100, but small gaps below a conservative threshold are
    // statistically unusable) are heavily penalized.
    let dead_threshold: u32 = 12;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 45.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fill is highly desirable.
        score -= 60.0;
    } else {
        // Smooth reward for tight fits (small but usable residuals).
        score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).max(0.0);
    }

    // Reward filling bins that are already fairly full (small residual before placement).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin;
    // if the next item cannot fit in the post-residual, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual == next_item_size {
                score -= 20.0; // chained perfect fit
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer compacting
    // into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean (it is
    // the emptiest-ish bin), slightly penalize; if above mean, favor it.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.10 * diff;

    // New-bin candidate handling: an empty bin gets a neutral baseline; it should win
    // only when all open bins would produce dead space.
    if bin_residual == bin_capacity {
        score = 30.0 + 0.35 * open_bins_count as f64;
        if post_residual < dead_threshold && post_residual > 0 {
            score += 45.0 * (dead_threshold - post_residual) as f64;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * (item_size as f64);

    // 2-step lookahead: perfect chain match (post_residual == next_item_size)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // ideal: bin closes exactly after next item
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits here too; reward small leftover after the chain
        let chain_left = post_residual - next_item_size;
        score -= 25.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to lookahead: penalize proportionally
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 30.0 + 10.0 * (1.0 - progress) * poor_fit;
        if fitting_bins_count == 0 {
            score -= 45.0; // no alternative: new bin is fine
        }
    }

    // Mild pressure toward consolidating into fewer bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on large leftover space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
        // Chain bonus: leftover after hypothetically placing next item too.
        let chain_left = post_residual - next_item_size;
        score -= 8.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leftovers too small for the next item (dead space risk),
        // scaled by how close to death the space is.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state coupling: many open bins with slack -> prefer consolidation.
    let slack = mean_residual - bin_residual as f64;
    score += 0.08 * slack.max(0.0);

    // Time horizon: late in the stream, be more conservative (avoid stranding space).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0;
        // But if the item barely fits in any existing bin (large item, few fitting bins),
        // opening a new bin is more attractive.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 50.0 * fill_ratio * fill_ratio;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // keep room for the (bigger) next item elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fit reward via smooth polynomial in post_residual.
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = 60.0 * x * x - 40.0 * x;

    // Smooth coupling: tighter fits matter more as stream progresses.
    score *= 1.0 + 0.8 * progress;

    // Penalize residual that cannot fit a plausible future item (smooth non-linear).
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward residual that exactly accommodates lookahead (smooth kernel).
        let fit_quality = 1.0 - ((pr - next) / cap).abs();
        if fit_quality > 0.0 {
            score -= 12.0 * fit_quality * fit_quality;
        }
    }

    // Penalize waste relative to bin's current residual (relative fill quality).
    let fill = item / res.max(1.0);
    score -= 20.0 * fill * fill;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Mild dispersion penalty when many bins fit (prefer spreading).
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin gets neutral-ish base plus
    // penalty that shrinks if open bins are too full to be attractive.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // Penalize opening a new bin, more so early in the stream,
        // and when existing bins have healthy residuals.
        let mean_r = mean_residual / cap;
        score = 45.0 + 25.0 * (1.0 - progress) + 15.0 * mean_r * mean_r;
        if next > 0.0 && next <= pr {
            score -= 10.0; // new bin fits lookahead perfectly too
        }
    } else {
        // Slight preference for bins whose residual deviates from mean
        // (consolidate similar residual classes smoothly).
        let dev = ((res - mean_residual) / cap).abs();
        score += 5.0 * dev * dev;
    }

    // Small smooth tie-breaker by stream progress to stabilize selection.
    score += 0.5 * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (hard to fill later) are penalized.
    let r = post_residual;
    let class = r / 10; // integer division thresholds: 0..=10
    score += match class {
        0 => -30.0,                      // near-perfect fit, strongly reward
        1 => -12.0,
        2 => -4.0,
        3 => 2.0,
        4 => 6.0,
        5 => 10.0,
        _ => 14.0,
    };

    // Modulo-4 harmonic coupling: residues congruent to 0 mod 4 pair well
    // with typical item sizes; reward them, odd residues penalized slightly.
    let m = post_residual % 4;
    score += match m { 0 => -6.0, 1 => 4.0, 2 => 0.0, _ => 3.0 };

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            score -= 15.0 * (1.0 - nxt_res as f64 / cap);
        } else {
            // next item won't fit here: leftover is likely dead space
            score += 8.0 + 0.25 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            -100.0 // no alternative, must open
        } else {
            // opening a fresh bin wastes mean residual of open bins
            let waste = mean_residual * open_bins_count as f64;
            30.0 + waste * 0.05 + (item_size as f64 / cap) * 20.0
        };
        score += pressure;
        // late in the stream, consolidation is preferred over new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for tighter bins overall (best-fit bias).
    score -= (1.0 - bin_residual as f64 / cap) * 10.0;

    // Tie-break by mean residual alignment: bins close to mean residual
    // keep balance of usable space across bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space avoidance: small unusable gaps are heavily penalized
        let gap = post_residual as f64;
        if gap <= 10.0 {
            // unusable for any item (min size 1..100 stream; treat <10 as risky dead space)
            score += 60.0 * (11.0 - gap);
        } else if gap < item_size as f64 {
            // gap smaller than current item: mildly wasteful
            score += 8.0;
        }
        // Reward gaps that can still hold a typical future item
        if gap >= 40.0 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 40.0; // blocks the next item in this bin
        }
    }

    // Last chance: only bin that fits -> strong preference to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from existing bins
        score += 120.0 + 15.0 * open_bins_count as f64;
        // but if mean residual is small (open bins nearly full), new bin is fine
        score -= (mean_residual / 10.0).min(80.0);
    } else {
        // slight reward for filling existing bins as stream progresses
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
        // prefer tighter (fuller) bins among open ones
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect fit for the NEXT item is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match for next item: massive reward.
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize dead space that the next item cannot use.
        score += 0.6 * diff;
        // If next item fits exactly in residual, current item is a good blocker.
        if post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Reward bins tighter than the mean residual (good packing), penalize loose ones.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize creating tiny unusable dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Mild phase bias: later in the stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress;

    // New-bin candidate: keep it slightly unattractive unless it truly wins
    // (empty bin residual == capacity); discourage opening bins casually.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 0.35 * tightness * (bin_residual as f64 - post_residual as f64).max(0.0);

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a residual that is nearly-but-not usable.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should usually lose unless open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // Late in the stream, opening new bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    } else {
        // Prefer fuller bins among open bins (best-fit bias beyond post_residual).
        let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 8.0 * fill_ratio;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in the stream, keep bins balanced; late, pack tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 - progress) + pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (non-linear)
    let dead = (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 15.0 * dead * dead;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item fits worse after placement
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 12.0 * fits_next * (1.0 - pr) * (0.5 + progress);
    }

    // New-bin candidate: mild penalty early, discount late when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 6.0 * progress;
    }

    // Crowding factor among open bins
    score += 2.0 * (open_bins_count as f64).ln() * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space buckets (capacity / 4).
    let dead_class = post_residual / (bin_capacity / 4);
    score += 8.0 * dead_class as f64;

    // Reward tight fits (small post residual) strongly, with a non-linear boost.
    if post_residual <= bin_capacity / 10 {
        score -= 20.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item can fit into the post residual,
    // this placement is very desirable (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
    } else if next_item_size > 0 {
        // Post residual can't hold next item; penalize proportional to waste potential.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual <= bin_capacity / 5 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin has post_residual == bin_capacity - item_size.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when open bins fit poorly.
        score += 14.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the current item leaves a harmonic-friendly residue and next item is large,
        // a fresh bin can be attractive: reward when next item is big.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Mean residual pressure: when open bins are already loose, discourage
    // leaving more loose space; when tight, allow spreading.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Small penalty scaling with number of open bins to discourage bin proliferation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for tiny unusable gaps (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward using bins that would otherwise be "last chance" (avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening a new one.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near typical residual, plus pressure.
        score = mean_residual.max(0.0) + 5.0 + open_bins_count as f64 * 2.0;
        // If the next item is large and nothing fits it well, opening a fresh bin helps.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0;
        }
    } else {
        // Prefer bins whose post-residual can still host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 6.0;
        }
        // Mild preference for fuller bins (small residual) when many bins open.
        score += open_bins_count as f64 * 0.3;
    }

    // Late-stream tightening: prioritize compact packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly favor bins whose post-residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Chain-friendly: residual can still host the next item.
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally to how small the leftover is.
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
    }

    // Compare post-residual against mean residual: keep bins near the pack's average fill.
    let mean_post = mean_residual - item_size as f64;
    score += 0.8 * (post_residual as f64 - mean_post).abs();

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize leaving tiny unusable slivers (< 10, or below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // New-bin candidate baseline: only attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
        if fitting_bins_count <= 1 {
            score -= 200.0; // opening a new bin is fine when alternatives are bad
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Strong reward for near-perfect fills.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize dead space that cannot serve a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size as f64 {
            // Dead space relative to the lookahead item.
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
        } else {
            // Reward bins that can also host the next item.
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Early in the stream: favor consolidating into few bins; late: be flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.3;

    // Penalize bins whose residual deviates far from the mean (keep bin pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // New-bin candidate logic: only attractive when item is large and would leave
    // open bins with useful residuals anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 55.0;
        // Large items justify fresh bins (less likely to waste small residual space).
        new_bin_score -= (item_size as f64 - 50.0).max(0.0) * 0.6;
        // If the item fits poorly everywhere else (few fitting bins), new bin is fine.
        if fitting_bins_count <= 1 {
            new_bin_score -= 20.0;
        }
        // Lookahead: if next item is large too, a fresh bin helps.
        if next_item_size >= item_size && next_item_size > 0 {
            new_bin_score -= 8.0;
        }
        // Late in stream, opening bins is less costly (no future to amortize? actually
        // total bins is what counts, so keep a mild progress penalty).
        new_bin_score += progress * 5.0;
        score = score.max(new_bin_score) + (new_bin_score - score).abs() * 0.0 + 0.0;
        // Blend: choose new bin only when clearly better.
        score = if new_bin_score < score { new_bin_score } else { score };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, quadratically (dead space is doubly bad).
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, keep bins roomy; late, squeeze residual harder.
    let late = progress * progress;
    score += 6.0 * late * (pr / cap) * (1.0 - pr / cap);

    // Reward filling bins tightly: item_size relative magnitude.
    let fill = item_size as f64 / cap;
    score -= 4.0 * fill * fill;

    // Prefer bins whose residual is close to the item (smooth fit term).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 2.5 * fit_gap * fit_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Slight preference for bins with below-average residual (consolidate space).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 5.0 * (1.0 - gap * gap);
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // existing residuals are large (smooth coupling with mean_residual).
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 3.0 - 30.0 * avg * (1.0 - avg);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (divisible by small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Dead-space penalty for very small unusable leftovers.
        if pr < 5 {
            score += 25.0;
        } else if pr < 10 {
            score += 12.0;
        }
    }

    // Lookahead: if the next item fits into the resulting residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0;
        // Extra reward when the chain leaves another harmonically clean residual.
        if (pr - next_item_size) % 5 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && pr > 0 && next_item_size > pr {
        // Next item cannot use the leftover: mild dead-space penalty.
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of existing bins; penalize
        // proportionally to how much residual already exists across bins.
        score += (mean_residual * open_bins_count as f64).max(0.0) * 0.3;
        // Large items fill a fresh bin well: small post_residual is good.
        // Small items into a new bin leave huge waste: extra penalty.
        if pr > 60 {
            score += 20.0;
        } else if pr > 40 {
            score += 8.0;
        }
        // If no open bin can fit the item at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: reward tight fits (item consumes most of residual).
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 20.0;
        // Perfect fit class.
        if pr == 0 {
            score -= 40.0;
        }
    }

    // Late in the stream, consolidation matters more: tighten scoring.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Medium gaps that only the smallest items could use: moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; residual becomes dead space.
            score += 12.0 * (post_residual as f64 / 100.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good existing option.
        let base = 55.0 + 3.0 * open_bins_count as f64;
        // If next item is large and this item is small, saving space is good.
        let keep_bonus = if next_item_size > 50 && item_size < 30 { 20.0 } else { 0.0 };
        score = base - keep_bonus;
    } else {
        // Mild pressure to consolidate into fewer bins.
        score += 0.5 * open_bins_count as f64;
        // Prefer tighter (already partially filled) bins slightly.
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Compare against mean residual: filling below-average-residual bins
    // (the fullest bins) is preferred.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual) — dead space is the enemy.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post residual can host the next item,
    // penalize residuals that leave a sliver the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainability reward, stronger when the fit is snug for the next item.
            let next_slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_slack / (bin_capacity as f64));
        } else {
            // Post residual becomes dead space relative to lookahead item.
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // Compare against mean residual: bins below-mean residual are already tight;
    // packing into them preserves big residuals elsewhere.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 2.0 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let is_last_chance_elsewhere = fitting_bins_count == 0;
        let poor_open_fits = fitting_bins_count as f64;
        // Default penalty for opening a new bin.
        score += 55.0;
        // But if nothing fits anywhere, opening is fine (penalty removed).
        if is_last_chance_elsewhere {
            score -= 55.0;
        } else if poor_open_fits == 1.0 {
            // A single fitting bin exists; opening a new bin should lose to it.
            score += 10.0;
        }
    }

    // Mild stream-progress term: later in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a quadratic bonus.
    score -= 2.5 * (1.0 - (post_residual as f64 / cap)).powi(3) * (post_residual as f64);

    // Penalize dead space: residual too small for the smallest plausible item.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 4.0;
    }

    // Lookahead: reward if post_residual exactly fits next item; penalize if next item
    // can no longer fit in this bin while it could have fit before placement.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= dead {
            // next item fits here: strong bonus, especially exact match
            score -= 12.0 + 8.0 * (1.0 - (dead - ni) / cap);
        } else {
            // next item won't fit here: mild penalty scaled by how badly it misses
            score += 3.0 * (ni - dead).min(cap) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins over emptier ones among many candidates.
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 6.0 * fill;

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate scoring.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / cap;
        // Penalize opening new bin when existing residuals are large (waste potential).
        score += 18.0 + 25.0 * pressure + 10.0 * (1.0 - progress);
        // Slightly cheaper to open a new bin early when few bins exist.
        score -= (open_bins_count as f64).min(10.0);
    } else {
        // Mild penalty for bins far from mean residual (outliers) to keep spread tight.
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 2.0 * dev;
    }

    // Time horizon: later in the stream, waste matters more -> tighten thresholds.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.35 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tighten the preference for tight fits
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress) * (1.0 - norm_pr);
    score += progress_coupling;

    // Smooth interaction with mean residual: penalize bins far from the mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (pr + 1.0);

    // Last-chance bonus: if this is the only fitting bin, reward strongly
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.15 * gap * gap / cap;
        // Perfect lookahead fit reward (smooth)
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        score -= 10.0 * fit_quality * fit_quality;
    }

    // Mild penalty for too many open bins, smooth in progress
    score += (open_bins_count as f64).ln() * (1.0 + progress);

    // New-bin candidate handling: empty bin gets a moderate default score,
    // slightly discouraged early, more acceptable when tight fits are rare
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 10.0 * (1.0 - progress) - 5.0 * (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "unusable" classes (small slivers) are rewarded for absorbing waste now.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: leftover that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // sliver creation is bad, but unavoidable sometimes
    }

    // Perfect fit reward via integer division classes.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= quarter {
        // post residual in (0, 25]: moderately usable, mild reward for tightness
        score -= 20.0 * (1.0 - pr / (quarter as f64));
    } else if post_residual <= half {
        score -= 10.0 * (1.0 - (pr - quarter as f64) / (quarter as f64));
    } else {
        // large residual: fine, bin stays flexible
        score += 5.0;
    }

    // Modulo/harmonic coupling: does the leftover pair well with the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to how well it nests
            let waste_after_next = post_residual - next_item_size;
            score -= 15.0 * (waste_after_next as f64 / c);
            if waste_after_next == 0 {
                score -= 20.0; // chain of perfect fits
            }
        } else {
            // next item cannot use this leftover: penalize leftovers in
            // "awkward" classes relative to next item size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(30.0);
        }
        // harmonic class check: leftover divisible-ish by next item
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or open bins are all tight.
    if bin_residual == bin_capacity {
        // baseline: a fresh bin scores its residual after placement
        score = pr + 30.0; // inherent cost of opening a new bin
        let load_ratio = item_size as f64 / c;
        if load_ratio > 0.5 {
            score -= 25.0 * (load_ratio - 0.5); // big items deserve fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        } else if fitting_bins_count == 1 {
            score += 20.0; // an existing bin is a last chance; discourage new bin
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Progress-based mild consolidation pressure early, flexibility late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * mean_residual / c * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward using a bin whose residual tightly matches the item (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: with many open bins, discourage spreading; with few, fine.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (0.5 + progress);

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item would leave an even worse gap, penalize slightly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_gap = post_residual - next_item_size;
        if nxt_gap > 0 && nxt_gap < 10 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (compact bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; make it unattractive unless it's a fresh stream
        // or all fits would create dead space.
        score += 40.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled against mean residual.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff * diff);
        // Slight preference for post_residual >= next_item_size (usable next step).
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Dead space for next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists; penalize opening bins early in the stream.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 25.0 * fill_ratio;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 8.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little waste,
    // but only when the leftover is unusable for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to lookahead: penalize proportionally.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += waste * 25.0;
        } else {
            // Leftover can host the next item: reward usable fit tightness.
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= snug * 12.0;
        }
    } else {
        // End of stream: pure tightness matters most.
        score -= (bin_capacity - post_residual) as f64 * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin is a good host,
    // i.e., when the item is large relative to typical residuals and early/mid stream.
    if bin_residual == bin_capacity {
        let tightness_elsewhere = (mean_residual - item_size as f64).abs();
        let pressure = 1.0 - (tightness_elsewhere / bin_capacity as f64).min(1.0);
        // Reward opening a fresh bin when open bins are poorly matched.
        score -= pressure * 20.0;
        // Late in the stream, prefer filling existing bins; penalize new bins.
        score += t * 18.0;
        // Many open bins: slight penalty to avoid bin proliferation.
        score += open_bins_count as f64 * 0.35;
    } else {
        // Favor bins whose residual is close to the item (best-fit coupling).
        let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += gap * 8.0;
        // Prefer bins below mean residual (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild global pressure: when few bins fit the item anywhere, tighten selection.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_c = progress.clamp(0.0, 1.0);

    // Normalized residual quantities
    let cap = bin_capacity as f64;
    let post_n = post_residual as f64 / cap;
    let fit_n = item_size as f64 / cap;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses.
    // Tightness = fraction of bin consumed by this item.
    let tightness = fit_n * fit_n; // quadratic emphasis on large items
    score -= 18.0 * tightness * (0.35 + 0.65 * progress_c);

    // Non-linear penalty on dead space: small post_residuals that are still unusable
    // are penalized super-linearly, but only relative to typical item scale.
    let dead = post_n * (1.0 - post_n); // peaks at post_n = 0.5 (worst half-empty waste)
    score += 10.0 * dead * (1.0 - 0.5 * progress_c);

    // Reward leaving residual that exactly matches the lookahead item (k=2 lookahead)
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - gap * gap) * (0.3 + 0.7 * progress_c);
    } else if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
        // Lookahead cannot fit here; mildly penalize blocking it with a smooth term
        let block = (next_item_size as f64 - post_residual as f64) / cap;
        score += 4.0 * block * block;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress_c);
    }

    // New-bin candidate handling: brand-new empty bin (bin_residual == bin_capacity).
    // Prefer existing bins by default; open a new bin only when the item is small
    // relative to residual spread of open bins (smooth coupling, no piecewise cutoff).
    if bin_residual == bin_capacity {
        let spread = (mean_residual / cap).clamp(0.0, 1.0);
        // Opening a new bin is more attractive when existing residuals are fragmented
        // (high mean residual spread) and early in the stream; penalize otherwise.
        score += 12.0 * (1.0 - spread) * (1.0 - 0.4 * progress_c);
        score += 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.5;
        // Small items keep new bins attractive (they pair with future items)
        score -= 5.0 * (1.0 - fit_n) * (1.0 - progress_c);
    } else {
        // Mild preference for filling fuller bins first (best-fit flavor, smoothed)
        let fullness = 1.0 - (bin_residual as f64 / cap);
        score -= 4.0 * fullness * fullness;
    }

    // Small regularization tie-breaker on post_residual (smooth, non-linear)
    score += 0.01 * (post_residual as f64) * (post_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score: f64;

    if is_new_bin {
        // Brand-new bin candidate: base cost of opening a bin.
        score = cap * 2.0;
        // Harmonic size classes: large items leave small post-residual, cheap to open for them.
        if item_size >= 70 {
            score -= 220.0;
        } else if item_size >= 50 {
            score -= 140.0;
        } else if item_size >= 30 {
            score -= 40.0;
        }
        // If no existing bin can fit the item, opening is mandatory.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // If the next item is huge, a fresh bin is valuable lookahead-wise.
        if next_item_size >= 60 {
            score -= 30.0;
        }
    } else {
        score = post;
        // Dead-space handling: residual below the smallest item is perfect filling.
        if post_residual < 10 {
            score -= 250.0;
        } else if post_residual < 20 {
            score -= 60.0;
        }
        // Harmonic classes on post_residual mod 25: prefer residuals near reusable classes.
        let m = post_residual % 25;
        score -= match m {
            0 => 18.0,
            5 => 10.0,
            10 => 6.0,
            15 => 3.0,
            20 => 1.0,
            _ => 0.0,
        };
        // Last-chance bin: strongly prefer using it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 160.0;
        }
        // Lookahead: reward if the next item fits into the post-residual.
        if next_item_size > 0 {
            if (next_item_size as u32) <= post_residual {
                score -= 30.0;
            } else {
                score += 12.0 * (post / cap);
            }
        }
        // Tightness reward: item filling most of the bin's residual is a good fit.
        let tight = item / (bin_residual as f64).max(1.0);
        score -= tight * 25.0;
        // Late in the stream, consolidate into bins with larger mean residual.
        if progress > 0.7 {
            score -= mean_residual * 0.12;
        }
        // Penalize leaving residual just above awkward small sizes.
        if post_residual > 80 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are dead weight; penalize them quadratically.
    if post_residual > 0 && post_residual < item_size {
        let dead = (item_size - post_residual) as f64;
        score += dead * dead * 0.5;
    }
    // Gaps below the absolute minimum item size are pure loss.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 25.0;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score += pressure * 2.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item would leave this bin's residual unusable anyway, mild reward.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: baseline attractiveness so we only open a new bin
    // when existing bins have poor fits. Scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 25.0 * progress + mean_residual * 0.15;
        // If this bin is the last chance, opening new is worse.
        if fitting_bins_count == 1 {
            score += 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still hold next item (good lookahead fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Post residual too small for next item: dead space penalty
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post residual against mean residual: prefer tightening loose bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in the stream, avoid proliferating bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 20.0;
        }
    }

    // Slight preference for filling large items into tight bins
    score += 0.3 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness preference: small post-residual wins
    score += post_residual as f64 * 0.02;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large enough to justify it (high utilization) or nothing else fits well
    if bin_residual == bin_capacity {
        let util = item_size as f64 / bin_capacity as f64;
        // Large items (>~60% of capacity) are natural bin starters
        score += 45.0 - 60.0 * util;
        // If the next item would fit in the leftover of the fresh bin, reward
        if next_item_size > 0 {
            if (post_residual as u32) >= next_item_size {
                score -= 20.0;
            } else {
                // leftover dead space for the known next item
                score += 12.0;
            }
        }
    }

    // Lookahead coupling: reward bins whose leftover can host the next item
    if next_item_size > 0 && bin_residual != bin_capacity {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // leftover too small for next item: penalize proportionally
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Penalize creating tiny unusable slivers (below minimum item size 1..100 range floor)
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Time horizon: as the stream progresses, prefer consolidating into existing bins
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if this bin's leftover is below the mean residual,
    // it is a "scarce" gap worth using; if above, mildly deprioritize
    score += (mean_residual - post_residual as f64) * 0.08;

    // Many open bins: discourage spreading; few open bins: allow more freedom
    if open_bins_count > 8 {
        score += 4.0;
    } else if open_bins_count < 3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - post / cap; // fraction of bin used after placement

    // Base: prefer small post-residual, with non-linear polynomial emphasis
    let mut score = post * post / cap;

    // Reward high utilization, amplified as the stream progresses
    score -= tightness * tightness * (20.0 + 60.0 * progress);

    // Extra polynomial coupling: squared utilization vs progress
    score -= (tightness * progress).powi(2) * 30.0;

    // Penalize post-residuals that are dead space relative to mean residual
    score += (post - mean_residual).abs() * 0.3;

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into the resulting post-residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0 + 5.0 * (1.0 - post / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving a residual too small for the lookahead item
        score += (next_item_size as f64 - post) * 0.5;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // existing bins fit poorly (large post-residual everywhere)
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { post.min(100.0) / cap } else { 1.0 };
        score = 0.5 * cap + 0.4 * post - 20.0 * pressure - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual ---
    // Class residuals into buckets of 10 (capacity fractions): 0 = perfect fit.
    let class = post_residual / 10;
    let phase = post_residual % 10;

    // Perfect and near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if phase == 0 {
        score -= 18.0;
    } else {
        // Within-class penalty: dead space inside a class is bad.
        score += phase as f64 * 0.8;
    }

    // Harmonic penalty: residual classes 1..3 (tiny unusable slivers 10..30)
    // are dangerous unless a small item may still land there.
    if class >= 1 && class <= 3 {
        if next_item_size as f64 <= post_residual as f64 {
            // Lookahead item fits exactly into the sliver: reward keeping it.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 12.0 - slack * 0.5;
        } else {
            // Sliver becomes dead space.
            score += 10.0 + (4 - class) as f64 * 4.0;
        }
    }

    // Lookahead coupling: if the next item fits, this bin becomes more valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use leftover: mild penalty scaled by leftover size.
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; discourage unless item is large
        // and no tight fit exists elsewhere.
        let pressure = item_size as f64 / bin_capacity as f64;
        score += 45.0 - pressure * 30.0;
        if item_size >= 60 {
            score -= 20.0; // large items: fresh bin is fine
        }
        if item_size <= 20 {
            score += 15.0; // tiny items should go into existing space
        }
    }

    // Mean-residual coupling: when open bins are already loose, prefer
    // filling them rather than spreading; when tight, new bins are ok.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - post_residual as f64) * 0.05;

    // Late-stream consolidation: as the stream ends, waste less.
    score -= progress * 5.0;

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are worthless.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }
    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward residuals that can still hold future items, scaled by lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual >= next_item_size * 2 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the known next item.
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: neutral baseline, only attractive when fits are bad.
    if bin_residual == bin_capacity {
        score = 25.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 1 {
            score += 50.0; // never open new bin when a last-chance fit exists
        }
        if post_residual == 0 {
            score += 100.0;
        }
    }

    // Slight preference for tighter existing fits.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear urgency
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Aggressive 2-step lookahead: reward when post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> strong bonus
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here later: mild reward scaled by closeness
            score -= (20.0 - gap.min(20.0)) * 0.8;
        } else {
            // Dead space relative to next item: penalize proportionally
            score += gap * 0.6;
        }
    }

    // Compare against mean residual: bins below mean residual are "tighter",
    // filling them first preserves loose capacity elsewhere
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.35;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when fits are poor (large dead space)
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // = capacity - item_size for new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin can host current + next item comfortably
            score -= 18.0;
        }
        // Penalize opening new bin when it would strand lots of space
        score += waste * 0.9;
        // More open bins already -> prefer packing into existing ones
        score += open_bins_count as f64 * 2.0;
    }

    // Late in stream: consolidate harder, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.20;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize leftover space, with non-linear (quadratic) growth.
    let mut score = post + 40.0 * norm_post * norm_post * cap;

    // Reward tight fits: coupling of post_residual with item size.
    let item_f = item_size as f64;
    let tightness = 1.0 - (item_f / cap);
    score -= 25.0 * (1.0 - norm_post).powi(2) * (1.0 - tightness);

    // Stream-progress coupling: later in the stream, waste is costlier.
    score += 30.0 * progress * norm_post * norm_post;

    // Penalize bins whose residual diverges from the mean (keeps pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_post);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 20.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 / cap);
    }

    // New-bin candidate: empty bin should only win when fit is poor everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress.
        score = cap * (1.2 - 0.4 * progress);
        if fitting_bins_count == 1 {
            // Opening a new bin when an existing bin is a last chance is bad.
            score += 80.0;
        }
        // Prefer opening a new bin for large items that leave big post-residuals.
        score -= 15.0 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are multiples of common
    // item sizes (gcd-style classes) are far more reusable than odd dead space.
    let cap = bin_capacity as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residual below the minimum item size is unusable.
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic class bonus: post_residual divisible by small harmonics (5,10,20,25)
        // is more likely to be filled by future items.
        let r = post_residual;
        if r % 5 == 0 { score -= 12.0; }
        if r % 10 == 0 { score -= 10.0; }
        if r % 20 == 0 { score -= 6.0; }
        if r % 25 == 0 { score -= 5.0; }
        // Odd / prime-ish residuals are dead space.
        if r % 2 == 1 && r % 5 != 0 { score += 8.0; }

        // Lookahead: if the next item fits exactly into the resulting residual,
        // strongly favor this bin (chained fit).
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 80.0;
            } else if post_residual >= next_item_size {
                let next_post = post_residual - next_item_size;
                if next_post % 10 == 0 { score -= 20.0; }
                if next_post < 10 && next_post > 0 { score += 25.0; }
            } else {
                // Next item cannot follow in this bin: mild penalty scaled by
                // how much residual would be stranded.
                if post_residual < next_item_size {
                    score += (next_item_size - post_residual) as f64 * 0.15;
                }
            }
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling fuller bins: couple with mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer open bins when they give a decent fit; the empty-bin call gets
    // penalized progressively as the stream progresses (consolidation phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 40.0 * progress;
        // Opening new bins is more acceptable when many bins are open relative
        // to nothing (spread load early), less so late.
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual is in the same harmonic
    // "decade class" as the item (item_size / 10 bucket match).
    let item_class = item_size / 10;
    let res_class = bin_residual / 10;
    if item_class == res_class {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the smallest item threshold are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // New-bin candidate handling: opening a new bin is expensive unless current bin
    // would leave terrible dead space or the next item fits better in a fresh bin.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If next item is large and this bin would be nearly emptied, a fresh bin is fine.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
        if post_residual < 10 {
            score -= 45.0; // current bin would become dead space anyway -> new bin
        }
    }

    // Lookahead: if the next item would fit exactly in the post_residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 10.0; // dead space that next item cannot use
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), classic best-fit.

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect match: next item exactly consumes remaining space.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here; mild reward proportional to tightness.
            score -= 20.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += 0.35 * (post_residual as f64 - nxt).abs();
        }
    }

    // Coupling with mean residual: prefer bins that reduce dispersion of residuals.
    let post_f = post_residual as f64;
    score += 0.25 * (post_f - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make an empty bin mildly attractive only when
    // no open bin fits well (post_residual small is already favored), but penalize
    // opening bins when the item fits an existing bin decently.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count > 0 && post_residual < bin_capacity / 2 {
            // An open bin would leave less than half wasted; discourage new bin.
            score += 25.0;
        }
        // Late in the stream, avoid opening new bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), with a non-linear squash
    // so going from residual 5 -> 0 matters far more than 60 -> 55.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize placing small items into bins with large residuals (wasted capacity),
    // but only when other bins could also take the item.
    if fitting_bins_count > 1 {
        let waste = (post_residual as f64) - (next_item_size as f64).min(post_residual as f64);
        if waste > 0.0 {
            score += 0.15 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 1.2 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual becomes dead space w.r.t. the next item: penalize.
            score += 0.25 * post_residual as f64;
        }
    } else {
        // Last item in stream: purely minimize post_residual (already the base).
        score -= 3.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= 0.05 * mean_residual * progress;
    }

    // New-bin candidate handling: an empty bin gets a neutral-to-slightly-high score,
    // so it only wins when existing placements are genuinely bad (large post_residual
    // or dead-space penalties accumulate above this threshold).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.65 - 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Core: quadratic penalty on leftover space (waste), slightly amplified as stream progresses
    let mut score = x * x * (1.0 + 1.5 * progress) * cap;

    // Cubic coupling: harshly punish tiny-but-nonzero leftovers (dead space)
    score += 0.8 * x * (1.0 - x) * (1.0 - x) * cap;

    // Lookahead: reward post_residual that can still hold the next item
    if next_item_size > 0 {
