        } else {
            // leftover too small for next item: penalize proportionally to how close it was
            score += 0.4 * (1.0 - post / nxt.max(1.0)) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count <= 1 && bin_residual < cap {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when decent alternatives exist,
    // but relax penalty late in stream or when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = mean_residual / cap;
        let mut penalty = 12.0 * (1.0 - crowd);
        penalty *= 1.0 - 0.5 * progress;
        if next_item_size > 0 && next_item_size as f64 > post {
            penalty -= 3.0; // fresh bin fits next item well
        }
        score += penalty.max(0.0);
    } else {
        // mild preference toward fuller bins (best-fit flavor)
        score -= 0.3 * (1.0 - x);
    }

    // Tie-break: prefer bins with residual close to item (tight fits)
    score += 0.2 * ((resid - item_size as f64) / cap - x).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // residue classes modulo 10 (small dead space is often reusable).
    let post = post_residual as u32;
    let class = post % 10;
    let quot = post / 10;

    // Perfect-fit reward: post_residual in {0} is ideal.
    if post == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space quadratically, but with harmonic-class modulation:
        // residues {0, 5} are "harmonic" (friendly to common item sizes), others worse.
        let harmonic_bonus: f64 = match class {
            0 => 6.0,
            5 => 4.0,
            2 | 4 | 6 | 8 => 1.0,
            _ => -2.0,
        };
        score += (post as f64) * (post as f64) * 0.02 - harmonic_bonus;
        // Extra penalty for tiny unusable slivers (1..=3) unless next item is tiny.
        if post <= 3 && next_item_size > post {
            score += 12.0;
        }
        // Reward post-residuals that can still hold the next item (lookahead fit).
        if next_item_size > 0 && next_item_size <= post {
            score -= 8.0;
            // Extra reward if next item fills it near-perfectly.
            let nxt_gap = post - next_item_size;
            if nxt_gap <= 5 {
                score -= 6.0;
            }
        } else if next_item_size > 0 {
            // Next item cannot use this bin's leftover; mildly penalize.
            score += 3.0;
        }
        // Coarse class reward: quot tiers (0..=9 dead space units).
        score -= (quot as f64) * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // (avoid opening a new bin) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post <= 10 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins, but the penalty shrinks if the item is large relative
    // to capacity (poor fits elsewhere) or if no open bin fits well.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score = cap * 0.55 + frac * 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: opening a new bin is rarely better unless
            // the item is huge and the existing bin would be nearly emptied anyway.
            if frac < 0.35 {
                score += 25.0;
            }
        }
        // Late in the stream, slightly discourage spawning extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    } else {
        // Reuse bonus scaled by how "full" the bin becomes after placement.
        let fill = 1.0 - (post as f64) / cap;
        score -= fill * 10.0;
    }

    // Mild global pressure: many open bins with high mean residual -> consolidate.
    if bin_residual != bin_capacity {
        score += (mean_residual - post as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items are toxic.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 40.0;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement blocks the next item that could have fit the bin as-is.
        score += 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins implicitly
    // by penalizing high residuals less coherently; instead penalize score for bins
    // far from mean residual to keep consolidation.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large and no tight option exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened casually.
        score += 60.0;
        // Pressure from number of already open bins.
        score += open_bins_count as f64 * 5.0;
        // Large items are fine to start a fresh bin with.
        score -= (item_size as f64 / bin_capacity as f64) * 80.0;
        // If the next item also fits in a fresh bin alongside this one, new bin is good.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
    }

    // Late in the stream, consolidate harder (fewer bins matter more).
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual leaves room for next item: reward closeness of the gap.
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize small dead space more than large (usable) space.
        let waste = post_residual as f64;
        score += 30.0 * (1.0 - waste / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize bins with residuals far above mean (keep mean residual low for consolidation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // New-bin candidate: make it expensive unless current bin leaves very poor dead space
    // and next item is large (better to start fresh).
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual == bin_capacity
            && (post_residual as f64) > 0.0;
        let tiny_left = next_item_size > 0 && next_item_size >= bin_residual
            && bin_residual < bin_capacity;
        let _ = (bad_fit, tiny_left);
        // Base cost of a new bin; discounted late in the stream when consolidation matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 400.0 - 100.0 * progress;
        // If this bin would leave unusable sliver and next item is big, cheaper to open new bin.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.max(1) - item_size.max(1) {
            score -= 250.0;
        }
    }

    // Slight preference for tighter fits overall (small post residual), but not below usable sizes.
    if post_residual < 10 && post_residual > 0 {
        score -= 20.0; // near-perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving small unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item uses the leftover
            let nr = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * nr;
        } else {
            // next item won't fit here: post-residual is likely dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: pure tightness matters
        score -= 5.0 * fill_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        // if open bins have plenty of space, discourage new bin
        score += 30.0 * (1.0 - crowding);
        // early in the stream, prefer reusing; late, allow spreading
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with below-average residual (consolidate emptier bins usage).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post-residual, with non-linear shrink of large residuals
    let mut score = pr + 0.35 * (pr / cap).powi(2) * cap;

    // Tight-fit reward: smooth quadratic coupling of fill fraction with progress
    let fill = it / cap;
    score -= 22.0 * fill.powi(2) * (1.0 + progress);

    // Penalize residual that is hard to reuse: smooth trough around mid residuals
    let r = pr / cap;
    score += 14.0 * (std::f64::consts::PI * r).sin().abs() * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (nx / cap) * (0.5 + progress);
        }
    } else {
        // Last item: strongly prefer tightest possible fit
        score -= 25.0 * fill;
    }

    // Mild pressure to consolidate into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // New-bin candidate: penalize opening a new bin, less so when mean residual is high
    if bin_residual == bin_capacity {
        let mean_fill_gap = (mean_residual / cap).max(0.0);
        score += 20.0 - 12.0 * mean_fill_gap.min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "small residue" classes (1..=10) are nearly wasted -> heavy penalty.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        if pr <= 10 {
            score += 40.0 * (1.0 - pr as f64 / 10.0); // dead space of 1..10 is almost useless
        } else if class == 0 {
            score -= 6.0; // residue is a round multiple of 10: reusable by common sizes
        } else if class <= 3 {
            score += 8.0; // awkward small leftover
        } else {
            score -= 3.0; // decent reusable leftover (>= 14)
        }
    } else {
        score -= 25.0; // perfect fit
    }

    // Fractional capacity coupling: reward placements leaving residue that
    // matches common item-size harmonic slots (multiples of 20, 25, 50).
    let fits_slot = (pr % 20 == 0 && pr > 0) || (pr % 25 == 0 && pr > 0) || pr == 50;
    if fits_slot {
        score -= 10.0;
    }

    // Lookahead: if next item fits the post-residue, reward strongly.
    if next_item_size > 0 && (pr as u64) >= (next_item_size as u64) {
        let slack = pr as f64 - next_item_size as f64;
        score -= 12.0 - slack * 0.15; // tight lookahead fit preferred
    } else if next_item_size > 0 {
        score += 5.0; // next item won't reuse this residue
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or mean residual is low (nothing useful to pack into).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        score = 0.55 * cap + pressure * 8.0 - progress * 20.0;
        if next_item_size > 0 && (bin_capacity as u64) >= (item_size as u64 + next_item_size as u64) {
            score -= 15.0; // fresh bin can host this and the next item together
        }
    }

    // Mild global pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for typical future items (below 10)
    // or awkwardly small relative to the lookahead item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 25.0;
    } else {
        // Smooth penalty for small residuals (10..=25) that limit future packing.
        let r = post_residual as f64;
        if r <= 25.0 {
            score += 0.9 * (25.0 - r);
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward this bin; if next item nearly fits, mild reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let r = post_residual as f64;
        if n <= r {
            let slack = r - n;
            if slack == 0.0 {
                score -= 18.0;
            } else if slack <= 10.0 {
                score -= 6.0;
            } else {
                score += 0.15 * slack;
            }
        } else {
            // Next item won't fit here: slight penalty proportional to overshoot.
            score += 0.05 * (n - r);
        }
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new ones; penalize the new-bin candidate implicitly via
    // its typically large residual (handled naturally), but add pressure term.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // unless current fitting options are scarce (last-chance situations).
        if fitting_bins_count > 1 {
            score += 30.0 + 2.0 * open_pressure;
        } else if fitting_bins_count == 1 {
            // Only this bin fits; new bin is a genuine alternative — moderate cost.
            score += 8.0;
        }
    } else {
        // Reward using an existing bin, especially when few bins fit the item.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Prefer bins with tighter residuals (best-fit bias beyond raw post_residual).
        score += 0.05 * (bin_residual as f64 - post_residual as f64).recip().max(0.0);
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" — favor placing here to consolidate.
    let r = bin_residual as f64;
    if mean_residual > 0.0 && r < mean_residual {
        score -= 0.2 * (mean_residual - r);
    }

    // Stream progression: early in the stream, be slightly more liberal with
    // opening bins (future flexibility); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead match: next item exactly fills this bin afterwards.
        if diff == 0.0 {
            score -= 500.0;
        } else {
            // Penalize residual that is too small to ever hold the next item usefully,
            // and reward residuals slightly above the next item size.
            if (post_residual as u32) < next_item_size {
                score += 0.5 * diff;
            } else {
                score -= 0.3 * (30.0 - diff).max(0.0);
            }
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 150.0;
    }

    // Penalize creating tiny unusable dead space (residual below minimum item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate handling: an empty bin has high raw residual; make it
    // attractive only when existing fits are poor (large post_residual elsewhere)
    // or when many open bins already exist (avoid unbounded bin growth early).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so open bins with decent fits win.
        score += 120.0;
        // Early in the stream, opening bins is cheap; later, prefer filling.
        score -= 60.0 * (1.0 - progress);
        // If the current item is large relative to capacity, a fresh bin is safer.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Mild tie-breaking: prefer bins among few fitting candidates.
    score += 3.0 * fitting_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;  // moderately awkward leftover
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit, or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let mean_fit = item_size as f64 / mean_residual.max(1.0);
        let desperation = if mean_fit > 0.75 { 0.0 } else { 60.0 * (0.75 - mean_fit) };
        // Early in stream: keep bins consolidated; late: allow more spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 15.0 * progress - desperation;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 60 { score -= 10.0; }
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0; // residual too small for lookahead item
        }
    }

    // Prefer bins with below-mean residual (consolidating space usage).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Mild pressure to close out nearly-full bins.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight packing).
    let mut score = pr;

    // Non-linear reward for tight fits: quadratic coupling of fill ratio.
    let fill = it / cap;
    let tight_reward = 40.0 * fill * (1.0 - fill) * (1.0 - fill).max(0.0);
    score -= tight_reward * (1.0 + progress);

    // Reward using a bin that is the last chance to fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item fits well in the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let waste_after_next = pr - nxt;
            score -= 15.0 * (1.0 - waste_after_next / cap).max(0.0);
        } else {
            // Penalize leaving residual that no plausible item can use.
            let gap = pr - nxt;
            score += 0.15 * gap.max(0.0);
        }
    }

    // Penalize bins deviating from mean residual (keep residuals balanced),
    // with smooth coupling to stream progress.
    let dev = (pr - mean_residual).abs();
    score += 0.10 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, more so when other bins fit.
    if bin_residual == bin_capacity {
        let escape_bonus = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 30.0 + 10.0 * escape_bonus + 15.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets.
    // Small post_residual (<10) is dead space -> penalize extra.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual % 10 == 0 {
        // Perfect harmonic class: residual is a multiple of 10, highly reusable.
        score -= 6.0;
    } else if post_residual % 10 <= 3 {
        // Awkward sliver just above a harmonic boundary.
        score += 3.0 + (post_residual % 10) as f64;
    } else if post_residual % 10 >= 7 {
        // Close to next harmonic boundary: next small item can round it down.
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let waste_after_next = post_residual - next_item_size;
        score -= 8.0 + (waste_after_next as f64).sqrt() * 2.0;
        // Extra reward if post_residual - next_item_size lands on a harmonic class.
        if waste_after_next % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: this residual becomes dead weight.
        score += 5.0 + (post_residual as f64) * 0.05;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins that leave larger residuals among many candidates.
        score -= (post_residual as f64) * 0.02;
    }

    // New-bin candidate (pristine empty bin): only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // forced: no open bin fits
        } else if post_residual % 10 == 0 && post_residual >= 20 {
            // Opening fresh bin leaves a perfectly harmonic residual for big items.
            score -= 4.0;
        } else {
            score += 8.0; // discourage wasting a fresh bin on poor classes
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    // Deviation from mean residual: prefer bins below mean (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Strict dead-space avoidance ---
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Unusable small gap (1..=9): penalize proportionally to how close to a perfect fit it "wasted".
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }
    // Medium gaps (10..=20) are semi-usable; mild penalty to prefer tighter fits.
    if post_residual >= 10 && post_residual <= 20 {
        score += 3.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin remains useful for the next item: reward.
            score -= 6.0 + (next_item_size as f64) * 0.05;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Leftover gap can't serve the next item: penalize dead space harder.
            score += (next_item_size.min(10) as f64) * 0.8;
        }
    }

    // --- Last-chance pressure ---
    // If this is the only open bin that fits, strongly prefer using it over a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    }

    // --- Open-bin pressure ---
    // Mild reward for consolidating into already-open bins, scaled by how full they stay.
    if !is_new_bin {
        score -= 2.0;
        score += open_bins_count as f64 * 0.03 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Default: slightly worse than a decent existing fit so we reuse bins.
        score += 6.0;
        // But if the item is large relative to capacity, a fresh bin is attractive
        // (large items create big residuals elsewhere anyway).
        if item_size >= bin_capacity * 3 / 4 {
            score -= 8.0;
        }
        // Late in the stream, avoid spawning bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0;
    }

    // Tie-break: prefer bins whose residual is near the mean (keeps residual distribution balanced).
    score += (bin_residual as f64 - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score += 0.5 * (item_size as f64 / bin_capacity as f64);

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pair: fill bin completely after two items
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize leftover dead space
            score += 10.0 + 0.3 * post_residual as f64;
        }
    } else {
        // last item: reward complete fill
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Compare against mean residual: favor bins with below-average residual (tighter bins)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits poorly everywhere
    if bin_residual == bin_capacity {
        // empty bin: neutral-ish score; encourage it when item is large relative to typical residual
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = post_residual as f64 + 0.4 * item_size as f64
            - 10.0 * (item_size as f64 / bin_capacity as f64) * progress
            + if next_item_size > 0 && next_item_size > post_residual { 5.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer minimal post_residual.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: reward if the next item can fit into the post_residual (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving residuals that are too small for typical next items.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins that are much emptier than the mean residual (avoid fragmenting large spaces).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Penalize using nearly-full bins less (their residual is precious but small waste matters less).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when the fit into open bins is bad.
    if bin_residual == bin_capacity {
        // Base penalty so an open bin with reasonable fit is preferred.
        score += 14.0;
        // If no open bin can fit the item, the new bin is the only choice: remove penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early stream: opening bins is cheaper; late stream: discourage.
        score += 10.0 * (1.0 - progress);
    }

    // Mild penalty for very large dead space left behind.
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0; // near-perfect fill is excellent
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fit reward: strongly favor bins whose post_residual is small relative to capacity.
    let tight = 1.0 - (pr / cap);
    score -= 40.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: penalize if post_residual is small but nonzero and just below next item,
    // or reward if next item fits exactly into the remaining space.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let next_tight = 1.0 - (pr - ni) / cap;
            score -= 25.0 * next_tight * next_tight;
        } else {
            // dead space that next item cannot use
            score += 10.0 * (1.0 - pr / ni);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Late in the stream, prefer filling existing bins tighter rather than spreading.
    score += 15.0 * progress * (pr / cap);

    // New-bin candidate (empty bin): make it less attractive unless post_residual is genuinely
    // better than what open bins offer; scale by open bins count.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Mild pull toward mean residual to balance bin usage.
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "harmonically
    // friendly" to common item sizes (multiples of 5/10) are more reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        40.0 // perfect fill: strongly reward
    } else if pr % 10 == 0 && pr >= 10 {
        12.0 // round residual, easy to pair
    } else if pr % 5 == 0 {
        7.0
    } else if pr >= 10 && pr <= 30 {
        0.0 // small awkward gap
    } else {
        3.0
    };
    score -= class_bonus;

    // Dead space penalty: gaps too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or nearly; penalize if next item cannot use this bin's remainder.
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni == pr {
            score -= 25.0; // perfect chained fit
        } else if ni <= pr {
            let slack = (pr - ni) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            if slack < 10.0 { score -= 5.0; }
        } else {
            // next item won't fit here; if this bin is the only option now,
            // using it is last-chance and valuable.
            if fitting_bins_count == 1 {
                score -= 20.0;
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bonus: this is the only bin that can take the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity when
    // decent fits exist. Penalize unless the residual left behind is round
    // (harmonically reusable) or no open bin fits.
    if bin_residual == bin_capacity {
        let mut new_bin_score = (bin_capacity - item_size) as f64 + 10.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0; // forced: no alternative
        } else if (bin_capacity - item_size) % 10 == 0 {
            new_bin_score -= 8.0; // fresh bin leaves a round residual
        }
        // Late in the stream, avoid accumulating many near-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 6.0 * progress;
        // Many open bins with high mean residual => prefer reusing.
        if mean_residual > cap * 0.5 && open_bins_count > 2 {
            new_bin_score += 8.0;
        }
        score += new_bin_score;
    }

    // Mild tie-break: prefer filling bins with larger current residual
    // (best-fit flavor already via post_residual); add tiny mean coupling.
    score += 0.01 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is too small for the smallest plausible item (>= 1)
    // but especially if it is a tiny sliver (< 10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead sliver: extremely undesirable
    }

    // Penalize gaps that are large enough to be tempting but likely wasted
    // (between 1 and 15): quadratic dead-space pressure.
    if post_residual >= 1 && post_residual <= 15 {
        let g = post_residual as f64;
        score += (16.0 - g) * (16.0 - g) * 0.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post residual,
    // this placement is excellent; if it cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += 8.0; // next item won't fit here; residual may become dead space
        } else {
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score += 6.0; // would create a dead sliver after next item
            } else {
                score -= 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits the item
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are
    // very fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of a new bin
        // If current bins are fragmented (low mean residual relative to capacity),
        // opening a fresh bin becomes more acceptable.
        let frag = mean_residual / bin_capacity as f64;
        if frag < 0.25 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Open-bins pressure: with many open bins, favor filling existing ones
    // (higher residual utilization) over spreading items.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to what is needed (tight fit ranking).
    let waste = (bin_residual - item_size) as f64;
    score += 0.3 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: heavily favor bins where item nearly fills the bin.
    let tightness = 1.0 - post / cap; // 1.0 = perfect fill
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward when next item exactly matches post_residual,
    // or can fit into post_residual with a small remainder.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 25.0; // perfect 2-item fill
            } else {
                // smaller gap = better chain; decay with gap size
                score -= 20.0 * (-gap / 20.0).exp();
            }
        } else {
            // next item cannot follow here: penalize proportionally to overflow
            score += 5.0 * ((nxt - post) / cap).min(1.0);
        }
    }

    // Compare against mean residual: placing in a bin below mean residual
    // concentrates packing (good); placing in above-mean bins wastes space.
    if post < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0 * ((post - mean_residual) / cap).min(1.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating very small dead space (< 10, likely unusable).
    if post > 0.0 && post < 10.0 {
        score += 12.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to capacity or when no good fits exist.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        // Prefer fresh bin for large items (leaves big usable residual),
        // discourage when item is small (better to stuff into open bins).
        score += 8.0 - 18.0 * fill_ratio;
        if fitting_bins_count > 0 && fill_ratio < 0.5 {
            score += 6.0; // extra penalty: small item shouldn't open new bin
        }
        if next_item_size > 0 && (next_item_size as f64) <= (cap - item_size as f64) {
            score -= 10.0; // next item can join: pair large items together
        }
    }

    // Mild stream-progression pressure: as stream advances, prefer
    // consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 0.8 * tightness * (item_size as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Lookahead: reward post_residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space penalty scaled by how much next item can't fit.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    } else {
        // Last item: minimize post_residual hard.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into bins with small residual.
    if open_bins_count > 4 {
        score += 0.1 * (post_residual as f64 - mean_residual);
    }

    // Early in stream: be picky (prefer tight fits), late: just pack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.3 * progress;

    // New empty bin candidate: penalize so it's only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        let poor_fit = open_bins_count > 0
            && next_item_size > 0
            && post_residual >= next_item_size
            && item_size <= 50;
        score += if poor_fit { 60.0 } else { 45.0 };
        // Late in stream, a fresh bin is less costly.
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted space, with non-linear growth for small residuals
    let mut score = pr * (1.0 + 0.5 * (1.0 - pr / cap).powi(3));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer leaving flexible space; late, prefer tight fits.
    let tight = 1.0 - pr / cap;
    score += progress * 40.0 * tight.powi(2) - (1.0 - progress) * 10.0 * tight;

    // Lookahead: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = pr >= nx;
        if fits_next {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 + nx / cap * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty relative to crowdedness of open bins
    score += 0.05 * (open_bins_count as f64).ln() * pr / cap;

    // Slight deviation from mean residual: prefer bins near the mean (balance)
    score += 0.1 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / cap) * 20.0;

    // Harmonic class of post_residual: mod-10 granularity.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in [1..9] are "almost full" -> reward; exact multiples of 10
    // are reusable by common item sizes -> slight reward; large junk -> penalize.
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if class != 0 && pr < 10 {
        score -= 25.0; // tiny dead space, bin effectively closed
    } else if class == 0 {
        score -= 8.0; // round residual, easy to reuse
    } else if pr < 20 {
        score -= 5.0;
    } else {
        score += (pr as f64 - 20.0) * 0.35; // growing waste penalty
    }

    // Harmonic class of item size relative to capacity quarters.
    let q = (item_size * 4) / bin_capacity; // 0..3
    match q {
        3 => score -= 10.0, // large item: placing it anywhere is good
        2 => score -= 3.0,
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr && (pr - next_item_size) < 10 {
            score -= 18.0;
        } else if next_item_size > pr {
            score += 6.0; // next item won't fit here; mildly deprioritize
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default: discourage opening new bins when any bin fits.
        score += 15.0;
        // But if the item is huge (leaves little residual), a fresh bin is fine.
        if item_size >= (bin_capacity * 3) / 4 {
            score -= 20.0;
        }
        // Many open bins with high mean residual: consolidation pressure low,
        // allow new bin when existing fits would be very loose.
        if mean_residual > 40.0 && post_residual < (mean_residual as u32) {
            score -= 10.0;
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference to fill earlier (lower-index) bins: use open_bins_count
    // as a mild tiebreaker to keep bins clustered.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small unusable gaps (< min item size) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 15.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 * 0.4;
    score -= open_pressure;

    // Lookahead: if next item fits the post residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap blocks the known next item: penalize dead space creation.
        score += 8.0;
    }

    // Prefer bins with residuals near the item (harmonize with mean residual).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early in the stream, be more willing to open bins (future flexibility);
    // later, consolidate aggressively.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive when existing bins would create dead space
    // or the fit is very loose.
    if bin_residual == bin_capacity {
        let dead_space_risk = post_residual > 0 && post_residual < 10;
        if dead_space_risk {
            score -= 70.0; // opening a new bin beats creating unusable gaps
        } else {
            score += 30.0; // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else {
            // Reward proximity of post_residual to next_item_size (lookahead matching).
            score -= 20.0 / (1.0 + diff as f64);
            // Penalize dead space that can't fit the next item at all.
            if post_residual < next_item_size {
                score += 12.0;
            }
        }
    }

    // Prefer bins whose residual is tight relative to the mean (consume crowded space).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: only fitting bin -> strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating very small unusable residuals (dead space < typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: neutral-ish score so it wins only when all fits are poor.
    if bin_residual == bin_capacity {
        score = 95.0 - (post_residual as f64) * 0.1;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of the bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward high fill non-linearly (tight fits strongly favored)
    score -= 60.0 * fill * fill;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use leftover; penalize proportionally to waste
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative compactness: prefer bins whose residual is below the mean
    // (packing into already-tight bins preserves loose bins for big items)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Early stream: be slightly conservative, keep bins balanced;
    // late stream: be greedy, minimize bin count aggressively
    score -= (1.0 - progress) * 5.0 * (mean_residual / bin_capacity as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Discourage proliferating many open bins early
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += 12.0;
    }

    // Mild new-bin penalty so existing fitting bins win ties
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual). Late: dead space is less costly
    // to leave if it becomes unusable, so the penalty curve flattens with progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let mut score = post * (1.0 - 0.35 * p2) + post * post / (2.0 * cap) * (0.5 + p3);

    // Reward good fits: small post_residual relative to capacity.
    let fit_ratio = post / cap;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward heavily;
    // if next item cannot fit post placement, mild penalty for creating dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 6.0 * (1.0 - gap) - 4.0 * gap;
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Mean residual coupling: placing in a bin below mean residual spreads space evenly.
    score += 0.05 * (mean_residual - post);

    // New-bin candidate: penalize opening a bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * fit_ratio;
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: near-zero post residual is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic class logic: classify post_residual by residue classes.
    // Residuals in classes that are "friendly" to common small items (mod 10)
    // are more reusable, so penalize dead zones less there.
    let pr = post_residual;
    let cls = pr % 10;
    match cls {
        0 => score -= 8.0,          // round residuals pair well with 10-multiples
        1 | 9 => score -= 3.0,
        2 | 8 => score -= 2.0,
        5 => score -= 4.0,          // half-class residuals pair with 5s
        _ => score += 3.0,          // awkward residues create dead space
    }

    // Integer-division thresholds on post_residual: small buckets (0..10)
    // are dead space; large buckets (>= half capacity) are reusable.
    if pr >= bin_capacity / 2 {
        score -= 6.0;
    } else if pr < 10 {
        score += 10.0;              // nearly dead residual
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.4;
            // Harmonic check: next item leaves another friendly residual
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; slight penalty if this bin is last chance
            if fitting_bins_count == 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Opening a new bin is wasteful unless current fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: high, so existing decent fits win.
        score += 45.0;
        // If many bins are open and mean residual is large, opening new bins
        // is less attractive (consolidate usage first).
        score += open_bins_count as f64 * 0.5;
        score += (mean_residual / bin_capacity as f64) * 20.0;
        // Late in the stream, prefer closing out bins rather than opening new.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // But if the item is huge and would leave a terrible residual anywhere,
        // a fresh bin is cleaner: big items fit best in empty bins.
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Mild preference for bins with below-average residual (consolidate fullness).
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but tiny unusable gaps are bad.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space penalty: gap too small for any item (min size 1..100, but
            // typical small items exist; penalize very small leftovers less harshly
            // if next item could use them).
            let dead = 10.0 - post_residual as f64;
            score += dead * 1.5;
        } else {
            // Usable gap: mild reward for larger usable leftover.
            score -= 0.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // If next item fits exactly in post_residual, big reward for reserving it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward.
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: penalize proportionally to wasted space.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> favor filling existing bins,
    // making the new-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly worse than average fit so we only
        // open when existing bins are poor fits.
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        // Existing bin: reward using it, more so when many bins are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean residual coupling: if this bin's residual is far below mean (tighter),
    // it's a good consolidation target.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.4;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // Early stream: be a bit more willing to open bins (spread items);
    // late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0; // cheaper to open new bin early
    } else {
        score += progress * 5.0; // favor existing bins late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

