    if bin_residual == bin_capacity {
        // Neutral base; only attractive when existing fits are terrible.
        score += 5.0;
        if next_item_size > 0 && item_size >= 60 {
            score -= 8.0; // big items may justify fresh bins
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_residual as f64 / bin_capacity as f64);

