    if open_bins_count > 2 && mean_residual > (bin_capacity as f64 * 0.5) {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity or fits are poor.
    if bin_residual == bin_capacity {
