        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, opening new bins is less costly (fewer future items
        // to fill them, but also less waste accumulates).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
        // If many bins are open already, discourage yet another.
        score += open_bins_count as f64 * 1.5;
        // If no other bin fits, the new-bin call is effectively forced; soften cost.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for tighter existing bins beyond raw post_residual:
    // favor bins whose residual was already small (high fill ratio).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 6.0;

    // Small time-horizon modulation: early in stream, be conservative about
    // wasting space; later, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
