}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: normalized post residual, non-linearly penalized (small leftovers are good)
    let norm_post = post / cap;
    let mut score = norm_post * norm_post * 120.0 + norm_post * 30.0;

    // Perfect fit reward: strong polynomial decay toward zero leftover
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0 * (1.0 - norm_post * 10.0);
    }

    // Dead-space penalty: leftover too small for the smallest plausible item
    if post_residual > 0 && post_residual < item_size {
        score += 25.0 * (1.0 - post as f64 / item_size.max(1) as f64);
    }

    // Lookahead coupling: reward leftover that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 18.0 * (1.0 - post as f64 / cap) * (nx / 100.0);
        } else {
            score += 12.0 * (nx / 100.0) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin, less so late in stream or with many bins
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 45.0 * (1.0 - openness) * (1.2 - progress);
        // but if the item is large relative to capacity, a fresh bin is fine
        score -= 30.0 * (item_size as f64 / cap) * (item_size as f64 / cap);
    }

    // Mean residual interaction: prefer bins whose residual deviates below the mean (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * dev.signum();

    // Late-stream consolidation: favor filling existing bins harder as stream ends
    score -= 20.0 * progress * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
