    // Harmonic class of post_residual: residues mod 10 and mod 25 create
    // "usable size classes" for future items (items are 1..100).
    let r10 = (post_residual % 10) as f64;
    let r25 = (post_residual % 25) as f64;
    let r50 = (post_residual % 50) as f64;

    // Penalize residuals that are not aligned to common item-size harmonics.
    // Residual exactly 0 is perfect; small nonzero residues are dead space.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space below minimum plausible item size
        score += 12.0 - post_residual as f64;
    } else {
        // Alignment rewards: residual divisible by 10/25/50 fits many sizes
        let align10 = 10.0 - r10;
        let align25 = 25.0 - r25;
        let align50 = 50.0 - r50;
        score -= 0.30 * align10 + 0.20 * align25 + 0.15 * align50;
        // Perfect harmonic matches
        if r10 == 0.0 { score -= 4.0; }
        if r25 == 0.0 { score -= 3.0; }
        if r50 == 0.0 { score -= 2.0; }
    }

    // Integer-division thresholds: which harmonic "slot" the residual falls in
    let slot = post_residual / 25; // 0..4
    let slot_bonus = match slot {
        0 => 8.0,   // 0..25: nearly full, only good if item was large
        1 => 2.0,   // 25..50
        2 => 0.0,   // 50..75
        3 => -3.0,  // 75..100: very flexible
        _ => -5.0,  // full-ish empty
    };
    score += slot_bonus;

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            // Next item fits here: strong reward, scaled by tightness
            let tight = (post_residual as f64 - nxt) / cap;
            score -= 10.0 * (1.0 - tight);
            // Harmonic match of next item to residual class
            if (post_residual as u32) % (next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this residual's remainder
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the
    // current item is huge relative to capacity or stream is early.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a new bin
        score += 45.0;
        // Large items justify fresh bins; small items should use open bins
        score -= 30.0 * frac * frac;
        // Early in stream, new bins are cheaper (more items to fill them with)
        score -= 10.0 * (1.0 - progress);
        // If no open bin fits at all, opening is necessary
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer filling bins with high residual (avoid scattering small items)
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * spread;

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small to hold the next item (or any
    // plausible item if next is unknown, min size 1..10 fallback).
    let min_useful = if next_item_size > 0 { next_item_size.min(10).max(1) } else { 10 };
    if post_residual < min_useful {
        // Dead space: gap below the smallest useful item size.
        score += 25.0 + 0.5 * (min_useful - post_residual) as f64;
    } else if post_residual < 10 {
        // Tiny gap that likely can't fit anything (items 1..100 but mostly >= 10 historically).
        score += 12.0;
    }

    // Reward tight fits strongly (post_residual near zero but still usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize proportionally to how close we are
        // to wasting the residual entirely.
        score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin (unless dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual >= min_useful {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidation into
    // existing bins; with few bins, be pickier about fit quality.
    let pressure = open_bins_count as f64;
    score -= pressure * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when current placements would create dead space or the
    // fit is loose. Baseline for empty bin should be moderately high so we
    // prefer filling existing bins, but beat heavily dead-space-penalized bins.
    if bin_residual == bin_capacity {
        // Neutral-ish base: slightly above a perfect fit, below dead-space bins.
        score = 30.0 + 0.5 * pressure;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 5.0;
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight — reward finishing it off.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= 3.0 * (mean_residual - res_f) / bin_capacity as f64;
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize larger post residuals quadratically.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            let gap = pr - next;
            // Exact match: next item fills this bin perfectly.
            if gap == 0.0 {
                score -= 40.0;
            } else {
                // Closer gap = better; penalize large unusable leftovers after next item.
                score += 0.1 * gap;
                if gap < 10.0 {
                    score -= 10.0; // near-exact chain bonus
                }
            }
        } else {
            // Next item cannot fit here; post_residual becomes dead space for lookahead.
            score += 0.25 * (next - pr);
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.05 * (pr - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no good fit exists. Empty bin has post_residual == capacity - item_size.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 60.0;
        // Large items open bins more readily.
        score -= 0.4 * item_size as f64;
        // Late in stream, keep bins closed.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins fit the item, definitely don't open a new one.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fill ratio of the bin after placement.
    let fill_after = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 0.9 * fill_after * fill_after * (bin_capacity as f64);

    // Penalize leaving awkward small dead space (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.5;
    }

    // Lookahead: bonus if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting tight space.
            score += 1.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax
    // the penalty when the fit into this empty bin is large and tight.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0 + 2.0 * open_bins_count as f64;
        let tight_fit = item_size as f64 / bin_capacity as f64;
        // If the item is large, a fresh bin is fine; small items should reuse bins.
        score += base_penalty - 14.0 * tight_fit * tight_fit;
        // Late in the stream, avoid opening bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.4 * (mean_residual - res_f);
    } else {
        score += 0.3 * (res_f - mean_residual);
    }

    // Global load balancing: with many open bins, encourage closing them out.
    if open_bins_count > 4 && post_residual == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base preference for tight fits (low post residual), smoothed polynomial.
    let mut score = pr_norm * pr_norm * cap;

    // Reward using an existing bin vs. opening a new one: new-bin candidate has
    // bin_residual == bin_capacity; add a fixed opening penalty so it only wins
    // when fits elsewhere are genuinely bad.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5 && item_size > 0;
    if is_new_bin {
        score += 18.0 + 12.0 * (1.0 - progress);
    } else {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Lookahead coupling: penalize post_residuals that are too small to hold the
    // next item (dead space), reward post_residuals that can still host it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (nxt / cap) * (1.0 - pr / cap);
        } else {
            let waste = (nxt - pr) / cap;
            score += 10.0 * waste * waste * cap;
        }
    }

    // Smooth stream-progress coupling: later in the stream, tighten more
    // aggressively (wasted space matters more as we approach the end).
    let tightness = 1.0 + progress * progress;
    score *= tightness;

    // Mild penalty when this bin's residual deviates from the mean residual,
    // encouraging residual homogenization across open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Slight preference to fill bins among many open bins (consolidation).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: reward residuals that other items can fill.
    let pr = post_residual;
    if pr > 0 {
        // class by integer division into 10-wide bands
        let band = pr / 10;
        match band {
            0 => score -= 25.0,               // nearly perfect fit
            1 => score -= 18.0,
            2 => score -= 12.0,
            3 => score -= 8.0,
            4 => score -= 5.0,
            5 => score -= 3.0,
            6 | 7 => score += 2.0,
            8 => score += 4.0,
            _ => {}
        }
        // Modulo-10 residue: small nonzero residues are dead space
        let m = pr % 10;
        if m == 0 {
            score -= 6.0; // round residual, highly reusable
        } else if m > 7 {
            score += 3.0; // awkward sliver
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Lookahead coupling: if next item fits post_residual exactly or well, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let nxt = next_item_size as f64;
        if next_item_size == pr {
            score -= 30.0;
        } else {
            let fill_ratio = nxt / (pr as f64);
            score -= 20.0 * fill_ratio;
            // harmonic check: post-post residual band
            let pp = pr - next_item_size;
            if pp % 10 == 0 { score -= 5.0; }
        }
    } else if next_item_size > pr {
        // next item won't fit here; penalize wasting residual
        score += (pr as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        let base = 35.0 + (open_bins_count as f64) * 0.5;
        // open new bin only if post_residual here would be large dead space
        let waste = (post_residual as f64) / cap;
        score = base + waste * 30.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 15.0; // existing bin serves lookahead better
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // no good home elsewhere -> open bin
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing)
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Stream progression: tighten late in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward very tight fits (post_residual close to zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: if the next item fits exactly in post_residual,
    // reward this placement; if next item would be blocked by a small gap, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins below mean residual (fill the emptier bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize by default so we prefer existing bins,
    // but relax the penalty when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual > 0 && post_residual < 10) {
            score -= 90.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual == next_item_size means the lookahead item
    // can exactly fill this bin afterwards.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Lookahead compatibility: reward when next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to lookahead item: penalize unusable leftovers.
        let dead = post_residual as f64;
        score += 0.5 * dead * (dead / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a fresh bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize leaving residuals that are unlikely to be useful (small scraps),
    // unless they exactly match a plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Tie-break toward bins with below-average residual (tighter bins first),
    // keeping large-residual bins flexible for big future items.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late in the stream, be more conservative: prefer filling existing bins
    // rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 25.0 * progress;

    // Mild penalty for opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalize proportionally.
        let waste = post_residual as f64;
        score += waste * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless
    // current bins fit poorly or mean residual is large and fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        // Base cost of a new bin; reduced when existing bins are badly fragmented.
        let mut new_bin_score = 120.0 - fragmentation * 0.5 - progress * 20.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 150.0; // must open a new bin
        }
        score = new_bin_score;
    }

    // Mild penalty for spreading items across many bins when residual is ample.
    if bin_residual >= item_size * 2 && open_bins_count > 1 {
        score += 5.0;
    }

    // Prefer using bins with below-average residual (consolidate fullness).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let t = progress * std::f64::consts::PI;
    let wave = 0.5 * (1.0 + (t).cos());
    score += norm_pr * norm_pr * 40.0 * wave;
    score -= norm_pr * 25.0 * (1.0 - progress);
    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (30.0 + 40.0 * progress);
    // penalize dead space when few bins can fit the item (last chance)
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }
    // lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64 / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 12.0;
        }
    }
    // new-bin candidate: mild penalty so open bins are preferred unless fit is poor
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * norm_pr * (1.0 - progress) + 20.0 * (1.0 - tightness);
    }
    // interaction with mean residual across open bins
    score += 0.05 * (mean_residual - pr);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate detection (empty bin: residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Harmonic class of the post-fit dead space ----
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: dead space < 10 (unusable by any future item, min size 1..100 but
    //          small scraps are weak) -> penalize as dead space.
    // Class 2: dead space can host the lookahead item -> strong reward.
    // Class 3: dead space divisible into useful chunks (harmonic of capacity).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if post_residual < 10 {
        // Dead space too small to be reliably useful: penalize heavily,
        // scaled by how much capacity we "wasted".
        score += 25.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Lookahead item fits here: reward chaining.
        let chain_waste = post_residual - next_item_size;
        score -= 40.0 - 0.2 * chain_waste as f64;
    }

    // Harmonic capacity-fraction classes: dead space near multiples of
    // common item sizes (e.g. 25/50/75 style quantiles) is more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr % 50 == 0 {
        20.0
    } else if pr % 25 == 0 {
        12.0
    } else if pr % 10 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Integer-division threshold: classify dead space into coarse buckets.
    let bucket = pr / 20; // 0..=5
    score += bucket as f64 * 2.0; // prefer bins that end in lower buckets (tighter)

    // ---- New-bin decision ----
    if is_new_bin {
        // Opening a new bin is expensive: penalize, but less when
        // this bin is the only fitting option (last chance) or when
        // the current bin would leave a bad (tiny) dead space.
        let last_chance = fitting_bins_count == 1 && !is_new_bin;
        let _ = last_chance;
        let mut new_bin_penalty = 60.0;
        // If existing options leave unusable scraps, new bin becomes attractive.
        if post_residual >= 10 && post_residual < 20 {
            new_bin_penalty -= 30.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 30.0 * progress;
        // Many open bins already: discourage spreading further.
        new_bin_penalty += 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
    } else {
        // Last-chance bin: strong reward to use it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 55.0;
        }
        // Prefer bins below mean residual (tighter bins) mildly.
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Lookahead anti-pattern: if placing here leaves a gap that exactly
    // blocks the next item while another bin could chain, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    let dead = post_residual < min_item;
    if dead {
        score -= 1000.0; // perfect fill: extremely desirable
    } else if post_residual > 0 && post_residual < 10 {
        // unusable sliver (below typical minimum item size) -> dead space
        score += 60.0;
    } else {
        // usable gap: mild reward for tight fit
        score -= (bin_capacity as f64 - post_residual as f64) * 0.25;
    }

    // Penalize gaps that cannot fit the lookahead item if they could have
    // (wasted opportunity), but reward gaps that exactly fit next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus open-bin pressure.
        score += 25.0 + pressure;
        // Opening a new bin is fine if item is large and current residuals are scattered
        if item_size > 70 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight reward proportional to how far below mean residual
        // this bin is (prefer filling emptier bins to consolidate).
        score -= (mean_residual - bin_residual as f64).max(0.0) * 0.15;
    }

    // Prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this placement leaves exactly the space the next item needs.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual large enough to also fit the next item: good chain placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use what remains.
        let waste = post_residual as f64;
        score += waste * 0.8;
    }

    // Penalize relative waste against the mean residual of open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Tight fit reward: near-exact fill is excellent.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.9 {
        score -= 15.0 * (tightness - 0.9) * 10.0;
    }

    // New-bin candidate: only attractive when no decent fit exists
    // (this bin would be fresh, so its post_residual == capacity - item_size is large).
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 30.0 * pressure + open_bins_count as f64 * 2.0;
        // Early in stream, opening bins is cheap; late, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Slight bias toward fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // Worse fit among open bins => new bin more attractive.
            let fit_quality = 1.0 - (item_size as f64 / bin_residual as f64);
            score -= 40.0 * fit_quality;
        }
        // Early in stream: opening bins cheaply builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // This placement creates residual the next item cannot use.
            score += (post_residual as f64).min(9.0);
        }
        // If next item exactly fills post_residual, strong reward.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Global state coupling: prefer placing into bins when many bins are open
    // with large mean residual (avoid spreading waste).
    if open_bins_count > 4 && mean_residual > item_size as f64 * 2.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Prefer filling bins that are already quite full (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio * fill_ratio * fill_ratio;

    // Late in stream: avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mean_res = mean_residual;
    let next = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), non-linearly amplified.
    let mut score = post;

    // Smooth polynomial coupling of tightness with stream progress:
    // tight fits matter more as the stream advances.
    let tightness = 1.0 - post / cap;
    let progress_coupling = tightness * tightness * (0.5 + 2.5 * progress * (1.0 - progress) * 4.0).min(3.0);
    score -= 12.0 * progress_coupling;

    // Penalize large dead space super-linearly (unusable slivers).
    let dead_threshold = cap * 0.25;
    if post < dead_threshold {
        let frag = (dead_threshold - post) / dead_threshold;
        score += 20.0 * frag * frag;
    } else {
        // Large leftover is good if it stays usable; mild reward.
        score -= 3.0 * (post / cap);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next > 0.0 && post >= next {
        let snug = 1.0 - (post - next) / cap;
        score -= 6.0 * snug;
    } else if next > 0.0 && post > 0.0 && post < next {
        // Creates a sliver the next item can't use; penalize relative to item size.
        score += 4.0 * (post / item.max(1.0));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // the item fits poorly everywhere. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (1.0 + progress * 10.0)).max(1.0);
        let mean_usable = mean_res / cap;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        let waste = 30.0 * mean_usable;
        // Later in the stream, consolidation matters more; early on, spreading is fine.
        let early_discount = 20.0 * (1.0 - progress);
        score += 35.0 + open_pressure * 2.0 + waste - early_discount;
        // If item is large, a fresh bin is more attractive.
        score -= 0.15 * item;
    }

    // Mild penalty for proliferating many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes define "usable" dead space.
    // Residuals that are multiples of common item sizes (10/20/25/50) are more reusable.
    let pr = post_residual;
    let harmony_bonus: f64 = if pr == 0 {
        -40.0 // perfect fill
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -6.0
    } else {
        4.0 // awkward residue class: penalize
    };
    score += harmony_bonus;

    // Integer-division threshold: small post_residual is dead space.
    if pr > 0 && pr < 10 {
        score += 30.0;
    } else if pr < 20 && pr > 0 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot class
            score += ((next_item_size - pr) % 30) as f64 * 0.2;
        }
    } else {
        // last item: prefer tightest fit anywhere
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that makes it attractive
    // only when existing bins have poor fits (large post_residual already penalized).
    if bin_residual == bin_capacity {
        score = 45.0 + (item_size as f64) * 0.1 - harmony_bonus.abs() * 0.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    // Mean-residual coupling: when open bins are mostly full, prefer consolidating.
    if mean_residual < 15.0 {
        score -= 8.0;
    }

    // Stream progression: early on, be a bit greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    let dead_threshold = 10.0;
    if post_residual > 0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 8.0; // tiny leftover = wasted space forever
    }

    // Reward tight fits (low post residual relative to capacity).
    score -= (cap - pr) / cap * 4.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let pressure = (open_bins_count as f64 / (1.0 + step_index as f64)) * 3.0;
    score += pressure * (pr / cap);

    // Mean residual coupling: penalize leaving residual far above mean (fragmentation).
    score += ((pr - mean_residual).abs()) * 0.3;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 3.0;
    } else if next_item_size > 0 && pr < next_item_size as f64 && pr < 10.0 {
        score += 5.0; // dead space confirmed unusable by lookahead
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 20.0 + pressure;
        if fitting_bins_count == 0 {
            score = -50.0; // must open new bin
        } else if fitting_bins_count == 1 {
            score = base + 10.0; // keep the last-chance bin alive
        } else {
            score = base + (post_residual as f64) * 0.5; // prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize unusable dead space (residual smaller than any item).
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here: reward tight chaining.
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - chain_fit / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0).min(1.0);
        }
    }

    // Relative residual vs mean: prefer tighter-than-average bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it yields a
    // perfect or near-perfect 2-step plan while existing bins are fragmented.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
        if item_size >= bin_capacity / 2 {
            score -= 50.0;
        }
    }

    // Late in stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 120.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is already good; amplify).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;  // hard-to-fill zone
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly anywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0;                       // default: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 200.0;                  // nothing fits: must open new bin
        } else if fit_ratio < 0.55 && post_residual as f64 > mean_residual {
            score -= 10.0;                   // poor fit elsewhere, fresh bin keeps flexibility
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 18.0;
        }
        // Late in stream, avoid opening bins that will be wasted.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 {
            score += 20.0 * progress;
        }
    } else {
        // Existing bin: lookahead pairing bonus — if next item fits in post_residual, reward.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 10.0;
        }
        // Reward bins below mean residual (consolidating emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Penalize scattering across many open bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Slight global preference to keep open_bins_count low.
    score -= 0.05 * (bin_capacity as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: post residual, but penalize large residuals more sharply (dead space).
    let mut score = pr + 0.35 * (pr / cap).powi(3) * cap;

    // Tight fits are rewarded: small post_residual relative to item size.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (it / cap);

    // Smooth stream-progress coupling: later in the stream, prefer tighter packing.
    let progress_weight = 6.0 * progress * (1.0 - progress) + 3.0 * progress;
    score -= progress_weight * tightness;

    // Penalize bins whose residual deviates from mean residual (fragmentation control),
    // with smooth quadratic coupling.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless fit is bad.
    if is_new_bin {
        score += 10.0 - 6.0 * progress;
        // If lookahead item is large, opening a fresh bin is more attractive.
        let nx = next_item_size as f64;
        if nx > 0.0 {
            score -= 0.06 * nx;
        }
    } else {
        // Lookahead fit bonus: if next item fits in the resulting residual, reward.
        let nx = next_item_size as f64;
        if nx > 0.0 && nx <= pr {
            score -= 5.0 * (nx / cap) * (1.0 - progress);
        } else if nx > pr {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity fractions
    let pr = post_residual as u32;
    let class = pr % 10;
    // Reward residuals that fall in "usable" harmonic classes (multiples of 5, small primes)
    let class_bonus: f64 = match class {
        0 => -6.0,
        5 => -3.0,
        2 | 4 | 6 | 8 => -1.0,
        _ => 1.5,
    };
    score += class_bonus;

    // Integer-division threshold: how many size-10 slots remain
    let slots = pr / 10;
    score -= (slots as f64) * 1.2;

    // Tight fit reward
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 4.0;
        } else {
            // next item won't fit here; penalize leaving medium dead space
            if pr > 30 {
                score += (pr as f64 - 30.0) * 0.15;
            }
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when few fitting bins or huge item
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 30.0
            + mean_residual * 0.25
            + (open_bins_count as f64) * 1.5
            - (fitting_bins_count as f64) * 6.0
            - progress * 5.0;
        // If next item is large and current item small, opening fresh bin is worse
        if next_item_size > item_size {
            score = base + 10.0;
        } else {
            score = base;
        }
    }

    // Mild penalty for leaving residual near-but-not-at awkward values
    if pr > 0 && pr < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    } else if post_residual > 12 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fits are greatly rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin when open bins can fit,
    // unless the fit would create dead space.
    if bin_residual == bin_capacity {
        score += 80.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if post_residual <= 12 {
            score -= 60.0; // opening fresh bin avoids dead space
        }
        // lookahead: if next item fits the fresh residual, bonus
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins whose residual is close to item size (tight fits).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.5;

    // Lookahead synergy: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: keep post_residual close to the next item's size (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * gap; // reward exact/near match with lookahead item
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: next item exactly fills this bin
        } else if post_residual < next_item_size {
            score += 12.0; // dead space too small for the lookahead item
        }
    } else {
        // Last item: only care about waste now.
        score += 5.0;
    }

    // Penalize unusable slivers relative to the smallest possible item (1..100 unknown, use item_size as proxy floor).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter; prefer filling tighter bins.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no existing bin
    // fits well (large post_residual waste everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let waste_vs_mean = (post_residual as f64 - mean_residual).max(0.0);
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            // An open bin can host the next item too; discourage new bin.
            score += 30.0 + 0.5 * waste_vs_mean;
        } else if fitting_bins_count > 0 {
            // All fits would create dead space; mildly favor fresh bin.
            score -= 10.0;
        }
        // Early stream: new bins are cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly fit future items
    // (items are 1..=100, but small fragments are hard to use).
    if post_residual > 0 {
        let frag = 1.0 - (post_residual as f64) / 30.0;
        if frag > 0.0 {
            score += 8.0 * frag * frag;
        }
    } else {
        // Perfect fill is excellent.
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item can still go here: mild reward proportional to remaining slack
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // next item won't fit here: slight penalty for stranding residual
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // fits poorly everywhere else. Compare against mean residual of open bins.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its residual equals capacity, so start high
        // and subtract only when current bins are congested.
        score += 25.0;
        // If open bins are on average tight (low mean residual), a new bin is fine.
        let congestion = 1.0 - (mean_residual / (bin_capacity as f64)).clamp(0.0, 1.0);
        score -= 30.0 * congestion;
        // If many bins already fit the item, discourage opening a new one.
        score += 6.0 * (fitting_bins_count as f64).min(5.0);
        // Early in the stream, opening bins is cheaper (build capacity for future).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // Next item very large: better to keep residual big now.
        if next_item_size > post_residual.max(1) && next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Global balance: prefer bins whose residual deviates from the mean in a way
    // that harmonizes the pool (keep residuals homogeneous for future flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins that are already partially filled (consolidation).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill;

    // Mild time pressure: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more,
    // large dead space is penalized progressively more.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.35 * p2 + 0.55 * p3);
    score -= (cap - pr) * (0.25 * p2 + 0.45 * p3) * 0.1;

    // Penalize post residual that cannot fit the next item (smooth logistic-ish gate)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr / nxt).min(1.0).max(0.0);
        let gate = usable * usable * (3.0 - 2.0 * usable); // smoothstep
        score -= 6.0 * gate * (1.0 + progress);
        // extra reward if next item fits perfectly after this placement
        if pr as u32 == next_item_size {
            score -= 12.0;
        }
    } else {
        // last item: strongly prefer filling bins completely
        score -= 15.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: penalize opening a new bin,
    // but relax penalty when few bins can fit the item (last-chance scenarios)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 22.0 * (1.0 - 0.6 * scarcity) * (1.0 + 0.3 * openness) - 8.0 * scarcity * progress;
    } else {
        // Reward using existing bins, more when they are scarce options
        if fitting_bins_count <= 2 {
            score -= 7.0;
        }
        // Mild penalty when bin residual deviates from mean residual
        // (prefer bins whose residual is typical, keep diversity of gaps)
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 2.5 * dev * (1.0 - progress);
    }

    // Small tie-break favoring fuller bins overall
    score -= 0.05 * (cap - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands. Leftovers in the lowest band (tiny dead space)
    // are excellent; mid-band leftovers are wasteful.
    let frac = post_residual as f64 / bin_capacity as f64;
    let band = (post_residual / 10).min(9); // integer-division threshold classes
    match band {
        0 => score -= 12.0,          // near-perfect fill
        1 => score -= 6.0,
        2 => score -= 2.0,
        3 | 4 => score += 4.0,       // awkward mid residual
        5 | 6 => score += 1.0,
        _ => {}
    }

    // Modulo-class coupling: if next item fits exactly into post_residual
    // (harmonic match), strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0; // perfect harmonic chaining
        } else if gap <= 5 {
            score -= 8.0;
        } else {
            score += gap as f64 * 0.15;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: dead-space risk
        score += 6.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // fitting bins are poor (residual much larger than item) or none exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_open = fitting_bins_count == 0
            || (bin_capacity as f64 - mean_residual) < 0.0
            || mean_residual < item_size as f64 * 0.5;
        if poor_open {
            score -= 18.0;
        } else {
            score += 10.0 + frac * 5.0;
        }
    }

    // Small coupling with stream progress: pack tighter early, allow
    // spreading later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // Mean-residual alignment: prefer bins near the mean (keeps residual
    // distribution harmonized).
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize blocking the next item in this bin
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer already-open bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Mean-residual coupling: if this bin is tighter than average, favor it.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when the item is large relative
    // to residual space in typical open bins, otherwise discourage.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if large_item {
            score -= 5.0;
        } else {
            score += 18.0 + 0.2 * item_size as f64;
        }
        // Discourage opening new bins late in the stream.
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter residual fill (larger item into this bin).
    score -= item_size as f64 * 0.5;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect match: bin's post-residual exactly fits next item -> strong reward.
        let diff = post - nxt;
        if diff == 0.0 {
            score -= 30.0;
        } else if diff > 0.0 {
            // Post-residual larger than next item: usable but wasteful.
            // Penalize small overshoots heavily (dead space trap), relax for big gaps.
            if diff < 10.0 {
                score += (10.0 - diff) * 2.0;
            } else {
                score -= (diff - 10.0).min(40.0) * 0.2;
            }
        } else {
            // Next item won't fit in post-residual: mild penalty scaled by gap size.
            score += (-diff).min(50.0) * 0.3;
        }

        // Chain fit: item + next item both fit now -> excellent packing.
        if item_size as f64 + nxt <= bin_residual as f64 {
            score -= 15.0;
        }
    } else {
        // Last item: pure best-fit, no lookahead concerns.
        score -= 20.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Prefer bins whose residual deviates favorably from the fleet mean:
    // a below-mean residual bin that still fits is a "good fit" candidate.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(60.0) * 0.15;
    } else {
        score += (res - mean_residual).min(60.0) * 0.05;
    }

    // --- Last-chance bonus ---
    // If this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    // Brand-new empty bin: high baseline cost so it's chosen only when
    // open bins offer poor fits (their scores should be pushed below this).
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening a bin is riskier (leftover waste).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // If many bins are already open, discourage further fragmentation.
        score += open_bins_count as f64 * 1.0;
        // Exception: huge items relative to capacity may justify a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
