pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: minimize wasted space, with a mild non-linear (quadratic) penalty
    // on large post-residuals so tight fits are strongly preferred.
    let mut score = post + 0.9 * (post / cap) * post;

    // Smooth coupling of post_residual with stream progress:
    // early on, be slightly lenient with leftover space; late in the stream,
    // penalize leftovers more aggressively (less time to fill them).
    let progress_coupling = post * (0.25 + 0.75 * progress * progress);
    score += 0.35 * progress_coupling;

    // Cubic smooth interaction: residual fragmentation risk grows
    // non-linearly as post_residual approaches half-capacity ("dead zone").
    let frag = (post / cap - 0.5) * (post / cap - 0.5);
    score += 8.0 * frag * (post / cap);

    // Reward bins whose residual closely matches the item (near-perfect fit),
    // using a smooth Gaussian-like kernel on the fit ratio.
    let fit_ratio = item / bin_residual.max(1) as f64;
    let closeness = -1.0 * (fit_ratio - 1.0) * (fit_ratio - 1.0);
    score += 12.0 * closeness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (smoothly scaled by how well it actually fits).
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // Lookahead: if the next item would fit in the post-residual, reward this
    // placement (chaining items in one bin); else slight penalty.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 6.0 * (1.0 - (next / post - 0.5) * (next / post - 0.5));
        } else {
            let overflow = (next - post) / cap;
            score += 4.0 * overflow * overflow;
        }
    }

    // Penalize bins that are much emptier than the mean (avoid scattering),
    // with a smooth quadratic deviation term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin fits well. Penalize the empty-bin call smoothly, scaled by
    // how many bins already fit the item and the stream progress.
    if bin_residual == bin_capacity {
        let spread_penalty = 20.0 + 30.0 * (fitting_bins_count.min(8) as f64 / 8.0);
        let late_bonus = 10.0 * progress;
        score += spread_penalty + late_bonus;
        // But if the item is large relative to capacity, a fresh bin is fine
        // (smooth relief for big items).
        score -= 18.0 * (item / cap) * (item / cap);
    }

    // Mild preference to consolidate into fewer bins as stream advances.
    score += 0.05 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "awkward"
    // classes (tiny dead space < 10, or mid-range 31..60 that rarely fits
    // anything useful) get penalized; clean classes get rewarded.
    let pr = post_residual;
    let class = pr / 10; // integer division class 0..10
    match class {
        0 => score += 25.0,                    // unusable sliver
        1 => score -= 5.0,                     // clean small leftover
        2 => score -= 8.0,                     // sweet spot ~20
        3 => score += 4.0,                     // awkward 30s
        4 => score += 6.0,                     // awkward 40s
        5 => score += 3.0,                     // borderline
        6 => score -= 2.0,
        7 => score += 2.0,
        8 => score += 5.0,
        9 => score += 8.0,                     // nearly empty bin left behind
        _ => {}
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        // Perfect chain fit gets extra reward
        if pr == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host next item: penalize mildly
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: make empty bin attractive only when open
    // bins are fragmented (high mean residual spread) or late in the stream
    // with many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - pr as f64).abs() / bin_capacity as f64;
        score -= 10.0 * progress + 20.0 * fragmentation;
        // If item is large relative to capacity, fresh bin is natural
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Slight preference to pack into emptier existing bins when many bins open
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64 - mean_residual / bin_capacity as f64).abs();

    // Tie-break with fine-grained modulo harmonic: prefer post_residual near
    // multiples of 10 (cleaner future packing).
    let rem = pr % 10;
    if rem <= 2 || rem >= 8 {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a gap that exactly matches next item only mildly; but if
    // post_residual cannot host next_item while other space exists, slight penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading when many bins already open.
    if bin_residual != bin_capacity {
        score -= 3.0;
        score += 0.15 * open_bins_count as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit would be terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.1 * open_bins_count as f64;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Progress scaling: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack afterwards
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 25.0 - slack as f64;
        } else {
            // leftover after next item is dead-space prone; mild penalty
            score += slack as f64 * 0.15;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here after placement: penalize proportionally
        let miss = next_item_size - post_residual;
        score += miss as f64 * 0.4;
    }

    // Penalize tiny unusable post residuals (dead space)
    if post_residual < 10 {
        score += 20.0;
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // forced to open new bin
        } else {
            // discourage new bin unless current placement is a terrible fit
            let waste_ratio = post_residual as f64 / bin_capacity as f64;
            if post_residual > 0 && waste_ratio < 0.15 && next_item_size > 0 && next_item_size > post_residual {
                score -= 35.0; // poor fit AND lookahead miss -> open new bin
            } else {
                score += 15.0 + open_bins_count as f64 * 0.5;
            }
        }
    }

    // Mild stream-progression pressure: as stream advances, favor compacting
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post-placement residual (tight fit).
    let mut score = post_residual as f64;

    // Normalized progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits more strongly: quadratic shaping on post_residual.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Lookahead: if the next item fits exactly or well in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            // Perfect pair packing bonus.
            if slack == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize leaving a gap
            // sized such that next item is stranded; heavier late in the stream.
            score += 4.0 + 6.0 * progress;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to typical residual space, or no real alternative exists.
    if bin_residual == bin_capacity {
        // Neutral-ish base for the new bin: its post residual is already its score,
        // but add a mild inertia penalty that shrinks when open bins are fragmented
        // (high mean residual means existing bins are mostly unusable anyway).
        let fragmentation = mean_residual / cap;
        score += 8.0 * (1.0 - fragmentation);
        // Early in the stream, slightly discourage hoarding new bins.
        score += 6.0 * (1.0 - progress);
    } else {
        // Real bin: reward using bins that are already heavily loaded (low residual),
        // encouraging closure of bins rather than spreading load.
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 10.0 * fill * fill;

        // Penalize choosing a bin whose residual is much larger than needed
        // (wasting capacity that other items might need) — already partly covered
        // by post_residual, add coupling with mean residual state.
        if (post_residual as f64) > mean_residual {
            score += 0.10 * (post_residual as f64 - mean_residual);
        }
    }

    // Slight global pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    // Item-size coupling: large items should prefer the emptiest adequate bin,
    // small items should fill leftovers. Penalize large items in nearly-full bins
    // less, small items in nearly-full bins more (dead-space avoidance).
    let item = item_size as f64;
    if item < 30.0 && post_residual > 30 {
        score += 3.0; // tiny item leaving a big hole
    }
    if item > 60.0 && post_residual < 10 {
        score -= 3.0; // big item nearly perfectly closing a bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a smooth non-linear (quadratic) shaping.
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 30.0;

    // Smooth polynomial coupling with stream progress: tighter packing valued
    // more strongly as the stream advances (quartic ramp).
    let ramp = progress * progress * (3.0 - 2.0 * progress);
    score += norm_pr * ramp * 60.0;

    // Penalize dead space relative to mean residual (smooth interaction).
    score += (norm_pr - mean_residual / cap).abs() * 15.0 * (0.5 + ramp);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: reward leaving space for the next item smoothly.
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let fit_next = if ns <= pr { 1.0 } else { 0.0 };
        let gap = ((ns - pr) / cap).max(0.0);
        score += gap * gap * 20.0 - fit_next * 12.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating bins, smoothly scaled by progress.
    score += (open_bins_count as f64).ln1p() * 4.0 * (0.3 + 0.7 * progress);

    // New-bin candidate: discourage unless it is genuinely the best option
    // (smooth surcharge decaying as residual of this candidate is small).
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress * 0.5) + item_size as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are small-but-nonzero are "dead space" — penalize harshly
    if pr > 0 && pr <= 10 {
        score += 40.0; // nearly dead space
    } else if pr > 10 && pr <= 20 {
        score += 12.0;
    } else {
        // residue class shaping: multiples of 10 are reusable by typical item sizes
        score -= match class {
            0 => 8.0,
            5 => 3.0,
            _ => 0.0,
        };
    }

    // Harmonic class of bin_residual relative to item: how well item divides the residual
    if bin_residual > 0 {
        let q = bin_residual / item_size.max(1);
        let r = bin_residual % item_size.max(1);
        if r == 0 && q >= 1 {
            score -= 15.0; // item tiles residual perfectly
        } else if r <= 5 {
            score += 5.0; // leaves sliver
        }
    }

    // Lookahead coupling: can the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward, scaled by how tight the fit is
            let tightness = (next_item_size as f64) / (pr as f64);
            score -= 10.0 + 20.0 * tightness;
            // exact harmonic match: next item exactly fills post residual
            if next_item_size == pr {
                score -= 30.0;
            }
        } else {
            // next item won't fit: mildly penalize leaving large residual that attracts nothing
            if pr > next_item_size + 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are used only when open-bin fits are poor
        score += 55.0;
        // large items (harmonic high class) justify fresh bins
        if item_size >= 50 {
            score -= 15.0;
        }
        // early stream: slightly more willing to open bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
        // many open bins with high mean residual: prefer filling those, penalize new bin
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 20.0;
        }
    }

    // Prefer bins tighter than the mean residual (good consolidation)
    score -= 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Modulo threshold on next_item_size: sizes near multiples of 10 tile well with residuals of same class
    if next_item_size > 0 && pr > 0 && (next_item_size % 10) == (pr % 10) && next_item_size <= pr {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A gap is "dead" if no plausible future item (>=1) can ever use it well.
        // Penalize gaps below the minimum useful threshold more than proportionally.
        let dead_threshold = 10.0_f64.min(bin_capacity as f64);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 12.0;
        }
        // Moderate gaps that only very large items could fill are also risky.
        if post_residual >= 10 && post_residual < 30 {
            score += (30.0 - post_residual as f64) * 1.5;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (low wasted fraction).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage scattering across many open bins,
    // but allow spreading when mean residual is high (bins are roomy).
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has neutral base (post_residual = capacity),
    // but should only win when the best existing fit is poor. Penalize it moderately,
    // more when many bins are already open and could still absorb items.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.3 * open_bins_count as f64;
        // If lookahead item fits the leftover space, opening new bin is less attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Lookahead synergy: if the next item exactly fits the post_residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        // Partial synergy: next item can still use the remainder.
        score -= 8.0;
    }

    // Late-stream consolidation: near the end, prefer filling existing bins fully.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still host the next item: mildly reward closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.8;
    }

    // Penalize tiny unusable residuals (< smallest plausible item) as dead space.
    if post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Compare against mean residual: bins tighter than average are better to fill.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: penalize slightly so it's only chosen when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    // Early in stream, be a bit more willing to open bins (spread items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space too small for the smallest item (1..100 unknown dist, assume ~10 floor).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward if chain continues: next item almost exactly consumed.
        let chain_left = post_residual - next_item_size;
        if chain_left < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Next item would fit this bin only before placement -> avoid wasting the chance poorly.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in stream, opening bins is cheaper; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Many open bins -> discourage opening more.
        score += (open_bins_count as f64).ln().max(0.0) * 6.0;
    }

    // Prefer bins with below-mean residual (keep one bin for big future items).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Slight preference for fuller bins overall (best-fit flavor).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer filling bins tightly (low post_residual).
    let mut score = pr;

    // Non-linear polynomial coupling: normalized post-residual shaped by progress.
    let x = pr / cap; // in [0,1]
    let shape = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes mid-range waste smoothly
    score += 12.0 * shape * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses (consolidation pressure).
    score -= 8.0 * (1.0 - x) * (1.0 - x) * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly, more early (keep bins open), less late.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
        // But if it fits the next item perfectly while current fit is loose, soften penalty.
        if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 3.0 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && (next_item_size as u32) < post_residual {
        // Partial reward proportional to how well next item uses leftover space.
        let util = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * util * util;
    }

    // Slight penalty for very small post_residual that can't fit minimum item (dead space),
    // unless it's exactly zero (perfect fit).
    if pr > 0.0 && pr < 1.0 * cap * 0.01 {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins deviating from mean to balance residuals.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (modulo arithmetic) ----
    // Residuals that are "harmonically useful" (divisible into common small
    // item sizes) are less wasteful than awkward dead space.
    let pr = post_residual;
    let class = pr % 20; // coarse harmonic bucket on capacity fraction of 100
    let class_penalty: f64 = match class {
        0 => -8.0,               // perfectly reusable (0,20,40,60,80,100)
        10 => -5.0,              // half-capacity harmonics
        5 | 15 => 3.0,           // odd 5-multiples, mildly awkward
        _ => {
            // non-multiples of 5: penalize proportional to distance from
            // nearest multiple of 10 (dead space that few items can use)
            let d = class.min(20 - class) as f64;
            1.5 + 0.4 * d
        }
    };
    score += class_penalty;

    // Integer-division threshold: post_residual in [1,9] is prime dead space
    if pr / 10 == 0 && pr > 0 {
        score += 6.0; // tiny unusable slivers are bad
    }
    if pr == 0 {
        score -= 10.0; // perfect fill
    }

    // ---- Tightness reward: fraction of bin consumed by this item ----
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0; // avoid opening a new bin if this is the only fit
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: discourage unless existing fits are bad.
        score += 18.0;
        // If many bins can already fit the item, strongly deprioritize new bin.
        if fitting_bins_count > 1 {
            score += 12.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // Large items (>= half capacity) pair poorly with leftovers; a fresh
        // bin is more acceptable for them.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
        // Lookahead: if next item is large, keep fresh capacity available.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 4.0;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // ---- Lookahead coupling: reward leaving room for the next item ----
    if next_item_size > 0 {
        if pr >= next_item_size {
            // post residual can host the next item: harmonically good
            let ratio = next_item_size as f64 / pr as f64;
            score -= 6.0 * ratio; // snug reuse of leftover
            // exact harmonic match: modulo zero means perfect chain
            if pr % next_item_size == 0 {
                score -= 4.0;
            }
        } else if pr > 0 {
            // leftover too small for next item: penalize by dead fraction
            score += 3.0 * (1.0 - pr as f64 / next_item_size as f64);
        }
    }

    // ---- Context coupling with mean residual ----
    // If this bin's residual is far below the mean, it is a "crumb bin":
    // finishing it off is good; leaving it is bad.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.0 * (bin_residual as f64 / mean_residual.max(1.0));

    // Prefer consolidating into bins whose residual is close to the item
    // (best-fit style) with a non-linear squash.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * tight * tight;

    // Many open bins: mild pressure to fill existing ones rather than spread.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // the smallest plausible item (1..=10) are pure waste.
    if post_residual < 10 {
        // Dead space: heavily penalize, scaled by how deep into the stream we are.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * progress;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Small gap: risky, moderately penalize.
        score += 12.0;
    } else {
        // Healthy residual: reward tight fits (small post_residual in usable range).
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Next-item lookahead: if the next item fits exactly into post_residual,
    // strongly reward keeping this residual shape.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 15.0; // sets up a near-perfect second placement
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0; // residual can't host next item either: dead end
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize bins when many bins are open to encourage
    // consolidation; reward spreading when few bins are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins whose residual is below mean residual
    // (fill fuller bins first, keep emptier bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins
    // score poorly (dead-space penalties push them above this).
    if bin_residual == bin_capacity {
        score = 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item size (perfect 2-step fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Mild reward: post_residual large enough to fit next item.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (post_residual as f64 - next_item_size as f64) * 0.1;
    }
    // Penalize creating dead space that next item cannot use.
    else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor filling it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (poor utilization) mildly.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New empty bin candidate: penalize opening a new bin, especially when
    // other bins fit the item or residual would be wasted.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // Opening a new bin is fine if it enables a perfect 2-step match.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Slight preference for tighter bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual more strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize exact fills less (perfect fit is great).
    if post_residual == 0 {
        score -= 20.0;
    }

    // Dead-space penalty: small post_residual that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits in the post residual, big reward.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let slack = (post_residual as f64 - next_item_size as f64) / (bin_capacity as f64);
            score -= 25.0 * (1.0 - slack);
        } else {
            // Next item won't fit here; penalize wasting a large residual.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 15.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins to keep options open.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when item is large and current
        // open bins have poor average fit quality.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / (bin_capacity as f64);

        // Penalize opening a new bin by default.
        score += 55.0;

        // Relax penalty if the item is large (would leave tiny residual in any bin)
        // and mean residual is low (existing bins are mostly full).
        let poor_fit = (mean_frac < item_frac * 1.05);
        if poor_fit {
            score -= 40.0 * (1.0 - progress);
        }

        // Late in the stream, avoid opening new bins even harder.
        if progress > 0.8 {
            score += 25.0 * progress;
        }
    } else {
        // Slight preference for bins whose residual is close to mean (balanced load),
        // but favor fuller bins overall.
        let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fullness;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score += 1.5 * ((open_bins_count as f64).ln());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer small post-residual, with non-linear sharpening
    let norm_pr = pr / cap;
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Reward tight fits quadratically
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 12.0;

    // Interaction: post-residual vs stream progress — late in stream, be greedier
    score += norm_pr * norm_pr * (0.5 + 2.0 * progress) * 8.0;

    // Lookahead coupling: residual that fits next item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= (1.0 - slack) * (1.0 - slack) * 6.0;
    } else if next_item_size > 0 {
        // dead space relative to next item
        score += (next_item_size as f64 - pr) / cap * 5.0;
    }

    // Last-chance bonus: only one bin fits -> strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins far from the mean when mean is large
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= dev * dev * 2.0;

    // New-bin handling: penalize opening a new bin, less so early or when
    // no open bin fits and item is large
    if is_new_bin {
        let mut penalty = 10.0 + 8.0 * progress;
        if fitting_bins_count == 0 {
            penalty = 2.0 - 1.5 * progress;
        } else if fitting_bins_count == 1 {
            penalty += 20.0;
        }
        // small items waste a fresh bin
        penalty += (cap - item_size as f64) / cap * 4.0;
        score += penalty;
    } else {
        // mildly reward using already-open bins
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space quality classes.
    // Residuals that are hard to fill later (small odd pockets) get penalized;
    // "nice" residuals (0, or large enough to fit typical items) rewarded.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals in [1..9] are near-dead space unless next item fills them.
        if pr < 10 {
            score += 25.0;
            if next_item_size == pr {
                score -= 60.0; // next item exactly consumes the pocket
            }
        }
        // Modulo-10 harmonic ladder: residuals divisible by 10/20/25/50 are friendly.
        if class == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 7.0; }
        // Integer-division thresholds: how many "typical" small items (<=20) fit.
        let small_slots = pr / 20;
        score -= 4.0 * small_slots as f64;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
        // Chain: next item leaves another class-0 residual?
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; slight penalty since bin may strand.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or item is large relative to typical residuals.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a bin.
        score += 40.0;
        // Attractive if item is big and would leave other bins fragmented:
        // large item into fresh bin keeps small residuals for small items.
        let big_item = item_size > 60;
        if big_item { score -= 20.0; }
        // If many bins already open and mean residual is low (fragmented state),
        // discourage yet another bin.
        if open_bins_count > 4 && mean_residual > 30.0 {
            score += 15.0;
        }
        // Early stream: allow new bins more freely.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.2 { score -= 10.0; }
        // If no existing bin fits well (post_residual would be tiny), new bin competes.
        // (handled implicitly since per-bin score rises with tiny residuals)
    }

    // Mild pressure to consolidate: fewer open bins -> prefer existing bins.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for filling bins with larger residual first (best-fit style),
    // already encoded via post_residual base term.

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward very tight fits (residual smaller than min item size is dead space anyway).
    if post_residual > 0 && post_residual < item_size.min(10) {
        score -= 10.0;
    }

    // Pressure from number of open bins: discourage opening extra bins
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // But if this item would leave a dead-space gap in an existing bin,
        // opening a fresh bin becomes relatively more attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
    } else {
        // Last-chance bin: strongly prefer using it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual can't serve the next item: mild penalty for blocking.
        score += 5.0;
    }

    // Slight preference for keeping mean residual balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fills (dead space is the enemy)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover space can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // leftover still usable by next item: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit in the leftover: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 25.0 * (gap / bin_capacity as f64);
        }

        // Two-item lookahead: can this bin absorb current + next item tightly?
        let two = item_size + next_item_size;
        if two <= bin_residual {
            let two_left = bin_residual - two;
            score -= 30.0 * (1.0 - two_left as f64 / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 15.0 * (mean_residual - resid) / bin_capacity as f64;
    } else {
        score += 10.0 * (resid - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize the brand-new-bin candidate unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let mean_frag = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln_1p();
        // new bin is attractive only if existing residuals are large/fragmented
        score += 120.0 - 90.0 * mean_frag - 8.0 * pressure;
        // but if the next item pairs perfectly with the current one in a fresh bin, favor it
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 50.0;
        }
    }

    // Slight late-stream tightening: waste matters more as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize creating dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space unusable by next item; worse when it's large.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        } else {
            // Reward bins that remain useful for the next item.
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless the item
    // fits poorly everywhere or open-bin residuals are all large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Opening a new bin is more attractive early and when open bins
        // have large residuals (poor fits elsewhere).
        score += 30.0 - 20.0 * progress - 10.0 * pressure;
        // If item is large relative to capacity, new bin is more attractive.
        score -= 0.1 * item_size as f64;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64);
    score += 0.15 * gap;

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    // Nudge toward bins below mean residual (consolidate emptier bins).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer large post_residual (keep bins flexible).
    // Late stream: prefer small post_residual (tight packing matters more).
    let pr_norm = pr / cap;
    let flexibility_weight = (1.0 - progress).powi(2);
    let tightness_weight = progress.powi(2);

    let mut score = pr_norm * (1.0 + flexibility_weight * pr_norm)
        - tightness_weight * (pr_norm * pr_norm) * cap * 0.5;

    // Reward near-perfect fits with a smooth non-linear term.
    let perfect = 1.0 - (pr_norm * pr_norm);
    score -= perfect * perfect * cap * 0.6;

    // Last-chance bin: smooth penalty for wasting the only fitting bin on a poor fit.
    if fitting_bins_count == 1 {
        score += pr_norm * pr_norm * cap * (0.3 + 0.7 * progress);
    }

    // Lookahead coupling: smooth reward if next item fits the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack) * (1.0 - slack) * 8.0 * (0.5 + progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += gap * gap * 6.0;
        }
    }

    // Mild dispersion penalty: avoid leaving residuals far from the mean.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 4.0 * (1.0 - progress);

    // New-bin candidate handling: penalize opening a new bin when good fits exist,
    // but allow it when current residuals are all poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 15.0 * crowding * (1.0 - progress)
            - 10.0 * progress * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "usable"
    // residue classes (multiples of small denominators) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 3.0; }
        if pr % 50 == 0 { harmonic_bonus += 3.0; }
        // Small leftovers (< 10) are dead space for items >= 10... but sizes
        // can be as small as 1, so scale dead-space penalty by stream position.
        if pr < 10 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (10.0 - pr as f64) * (1.0 + 0.5 * progress);
        }
        score -= harmonic_bonus;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item exactly fills the post-residual,
    // this placement is excellent (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mildly good, better the tighter the chain.
            score -= 4.0 * (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        }
        // Next item cannot fit the leftover: leftover likely becomes dead space
        // unless it is harmonically reusable; penalize modestly.
        if next_item_size > post_residual && post_residual > 0 {
            score += 3.0;
        }
    }

    // Fractional capacity classes: prefer bins whose fill level is in the
    // upper half of the capacity (packing tight bins first).
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    if fill_frac > 0.5 {
        score -= 5.0 * fill_frac;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor. Give it a mild default penalty so decent fits beat it,
    // but allow it to win when all open bins have tiny residuals.
    if bin_residual == bin_capacity {
        score += 8.0;
        if open_bins_count == 0 {
            score -= 30.0; // must open something
        } else if mean_residual < 15.0 {
            score -= 10.0; // open bins are nearly full -> prefer new bin
        }
    }

    // Slight preference for fewer open bins being consolidated.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0; // dead space of 1..9 is nearly wasted
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is highly desirable
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening new ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: an empty bin gets a baseline that reflects pressure.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
        // If nothing fits well (few fitting bins), opening a new bin becomes attractive.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // next item will perfectly use the remainder
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0; // remainder will be dead space for the next item too
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit with the next item (2-step lookahead match).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match with next item also gets a moderate reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 25.0 - 2.5 * gap;
        }
    }
    // Penalize dead space that is too small for the smallest possible item (1..100 range).
    if post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current item is large relative
    // to residuals or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified.
        score += 30.0;
        // Open a new bin when the item is large and would leave a poor fit elsewhere.
        if item_size >= 50 {
            score -= 35.0;
        }
        // If the next item would perfectly fill the residual of this new bin, favor it.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 55.0;
        }
        // Late in the stream, avoid proliferating bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins already: discourage opening another.
        score += open_bins_count as f64 * 2.0;
    }

    // Slight preference for tightest bins overall.
    score -= (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Penalize creating awkward dead space that nothing small can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver is wasted space
    }

    // Lookahead: if the next item fits into the resulting residual, favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 - slack * 0.05;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // This placement strands space the next item can't use.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make opening a new bin moderately expensive,
    // but cheaper late in the stream or when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 18.0 + post_residual as f64; // base cost + residual (100)
        new_bin_cost -= progress * 6.0;
        if open_bins_count as f64 > 0.0 && mean_residual > 40.0 {
            new_bin_cost -= 5.0; // fragmentation: many loose bins, a fresh one is fine
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > 50 {
            new_bin_cost -= 4.0; // big item coming: fresh bin absorbs it better
        }
        score = new_bin_cost;
    }

    // Mild preference for filling bins that are already low relative to the mean.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr) * 100.0;

    // Smooth polynomial coupling with stream progress: tighten packing as stream advances
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress);
    score -= progress_coupling * 30.0 * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual).powi(2) / (cap * cap);
    score += 20.0 * dead * (1.0 - progress);

    // Last-chance bonus: smooth, stronger late in the stream
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress_coupling;
    }

    // Lookahead: reward residual that can fit the next item (smooth quadratic mismatch)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let mismatch = ((pr - ns) / cap).powi(2);
        score += 10.0 * mismatch - 8.0 * (-mismatch * 4.0).exp();
    }

    // Mild penalty for spreading across many bins when residual is large
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity classes (1..=4)
    let item_class = ((item_size * 4 + bin_capacity - 1) / bin_capacity).max(1) as f64;
    // Harmonic class of the next item
    let next_class = if next_item_size == 0 {
        0.0
    } else {
        ((next_item_size * 4 + bin_capacity - 1) / bin_capacity).max(1) as f64
    };

    // Dead-space penalty: residual below smallest item threshold (class 1 floor ~ cap/4)
    let dead_threshold = cap / 4.0;
    let pr = post_residual as f64;
    if pr < dead_threshold {
        score += (dead_threshold - pr) * 2.5; // unusable sliver penalty
    }

    // Perfect-ish fit reward: post_residual is a multiple of small harmonic units
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer division thresholds on post_residual: which next-item classes could still fit
    let fit_classes_next = (post_residual * 4) / bin_capacity; // max next class fitting
    if next_item_size > 0 {
        if fit_classes_next >= (next_item_size * 4 + bin_capacity - 1) / bin_capacity {
            score -= 4.0; // bin remains compatible with lookahead item
        } else {
            score += 3.0; // lookahead cannot use this bin afterwards
        }
        // Pairing bonus: post_residual exactly matches next item size
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin
        score += 15.0;
        // If item is large (high class), fresh bin is more acceptable
        score -= (item_class - 1.0) * 4.0;
        // If all fitting bins would leave tiny residue, allow opening new bin
        if pr < 8.0 && fitting_bins_count >= 1 {
            score -= 12.0;
        }
    }

    // Waste ratio term: fraction of bin wasted relative to capacity
    score += (pr / cap) * 5.0;

    // Stream progression: later in stream, prefer tighter packing (penalize loose bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr / cap) * progress * 8.0;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - pr as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (1) is trivial,
    // so instead treat gaps below a usable threshold as increasingly toxic, super-linearly.
    let gap = post_residual as f64;
    let usable_threshold = 20.0; // gaps below this rarely get filled well
    if gap > 0.0 && gap < usable_threshold {
        let deadness = (usable_threshold - gap) / usable_threshold; // 0..1
        score += deadness * deadness * 45.0;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Coupling with lookahead: leaving a gap that exactly fits the next item is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that is too small for the known next item (wasted space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it over
    // opening a new bin (which would also carry a large post_residual anyway).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, tighten packing (mild best-fit sharpening);
    // when few bins are open, slightly tolerate spread to keep future flexibility.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Mean-residual coupling: if this bin's residual is far below the mean, it's a tight bin;
    // filling tight bins fully is good, so reward low relative residual.
    let rel = (bin_residual as f64) / (bin_capacity as f64);
    let mean_rel = mean_residual / (bin_capacity as f64);
    score += (rel - mean_rel) * 8.0;

    // Slight progression term: late in the stream, be more aggressive about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 5 {
            score -= 40.0 - (gap as f64) * 4.0;
        } else {
            score += (gap as f64) * 0.4;
        }
        // Penalize leaving residual smaller than next item but large (dead space).
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += (post_residual as f64) * 0.3;
        }
    }

    // Penalize deviating from mean residual context.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless it is the only option or fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reward tight fits in existing bins.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Late in stream: prefer consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: reward small post-residual, with non-linear emphasis.
    let cap_f = bin_capacity as f64;
    let tight = (post_residual as f64) / cap_f;
    score += 12.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that no plausible item (>=1) can exploit well:
    // residual too small relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here: slight penalty if this bin would be left
            // with awkward residue.
            score += 2.0;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is wasteful early on when other bins fit;
        // penalize it, scaled by how many bins already fit the item.
        if fitting_bins_count > 0 {
            score += 40.0 + 5.0 * (fitting_bins_count as f64);
        } else {
            // No open bin fits: must open new bin; make its score neutral-low.
            score -= 10.0;
        }
        // Late in the stream, be more willing to open new bins since
        // leftover residue in old bins is less valuable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress * progress;
    } else {
        // Reward using existing bins, more when many bins are open.
        score -= 3.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Global state: prefer filling bins below the mean residual (balance),
    // i.e. if this bin's residual is below mean, it's tighter than average.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res_f - mean_residual) / mean_residual;
        score += 4.0 * rel; // tighter-than-average bin gets lower score
    }

    // Prefer placing large items into fuller bins (waste-aware).
    let item_frac = item_size as f64 / cap_f;
    score -= 10.0 * item_frac * (1.0 - res_f / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // 0..1
    let poly = norm_post * norm_post * (3.0 - 2.0 * norm_post); // smoothstep in [0,1]
    score += poly * (20.0 + 30.0 * progress) - progress * 15.0 * poly;

    // Penalize dead space more as the stream progresses (less room to recover).
    score += (1.0 - poly) * poly * 10.0 * progress;

    // Reward tight fits strongly, scaled by progress.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: reward leaving space that can still serve the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - ((post - nxt) / cap).abs());
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln() * 1.5;

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are large.
    if bin_residual == bin_capacity {
        score = post + 12.0 + 30.0 * (1.0 - progress) - 20.0 * progress * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (dead space) are penalized proportionally.
    let pr = post_residual;
    let class = pr % 10; // decade residue class
    score += (class as f64) * 0.35;

    // Integer-division thresholds on post_residual:
    // leftover >= 50 means bin is still half usable -> mild bonus;
    // leftover in (0,10) is nearly perfect packing -> strong bonus.
    if pr == 0 {
        score -= 60.0;
    } else if pr < 10 {
        score -= 25.0;
    } else if pr >= 50 {
        score += 8.0;
    }

    // Capacity-fraction coupling: waste measured as fraction of capacity.
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * 40.0;

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // modulo harmonic match between leftover and next item size
            let m = post_residual % next_item_size.max(1);
            score -= (10 - (m as f64).min(10.0)) * 0.8;
        } else {
            // next item cannot use this leftover at all -> penalize dead space more
            score += 6.0;
        }
    }

    // Last-chance bin: only fitting bin -> strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // competition: slightly prefer bins among many candidates with tighter fit
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate (empty bin): must score poorly unless current bins are bad.
    // Base penalty, reduced when mean residual of open bins is small (poor options)
    // or stream is nearly done.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 120.0;
        score -= mean_residual.min(60.0) * 1.2;
        score -= progress * 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // reserving empty bin for a big next item is fine
        }
    }

    // Prefer filling bins whose residual is closest to the item (tight fit) via
    // harmonic ratio between item and residual.
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= ratio * 12.0;

    // Many open bins with high mean residual: encourage consolidation into fuller bins.
    if open_bins_count > 3 {
        score += (mean_residual - post_residual as f64).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: gaps that no realistic item (>=1) can use
    // are worst; gaps below typical small-item sizes are heavily penalized.
    if post_residual < 10 {
        score += 60.0; // near-zero gap: pure waste
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Pressure from number of open bins: prefer filling existing bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 12.0;
    } else if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) > -5 {
        score += 6.0; // next item nearly fits: risky dead space
    }

    // New bin candidate: keep it neutral-to-slightly-penalized unless alternatives are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: if mean residual is large, discourage wasting space here
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-match_gap / 12.0).exp(); // strong reward for perfect 2-step fit
        // Penalize residuals that are just barely below the next item (dead space for step 2)
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Penalize creating residuals that are hard to reuse relative to mean residual.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 10 {
            score -= 20.0; // near-perfect fill
        }
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is attractive early in the stream or when open bins are full-ish.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64); // new bin can host next item too
        }
        if progress < 0.2 {
            score -= 8.0;
        }
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 12.0; // open bins are nearly full, new bin reasonable
        }
    }

    // Mild preference for filling bins more completely overall.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: filling a bin well relative to its current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Lookahead: reward if the next item can also fit in the post-placement residual.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 6.0 + 8.0 * progress; // lookahead worth more later in the stream
        } else {
            // Dead-space risk: next item cannot follow into this bin.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across too many open bins with large mean residual.
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64 - 3.0) * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin should only win when
    // alternatives are poor or nonexistent.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // forced: no open bin fits
        } else {
            // Compete against existing bins: penalize more when many bins fit
            // or when existing bins would accept the item reasonably well.
            score += 18.0 + 6.0 * fitting_bins_count as f64;
            if fit_ratio > 0.8 {
                score += 10.0; // existing bins would be packed tightly; don't open new
            }
        }
    }

    // Mild reward for near-perfect closure (leaving tiny unusable residue is fine,
    // but exact closure is excellent).
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        - 18.0 * norm_pr * (1.0 - norm_pr) * (0.5 + progress)
        + 30.0 * norm_pr * norm_pr * progress;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 * (1.0 - pr / nx.max(1.0));
        }
    }

    // Penalize deviation from mean residual (fragmentation pressure)
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty when many bins are open, encouraging consolidation
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes via integer division
    let post = post_residual as f64;
    let class = (post_residual / 10) as f64; // decade class of leftover
    score += class * 1.7;

    // Penalize post_residuals in "unusable" bands (1..9 and 11..19 style gaps)
    let rem10 = post_residual % 10;
    if rem10 > 0 && post_residual < 10 {
        score += 12.0; // tiny dead space, almost unusable
    } else if rem10 > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's size class aligns with leftover class
            let nxt_class = (next_item_size / 10) as f64;
            score -= 4.0 + nxt_class * 0.8;
            // exact modulo alignment bonus
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; leftover becomes final dead space
            score += post * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only good when current
    // fits are poor (large post_residual relative to capacity) or few bins open
    if bin_residual == bin_capacity {
        let poor_fit = post / cap; // = 1.0 for empty bin; compare via mean residual instead
        let _ = poor_fit;
        let mean_tightness = mean_residual / cap;
        // open new bin if existing bins are already tight (low mean residual)
        score = 40.0 - mean_tightness * 25.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if fitting_bins_count <= 1 {
            score += 30.0; // don't abandon a last-chance bin
        }
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 8.0; // new bin helps the lookahead too
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for spreading across too many bins
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum
    // item size (1) are pure waste; small gaps in general are penalized
    // super-linearly so the packer prefers leaving either ~0 or a large,
    // reusable residual.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // penalize unusable/tiny gaps very hard
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr);
        } else if post_residual <= 30 {
            score += 0.8 * (30.0 - pr) * (30.0 - pr) / 10.0;
        }
        // dead space relative to capacity
        score += 0.5 * (pr * pr) / bin_capacity as f64;
    } else {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits (item consumes most of the bin)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin (unless post_residual is
    // terrible dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open
    // and this bin's residual is near the mean (a "typical" bin is fine to use).
    if open_bins_count > 4 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * open_bins_count as f64 * (deviation / bin_capacity as f64);
        score -= 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: the empty bin should only win when no open
    // bin offers a decent fit. Give the empty bin a mild penalty so existing
    // bins with reasonable fits win, but keep it competitive against bins
    // that would leave heavy dead space.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened when stream is early
        // (few open bins) or when the next item is large (reserve space).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 18.0 + 30.0 * progress;
        // if next item is large, a fresh bin preserves flexibility
        if next_item_size > 50 {
            new_bin_cost -= 12.0;
        }
        if open_bins_count == 0 {
            new_bin_cost = -10.0;
        }
        score += new_bin_cost;
    } else {
        // Using an open bin: reward keeping future flexibility for the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // this bin can still host the lookahead item: reward
                score -= 8.0;
            } else if post_residual > 0 && post_residual < next_item_size {
                // creates a gap the next item cannot use: penalize
                score += 0.3 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Mild late-stream tightening: as the stream progresses, prefer
    // consolidating into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit for the NEXT item: post_residual exactly equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post residual: strong 2-step lookahead reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Bonus scaled by how tightly the next item fills the remaining space
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to wasted capacity
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize mildly so we only open when fits are poor,
    // but discount the penalty late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - 0.5 * progress);
    }

    // Reward bins whose residual is already below mean (tight bins)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 0.15 * diff;
        } else {
            score += 0.1 * (-diff);
        }
    }

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residuals are good, but residuals too
    // small for the smallest future item (<=10) are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement; if it nearly fits, mild reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 2.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity (poor fit elsewhere) or many bins are open
    // with fragmented residuals.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        let fragmentation = if mean_residual > 0.0 && mean_residual < item_size as f64 {
            15.0
        } else {
            0.0
        };
        // Base penalty keeps new bins as a fallback; reduced for big items
        // or when existing bins are too fragmented to help.
        score += 45.0 - large_item_bonus - fragmentation;
        // Early in the stream, opening bins is cheaper (more items to come
        // that may fill them); later, prefer consolidation.
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference for filling bins with below-average residual
    // (consolidate the emptier bins' contents).
    if bin_residual < bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Slight reward for using many open bins efficiently (avoid bin sprawl).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: penalize wasted post residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr;
    score += 0.9 * (pr * pr) / cap;
    score += 0.35 * (pr * pr * pr) / (cap * cap);

    // Smooth progress coupling: later in stream, waste matters more
    score += pr * (0.6 * progress + 0.8 * progress * progress);

    // Reward tight fits: subtract based on fill ratio, amplified non-linearly
    let fill = 1.0 - pr / cap;
    score -= 14.0 * fill * fill * fill;

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 9.0 + 6.0 * progress;
    }

    // Prefer bins with residuals below mean (pack small gaps first)
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - diff / cap).max(0.0) * (1.0 - diff / cap).max(0.0);
        if pr < next_item_size as f64 {
            score += 4.0; // dead space penalty if next item cannot fit
        }
    }

    // Slight preference for consolidating into fewer bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Reward near-perfect fits: post_residual in small harmonic classes
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= eighth {
        score -= 20.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    } else {
        // Penalize dead space that cannot fit typical items
        score += (post_residual as f64) * 0.15;
    }

    // Modulo-10 class: residual divisible by common item classes is reusable
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 6.0;
    } else if m10 >= 8 {
        score += 3.0; // awkward sliver class
    }

    // Lookahead coupling: can next_item_size fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item lands in same class bucket
            let diff = post_residual - next_item_size;
            if diff <= eighth {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += (next_item_size as f64) * 0.10; // next item will need another bin
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when residual is very tight
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins win by default
        score += 40.0;
        // If the current bin's post-residual would be a bad class (too small for min item 1..100),
        // and a new bin gives a clean full residual, relax the penalty
        if post_residual < 10 && post_residual > 0 {
            score -= 45.0; // opening fresh bin beats wasting a sliver
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 10.0;
        }
        // Many open bins with low mean residual: avoid spreading
        if open_bins_count > 4 && mean_residual < cap * 0.3 {
            score += 10.0;
        }
    }

    // Mild preference for fuller bins overall (lower residual = lower score already)
    score -= (bin_residual as f64 / cap) * 5.0;

    // Small noise-free tiebreaker on bin index proxy via mean residual divergence
    score += (mean_residual - post) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
