    }

    // Pressure from number of open bins: prefer consolidating when many open.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.05 * open_pressure;

    // New-bin candidate: keep it unattractive unless residuals everywhere are tiny.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * mean_residual.signum();
        if mean_residual < 15.0 && mean_residual > 0.0 {
            score -= 45.0;
        }
    }

    // Late in stream: slightly prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    }

    // Aggressive 2-step lookahead: bonus if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills remaining space
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // penalty if next item cannot fit here, scaled by how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 30.0 * (miss / bin_capacity as f64);
        }
    }

    // Penalize large dead space relative to mean residual (fragmentation).
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.5 * dead;
    } else {
        score += 0.2 * dead; // slightly reward keeping residual near/below mean
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // Penalize opening a new bin when good fitting bins exist (new-bin candidate check).
    if bin_residual == bin_capacity {
        // new empty bin: neutral base, penalize if open bins could handle it
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // empty bin still useful for the lookahead pair
            score -= 40.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Slight preference to fill bins more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post residual)
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: reward if the next item fits exactly/well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize leaving medium dead space
            if post_residual < next_item_size && post_residual > 0 {
                score += (post_residual as f64) * 0.3;
            }
        }
    }

    // Last chance: this is the only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New bin candidate handling: only attractive when fits are poor or many bins open
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) < 0.35 * bin_capacity as f64;
        let late_stream = (step_index as f64) / (total_items.max(1) as f64) > 0.6;
        let crowded = open_bins_count as f64 > 4.0 + 0.05 * mean_residual;
        if poor_fit && (late_stream || crowded) {
            score -= 30.0; // opening fresh bin better than fragmenting
        } else {
            score += 45.0 + 0.5 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Prefer bins with residual below mean (consolidate fullness)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // Time horizon: early stream, be conservative; late stream, squeeze harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Avoid creating tiny unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post residual), with smooth polynomial sharpening
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = post as f64 * (1.0 + 2.0 * x * x);

    // Smooth stream-progress coupling: as stream advances, tighten more aggressively
    score *= 1.0 + 1.5 * progress * (1.0 - x);

    // Lookahead coupling: reward leaving space usable by next item, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = 1.0 - (post - nxt) / cap; // exact match for next item => ~1
            score -= 8.0 * slack_fit * slack_fit;
        } else {
            let dead = (nxt - post) / cap;
            score += 10.0 * dead * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty scaled by number of alternatives to encourage spreading
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a bin unless it would be a genuinely tight fit
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * (1.0 - x) * (1.0 - x);
    }

    // Mean-residual context: penalize placing into bins deviating from mean residual
    score += 0.5 * (post - mean_residual).abs();

    // Small penalty per open bin to discourage bin proliferation
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    let frac = (post_residual as f64) / (bin_capacity as f64);

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class bonus: residuals landing in "reusable" classes
    // (multiples of 10 and 20) are more likely to accept future items.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is a chain win.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= (20.0 - gap.min(20) as f64) * 1.5;
        } else {
            // Next item does not fit here: penalize leaving a large awkward residue
            // unless it is a clean harmonic class.
            let awkward = if post_residual % 10 != 0 && post_residual < next_item_size {
                (next_item_size - post_residual) as f64 * 0.5
            } else { 0.0 };
            score += awkward;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild pressure toward consolidating into few bins when many are open.
    score += (open_bins_count as f64) * 0.3;

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Early in stream: slightly favor tight fills; late: accept looser fits
    // to avoid opening new bins near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // New-bin candidate (empty bin): should only win when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = 120.0 + item_size as f64 * 0.5 - progress * 30.0;
        // If the item would leave a perfect harmonic residue in a fresh bin, ease it.
        if item_size % 10 == 0 {
            score -= 10.0;
        }
    }

    // Small tie-breaker on class index to prefer lower-class (tighter) residuals.
    score += class as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        // But if next item is large and current item small, new bin is fine.
        if next_item_size > 0 && next_item_size > item_size * 2 {
            score -= 20.0;
        }
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 20.0;
        }
    }

    // Pressure from many open bins: prefer filling existing bins.
    score += open_bins_count as f64 * 0.3;

    // Slight preference for bins tighter than the mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late in the stream, be extra conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);

        // Penalize post-residual that is dead space (too small for typical items)
        if post_residual < next_item_size.min(10) {
            score += 10.0;
        }
        // Bonus when post_residual can host the next item exactly (chain packing)
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Penalize waste relative to mean residual: creating below-average residual
    // space is wasteful unless it's a perfect lookahead match
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score += 0.3 * (mean_residual - residual_f);
    } else {
        score -= 0.1 * (residual_f - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate (empty bin): penalize unless current fit is terrible
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // New bin is attractive when the item is large (leaves useful residual)
        // or when many bins are already open
        score = 100.0 - 30.0 * tightness - 0.5 * open_bins_count as f64;

        // If only one fitting bin exists, discourage opening a new bin
        if fitting_bins_count <= 1 {
            score += 50.0;
        }
        // Lookahead: if next item fits well in the fresh residual, encourage new bin
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight time decay: early on, be more conservative with residual space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating awkward dead space that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax when the item
    // would leave a bad fit or when many bins already exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 35.0;
        // Later in the stream, consolidating matters more.
        penalty *= 1.0 + 0.5 * progress;
        // If item fits poorly everywhere else (large item, few fitting bins), allow new bin.
        if fitting_bins_count <= 1 && item_size >= 50 {
            penalty -= 30.0;
        }
        // Lookahead: if the next item could combine with leftover space, discourage new bin.
        if next_item_size > 0 && next_item_size <= post_residual.max(bin_residual.saturating_sub(item_size)) {
            penalty += 15.0;
        }
        score += penalty;
    }

    // Lookahead coupling: prefer bins whose post-residual accommodates the next item.
    if next_item_size > 0 && !is_new_bin {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Prefer fuller bins relative to the current average residual (reduce fragmentation).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.5 * (mean_residual - residual_f);
    } else {
        score += 0.3 * (residual_f - mean_residual);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // non-linear coupling of post_residual with stream progress
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 18.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // reward tight fits more strongly as the stream progresses
    score -= item_norm * item_norm * 10.0 * (1.0 + progress);

    // penalize dead space relative to mean residual (non-linear)
    score += 6.0 * (pr - mean_residual).abs() / cap * (0.3 + progress);

    // last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = pr_norm - nx;
        if gap >= 0.0 {
            score -= 8.0 * nx * (1.0 - gap);
        } else {
            score += 6.0 * (-gap) * (1.0 + progress);
        }
    }

    // crowding pressure: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - pr_norm);

    // new-bin candidate: penalize slightly, less so early in stream
    if bin_residual == bin_capacity {
        score += 8.0 * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "small" classes are rewarded strongly (dead space avoided).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Classify residual into harmonic bands via integer division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    } else if post_residual <= 40 {
        score -= 4.0;
    } else {
        score += 6.0 * frac; // large leftover: mild penalty on top of raw residual
    }

    // Modulo-arithmetic harmonic classes: residuals that are multiples of
    // common small item sizes are more reusable.
    for m in [10u32, 20, 25, 50] {
        if post_residual >= m && post_residual % m == 0 {
            score -= 8.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= (20.0 - (gap.min(20)) as f64) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has raw residual == capacity,
    // which already scores high (bad). Add extra penalty scaled by how many
    // open bins exist, so new bins are only chosen when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).min(20.0) * 0.5;
        // But allow new bins late in the stream if mean residual is tiny
        // (all open bins nearly full anyway).
        if mean_residual < 10.0 {
            score -= 20.0;
        }
    }

    // Progress coupling: slightly prefer compacting into few bins early,
    // and tolerate opening bins late when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Prefer bins whose residual deviates favorably from the mean.
    score -= (mean_residual - pr).max(-20.0).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small unusable gaps (below minimum item size 1..~20)
    // are heavily penalized since they can never be filled.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.5;
    }
    // Exact fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 30.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open bins pressure: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // New empty bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If next item is large, opening fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item can use this bin's post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Slight preference for bins with residual near mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // 2-step lookahead: reward post_residual matching next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // perfect chain: next item exactly fills the bin afterwards
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // dead space that next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 + 0.15 * post_residual as f64;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Penalize tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Deviation from mean residual: prefer bins with less residual than average
    score += 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // no good fit exists among open bins
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit_exists = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) > 0 && (bin_residual - item_size) < 10);
        if poor_fit_exists {
            score -= 12.0;
        } else {
            score += 35.0 + 20.0 * progress;
        }
    }

    // Mild penalty for many open bins: encourage consolidation
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Reward placements that leave room for the lookahead item (perfect chain).
    if nxt > 0.0 {
        if post >= nxt {
            // next item can still fit here: reward proportionally to slack quality
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            // dead space relative to next item: penalize wasted capacity
            score += 4.0 * (nxt - post) / cap * (1.0 - progress);
        }
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual deviates below the mean (filling the emptiest usable bins).
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0) / cap;

    // New empty bin candidate: baseline cost of opening a bin, discounted early
    // or when item is large and would otherwise leave a very poor fit elsewhere.
    if bin_residual == bin_capacity {
        let open_cost = 30.0 + 40.0 * progress;
        let large_item_relief = (item / cap) * 20.0;
        score = open_cost - large_item_relief;
        // If this bin is the only fitting option, opening is mandatory anyway.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: late in the stream, tighten more aggressively
    score += 20.0 * progress * norm_pr * norm_pr;

    // Penalize bins far from mean residual (encourage balanced residuals smoothly)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead coupling: reward leaving post residual close to next item size
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - gap * gap);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate: make empty bins attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 30.0 * (1.0 - (pr / cap).min(1.0)) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class logic: partition post_residual into residue classes mod 10.
    // Dead space that cannot hold the smallest item (1..100 range, min 1) is worst;
    // classes divisible into small chunks are more reusable.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 8.0,           // clean class, reusable by multiples of 10
        1 | 2 | 3 => score -= 3.0,   // nearly clean, minor filler fits
        4 | 5 | 6 => score += 2.0,   // awkward middle class
        _ => score += 5.0,           // 7..9: dead-space prone
    }

    // Integer-division thresholds: post_residual / next_item_size
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead item fits here: reward keeping room for it.
            let ratio = pr as f64 / next_item_size as f64;
            if ratio >= 1.0 && ratio < 2.0 {
                score -= 18.0; // next item exactly consumes this bin's slack
            } else if ratio >= 2.0 {
                score -= 6.0;  // room for next plus more
            }
        } else {
            // Next item cannot fit here; penalize leaving a gap smaller than next item.
            score += 10.0 + (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline penalty so it is only
    // chosen when open bins fit poorly. Scale pressure with stream progress and
    // number of open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 95.0 + progress * 20.0 + open_bins_count as f64 * 1.5;
        // Allow opening a new bin when the item is huge relative to remaining slack
        // everywhere (approximated via mean residual).
        if item_size as f64 > mean_residual + 15.0 {
            score -= 40.0;
        }
        // If item nearly fills a fresh bin, opening is fine.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 25.0;
        }
    } else {
        // Mild preference for filling already-open bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
        // Penalize bins deviating far from mean residual (keep portfolio balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.08;
    }

    // Small penalty for very large leftover that only a huge future item could use,
    // expressed via integer division of residual by 10 (harmonic decade).
    let decade = pr / 10;
    if decade >= 5 {
        score += 4.0; // large slack bins are less urgent to fill now
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        // A residual gap is "dead" if the next item (or a typical item) cannot use it.
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            // Unusable gap: dead space penalty grows as gap shrinks (smaller gap = worse).
            let dead = post_residual as f64;
            score += 40.0 * (1.0 - dead / 30.0).max(0.0) + 15.0;
        } else {
            // Next item fits: reward leaving exactly the right gap.
            score -= (post_residual as f64 - next_item_size as f64).abs() * 0.3;
            score -= 10.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Tight fit reward relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; consolidate.
    score += open_bins_count as f64 * 0.6;

    // Mean residual coupling: if mean residual is small (bins nearly full),
    // prefer filling existing bins; if large, allow opening new ones.
    score += (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when the current item is small relative
        // to mean residual (poor fit everywhere else) or few bins fit it.
        let poor_fit_pressure = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).max(0.0)
        } else {
            2.0
        };
        // Default: make new bin moderately expensive.
        score += 30.0;
        // If this is a last-resort situation, discount the new bin.
        if fitting_bins_count <= 2 && poor_fit_pressure < 1.0 {
            score -= 20.0;
        }
    }

    // Slight late-stream consolidation: as stream progresses, tighten selection.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits exactly-ish in the leftover space.
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 150.0; // perfect chain: item then next item fill bin
            }
        } else {
            // Leftover too small for next item: penalize dead space,
            // but less harsh if the residual itself is tiny.
            let dead = post_residual as f64;
            score += 0.5 * dead * (dead / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a brand-new bin unless it enables a great fit
    // (post_residual matching next item) or current bins are all poor fits.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5;
        let poor_existing = mean_residual > (bin_capacity as f64 - item_size as f64) * 0.9;
        if !(good_lookahead || poor_existing) {
            score += 250.0;
        } else {
            score += 25.0;
        }
    }

    // Late in the stream, be more conservative: keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize creating small unusable dead space (< next item size or < 10).
    let min_future_need = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < min_future_need {
        score += 18.0 + (min_future_need - post_residual) as f64;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 25.0;
        } else if slack < 10.0 {
            score -= 8.0;
        }
    }

    // Last chance: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer bins with smaller residual (waste big bins last).
        score += (bin_residual as f64) * 0.15;
    }

    // New-bin candidate: make it unattractive unless the item is huge or fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is fine for very large items (hard to place later).
        if item_size >= 70 {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out with new bins to avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.85 {
            score -= 12.0 * progress;
        }
        // If many open bins with large mean residual, avoid opening yet another.
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 15.0;
        }
    }

    // Mild preference for filling already-open bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Discourage leaving many half-empty bins when open bin count grows.
    if open_bins_count > 5 && post_residual > 50 {
        score += 0.2 * (post_residual as f64 - 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tightest fit preferred (minimize post residual)
    let mut score = pr;

    // Smooth non-linear coupling: penalize residual more when it is "dead space"
    // (too small to be useful later), scaled by stream progress.
    let dead_zone = cap * 0.35;
    let deadness = ((dead_zone - pr) / dead_zone).max(0.0);
    score += deadness * deadness * (8.0 + 12.0 * progress);

    // Reward filling bins tightly, with mild progress-dependent urgency.
    let fill = 1.0 - pr / cap;
    score -= fill * fill * (6.0 + 10.0 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to keep alternatives available
        score += 2.0 * ((fitting_bins_count as f64).ln()).max(0.0);
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed.
    if bin_residual == bin_capacity {
        let needed = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 * (1.0 - needed) + 15.0 * (1.0 - progress);
        // If next item could use this residual, soften slightly.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 5.0;
        }
    }

    // Lookahead: penalize leaving residual that fits next item poorly
    // (residual much larger than next item wastes capacity).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += (gap / cap) * (4.0 + 6.0 * progress);
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (close out low-residual bins first).
    let dev = (mean_residual - pr) / cap;
    score += dev * (2.0 + 3.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward (residual exactly consumed).
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: small residues (< 10) are dead space
    // unless they are exactly 0. Penalize tiny-but-nonzero leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Residue classes via modulo: residues that are multiples of common
    // item granularities are more reusable.
    let r = post_residual;
    if r >= 10 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post residual, this is a
    // chaining opportunity — reward proportionally to next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual becomes unusable for the next item: penalize dead space.
        score += (next_item_size as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: residual == capacity. Penalize opening a new bin
    // unless the item is large or there are few fitting alternatives.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        if !large_item && fitting_bins_count > 0 {
            score += 90.0;
        }
        if fitting_bins_count > 2 {
            score += 60.0;
        }
        // Late in the stream, opening new bins freely is fine (fewer future
        // items to strand), so soften the penalty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 50.0;
    }

    // Prefer bins whose residual deviates from the mean in a "tighter"
    // direction (best-fit flavor): bins below mean residual fit better.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Mild penalty for leaving very large residuals (wasteful bins).
    if post_residual > bin_capacity / 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps below minimum item size 10, or tiny gaps)
    if post_residual < 10 {
        score += 40.0; // dead space that can never be used
    } else if post_residual <= 20 {
        score += 8.0; // risky small gap, only fits very small items
    }

    // Reward tight fits: small post_residual relative to bin capacity
    score -= 2.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Open bins pressure: penalize using a bin when many bins are open,
    // unless it's a tight fit; encourages consolidating items
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.05 * open_pressure * (post_residual as f64 / 10.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual exactly-ish, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }
    // If next item cannot fit in post_residual but the gap is large, mild penalty for waste
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so it's chosen only
    // when open bins would create bad dead space
    if bin_residual == bin_capacity {
        score += 12.0;
        // Opening a new bin is attractive if next item is large and would leave open bins unusable
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 6.0;
        }
    }

    // Late-stream tightening: as stream progresses, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-item match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the leftover space (good chaining).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
    }
    // Next item cannot use the leftover: dead-space penalty grows with waste.
    else if next_item_size > 0 {
        let waste = post_residual as f64;
        score += 0.6 * waste;
        if post_residual < 10 {
            score += 20.0; // tiny unusable sliver
        }
    }

    // Reward near-full bins (tight fits close bins efficiently).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score += pressure + 0.2 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with the upcoming large item
        }
    }

    // Late-stream urgency: consolidate into existing bins as the stream ends.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize leaving dead space that cannot hold typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / cap);
        }
    } else {
        // Last item: prefer fullest packing possible.
        score -= 30.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so we only open new bins when alternatives score badly.
        score += 90.0;
        // More acceptable late in the stream or when few bins fit the item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If open bins have large mean residual, opening new bins is less costly.
        score -= 0.2 * mean_residual;
    }

    // Mild preference for filling bins with larger residual when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let residual_norm = bin_residual as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.5 * fit_ratio) + 0.02 * pr * pr / cap;

    // Reward tight fits smoothly: penalize when post_residual is far from 0
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness * tightness * (1.0 + progress);

    // Smooth interaction: stream progress amplifies preference for filling existing bins
    score -= 20.0 * progress * residual_norm * (1.0 - residual_norm);

    // Last-chance bin: strongly favor it, scaled smoothly by fit tightness
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // Next-item lookahead: if next item fits smoothly in post-residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            // next item won't fit: penalize leaving large unusable space
            score += 5.0 * (pr / cap) * (pr / cap);
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (fill emptier-first effect)
    score += 0.1 * (pr - mean_residual);

    // New-bin candidate: penalize opening a new bin, more so as stream progresses,
    // unless it's a near-perfect fit scenario (empty bin always has pr == cap)
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 45.0; // worst dead space
    } else if pr > 10 && pr <= 20 {
        score += 18.0;
    } else if pr > 20 && pr <= 35 {
        score += 6.0;
    } else if pr == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Integer-division class: residual mod 10 (harmonic granularity of item sizes)
    let residue_class = pr % 10;
    if pr > 0 && residue_class != 0 {
        score += residue_class as f64 * 0.8;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 22.0; // chain placement possible
            // extra reward if next item exactly fills the leftover
            if next_item_size == pr {
                score -= 18.0;
            }
        } else {
            // next item won't fit here: penalize more if leftover is small
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when current bin fits poorly,
        // but discourage when a good existing fit exists.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * progress;
        if fitting_bins_count <= 1 && item_size < bin_capacity {
            score -= 20.0; // poor alternatives: new bin acceptable
        }
        // A fresh bin keeps max flexibility for the lookahead item
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Prefer tighter bins among fitting ones (relative to mean residual)
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Slight preference for bins that will end more full
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (nonzero but too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (near-perfect packing)
    if post_residual == 0 {
        score -= 25.0;
    } else {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it unattractive unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        // If next item is large and current item is small, opening a fresh bin is less bad
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits snugly into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    }
    // Penalize post residual that cannot host the next item (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Reward tight fits relative to bin capacity
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Compare against mean residual: prefer bins that reduce residual spread
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when the item would fit reasonably elsewhere
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let best_possible = 100.0 - item_size as f64;
            if post_residual as f64 >= best_possible - 1.0 {
                score += 50.0;
            } else {
                score += 10.0 + item_size as f64 / 4.0;
            }
        } else {
            score -= 10.0; // no alternative: new bin is fine
        }
    }

    // Slight preference for consolidating when many bins are open
    score += 0.3 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post residual is small relative to capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize leaving dead space that no future item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits in the post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect pairing: item + next item exactly fill this bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins -> this placement is low-stakes; slight penalty for waste.
    if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state coupling: when mean residual is low, conserve bin space more aggressively.
    let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += pressure * (post_residual as f64) * 0.3;

    // Time horizon: early in stream, be more willing to open bins (penalize cramming);
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 3.0;

    // New-bin candidate handling: empty bin is a fallback.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when current bins are fragmented
        // (high mean residual spread) or item is large and nothing fits well.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 - 0.4 * (open_bins_count as f64) + fragmentation * 0.1;
        // If this is the only fitting option, opening a new bin is natural.
        if fitting_bins_count <= 1 {
            score += 10.0;
        }
        // Late stream: discourage new bins.
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit), non-linearly scaled.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Reward tight fits super-linearly (dead space is worse late in the stream).
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * item * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    } else {
        // Mild penalty when many bins compete, to encourage consolidation.
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            // Perfect match for next item is great; near-match also good.
            score -= 35.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Penalize bins whose residual is far above the mean (fragmentation).
    let dev = (res - mean_residual) / cap;
    score += dev * dev * 25.0;

    // New-bin candidate handling: an empty bin is a fallback; make it costly
    // unless the item is large relative to residual or stream is early.
    if bin_residual == bin_capacity {
        let new_bin_cost = 45.0 * (1.0 - 0.5 * progress) - item * 0.3;
        score += new_bin_cost.max(2.0);
    }

    // Smooth polynomial coupling: stream progress amplifies residual cost.
    let poly = (pr / cap).powi(2) * (1.0 + progress) * 30.0;
    score += poly;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // --- Harmonic class of the post residual (modulo arithmetic) ---
    // Class 0: post_residual divisible by 10 -> clean slot structure.
    let cls = (post_residual % 10) as f64;
    score += cls * 0.35; // ragged remainders are dead space

    // Integer-division thresholds: how many "next item slots" fit in post_residual
    if next_item_size > 0 {
        let slots = post_residual / next_item_size.max(1);
        // Reward bins that can still host the lookahead item (chaining)
        if post_residual >= next_item_size {
            score -= 6.0 + slots as f64 * 1.5;
        } else {
            // post_residual too small for next item: penalize proportionally to waste
            score += (post_residual as f64) * 0.25;
        }
        // Harmonic coupling: if next item divides post_residual evenly, it's a perfect chain
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    } else {
        // Last item: just prefer tightest fit
        score -= 5.0;
    }

    // Tight-fit reward: post_residual small relative to capacity
    let frac = post_residual as f64 / cap;
    if frac < 0.10 {
        score -= 12.0;
    } else if frac < 0.25 {
        score -= 5.0;
    } else if frac > 0.6 {
        // leaving a very loose bin: mild penalty
        score += 4.0 * frac;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current item is huge
    // relative to capacity (would strand a big residual in any open bin).
    if bin_residual == bin_capacity {
        let huge = (item_size as f64 / cap) > 0.75;
        let stranded = open_bins_count > 0
            && fitting_bins_count >= 1
            && post_residual > 0
            && (post_residual as f64) < (item_size as f64 * 0.2);
        if huge || stranded {
            score -= 20.0;
        } else {
            // default: prefer existing bins
            score += 18.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Late-stream consolidation: fewer open bins is better near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.4;
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let dead_threshold = 9.0_f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 12.0;
        }
        // Non-linear penalty on residual far from zero but too small for typical items.
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit is heavily rewarded.
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.4;

    // Slight bias toward filling larger-residual bins later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * (0.5 + progress);

    // Prefer bins whose residual deviates from the mean (tighter consolidation).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    // New-bin candidate: penalize opening a new bin unless it is truly needed.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 200.0;
        } else {
            // penalize mismatches, scaled by how far off the lookahead fit is
            score += diff * 0.6;
            // if the next item cannot fit in the post residual, penalize dead space
            if (post_residual as i64 - next_item_size as i64) < 0 {
                score += (next_item_size as f64 - post_residual as f64) * 1.2;
            }
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // Prefer bins tighter than the mean residual (fill fuller bins first)
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current bin would leave unusable dead space
    if bin_residual == bin_capacity {
        // opening a new bin is fine if no open bin gives a good lookahead fit
        let good_fit = next_item_size > 0
            && post_residual == next_item_size;
        if good_fit {
            score -= 15.0;
        } else {
            score += 60.0;
        }
    }

    // Mild penalty for leaving very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Slight preference for filling more bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Reward near-perfect packing even more.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize dead space.
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Penalize leaving residuals that are small and unlikely to be useful,
    // but only mildly when many bins are open (fragmentation spread out).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 / (open_bins_count as f64).max(1.0);
    }

    // New-bin candidate handling: opening a new bin should generally lose,
    // unless the fit into open bins is poor and mean residual is already large.
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins are preferred for decent fits.
        score += 40.0;
        // But if the item fits nowhere tightly (mean residual far above item size),
        // opening fresh capacity becomes attractive late in the stream.
        let spread = mean_residual - item_size as f64;
        if spread > 30.0 {
            score -= 25.0 + spread * 0.2;
        }
        // Early in the stream, be more willing to open bins (build diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Mild global pressure: when many bins are open, prefer consolidating
    // into existing bins to reduce fragmentation.
    score += (open_bins_count as f64).ln().max(0.0) * fit_ratio * 3.0;

    // Prefer bins whose residual is already below average (they're "used up");
    // placing into them keeps mean residual distribution tight.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_frac = post / cap;

    // Base: prefer small post_residual (tight fit), with a non-linear
    // polynomial shaping that increasingly penalizes dead space as the stream progresses.
    let mut score = post * (1.0 + 0.8 * progress * progress)
        - 12.0 * (1.0 - residual_frac).powi(3) * (1.0 + 0.5 * progress);

    // Exact fit reward (smoothed via polynomial in post_residual).
    score -= 6.0 * (1.0 - (post / 10.0).min(1.0)).powi(2);

    // Last-chance bin: strongly reward, scaled by how tight the fit is.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - residual_frac);
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to concentrate packing.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Lookahead: if the next item can use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - (slack / cap).powi(2));
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for the next item: penalize unusable sliver.
        score += 6.0 * (1.0 - post / cap);
    }

    // Coupling with mean residual: avoid placing into bins far from the mean
    // (keeps residual distribution balanced), smooth quadratic term.
    let dev = (post - mean_residual).abs();
    score += 0.05 * dev * dev / (cap * 0.5);

    // New-bin candidate: discourage opening a new bin when decent fits exist,
    // but allow it late in the stream or when current bins are all very tight.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).sqrt();
        score += 25.0
            + 20.0 * (1.0 - progress)
            + 3.0 * open_pressure
            - 10.0 * (mean_residual / cap).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modular arithmetic on capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;

    // Dead-space penalty: residuals in awkward harmonic classes (mod 10) are harder to fill.
    let class = post_residual % 10;
    let awkward = match class {
        1 | 2 | 3 | 7 | 8 | 9 => true,
        _ => false,
    };
    if awkward {
        score += 6.0 + 0.05 * (100.0 - pr);
    } else {
        score -= 2.0;
    }

    // Perfect or near-perfect closure reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    }

    // Integer-division thresholds: residual band structure (harmonic intervals of 20).
    let band = post_residual / 20;
    score += band as f64 * 3.0; // larger leftover is worse, superlinear via band steps
    score += 0.02 * pr * pr / c; // quadratic waste penalty

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer tighter fits among them (post_residual already does this).
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            score -= 15.0 - 0.1 * leftover2 as f64;
            // Harmonic match: next item shares residue class with residual
            if post_residual % 10 == next_item_size % 10 {
                score -= 6.0;
            }
        } else {
            // Next item cannot fit here anyway; mild penalty for stranding space.
            score += 4.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline offset so it only wins
    // when open bins would create bad fits.
    if bin_residual == bin_capacity && item_size > 0 {
        score += 12.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin has room for lookahead too
            score -= 5.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / c);

    // Mean residual coupling: avoid bins far from the mean unless it's a good closure.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Post-residual that can still fit the next item is desirable (keeps bin usable).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the lookahead item: mild extra penalty scaled by tightness.
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual != bin_capacity {
        score -= open_pressure * 0.5;
    } else {
        // New-bin candidate: only attractive when few bins open or mean residual is tiny.
        score -= (open_bins_count as f64).max(1.0).recip() * 20.0;
        score += (mean_residual / bin_capacity as f64) * 10.0;
        // Discard new-bin option if it would waste most of a fresh bin on a small item.
        score += (item_size as f64 / bin_capacity as f64).recip() * 5.0;
    }

    // Prefer bins whose residual is closest above the item (tight packing).
    score += (bin_residual - item_size) as f64 * 0.05;

    // Late in the stream, be more conservative: keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: item + next item fill bin exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward near-perfect matches (post_residual can hold next item with little waste).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use, scaled by how small the gap is.
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 2.0 * gap;
    }

    // Penalize leaving small unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer tight fits relative to current residual.
    score += 0.3 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    // Relative to mean residual: bins with residual near mean are neutral; large-residual bins
    // should absorb items to consolidate small bins.
    score -= 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: make it attractive only when few bins fit the item
    // or the residual is large and the item is big (poor fit elsewhere).
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 20.0;
        } else {
            // Discourage opening new bins when existing bins fit fine.
            score += 40.0 + 0.5 * item_size as f64;
        }
    }

    // Late in the stream, be more conservative: favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post-residual is small.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that the next item cannot use (lookahead coupling).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // dead space relative to lookahead
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 10.0; // next item fits snugly afterward
        }
    } else {
        // Last item: just fill as tightly as possible.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate logic: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is attractive only if existing bins fit poorly
        // (large post_residual everywhere) or many bins already fit fine.
        let spread = mean_residual - (post_residual as f64);
        score += 25.0; // base cost of opening a bin
        if mean_residual < 20.0 {
            score -= 20.0; // existing bins are nearly full; fresh space is valuable
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += (next_item_size as f64) * 0.1; // slight penalty: fresh bin keeps big room, fine
            score -= 5.0;
        }
        let _ = spread;
    } else {
        // Mild reward for keeping many open bins well-used (avoid fragmentation).
        score += (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Time horizon: later in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Global residual balance: prefer bins below mean residual (fill emptier bins first).
    score += 0.15 * ((mean_residual - bin_residual as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer minimal post residual, but with diminishing (quadratic) waste pressure.
    let mut score = post + 12.0 * (post / cap).powi(2) * cap;

    // Smooth tight-fit reward: gaussian-like coupling of item size to residual.
    let fit_ratio = item / cap;
    score -= 25.0 * fit_ratio * (1.0 - fit_ratio).exp();

    // Stream progress coupling: later in the stream, waste matters more (smooth cubic ramp).
    let pressure = progress * progress * (3.0 - 2.0 * progress);
    score += pressure * post * 0.8;

    // Mean-residual divergence: penalize bins deviating from fleet mean (encourages balance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * cap * (0.5 + pressure);

    // Lookahead: reward leaving room for the next item (smooth, non-linear).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 15.0 * (1.0 - (gap / cap)).max(0.0).powi(3);
        // Penalize post-residual that is just barely too small for next item (dead space).
        if post < nxt {
            score += 10.0 * (1.0 - post / nxt) * (1.0 + pressure);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly so open bins are preferred unless they fit poorly.
    if is_new_bin {
        score += 18.0 + 10.0 * (1.0 - progress) - 8.0 * (open_bins_count as f64).ln().max(0.0);
        // A new bin becomes attractive when existing fits would leave big waste.
        score += pressure * post * 0.3;
    }

    // Small penalty for proliferating open bins late in stream.
    score += (open_bins_count as f64) * 0.15 * pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near a multiple of 10
    // are "clean" classes (item sizes 10..80 make decade-aligned leftovers
    // more reusable). Reward small residues modulo 10.
    let harmonic = (post_residual % 10) as f64;
    score -= 1.5 * (5.0 - harmonic).abs(); // residue 0 or 10 best, 5 worst

    // Dead-space class: post residual in the awkward mid zone (11..=30)
    // is hard to fill for typical item sizes; penalize it quadratically.
    if post_residual > 10 && post_residual <= 30 {
        let d = post_residual as f64 - 10.0;
        score += 0.6 * d * d / 4.0;
    }

    // Lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for exact/near-exact harmonic match with next item.
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to how much it misses,
        // scaled by the next item's size class (bigger misses are worse).
        let miss = (next_item_size - post_residual) as f64;
        score += 0.08 * miss * (1.0 + next_item_size as f64 / 100.0);
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): discourage opening
    // a fresh bin unless the item is large and the leftover is still useful,
    // or there are no alternatives at all.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 60 {
            score -= 10.0; // large items justify fresh bins more often
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin can take it: must open
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure toward packing into bins below the mean residual
    // (balances load across open bins).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.15 * (mean_residual - res).min(30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item are pure waste — penalize hard.
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 4.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a residual that exactly fits the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize residuals that can't fit the next item but are near it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Open-bin pressure: prefer bins that are already relatively full
    // (small residual relative to capacity) to consolidate waste.
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score += fill_ratio * 10.0;

    // Pressure from number of open bins: when many bins are open,
    // favor filling existing bins over spreading out.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if mean residual is large, encourage
    // using the emptiest-feeling bins less (prefer tight fits).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin unattractive by default,
    // but attractive when the item would leave a large, awkward residual
    // in an existing bin (poor fit) or when few bins fit the item.
    if bin_residual == bin_capacity {
        score = 100.0
            + open_bins_count as f64 * 0.3
            - (fitting_bins_count as f64) * 15.0
            - (bin_residual - item_size) as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // new bin keeps space for similar next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in the stream, be more selective; late, just pack.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward residual that exactly matches next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward, scaled by slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(40.0) * 0.25;
        } else {
            // Dead space: next item cannot use the remainder.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * (0.8 + 0.6 * progress);
        }
    }

    // Penalize residuals too small to ever be useful (below min plausible item size ~1,
    // so instead penalize relative to mean residual: leaving much less than average).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual * 0.5 - post_residual as f64) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave awkward tiny remainder
    // or when the item fits perfectly into a fresh bin leaving a well-shaped residual.
    if bin_residual == bin_capacity {
        // Slight default cost so we prefer reusing bins with good fits.
        score += 8.0;
        // Perfect fit of item into fresh bin with nice leftover for typical items.
        if bin_capacity - item_size >= next_item_size && next_item_size > 0 {
            score -= 12.0;
        }
        // Late in stream, opening new bins is cheap-ish.
        score -= 10.0 * progress;
    }

    // Prefer tighter fits overall: small post_residual is good (already base score),
    // add extra shaping for very tight fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that likely cannot be reused.
    let dead = post_residual as f64;
    if dead > 0.0 {
        let small_gap = dead < 10.0;
        score += if small_gap { -6.0 } else { dead * 0.05 };
    }

    // Lookahead: reward if the next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if (next_item_size as u64) <= post_residual as u64 {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize blocking: post_residual too small for anything useful.
            score += 3.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but encourage opening a new bin
    // only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55; // baseline ~55
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 15.0; // discourage abandoning the single fitting bin
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > 20.0 {
        score -= 0.05 * mean_residual;
    }

    // Progress-aware tightening: later in the stream, prefer near-perfect fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (many items remain to fill gaps);
    // late in the stream, dead space becomes costly (quadratic growth).
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress;
    score += 30.0 * poly;

    // Smooth fit-quality reward: tight fits (small post_residual relative to item) get a bonus.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // with a smooth quadratic decay as the gap shrinks toward zero.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // Penalize creating a gap that cannot host the next item, scaled by gap size.
        let miss = (next_item_size - post_residual) as f64 / cap;
        score += 10.0 * miss * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smooth exponential-shaped reward).
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in the direction of filling down toward zero (variance-reduction shaping).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 + progress);

    // New-bin candidate handling: brand-new empty bins get a smooth opening cost
    // that shrinks as the stream progresses and when few bins fit the item.
    if bin_residual == bin_capacity {
        let open_cost = 25.0 * (1.0 - progress) * (1.0 - progress)
            + 10.0 / (1.0 + fitting_bins_count as f64);
        score += open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: prefer bins whose post_residual is small but not a dead sliver.
    if post_residual > 0 && post_residual < 10 {
        // Unusable dead space penalty (items >= 1, so residual < smallest item is waste)
        score += 25.0;
    }

    // Harmonic class: reward when the lookahead item exactly harmonizes with post_residual
    // (next item fills the bin completely -> perfect two-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect follow-up fill
        } else if next_item_size <= post_residual {
            // fraction of post_residual consumed by next item; reward high coverage
            let cover = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * cover;
        } else {
            // next item cannot use this residual; slight penalty proportional to leftover
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Integer-division harmonic classes on post_residual: bins whose residual lies in a
    // "useful" class (>= 20, i.e. can host another small item) are mildly preferred over
    // mid-gap residuals that waste space.
    let class = post_residual / 20; // 0..=5 classes
    match class {
        0 => {
            if post_residual > 0 {
                score += 20.0; // dead-space class
            }
        }
        1 => score += 2.0,  // 20..39: usable but loose
        2 => score += 0.0,  // 40..59: neutral
        3 => score -= 1.0,  // 60..79
        _ => {}             // near-empty bin: baseline (new-bin candidate lives here)
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate guard: make empty bins less attractive than any reasonable fit,
    // unless the stream is early (building a spread of bins can help) or the only fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: allow slightly more willingness to open bins.
        score -= 10.0 * (1.0 - progress);
        // If many open bins exist and mean residual is high, opening fresh bins is fine.
        if open_bins_count > 4 && mean_residual > item_size as f64 * 1.5 {
            score -= 5.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    // Tie-break toward tighter global state: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the minimum item size (1..10)
    // are pure waste, so add a strong nonlinear penalty.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // Small gaps may still be usable; mild penalty scaled by gap tightness.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: post_residual close to 0 (but >= 10) is desirable.
    if post_residual >= 10 {
        score -= 12.0 * (1.0 - post_residual as f64 / 50.0).max(0.0);
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins,
    // making the new-bin candidate less attractive.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of all existing bins;
        // penalize proportionally to how well existing bins could absorb the item.
        score += 30.0 + mean_residual * 0.3;
        // If item is small, a new bin wastes capacity; penalize more.
        if item_size <= 30 {
            score += 20.0;
        }
        // If next item is large, having a fresh bin may help slightly.
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.5 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward exact-ish match between post_residual and next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect follow-up fit strongly rewarded
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits in the leftover: mild reward proportional to closeness
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use leftover: penalize dead space
            score += 6.0 + 0.3 * gap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in stream, avoid opening new bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is small, a fresh bin is more attractive
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    // Many open bins: discourage spreading
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room for the lookahead item.
            let slack_after_next = post_residual - next_item_size;
            score -= 3.0 * (slack_after_next as f64 / bin_capacity as f64).min(1.0);
        } else {
            // Dead space smaller than next item is wasted.
            score += 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // forced new bin
        }
        // Early in the stream, slightly more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
    }

    // Reward placing into bins with residual far above the mean (balancing).
    score -= 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Slight preference for fewer open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer tight packing (low post residual).
    let mut score = post;

    // Reward tight fits: normalized tightness of the placement.
    let tightness = 1.0 - (post / cap);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    let dead = post / cap;
    score += 30.0 * dead * (1.0 - dead) * (1.0 - dead);

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let nxt = next_item_size as f64 / cap;
        score -= 18.0 * nxt * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += open_pressure * (post / cap) * 20.0;

    // Mean residual coupling: penalize bins far above the mean residual
    // (keeps residual distribution homogeneous), scaled by progress.
    score += 8.0 * progress * ((post - mean_residual) / cap).abs();

    // New-bin candidate: empty bin has large post residual; make it less
    // attractive unless the current bin would leave a nearly unusable gap.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "coarse" residue classes (divisible by large powers/small divisors of cap)
    // are more reusable, so reward them.
    let post = post_residual;
    if post > 0 {
        let mut bonus = 0.0;
        if post % 50 == 0 { bonus += 12.0; }
        else if post % 25 == 0 { bonus += 8.0; }
        else if post % 10 == 0 { bonus += 6.0; }
        else if post % 5 == 0 { bonus += 3.0; }
        score -= bonus;

        // Dead-space penalty: residuals too small for the smallest plausible item
        if post < 5 {
            score += 40.0;
        } else if post < 10 {
            score += 15.0;
        }
    } else {
        // Perfect fit is ideal
        score -= 25.0;
    }

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / cap;
    score -= 20.0 * fill_frac;

    // Lookahead coupling: reward residual that can host the next item exactly
    if next_item_size > 0 {
        if post >= next_item_size {
            let slack = post - next_item_size;
            score -= 10.0;
            if slack % 10 == 0 { score -= 4.0; }
        } else {
            score += 8.0; // this bin dies for the next item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Tightness relative to the fleet mean: prefer tighter-than-average bins
    let tightness = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * tightness;

    // New-bin candidate: only attractive when the stream is early or no bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = cap * 0.55; // baseline: mid-range score
        if fitting_bins_count == 0 {
            nb -= 60.0; // nothing fits anywhere: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            nb += 10.0; // big next item argues for a fresh bin
        }
        nb += 15.0 * progress; // later in stream, prefer consolidation over new bins
        if open_bins_count > 8 {
            nb += 10.0; // too many open bins already
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    score += open_bins_count as f64 * 0.6;

    // If next item fits exactly into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 3.0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't host the next item: mild penalty scaled by gap.
        score += ((next_item_size - post_residual) as f64).min(20.0) * 0.4;
    }

    // Mean-residual coupling: if this bin is far below average residual
    // (already dense), slightly favor it.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; high enough that good fits win,
        // low enough to beat bins leaving tiny dead space.
        score = bin_capacity as f64 * 0.85 + open_bins_count as f64 * 0.2;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
        if post_residual == 0 {
            score -= 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fit is heavily favored.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space that is too small to ever be useful (min item size 1, but typical small).
        let waste = post_residual as f64;
        if waste < 5.0 {
            score -= 25.0; // small dead space is fine, near-perfect fit
        } else {
            // quadratic penalty on wasted space
            score += (waste * waste) / (bin_capacity as f64 * 2.0);
        }
    }

    // Aggressive 2-step lookahead: if next item exactly matches post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chaining of next item into residual
        } else if next_item_size <= post_residual {
            // next item fits too: moderate reward proportional to how well it packs
            let leftover2 = post_residual - next_item_size;
            score -= 30.0 - (leftover2 as f64) * 0.5;
        } else {
            // next item cannot use this bin's residual: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Compare residual against mean residual across open bins.
    // Bins with residual below mean are more "committed"; prefer filling them.
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = resid / mean_residual;
        if rel < 1.0 {
            score -= (1.0 - rel) * 20.0; // below-average residual: good candidate
        } else {
            score += (rel - 1.0) * 5.0; // above-average residual: deprioritize slightly
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the current item is large relative to capacity and no tight option exists.
    if bin_residual == bin_capacity {
        // neutral base for new bin; add a fixed opening cost that tight fits can beat
        score += 15.0;
        // if next item is also large, opening fresh bin may allow pairing
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
        // early in stream, opening bins is cheaper (more future items to consolidate)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference to keep number of open bins low: when many bins are open,
    // favor placements that close out bins (small post_residual already does this).
    if open_bins_count > 8 && post_residual <= 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted capacity quadratically; small dead space is tolerable.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + item_size as f64 * 0.2;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin could also host the next item: reward proportionally.
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Placing here blocks the next item from using this bin: mild penalty.
            score += next_item_size as f64 * 0.1;
        }
    }

    // Tight-fit preference: item filling most of residual is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Time horizon: early in stream, be conservative about opening new bins;
    // later, allow tighter packing pressure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist and mean residual is large.
        if open_bins_count > 0 {
            score += 15.0 + mean_residual * 0.5 - progress * 10.0;
        } else {
            score -= 50.0; // must open first bin
        }
    }

    // Fragmentation guard: avoid leaving residuals in awkward zone (30..60)
    // that rarely fits future items, more so late in the stream.
    if post_residual >= 30 && post_residual <= 60 {
        score += 8.0 + progress * 6.0;
    }

    // Slight preference for bins with residual close to item (best-fit flavor).
    score += (bin_residual - item_size) as f64 * 0.05;

    // Tie-break with global state: fewer open bins is better all else equal.
    score += open_bins_count as f64 * 0.02;

    score
}
